package org.apache.commons.math3.distribution;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        HypergeometricDistribution liftedDist;
        try {
            liftedDist = new HypergeometricDistribution(43130568, 42976365, 50);
        } catch (Exception e) {
            return;
        }

        for (int i = 0; i < 100; i++) {
            final int sample;
            try {
                sample = liftedDist.sample();
            } catch (Exception e) {
                return;
            }
            // Lifted directly from HypergeometricDistributionTest.testMath1021:
            // every sample from this real distribution must satisfy 0 <= sample <= n (here n == 50).
            if (sample < 0 || sample > 50) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:lifted-math1021] semantic mismatch: sample=" + sample + " not in [0,50]");
            }
        }

        final double p;
        switch (data.consumeInt(0, 5)) {
            case 0:
                p = 0.5d;
                break;
            case 1:
                p = 0.75d;
                break;
            case 2:
                p = 0.9d;
                break;
            case 3:
                p = 0.99d;
                break;
            case 4:
                p = 0.999d;
                break;
            default:
                p = data.consumeInt(1, 999999) / 1000000.0d;
                break;
        }

        final int x;
        final double mass;
        try {
            // Contract justification:
            // inverseCumulativeProbability(p) returns a value of the integer distribution.
            // For HypergeometricDistribution, the support is the set of integers with non-zero probability,
            // so the returned quantile must itself have strictly positive probability mass.
            // This is an observable post-condition independent from merely checking bounds:
            // a throw-deleting or clamping band-aid could hide negatives while still returning a non-support point.
            x = liftedDist.inverseCumulativeProbability(p);
            mass = liftedDist.probability(x);
        } catch (Exception e) {
            return;
        }
        if (!(mass > 0.0d)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:invcdf-positive-mass] consistency violation: p=" + p + ", x=" + x + ", probability(x)=" + mass);
        }

        final int N;
        final int m;
        final int n;
        final HypergeometricDistribution fuzzDist;
        final int lower;
        final int upper;
        final double p2;
        final int q;
        final double qMass;
        try {
            N = data.consumeInt(1, 1_000_000);
            n = data.consumeInt(1, Math.min(200, N));
            int minM = Math.max(0, N - 1000);
            if (minM > N) {
                minM = 0;
            }
            m = data.consumeInt(minM, N);
            fuzzDist = new HypergeometricDistribution(N, m, n);
            lower = fuzzDist.getSupportLowerBound();
            upper = fuzzDist.getSupportUpperBound();

            // Strategy (c): exercise values around the changed Chebyshev upper-bracket condition.
            // Using p strictly inside (0,1) reaches the real inverseCumulativeProbability path.
            p2 = data.consumeInt(1, 999999) / 1000000.0d;
            q = fuzzDist.inverseCumulativeProbability(p2);
            qMass = fuzzDist.probability(q);
        } catch (Exception e) {
            return;
        }

        // Same documented guarantee as above, generalized to additional valid distributions.
        if (!(qMass > 0.0d)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:fuzzed-invcdf-support-point] consistency violation: N=" + N + ", m=" + m + ", n=" + n
                            + ", support=[" + lower + "," + upper + "], p=" + p2 + ", x=" + q
                            + ", probability(x)=" + qMass);
        }
    }
}

