package org.apache.commons.math3.distribution;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        // Lifted oracle from HypergeometricDistributionTest.testMath1021.
        final int fixedN = 43130568;
        final int fixedM = 42976365;
        final int fixedSampleSize = 50;
        HypergeometricDistribution fixedDist;
        int[] fixedSamples = new int[100];
        try {
            fixedDist = new HypergeometricDistribution(fixedN, fixedM, fixedSampleSize);
            for (int i = 0; i < fixedSamples.length; i++) {
                fixedSamples[i] = fixedDist.sample();
            }
        } catch (Throwable ignored) {
            return;
        }
        for (int i = 0; i < fixedSamples.length; i++) {
            final int sample = fixedSamples[i];
            if (sample < 0) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:lifted-math1021-nonnegative] semantic mismatch: sample=" + sample + " at draw=" + i);
            }
            if (sample > fixedSampleSize) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:lifted-math1021-upper] semantic mismatch: sample=" + sample + ", n=" + fixedSampleSize + " at draw=" + i);
            }
        }

        final int N = data.consumeInt(2, 1_000_000);
        final int m = data.consumeInt(0, N);
        final int n = data.consumeInt(0, N);

        HypergeometricDistribution dist;
        int lower;
        int upper;
        double reportedMean;
        double reportedVariance;
        int sample;
        try {
            dist = new HypergeometricDistribution(N, m, n);
            lower = dist.getSupportLowerBound();
            upper = dist.getSupportUpperBound();
            reportedMean = dist.getNumericalMean();
            reportedVariance = dist.getNumericalVariance();
            sample = dist.sample();
        } catch (Throwable ignored) {
            return;
        }

        // sample() must return a value in the distribution's own support.
        if (sample < lower || sample > upper) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:sample-vs-stated-support] consistency violation: sample=" + sample
                            + ", support=[" + lower + "," + upper + "]"
                            + ", N=" + N + ", m=" + m + ", n=" + n);
        }

        // Hypergeometric mean formula: n * m / N.
        final double expectedMean = ((double) n * (double) m) / (double) N;
        if (!nearlyEqual(reportedMean, expectedMean, 1e-12, 1e-12)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:mean-formula] consistency violation: reportedMean=" + reportedMean
                            + ", expectedMean=" + expectedMean
                            + ", N=" + N + ", m=" + m + ", n=" + n);
        }

        // Hypergeometric variance formula:
        // n * m * (N - n) * (N - m) / (N * N * (N - 1)).
        final double expectedVariance =
                ((double) n * (double) m * (double) (N - n) * (double) (N - m))
                        / ((double) N * (double) N * (double) (N - 1));
        if (!nearlyEqual(reportedVariance, expectedVariance, 1e-12, 1e-12)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:variance-formula] consistency violation: reportedVariance=" + reportedVariance
                            + ", expectedVariance=" + expectedVariance
                            + ", N=" + N + ", m=" + m + ", n=" + n);
        }

        // A distribution's mean must lie within its stated support bounds.
        if (reportedMean < lower || reportedMean > upper) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:mean-within-stated-support-bounds] consistency violation: mean=" + reportedMean
                            + ", support=[" + lower + "," + upper + "]"
                            + ", N=" + N + ", m=" + m + ", n=" + n);
        }
    }

    private static boolean nearlyEqual(double a, double b, double absTol, double relTol) {
        double diff = Math.abs(a - b);
        if (diff <= absTol) {
            return true;
        }
        double scale = Math.max(Math.abs(a), Math.abs(b));
        return diff <= relTol * scale;
    }
}

