package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        synchronized (FuzzHarness.class) {
            Locale realDefaultLocale = Locale.getDefault();
            TimeZone realDefaultTimeZone = TimeZone.getDefault();
            try {
                Locale.setDefault(Locale.US);
                TimeZone.setDefault(TimeZone.getTimeZone("UTC"));

                FastDateFormat format1 = FastDateFormat.getDateInstance(FastDateFormat.FULL, Locale.GERMANY);
                FastDateFormat format2 = FastDateFormat.getDateInstance(FastDateFormat.FULL);
                Locale.setDefault(Locale.GERMANY);
                FastDateFormat format3 = FastDateFormat.getDateInstance(FastDateFormat.FULL);

                if (format1.getLocale() != Locale.GERMANY) {
                    throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-locale] semantic mismatch: expected same locale de_DE but was " + format1.getLocale());
                }
                if (format2.getLocale() != Locale.US) {
                    throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-locale] semantic mismatch: expected same locale en_US but was " + format2.getLocale());
                }
                if (format3.getLocale() != Locale.GERMANY) {
                    throw new FuzzerSecurityIssueLow("[oracle:lifted-format3-locale] semantic mismatch: expected same locale de_DE but was " + format3.getLocale());
                }
                if (format1 == format2) {
                    throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct formatter instances for explicit Germany vs default US");
                }
                if (format2 == format3) {
                    throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct formatter instances across changed default locales");
                }

                /* Contract: getDateInstance(style) returns a localized standard date formatter.
                 * The real implementation derives its pattern from DateFormat.getDateInstance(style, locale),
                 * so a silent wrong-value fix that merely avoids the known symptom still violates this
                 * independently recomputable post-condition. */
                String expectedUsPattern = ((SimpleDateFormat) DateFormat.getDateInstance(FastDateFormat.FULL, Locale.US)).toPattern();
                String actualUsPattern = format2.getPattern();
                if (!expectedUsPattern.equals(actualUsPattern)) {
                    throw new FuzzerSecurityIssueLow("[oracle:date-default-pattern-us] consistency violation: expected pattern=" + expectedUsPattern + " actual=" + actualUsPattern + " locale=" + format2.getLocale());
                }

                String expectedDePattern = ((SimpleDateFormat) DateFormat.getDateInstance(FastDateFormat.FULL, Locale.GERMANY)).toPattern();
                String actualDePattern = format3.getPattern();
                if (!expectedDePattern.equals(actualDePattern)) {
                    throw new FuzzerSecurityIssueLow("[oracle:date-default-pattern-de] consistency violation: expected pattern=" + expectedDePattern + " actual=" + actualDePattern + " locale=" + format3.getLocale());
                }

                int dayOffset = data.consumeInt(-1000, 1000);
                Date sampleDate = new Date(((long) dayOffset) * 24L * 60L * 60L * 1000L);
                String expectedUsRendered = ((SimpleDateFormat) DateFormat.getDateInstance(FastDateFormat.FULL, Locale.US)).format(sampleDate).replaceAll("\\s+", "");
                String actualUsRendered = format2.format(sampleDate).replaceAll("\\s+", "");
                if (!expectedUsRendered.equals(actualUsRendered)) {
                    throw new FuzzerSecurityIssueLow("[oracle:date-render-us] semantic mismatch: expected=" + expectedUsRendered + " actual=" + actualUsRendered);
                }
                String expectedDeRendered = ((SimpleDateFormat) DateFormat.getDateInstance(FastDateFormat.FULL, Locale.GERMANY)).format(sampleDate).replaceAll("\\s+", "");
                String actualDeRendered = format3.format(sampleDate).replaceAll("\\s+", "");
                if (!expectedDeRendered.equals(actualDeRendered)) {
                    throw new FuzzerSecurityIssueLow("[oracle:date-render-de] semantic mismatch: expected=" + expectedDeRendered + " actual=" + actualDeRendered);
                }

                Locale[] locales = new Locale[] {Locale.US, Locale.GERMANY, Locale.JAPAN, Locale.FRANCE};
                Locale explicitLocale = locales[data.consumeInt(0, locales.length - 1)];
                int dateStyle = data.consumeInt(0, 3);
                int timeStyle = data.consumeInt(0, 3);

                Locale.setDefault(Locale.US);
                FastDateFormat dt1;
                FastDateFormat dt2;
                try {
                    dt1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, (TimeZone) null, explicitLocale);
                    Locale.setDefault(Locale.GERMANY);
                    dt2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, (TimeZone) null, explicitLocale);
                } catch (RuntimeException e) {
                    return;
                }

                /* Contract: getDateTimeInstance(style, style, tz, locale) with explicit locale overrides the system
                 * locale. Flipping the patched locale/null condition or dropping bookkeeping can still return a
                 * formatter, but not the locale/pattern that DateFormat defines for that explicit locale. */
                if (dt1.getLocale() != explicitLocale) {
                    throw new FuzzerSecurityIssueLow("[oracle:datetime-explicit-locale-1] semantic mismatch: expected same locale " + explicitLocale + " but was " + dt1.getLocale());
                }
                if (dt2.getLocale() != explicitLocale) {
                    throw new FuzzerSecurityIssueLow("[oracle:datetime-explicit-locale-2] semantic mismatch: expected same locale " + explicitLocale + " but was " + dt2.getLocale());
                }

                String expectedDateTimePattern;
                try {
                    expectedDateTimePattern = ((SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle, explicitLocale)).toPattern();
                } catch (RuntimeException e) {
                    return;
                }
                if (!expectedDateTimePattern.equals(dt1.getPattern())) {
                    throw new FuzzerSecurityIssueLow("[oracle:datetime-explicit-pattern-1] consistency violation: expected pattern=" + expectedDateTimePattern + " actual=" + dt1.getPattern() + " locale=" + dt1.getLocale());
                }
                if (!expectedDateTimePattern.equals(dt2.getPattern())) {
                    throw new FuzzerSecurityIssueLow("[oracle:datetime-explicit-pattern-2] consistency violation: expected pattern=" + expectedDateTimePattern + " actual=" + dt2.getPattern() + " locale=" + dt2.getLocale());
                }

                String dtRendered1 = dt1.format(sampleDate).replaceAll("\\s+", "");
                String dtRendered2 = dt2.format(sampleDate).replaceAll("\\s+", "");
                if (!dtRendered1.equals(dtRendered2)) {
                    throw new FuzzerSecurityIssueLow("[oracle:datetime-explicit-default-independence] metamorphic violation: explicit locale result changed across default-locale flip input=" + sampleDate.getTime() + " lhs=" + dtRendered1 + " rhs=" + dtRendered2);
                }

                FastDateFormat direct = FastDateFormat.getInstance(expectedDateTimePattern, explicitLocale);
                String directRendered = direct.format(sampleDate).replaceAll("\\s+", "");
                if (!dtRendered1.equals(directRendered)) {
                    throw new FuzzerSecurityIssueLow("[oracle:datetime-vs-getinstance] metamorphic violation: getDateTimeInstance disagrees with getInstance on identical locale-derived pattern input=" + sampleDate.getTime() + " lhs=" + dtRendered1 + " rhs=" + directRendered);
                }
            } finally {
                Locale.setDefault(realDefaultLocale);
                TimeZone.setDefault(realDefaultTimeZone);
            }
        }
    }
}

