package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        Locale realDefaultLocale = Locale.getDefault();
        TimeZone realDefaultTimeZone = TimeZone.getDefault();
        try {
            Locale.setDefault(Locale.US);

            FastDateFormat format1 = FastDateFormat.getDateInstance(FastDateFormat.FULL, Locale.GERMANY);
            FastDateFormat format2 = FastDateFormat.getDateInstance(FastDateFormat.FULL);
            Locale.setDefault(Locale.GERMANY);
            FastDateFormat format3 = FastDateFormat.getDateInstance(FastDateFormat.FULL);

            if (format1.getLocale() != Locale.GERMANY) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-locale] semantic mismatch: expected same locale de_DE but was " + format1.getLocale());
            }
            if (format2.getLocale() != Locale.US) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-locale] semantic mismatch: expected same locale en_US but was " + format2.getLocale());
            }
            if (format3.getLocale() != Locale.GERMANY) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format3-locale] semantic mismatch: expected same locale de_DE but was " + format3.getLocale());
            }
            if (format1 == format2) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct formatter instances for explicit Germany vs default US");
            }
            if (format2 == format3) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct formatter instances across changed default locales");
            }

            try {
                int[] styles = new int[] {
                    FastDateFormat.FULL,
                    FastDateFormat.LONG,
                    FastDateFormat.MEDIUM,
                    FastDateFormat.SHORT
                };
                Locale[] locales = new Locale[] {
                    Locale.FRANCE,
                    Locale.ITALY,
                    Locale.JAPAN,
                    Locale.CANADA_FRENCH
                };
                int style = styles[data.consumeInt(0, styles.length - 1)];
                Locale chosenLocale = locales[data.consumeInt(0, locales.length - 1)];
                long millis = data.consumeInt(-1_000_000, 1_000_000) * 1000L;
                Date fixedDate = new Date(millis);

                Locale.setDefault(chosenLocale);

                FastDateFormat apiFormatter = FastDateFormat.getDateInstance(style);
                String apiOut = apiFormatter.format(fixedDate).replaceAll("\\s+", "");
                String jdkOut = DateFormat.getDateInstance(style, chosenLocale).format(fixedDate).replaceAll("\\s+", "");

                if (!apiOut.equals(jdkOut)) {
                    throw new FuzzerSecurityIssueLow("[oracle:default-style-jdk-render] semantic mismatch: getDateInstance(style) must behave as a localized standard date formatter for the current default locale; locale=" + chosenLocale + " style=" + style + " millis=" + millis + " actual=" + apiOut + " expected=" + jdkOut);
                }

                String expectedPattern = ((SimpleDateFormat) DateFormat.getDateInstance(style, chosenLocale)).toPattern();
                String actualPattern = apiFormatter.getPattern();
                if (!expectedPattern.equals(actualPattern)) {
                    throw new FuzzerSecurityIssueLow("[oracle:default-style-jdk-pattern] semantic mismatch: getDateInstance(style) must use the JDK localized date pattern for the current default locale; locale=" + chosenLocale + " style=" + style + " actualPattern=" + actualPattern + " expectedPattern=" + expectedPattern);
                }
            } catch (RuntimeException e) {
                throw e;
            } catch (Throwable t) {
                return;
            }

            try {
                int[] styles = new int[] {
                    FastDateFormat.FULL,
                    FastDateFormat.LONG,
                    FastDateFormat.MEDIUM,
                    FastDateFormat.SHORT
                };
                Locale[] locales = new Locale[] {
                    Locale.US,
                    Locale.GERMANY,
                    Locale.FRANCE,
                    Locale.JAPAN
                };
                TimeZone[] zones = new TimeZone[] {
                    TimeZone.getTimeZone("UTC"),
                    TimeZone.getTimeZone("GMT+01:00"),
                    TimeZone.getTimeZone("America/New_York"),
                    TimeZone.getTimeZone("Asia/Tokyo")
                };

                int dateStyle = styles[data.consumeInt(0, styles.length - 1)];
                int timeStyle = styles[data.consumeInt(0, styles.length - 1)];
                Locale explicitLocale = locales[data.consumeInt(0, locales.length - 1)];
                TimeZone explicitZone = zones[data.consumeInt(0, zones.length - 1)];
                long millis = data.consumeInt(-1_000_000, 1_000_000) * 1000L;
                Date fixedDateTime = new Date(millis);

                Locale.setDefault(Locale.ITALY);
                TimeZone.setDefault(TimeZone.getTimeZone("UTC"));

                FastDateFormat dt = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, explicitZone, explicitLocale);

                if (dt.getLocale() != explicitLocale) {
                    throw new FuzzerSecurityIssueLow("[oracle:datetime-explicit-locale-getter] semantic mismatch: explicit locale must be retained by formatter; expected=" + explicitLocale + " actual=" + dt.getLocale());
                }

                SimpleDateFormat jdk = (SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle, explicitLocale);
                jdk.setTimeZone(explicitZone);

                String apiOut = dt.format(fixedDateTime).replaceAll("\\s+", "");
                String jdkOut = jdk.format(fixedDateTime).replaceAll("\\s+", "");
                if (!apiOut.equals(jdkOut)) {
                    throw new FuzzerSecurityIssueLow("[oracle:datetime-explicit-jdk-render] semantic mismatch: explicit locale/timezone date-time formatter must match JDK rendering; locale=" + explicitLocale + " zone=" + explicitZone.getID() + " dateStyle=" + dateStyle + " timeStyle=" + timeStyle + " millis=" + millis + " actual=" + apiOut + " expected=" + jdkOut);
                }
            } catch (RuntimeException e) {
                throw e;
            } catch (Throwable t) {
                return;
            }
        } finally {
            Locale.setDefault(realDefaultLocale);
            TimeZone.setDefault(realDefaultTimeZone);
        }
    }
}

