package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static String nonEmptyToken(String s, String fallback) {
        if (s == null) {
            return fallback;
        }
        s = s.replace("|", "").replaceAll("\\s+", "");
        if (s.length() == 0) {
            return fallback;
        }
        return s;
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        StrBuilder seed = new StrBuilder("onetwothree");
        seed.deleteFirst("three");
        boolean seedContains = seed.contains('h');
        if (seedContains != false) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-lang295-contains] semantic mismatch: after deleteFirst(\"three\") on \"onetwothree\", contains('h') expected false but was "
                    + seedContains);
        }
        int seedIndex = seed.indexOf('h');
        if (seedIndex != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-lang295-indexof] semantic mismatch: after deleteFirst(\"three\") on \"onetwothree\", indexOf('h') expected -1 but was "
                    + seedIndex);
        }

        char probe;
        String rawPrefix;
        String prefix;
        String suffix;
        StrBuilder sb;
        boolean actualContains;
        int actualIndex;
        boolean actualContainsString;
        int actualLastIndex;
        try {
            probe = (char) data.consumeInt(33, 126);
            rawPrefix = data.consumeAsciiString(24);
            StringBuilder filtered = new StringBuilder();
            for (int i = 0; i < rawPrefix.length(); i++) {
                char c = rawPrefix.charAt(i);
                if (c != probe) {
                    filtered.append(c);
                }
            }
            prefix = filtered.toString();
            suffix = "X" + probe + "Y";
            sb = new StrBuilder(prefix + suffix);
            sb.deleteFirst(suffix);
            actualContains = sb.contains(probe);
            actualIndex = sb.indexOf(probe);
            actualContainsString = sb.contains(String.valueOf(probe));
            actualLastIndex = sb.lastIndexOf(probe);
        } catch (Exception e) {
            return;
        }

        // StrBuilder deleteFirst(String) changes the current content; contains/indexOf/lastIndexOf are read-only queries
        // over that current builder content only. We constructed prefix to exclude probe and removed the only probe-bearing
        // suffix, so every correct implementation must report the probe absent afterwards.
        if (actualContains) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:constructed-removed-suffix-contains] semantic mismatch: probe survived deleted suffix; probe="
                    + (int) probe + " prefix=\"" + prefix + "\" suffix=\"" + suffix + "\"");
        }
        if (actualIndex != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:constructed-removed-suffix-indexof] semantic mismatch: expected indexOf(probe) == -1 but was "
                    + actualIndex + " probe=" + (int) probe + " prefix=\"" + prefix + "\" suffix=\"" + suffix + "\"");
        }
        // Sibling-agreement check outside the already-covered contains/indexOf family: contains(char) and contains(String)
        // answer the same question for a one-character logical input, so after constructing a builder known not to contain
        // probe, both overloads must report false.
        if (actualContainsString) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:char-string-overload-agree] semantic mismatch: contains(String.valueOf(probe)) expected false but was true; probe="
                    + (int) probe + " prefix=\"" + prefix + "\" suffix=\"" + suffix + "\"");
        }
        if (actualLastIndex != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lastindex-removed-suffix] semantic mismatch: expected lastIndexOf(probe) == -1 but was "
                    + actualLastIndex + " probe=" + (int) probe + " prefix=\"" + prefix + "\" suffix=\"" + suffix + "\"");
        }

        String t1 = nonEmptyToken(data.consumeAsciiString(8), "aa");
        String t2 = nonEmptyToken(data.consumeAsciiString(8), "bb");
        String t3 = nonEmptyToken(data.consumeAsciiString(8), "cc");
        char removedProbe = (char) data.consumeInt(33, 126);
        String base = t1 + "|" + t2 + "|" + t3;
        String removable = "|Z" + removedProbe + "Z";
        StrBuilder tokenBuilder;
        String[] expectedTokens;
        boolean containsAfterDelete;
        boolean containsStringAfterDelete;
        int tokenCount;
        String[] iterated;
        try {
            tokenBuilder = new StrBuilder(base + removable);
            tokenBuilder.ensureCapacity(tokenBuilder.length() + data.consumeInt(0, 32));
            tokenBuilder.deleteFirst(removable);

            // contains(char) is documented as a question ("whether the builder contains the character"), so a correct
            // implementation must not change the logical content observed afterwards; we re-read content through
            // asTokenizer() and its iterator methods hasNext/next to catch a patch that "fixes" the symptom by mutating state.
            containsAfterDelete = tokenBuilder.contains(removedProbe);
            containsStringAfterDelete = tokenBuilder.contains(String.valueOf(removedProbe));

            StrTokenizer expectedTokenizer = new StrTokenizer(tokenBuilder.toString());
            expectedTokenizer.setDelimiterChar('|');
