import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        // Lifted oracle from TimePeriodValuesTests.testGetMaxMiddleIndex().
        TimePeriodValues s = new TimePeriodValues("Test");
        int actual;

        actual = s.getMaxMiddleIndex();
        if (actual != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-empty] semantic mismatch: expected -1 but was " + actual
            );
        }

        s.add(new SimpleTimePeriod(100L, 200L), 1.0);
        actual = s.getMaxMiddleIndex();
        if (actual != 0) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-after-1] semantic mismatch: expected 0 but was " + actual
            );
        }

        s.add(new SimpleTimePeriod(300L, 400L), 2.0);
        actual = s.getMaxMiddleIndex();
        if (actual != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-after-2] semantic mismatch: expected 1 but was " + actual
            );
        }

        s.add(new SimpleTimePeriod(0L, 50L), 3.0);
        actual = s.getMaxMiddleIndex();
        if (actual != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-after-3] semantic mismatch: expected 1 but was " + actual
            );
        }

        s.add(new SimpleTimePeriod(150L, 200L), 4.0);

        // Hidden-state/read-only check: getMaxMiddleIndex() is a getter and the get*/hashCode family are readers;
        // calling a reader must not mutate observable series state. A "fix" that skips/rewrites bookkeeping in a
        // way that mutates state during the read would violate this post-condition even if no exception occurs.
        int beforeItemCount = s.getItemCount();
        int beforeMaxEnd = s.getMaxEndIndex();
        int beforeMaxMiddle = s.getMaxMiddleIndex();
        int beforeMaxStart = s.getMaxStartIndex();
        int beforeMinEnd = s.getMinEndIndex();
        int beforeMinMiddle = s.getMinMiddleIndex();
        int beforeMinStart = s.getMinStartIndex();
        String beforeDomain = s.getDomainDescription();
        String beforeRange = s.getRangeDescription();
        int beforeHash = s.hashCode();

        actual = s.getMaxMiddleIndex();
        if (actual != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-after-4] semantic mismatch: expected 1 but was " + actual
            );
        }

        int afterItemCount = s.getItemCount();
        int afterMaxEnd = s.getMaxEndIndex();
        int afterMaxMiddle = s.getMaxMiddleIndex();
        int afterMaxStart = s.getMaxStartIndex();
        int afterMinEnd = s.getMinEndIndex();
        int afterMinMiddle = s.getMinMiddleIndex();
        int afterMinStart = s.getMinStartIndex();
        String afterDomain = s.getDomainDescription();
        String afterRange = s.getRangeDescription();
        int afterHash = s.hashCode();

        if (beforeItemCount != afterItemCount
                || beforeMaxEnd != afterMaxEnd
                || beforeMaxMiddle != afterMaxMiddle
                || beforeMaxStart != afterMaxStart
                || beforeMinEnd != afterMinEnd
                || beforeMinMiddle != afterMinMiddle
                || beforeMinStart != afterMinStart
                || ((beforeDomain == null) ? (afterDomain != null) : !beforeDomain.equals(afterDomain))
                || ((beforeRange == null) ? (afterRange != null) : !beforeRange.equals(afterRange))
                || beforeHash != afterHash) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:getter-readonly] semantic mismatch: getMaxMiddleIndex changed observable state"
            );
        }

        // Strong invariant from the documented meaning of getMaxMiddleIndex():
        // it returns the index of the time period with the maximum middle milliseconds.
        // On the exact failing setup, middles are 150, 350, 25, 175, so the correct index is unambiguously 1.
        TimePeriodValues exact;
        int exactActual;
        int exactExpected;
        try {
            String name = data.consumeAsciiString(8);
            if (name == null || name.length() == 0) {
                name = "Test";
            }
            exact = new TimePeriodValues(name);
            exact.add(new SimpleTimePeriod(100L, 200L), 1.0);
            exact.add(new SimpleTimePeriod(300L, 400L), 2.0);
            exact.add(new SimpleTimePeriod(0L, 50L), 3.0);
            exact.add(new SimpleTimePeriod(150L, 200L), 4.0);
            exactActual = exact.getMaxMiddleIndex();
            long[] mids = new long[] {150L, 350L, 25L, 175L};
            exactExpected = 0;
            for (int i = 1; i < mids.length; i++) {
                if (mids[i] > mids[exactExpected]) {
                    exactExpected = i;
                }
            }
        } catch (Exception e) {
            return;
        }
        if (exactActual != exactExpected) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:manual-middle-order] relation maxMiddleIndex_matches_manual_middle_order_on_failing_setup violated: actual="
                    + exactActual + " expected=" + exactExpected
            );
        }

