        // for zero-length periods, start == end, so middle milliseconds == end milliseconds for every item.
        // Therefore the indices of the maxima must agree.
        int n = data.consumeInt(1, 5);
        int base = data.consumeInt(-100000, 100000);
        TimePeriodValues zeroLen;
        int zeroLenMiddle;
        int zeroLenEnd;
        try {
            zeroLen = new TimePeriodValues("S");
            for (int i = 0; i < n; i++) {
                long t = (long) base + i;
                zeroLen.add(new SimpleTimePeriod(t, t), (double) i);
            }
            zeroLenMiddle = zeroLen.getMaxMiddleIndex();
            zeroLenEnd = zeroLen.getMaxEndIndex();
        } catch (Exception e) {
