            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:zero-length-middle-end] relation zero_length_periods_maxMiddle_agrees_with_maxEnd violated: middle="
                    + zeroLenMiddle + " end=" + zeroLenEnd
            );
        }

