        try {
            long b = offset;
            constructed = new TimePeriodValues("C");
            constructed.add(new SimpleTimePeriod(b + 0L, b + 1000L), 1.0);   // middle 500, end 1000
            constructed.add(new SimpleTimePeriod(b + 900L, b + 901L), 2.0);  // middle 900, end 901
            constructed.add(new SimpleTimePeriod(b + 100L, b + 101L), 3.0);  // middle 100, end 101
            constructedMiddle = constructed.getMaxMiddleIndex();
            constructedEnd = constructed.getMaxEndIndex();
        } catch (Exception e) {
            return;
        }
        if (constructedMiddle != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:constructed-middle] semantic mismatch: expected middle-max index 1 but was "
                    + constructedMiddle
            );
        }
        if (constructedEnd != 0) {
