                long start = (long) startBase + (i * 10L);
                long end = start + 5L + i;
                double value = i + 0.25;
                SimpleTimePeriod p = new SimpleTimePeriod(start, end);
                viaDouble.add(p, value);
                viaNumber.add(p, new Double(value));
            }
        } catch (Exception e) {
            return;
        }
        if (viaDouble.getItemCount() != viaNumber.getItemCount()
                || viaDouble.getMaxEndIndex() != viaNumber.getMaxEndIndex()
                || viaDouble.getMaxMiddleIndex() != viaNumber.getMaxMiddleIndex()
                || viaDouble.getMaxStartIndex() != viaNumber.getMaxStartIndex()
                || viaDouble.getMinEndIndex() != viaNumber.getMinEndIndex()
                || viaDouble.getMinMiddleIndex() != viaNumber.getMinMiddleIndex()
                || viaDouble.getMinStartIndex() != viaNumber.getMinStartIndex()
                || !viaDouble.getDomainDescription().equals(viaNumber.getDomainDescription())
                || !viaDouble.getRangeDescription().equals(viaNumber.getRangeDescription())
                || viaDouble.hashCode() != viaNumber.hashCode()) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:add-overloads-agree] metamorphic violation: equivalent add overloads produced different observable state"
