package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import java.util.Arrays;
import java.util.List;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String liftedOut;
        try {
            liftedOut = compileIndependentProvides("apps", true);
        } catch (Throwable t) {
            return;
        }

        String expectedLifted =
                normalize("var apps={};apps.foo={};apps.foo.bar={};apps.foo.bar.B={};apps.foo.bar.C={}");
        String actualLifted = normalize(liftedOut);
        if (!expectedLifted.equals(actualLifted)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-testProvideInIndependentModules4] semantic mismatch: expected="
                            + expectedLifted + " actual=" + actualLifted);
        }

        String root = data.consumeBoolean() ? "apps" : "pkg";

        String relationOut;
        try {
            relationOut = compileIndependentProvides(root, true);
        } catch (Throwable t) {
            return;
        }

        int iRoot = relationOut.indexOf("var " + root + "={}");
        int iFoo = relationOut.indexOf(root + ".foo={}");
        int iBar = relationOut.indexOf(root + ".foo.bar={}");
        int iB = relationOut.indexOf(root + ".foo.bar.B={}");
        int iC = relationOut.indexOf(root + ".foo.bar.C={}");
        boolean ordered =
                iRoot >= 0 && iFoo >= 0 && iBar >= 0 && iB >= 0 && iC >= 0
                        && iRoot < iFoo && iFoo < iBar && iBar < iB && iBar < iC;
        // Contract justification: synthesized parent namespaces must precede children that depend on them;
        // a throw-deleting/branch-skipping patch can still compile but emit prefixes in the wrong order.
        if (!ordered) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:prefix-order] semantic mismatch: root="
                            + root + " output=" + relationOut);
        }

        String out1;
        String out2;
        try {
            out1 = compileIndependentProvides(root, true);
            out2 = compileIndependentProvides(root, false);
        } catch (Throwable t) {
            return;
        }

        String prefixSubsequence = normalize("var " + root + "={};" + root + ".foo={};" + root + ".foo.bar={};");
        String n1 = normalize(out1);
        String n2 = normalize(out2);
        // Contract justification: swapping independent child modules may change sibling child assignment order,
        // but must not change the synthesized parent-prefix subsequence root -> root.foo -> root.foo.bar.
        if (!n1.contains(prefixSubsequence) || !n2.contains(prefixSubsequence)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:swap-preserves-prefix-subsequence] semantic mismatch: out1="
                            + n1 + " out2=" + n2 + " required=" + prefixSubsequence);
        }

        String det1;
        String det2;
        try {
            det1 = normalize(compileIndependentProvides(root, true));
            det2 = normalize(compileIndependentProvides(root, true));
        } catch (Throwable t) {
            return;
        }
        // Consistency cross-check: two fresh, identically-constructed compilers compiling the same modules
        // must produce the same source; this independently recomputes the observable and catches masked state bugs.
        if (!det1.equals(det2)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:deterministic-recompile] consistency violation: first="
                            + det1 + " second=" + det2);
        }
    }

    private static String compileIndependentProvides(String root, boolean bThenC) {
        com.google.javascript.jscomp.Compiler compiler = new com.google.javascript.jscomp.Compiler();
        com.google.javascript.jscomp.CompilerOptions options = new com.google.javascript.jscomp.CompilerOptions();
        options.closurePass = true;

        List<com.google.javascript.jscomp.JSSourceFile> externs =
                Arrays.asList(com.google.javascript.jscomp.JSSourceFile.fromCode("externs", ""));

        JSModule m0 = new JSModule("m0");
        JSModule m1 = new JSModule("m1");
        JSModule m2 = new JSModule("m2");
        m1.addDependency(m0);
        m2.addDependency(m0);

        String m0src = "goog.provide('" + root + "');";
        String bsrc = "goog.provide('" + root + ".foo.bar.B');";
        String csrc = "goog.provide('" + root + ".foo.bar.C');";

        m0.add(com.google.javascript.jscomp.JSSourceFile.fromCode("m0", m0src));
        if (bThenC) {
            m1.add(com.google.javascript.jscomp.JSSourceFile.fromCode("m1", bsrc));
            m2.add(com.google.javascript.jscomp.JSSourceFile.fromCode("m2", csrc));
        } else {
            m1.add(com.google.javascript.jscomp.JSSourceFile.fromCode("m1", csrc));
            m2.add(com.google.javascript.jscomp.JSSourceFile.fromCode("m2", bsrc));
        }

        compiler.compileModules(externs, Arrays.asList(m0, m1, m2), options);
        return compiler.toSource();
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }
}

