package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        String liftedOut;
        try {
            Compiler liftedCompiler = compileIndependentProvideCase("apps", true);
            liftedOut = normalizeJs(liftedCompiler.toSource());
        } catch (Throwable t) {
            return;
        }
        String liftedExpected =
            normalizeJs("var apps={};apps.foo={};apps.foo.bar={};apps.foo.bar.B={};apps.foo.bar.C={}");
        if (!liftedExpected.equals(liftedOut)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-testProvideInIndependentModules4] semantic mismatch: expected="
                    + liftedExpected + " actual=" + liftedOut);
        }

        String root = data.consumeBoolean() ? "apps" : "pkg";
        Compiler compiler;
        Node module0Script;
        try {
            compiler = compileIndependentProvideCase(root, data.consumeBoolean());
            module0Script = firstJsScript(compiler.getRoot());
            if (module0Script == null) {
                return;
            }
        } catch (Throwable t) {
            return;
        }

        String first = statementQualifiedName(module0Script.getFirstChild());
        String second = statementQualifiedName(module0Script.getFirstChild() != null
            ? module0Script.getFirstChild().getNext() : null);
        String third = statementQualifiedName(module0Script.getFirstChild() != null
            && module0Script.getFirstChild().getNext() != null
            ? module0Script.getFirstChild().getNext().getNext() : null);

        String expectedFirst = root;
        String expectedSecond = root + ".foo";
        String expectedThird = root + ".foo.bar";

        /* Contract justification:
         * In ProvidedName.replace(), when a missing namespace has a parent namespace,
         * the code path says "Add it after the parent namespace" and calls addChildAfter
         * relative to parentName.replacementNode. In this exact three-module shape the
         * synthesized prefixes are only root.foo and root.foo.bar, so in the common module
         * the first three statements must be root, then root.foo immediately after it,
         * then root.foo.bar immediately after its parent. A band-aid that merely avoids
         * the visible string symptom by suppressing an exception or skipping bookkeeping
         * would still violate this AST sibling order.
         */
        if (!expectedFirst.equals(first)
            || !expectedSecond.equals(second)
            || !expectedThird.equals(third)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:ast-parent-child-adjacency] semantic mismatch: first="
                    + first + " second=" + second + " third=" + third
                    + " expectedFirst=" + expectedFirst
                    + " expectedSecond=" + expectedSecond
                    + " expectedThird=" + expectedThird
                    + " source=" + normalizeJs(compiler.toSource()));
        }

        int prefixCount = countModule0Prefixes(module0Script, root);
        /* Independent consistency check:
         * For root provide plus two independent child provides root.foo.bar.B/C, the only
         * missing prefixes that ProcessClosurePrimitives must synthesize in module 0 are
         * root.foo and root.foo.bar. Counting those initializations directly from the AST
         * must therefore yield exactly 2. This is a second observable of the same
         * replacement state, independent from the full-source oracle.
         */
        if (prefixCount != 2) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:prefix-count-module0] consistency violation: expected=2 actual="
                    + prefixCount + " source=" + normalizeJs(compiler.toSource()));
        }
    }

    private static Compiler compileIndependentProvideCase(String root, boolean bFirst) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        options.closurePass = true;

        java.util.List<JSSourceFile> externs =
            java.util.Arrays.asList(JSSourceFile.fromCode("externs", ""));

        JSModule m0 = new JSModule("m0");
        JSModule m1 = new JSModule("m1");
        JSModule m2 = new JSModule("m2");
        m1.addDependency(m0);
        m2.addDependency(m0);

        String m0src = "goog.provide('" + root + "');";
        String bsrc = "goog.provide('" + root + ".foo.bar.B');";
        String csrc = "goog.provide('" + root + ".foo.bar.C');";

        m0.add(JSSourceFile.fromCode("m0", m0src));
        if (bFirst) {
            m1.add(JSSourceFile.fromCode("m1", bsrc));
            m2.add(JSSourceFile.fromCode("m2", csrc));
        } else {
            m1.add(JSSourceFile.fromCode("m1", csrc));
            m2.add(JSSourceFile.fromCode("m2", bsrc));
        }

        compiler.compileModules(externs, java.util.Arrays.asList(m0, m1, m2), options);
        return compiler;
    }

    private static String normalizeJs(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static Node firstJsScript(Node root) {
        if (root == null) {
            return null;
        }
        Node jsRoot = root.getLastChild();
        if (jsRoot == null) {
            return null;
        }
        for (Node c = jsRoot.getFirstChild(); c != null; c = c.getNext()) {
            if (c.getType() == Token.SCRIPT) {
                return c;
            }
        }
        return null;
    }

    private static int countModule0Prefixes(Node script, String root) {
        int count = 0;
        for (Node stmt = script.getFirstChild(); stmt != null; stmt = stmt.getNext()) {
            String qn = statementQualifiedName(stmt);
            if ((root + ".foo").equals(qn) || (root + ".foo.bar").equals(qn)) {
                count++;
            }
        }
        return count;
    }

    private static String statementQualifiedName(Node stmt) {
        if (stmt == null) {
            return null;
        }
        if (stmt.getType() == Token.VAR) {
            Node name = stmt.getFirstChild();
            return name == null ? null : name.getString();
        }
        if (stmt.getType() == Token.EXPR_RESULT) {
            Node expr = stmt.getFirstChild();
            if (expr != null && expr.getType() == Token.ASSIGN) {
                return qualifiedName(expr.getFirstChild());
            }
        }
        return null;
    }

    private static String qualifiedName(Node n) {
        if (n == null) {
            return null;
        }
        if (n.getType() == Token.NAME || n.getType() == Token.STRING) {
            return n.getString();
        }
        if (n.getType() == Token.GETPROP) {
            Node left = n.getFirstChild();
            Node right = left != null ? left.getNext() : null;
            String l = qualifiedName(left);
            String r = qualifiedName(right);
            if (l == null || r == null || l.length() == 0 || r.length() == 0) {
                return null;
            }
            return l + "." + r;
        }
        return null;
    }
}

