package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Arrays;
import java.util.List;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String seedOut;
        try {
            seedOut = compileIndependentProvideFamily("apps", false);
        } catch (Throwable t) {
            return;
        }
        if (seedOut == null) {
            return;
        }
        String normSeedOut = normalize(seedOut);
        String expectedSeed =
                "var apps={};apps.foo={};apps.foo.bar={};apps.foo.bar.B={};apps.foo.bar.C={}";
        if (!normSeedOut.equals(normalize(expectedSeed))) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-seed-exact] semantic mismatch: expected="
                            + normalize(expectedSeed)
                            + " actual="
                            + normSeedOut);
        }

        String root;
        if (data.consumeBoolean()) {
            root = data.consumeBoolean() ? "apps" : "pkg";
        } else {
            int len = data.consumeInt(1, 60);
            root = repeat('a', len);
        }

        String out;
        try {
            out = compileIndependentProvideFamily(root, false);
        } catch (Throwable t) {
            return;
        }
        if (out == null) {
            return;
        }
        String normOut = normalize(out);

        int iRoot = normOut.indexOf("var" + root + "={}");
        int iFoo = normOut.indexOf(root + ".foo={}");
        int iBar = normOut.indexOf(root + ".foo.bar={}");
        int iB = normOut.indexOf(root + ".foo.bar.B={}");
        int iC = normOut.indexOf(root + ".foo.bar.C={}");
        boolean ordered =
                iRoot >= 0
                        && iFoo >= 0
                        && iBar >= 0
                        && iB >= 0
                        && iC >= 0
                        && iRoot < iFoo
                        && iFoo < iBar
                        && iBar < iB
                        && iBar < iC;
        if (!ordered) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:boundary-prefix-order] semantic mismatch: root="
                            + root
                            + " output="
                            + normOut);
        }

        // Contract from createDeclarationNode/expected transformed output:
        // the undotted root namespace is emitted as a VAR declaration, while dotted namespaces
        // are emitted as assignment expressions. A throw-deleting or overfit patch can preserve
        // some ordering while still synthesizing the wrong declaration kind, so we assert this
        // separately on the real transformed output.
        boolean declShapeOk =
                normOut.contains("var" + root + "={};")
                        && normOut.contains(root + ".foo={};")
                        && normOut.contains(root + ".foo.bar={};")
                        && !normOut.contains("var" + root + ".foo={}")
                        && !normOut.contains("var" + root + ".foo.bar={}")
                        && !normOut.contains("var" + root + ".foo.bar.B={}")
                        && !normOut.contains("var" + root + ".foo.bar.C={}");
        if (!declShapeOk) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:declaration-shape] semantic mismatch: root="
                            + root
                            + " output="
                            + normOut);
        }

        String swappedOut;
        try {
            swappedOut = compileIndependentProvideFamily(root, true);
        } catch (Throwable t) {
            return;
        }
        if (swappedOut == null) {
            return;
        }
        String normSwapped = normalize(swappedOut);

        // Metamorphic relation: swapping the two independent child modules may reorder sibling
        // assignments B/C, but must not change the declaration kind of the synthesized parent
        // prefixes produced from the same namespace family.
        boolean sameParentShapes =
                normOut.contains("var" + root + "={};")
                        && normOut.contains(root + ".foo={};")
                        && normOut.contains(root + ".foo.bar={};")
                        && normSwapped.contains("var" + root + "={};")
                        && normSwapped.contains(root + ".foo={};")
                        && normSwapped.contains(root + ".foo.bar={};");
        if (!sameParentShapes) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:swap-preserves-decl-kinds] metamorphic violation: root="
                            + root
                            + " lhs="
                            + normOut
                            + " rhs="
                            + normSwapped);
        }
    }

    private static String compileIndependentProvideFamily(String root, boolean swapChildren) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        options.closurePass = true;

        List<JSSourceFile> externs = Arrays.asList(JSSourceFile.fromCode("externs", ""));
        JSModule m0 = new JSModule("m0");
        JSModule m1 = new JSModule("m1");
        JSModule m2 = new JSModule("m2");
        m1.addDependency(m0);
        m2.addDependency(m0);

        String m0src = "goog.provide('" + root + "');";
        String bsrc = "goog.provide('" + root + ".foo.bar.B');";
        String csrc = "goog.provide('" + root + ".foo.bar.C');";

        m0.add(JSSourceFile.fromCode("m0", m0src));
        if (swapChildren) {
            m1.add(JSSourceFile.fromCode("m1", csrc));
            m2.add(JSSourceFile.fromCode("m2", bsrc));
        } else {
            m1.add(JSSourceFile.fromCode("m1", bsrc));
            m2.add(JSSourceFile.fromCode("m2", csrc));
        }

        compiler.compileModules(externs, Arrays.asList(m0, m1, m2), options);
        return compiler.toSource();
    }

    private static String normalize(String s) {
        return s == null ? null : s.replaceAll("\\s+", "");
    }

    private static String repeat(char c, int len) {
        StringBuilder sb = new StringBuilder(len);
        for (int i = 0; i < len; i++) {
            sb.append(c);
        }
        return sb.toString();
    }
}

