package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.util.ArrayList;
import java.util.List;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        Compiler lifted;
        try {
            lifted = compileModules(new String[] {
                    "goog.provide('apps');",
                    "goog.provide('apps.foo.bar.B');",
                    "goog.provide('apps.foo.bar.C');"
            });
        } catch (Throwable t) {
            return;
        }

        String liftedActual = normalizeCode(lifted.toSource());
        String liftedExpected =
                normalizeCode("var apps = {};apps.foo = {};apps.foo.bar = {};apps.foo.bar.B = {};apps.foo.bar.C = {}");
        if (!liftedExpected.equals(liftedActual)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-bug261] semantic mismatch: expected=" + liftedExpected + " actual=" + liftedActual);
        }

        try {
            Node firstScript = firstScript(lifted);
            if (firstScript != null) {
                Node appsFooStmt = findTopLevelNamespaceStatement(firstScript, "apps.foo");
                Node appsFooBarStmt = findTopLevelNamespaceStatement(firstScript, "apps.foo.bar");
                if (appsFooStmt != null && appsFooBarStmt != null) {
                    Node childBefore = firstScript.getChildBefore(appsFooBarStmt);
                    if (childBefore != appsFooStmt) {
                        throw new FuzzerSecurityIssueLow(
                                "[oracle:parent-after-child] consistency violation: apps.foo.bar not inserted immediately after apps.foo");
                    }
                }
            }
        } catch (RuntimeException e) {
            if (e instanceof FuzzerSecurityIssueLow) {
                throw e;
            }
            return;
        } catch (Throwable t) {
            return;
        }

        String ident = sanitizeIdentifier(data.consumeAsciiString(16));
        try {
            Compiler duplicate = compileModules(new String[] {
                    "goog.provide('" + ident + "'); /** @type {number} */ " + ident + " = 1;"
            });
            Node script = firstScript(duplicate);
            if (script == null) {
                return;
            }
            Node onlyStmt = script.getFirstChild();
            if (onlyStmt == null) {
                return;
            }

            if (onlyStmt.getType() != Token.VAR) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:dup-assign-to-var] semantic mismatch: expected VAR but saw token=" + onlyStmt.getType());
            }

            Node nameNode = onlyStmt.getFirstChild();
            if (nameNode == null || nameNode.getType() != Token.NAME || !ident.equals(nameNode.getString())) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:dup-assign-to-var] semantic mismatch: unexpected declaration shape for " + ident);
            }

            if (nameNode.getJSDocInfo() == null) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:jsdoc-preserved] semantic mismatch: JSDoc lost during assign->var conversion for " + ident);
            }

            if (onlyStmt.getNext() != null) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:explicit-detached] semantic mismatch: extra top-level statements remain after provide removal");
            }
        } catch (RuntimeException e) {
            if (e instanceof FuzzerSecurityIssueLow) {
                throw e;
            }
        } catch (Throwable t) {
        }
    }

    private static Compiler compileModules(String[] moduleSources) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        options.closurePass = true;

        List<JSSourceFile> externs = new ArrayList<JSSourceFile>();
        externs.add(JSSourceFile.fromCode("externs", ""));

        List<JSModule> modules = new ArrayList<JSModule>();
        for (int i = 0; i < moduleSources.length; i++) {
            JSModule module = new JSModule("m" + i);
            module.add(JSSourceFile.fromCode("m" + i + ".js", moduleSources[i]));
            modules.add(module);
        }

        compiler.compileModules(externs, modules, options);
        return compiler;
    }

    private static Node firstScript(Compiler compiler) {
        Node root = compiler.getRoot();
        if (root == null) {
            return null;
        }
        Node jsRoot = root.getLastChild();
        if (jsRoot == null) {
            return null;
        }
        return jsRoot.getFirstChild();
    }

    private static Node findTopLevelNamespaceStatement(Node script, String namespace) {
        for (Node stmt = script.getFirstChild(); stmt != null; stmt = stmt.getNext()) {
            if (declaresNamespace(stmt, namespace)) {
                return stmt;
            }
        }
        return null;
    }

    private static boolean declaresNamespace(Node stmt, String namespace) {
        if (stmt == null) {
            return false;
        }
        if (stmt.getType() == Token.VAR) {
            Node name = stmt.getFirstChild();
            return name != null && name.getType() == Token.NAME && namespace.equals(name.getString());
        }
        if (stmt.getType() == Token.EXPR_RESULT) {
            Node expr = stmt.getFirstChild();
            if (expr != null && expr.getType() == Token.ASSIGN) {
                Node lhs = expr.getFirstChild();
                return lhs != null && namespace.equals(lhs.getQualifiedName());
            }
        }
        return false;
    }

    private static String sanitizeIdentifier(String raw) {
        if (raw == null || raw.length() == 0) {
            return "ns";
        }
        StringBuilder sb = new StringBuilder();
        char first = raw.charAt(0);
        if (Character.isLetter(first) || first == '_' || first == '$') {
            sb.append(first);
        } else {
            sb.append('n');
        }
        for (int i = 1; i < raw.length(); i++) {
            char c = raw.charAt(i);
            if (Character.isLetterOrDigit(c) || c == '_' || c == '$') {
                sb.append(c);
            }
        }
        if (sb.length() == 0) {
            return "ns";
        }
        return sb.toString();
    }

    private static String normalizeCode(String s) {
        if (s == null) {
            return "";
        }
        return s.replaceAll("\\s+", "");
    }
}

