package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String seedOut;
        try {
            seedOut = compileIndependentProvideModules("apps",
                    "goog.provide('apps');",
                    "goog.provide('apps.foo.bar.B');",
                    "goog.provide('apps.foo.bar.C');");
        } catch (Throwable t) {
            return;
        }

        String expectedSeed = "var apps = {};apps.foo = {};apps.foo.bar = {};apps.foo.bar.B = {};apps.foo.bar.C = {}";
        if (!normalize(seedOut).equals(normalize(expectedSeed))) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-independent-modules4] semantic mismatch: expected="
                            + normalize(expectedSeed) + " actual=" + normalize(seedOut));
        }

        String depViolationSeed = findFirstMissingParentDependency(seedOut, "apps");
        if (depViolationSeed != null) {
            /*
             * Contract justification:
             * ProcessClosurePrimitives synthesizes missing namespace prefixes and, per the
             * code path in replace(), inserts a child namespace after its parent namespace.
             * Therefore, when the emitted statements are executed left-to-right, every
             * namespace assignment root.a.b = {} must have already initialized root.a.
             * A patch that merely masks top-level symptoms but keeps wrong insertion order
             * still violates this dependency check.
             */
            throw new FuzzerSecurityIssueLow(
                    "[oracle:parent-dependency-seed] consistency violation: " + depViolationSeed
                            + " output=" + normalize(seedOut));
        }

        String root = data.consumeBoolean() ? "apps" : "pkg";
        String bLeaf = data.consumeBoolean() ? "B" : "Bee";
        String cLeaf = data.consumeBoolean() ? "C" : "See";

        String fuzzOut;
        try {
            fuzzOut = compileIndependentProvideModules(
                    root,
                    "goog.provide('" + root + "');",
                    "goog.provide('" + root + ".foo.bar." + bLeaf + "');",
                    "goog.provide('" + root + ".foo.bar." + cLeaf + "');");
        } catch (Throwable t) {
            return;
        }

        String depViolationFuzz = findFirstMissingParentDependency(fuzzOut, root);
        if (depViolationFuzz != null) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:parent-dependency-fuzz] consistency violation: " + depViolationFuzz
                            + " output=" + normalize(fuzzOut));
        }

        String swappedOut;
        try {
            swappedOut = compileIndependentProvideModules(
                    root,
                    "goog.provide('" + root + "');",
                    "goog.provide('" + root + ".foo.bar." + cLeaf + "');",
                    "goog.provide('" + root + ".foo.bar." + bLeaf + "');");
        } catch (Throwable t) {
            return;
        }

        String depViolationSwapped = findFirstMissingParentDependency(swappedOut, root);
        if (depViolationSwapped != null) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:parent-dependency-swapped] consistency violation: " + depViolationSwapped
                            + " output=" + normalize(swappedOut));
        }
    }

    private static String compileIndependentProvideModules(
            String root, String module0Src, String module1Src, String module2Src) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        options.closurePass = true;

        JSModule m0 = new JSModule("m0");
        JSModule m1 = new JSModule("m1");
        JSModule m2 = new JSModule("m2");
        m1.addDependency(m0);
        m2.addDependency(m0);

        m0.add(JSSourceFile.fromCode("m0", module0Src));
        m1.add(JSSourceFile.fromCode("m1", module1Src));
        m2.add(JSSourceFile.fromCode("m2", module2Src));

        compiler.compileModules(
                Arrays.asList(JSSourceFile.fromCode("externs", "")),
                Arrays.asList(m0, m1, m2),
                options);
        return compiler.toSource();
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static String findFirstMissingParentDependency(String source, String root) {
        String normalized = normalize(source);
        String[] statements = normalized.split(";");
        Set<String> initialized = new HashSet<String>();

        for (String stmt : statements) {
            if (stmt.length() == 0) {
                continue;
            }

            String lhs = null;
            if (stmt.startsWith("var")) {
                int eq = stmt.indexOf("={}");
                if (eq > 3) {
                    lhs = stmt.substring(3, eq);
                }
            } else {
                int eq = stmt.indexOf("={}");
                if (eq > 0) {
                    lhs = stmt.substring(0, eq);
                }
            }

            if (lhs == null || lhs.length() == 0) {
                continue;
            }
            if (!lhs.equals(root) && !lhs.startsWith(root + ".")) {
                continue;
            }

            int lastDot = lhs.lastIndexOf('.');
            if (lastDot != -1) {
                String parent = lhs.substring(0, lastDot);
                if (!initialized.contains(parent)) {
                    return "statement=" + lhs + " missingParent=" + parent + " initialized=" + initialized;
                }
            }
            initialized.add(lhs);
        }

        return null;
    }
}

