package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Calendar;
import java.util.TimeZone;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String liftedActual;
        String liftedActualOverload;

        try {
            Calendar cal = Calendar.getInstance();
            cal.set(Calendar.MONTH, Calendar.DECEMBER);
            cal.set(Calendar.DAY_OF_MONTH, 31);
            cal.set(Calendar.YEAR, 2005);
            cal.set(Calendar.HOUR_OF_DAY, 0);
            cal.set(Calendar.MINUTE, 0);
            cal.set(Calendar.SECOND, 0);
            cal.set(Calendar.MILLISECOND, 0);

            Calendar cal2 = Calendar.getInstance();
            cal2.set(Calendar.MONTH, Calendar.OCTOBER);
            cal2.set(Calendar.DAY_OF_MONTH, 6);
            cal2.set(Calendar.YEAR, 2006);
            cal2.set(Calendar.HOUR_OF_DAY, 0);
            cal2.set(Calendar.MINUTE, 0);
            cal2.set(Calendar.SECOND, 0);
            cal2.set(Calendar.MILLISECOND, 0);

            long start = cal.getTime().getTime();
            long end = cal2.getTime().getTime();

            liftedActual = DurationFormatUtils.formatPeriod(start, end, "MM");

            // Documented sibling-agreement check: the 3-arg overload and the 5-arg overload
            // must agree when given the default timezone and default zero-padding behavior.
            // This is also a trusted extension of the lifted test: the exact same logical input
            // should still format to "09" through the real sibling overload.
            liftedActualOverload = DurationFormatUtils.formatPeriod(
                    start, end, "MM", true, TimeZone.getDefault());
        } catch (Exception e) {
            return;
        }

        if (!"09".equals(liftedActual)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-test] semantic mismatch: formatPeriod(2005-12-31, 2006-10-06, \"MM\") expected=09 actual="
                            + liftedActual);
        }

        if (!"09".equals(liftedActualOverload)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-overload] semantic mismatch: formatPeriod(2005-12-31, 2006-10-06, \"MM\", true, defaultTZ) expected=09 actual="
                            + liftedActualOverload);
        }

        if (!liftedActual.equals(liftedActualOverload)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-sibling-agreement] semantic mismatch: overloads disagree on lifted input lhs="
                            + liftedActual + " rhs=" + liftedActualOverload);
        }

        long start;
        long span;
        String fmt;
        String a;
        String b;
        try {
            int base = data.consumeInt(0, 1_000_000);
            int width = data.consumeInt(0, 1_000_000);
            start = (long) base * 1000L;
            span = (long) width * 1000L;

            String[] formats = new String[] {
                    "dHmsS", "ddHHmmssSSS", "HH:mm:ss.SSS", "mm:ss.SSS"
            };
            fmt = formats[data.consumeInt(0, formats.length - 1)];

            a = DurationFormatUtils.formatPeriod(start, start + span, fmt);
            b = DurationFormatUtils.formatPeriod(start, start + span, fmt, true, TimeZone.getDefault());
        } catch (Exception e) {
            return;
        }

        if (!a.equals(b)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:overload-default-tz] metamorphic violation: formatPeriod overloads disagree for start="
                            + start + " end=" + (start + span) + " format=" + fmt + " lhs=" + a + " rhs=" + b);
        }

        String c;
        String d;
        try {
            int dayOffset = data.consumeInt(0, 365);
            int extraDays = data.consumeInt(0, 365);
            int extraHours = data.consumeInt(0, 23);
            int extraMinutes = data.consumeInt(0, 59);
            int extraSeconds = data.consumeInt(0, 59);
            int extraMillis = data.consumeInt(0, 999);

            Calendar baseCal = Calendar.getInstance();
            baseCal.set(Calendar.YEAR, 2010);
            baseCal.set(Calendar.MONTH, Calendar.JANUARY);
            baseCal.set(Calendar.DAY_OF_MONTH, 1);
            baseCal.set(Calendar.HOUR_OF_DAY, 0);
            baseCal.set(Calendar.MINUTE, 0);
            baseCal.set(Calendar.SECOND, 0);
            baseCal.set(Calendar.MILLISECOND, 0);
            baseCal.add(Calendar.DAY_OF_MONTH, dayOffset);

            Calendar laterCal = (Calendar) baseCal.clone();
            laterCal.add(Calendar.DAY_OF_MONTH, extraDays);
            laterCal.add(Calendar.HOUR_OF_DAY, extraHours);
            laterCal.add(Calendar.MINUTE, extraMinutes);
            laterCal.add(Calendar.SECOND, extraSeconds);
            laterCal.add(Calendar.MILLISECOND, extraMillis);

            long s = baseCal.getTime().getTime();
            long e = laterCal.getTime().getTime();

            // Contract-based post-condition/metamorphic check:
            // formatPeriod formats the period according to the supplied timezone. If both instants
            // are shifted by a whole number of days, the elapsed duration is unchanged and, for a
            // format using only day-and-lower fields, the formatted result must stay the same.
            // A patch that merely avoids the buggy branch or does wrong month/day bookkeeping can
            // break this observable relation without ever throwing.
            c = DurationFormatUtils.formatPeriod(s, e, "ddHHmmssSSS");
            d = DurationFormatUtils.formatPeriod(
                    s + 24L * 60L * 60L * 1000L,
                    e + 24L * 60L * 60L * 1000L,
                    "ddHHmmssSSS");
        } catch (Exception e) {
            return;
        }

        if (!c.equals(d)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:day-shift-invariant] metamorphic violation: shifting both endpoints by one day changed a day-and-lower-only format lhs="
                            + c + " rhs=" + d);
        }
    }
}

