package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final double SQRT_EPS = Math.sqrt(2.22044604926e-16);
    private static final double ORTHO_TOL = 2.22044604926e-16;

    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        try {
            runFreudensteinRothCase(
                new double[] { 0.5, -2.0 },
                6.99887517584575,
                new double[] { 11.4124844654993, -0.896827913731509 }
            );
            runFreudensteinRothCase(
                new double[] { 5.0, -20.0 },
                6.9988751744895,
                new double[] { 11.4121122022341, -0.8968550851268697 }
            );
            runFreudensteinRothCase(
                new double[] { 50.0, -200.0 },
                11426454.595762,
                new double[] { 11.412069435091231, -0.8968582807605691 }
            );
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        checkLinearReturnedValueMatchesReturnedPoint(data);
        checkExactLinearFitHasZeroResidual(data);
    }

    private static void runFreudensteinRothCase(double[] start, double expectedRms, double[] expectedPoint)
        throws FunctionEvaluationException, OptimizationException {

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (2 + 1));
        optimizer.setCostRelativeTolerance(SQRT_EPS);
        optimizer.setParRelativeTolerance(SQRT_EPS);
        optimizer.setOrthoTolerance(ORTHO_TOL);

        FreudensteinRothFunction function = new FreudensteinRothFunction();
        VectorialPointValuePair optimum = optimizer.optimize(
            function,
            new double[] { 0.0, 0.0 },
            new double[] { 1.0, 1.0 },
            start.clone()
        );

        double actualRms = optimizer.getRMS();
        double[] actualPoint = optimum.getPointRef();

        assertClose("freudenstein-roth-rms", actualRms, expectedRms, 1.0e-6,
            "start=" + keyFor(start));
        assertClose("freudenstein-roth-point0", actualPoint[0], expectedPoint[0], 1.0e-6,
            "start=" + keyFor(start));
        assertClose("freudenstein-roth-point1", actualPoint[1], expectedPoint[1], 1.0e-6,
            "start=" + keyFor(start));

        double[] reevaluated = function.value(actualPoint);
        double[] returnedValue = optimum.getValueRef();
        if (reevaluated.length != returnedValue.length) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:freudenstein-roth-returned-value-length] semantic mismatch: start=" +
                keyFor(start) + " returnedLength=" + returnedValue.length +
                " reevaluatedLength=" + reevaluated.length
            );
        }
        for (int i = 0; i < reevaluated.length; ++i) {
            // Contract: VectorialPointValuePair stores the objective value "at this point".
            // A throw-deleting/early-return patch can return stale objective for the returned point.
            if (!closeEnough(returnedValue[i], reevaluated[i], 1.0e-8)) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:freudenstein-roth-returned-value-at-point] semantic mismatch: start=" +
                    keyFor(start) + " index=" + i + " returned=" + returnedValue[i] +
                    " reevaluated=" + reevaluated[i]
                );
            }
        }

        double independentRms = computeRmsFromValue(reevaluated);
        // Contract: getRMS() is the root mean square of the weighted residuals for the optimized state.
        // updateResidualsAndCost/doOptimize share residual state; an incorrect early return can leave getRMS()
        // inconsistent with the actually returned optimum even if the top-level return looks plausible.
        if (!closeEnough(actualRms, independentRms, 1.0e-8)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:freudenstein-roth-rms-consistency] consistency violation: start=" +
                keyFor(start) + " reportedRMS=" + actualRms +
                " recomputedRMS=" + independentRms
            );
        }

        double chiSquare = optimizer.getChiSquare();
        double independentChiSquare = 0.0;
        for (int i = 0; i < reevaluated.length; ++i) {
            independentChiSquare += reevaluated[i] * reevaluated[i];
        }
        if (!closeEnough(chiSquare, independentChiSquare, 1.0e-8)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:freudenstein-roth-chisquare-consistency] consistency violation: start=" +
                keyFor(start) + " reportedChiSquare=" + chiSquare +
                " recomputedChiSquare=" + independentChiSquare
            );
        }
    }

    private static void checkLinearReturnedValueMatchesReturnedPoint(FuzzedDataProvider data) {
        final int a = data.consumeInt(-5, 5);
        final int b = data.consumeInt(-5, 5);
        final int s0 = data.consumeInt(-10, 10);
        final int s1 = data.consumeInt(-10, 10);
        final double w0 = data.consumeInt(1, 5);
        final double w1 = data.consumeInt(1, 5);
        final double w2 = data.consumeInt(1, 5);

        DifferentiableMultivariateVectorialFunction f = new DifferentiableMultivariateVectorialFunction() {
            public double[] value(double[] p) {
                return new double[] { p[0] + 2.0 * p[1], 3.0 * p[0] - p[1], p[0] - p[1] };
            }

            public MultivariateMatrixFunction jacobian() {
                return new MultivariateMatrixFunction() {
                    public double[][] value(double[] p) {
                        return new double[][] {
                            { 1.0, 2.0 },
                            { 3.0, -1.0 },
                            { 1.0, -1.0 }
                        };
                    }
                };
            }
        };

        double[] target = new double[] { a + 2.0 * b, 3.0 * a - b, a - b };
        double[] weights = new double[] { w0, w1, w2 };
        double[] start = new double[] { s0, s1 };

        VectorialPointValuePair vp;
        double[] reevaluated;
        try {
            LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
            vp = opt.optimize(f, target, weights, start);
            reevaluated = f.value(vp.getPointRef());
        } catch (Exception e) {
            return;
        }

        double[] returned = vp.getValueRef();
        String violation = null;
        if (returned.length != reevaluated.length) {
            violation = "length returned=" + returned.length + " reevaluated=" + reevaluated.length;
        } else {
            for (int i = 0; i < returned.length; ++i) {
                double x = returned[i];
                double y = reevaluated[i];
                if (!closeEnough(x, y, 1.0e-8)) {
                    violation = "index=" + i + " returned=" + x + " reevaluated=" + y;
                    break;
                }
            }
        }
        if (violation != null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:optimum-value-matches-returned-point] relation violated: " + violation
            );
        }
    }

    private static void checkExactLinearFitHasZeroResidual(FuzzedDataProvider data) {
        final int a = data.consumeInt(-5, 5);
        final int b = data.consumeInt(-5, 5);
        final int s0 = data.consumeInt(-10, 10);
        final int s1 = data.consumeInt(-10, 10);
        final double w0 = data.consumeInt(1, 5);
        final double w1 = data.consumeInt(1, 5);
        final double w2 = data.consumeInt(1, 5);

        DifferentiableMultivariateVectorialFunction f = new DifferentiableMultivariateVectorialFunction() {
            public double[] value(double[] p) {
                return new double[] { p[0] + 2.0 * p[1], 3.0 * p[0] - p[1], p[0] - p[1] };
            }

            public MultivariateMatrixFunction jacobian() {
                return new MultivariateMatrixFunction() {
                    public double[][] value(double[] p) {
                        return new double[][] {
                            { 1.0, 2.0 },
                            { 3.0, -1.0 },
                            { 1.0, -1.0 }
                        };
                    }
                };
            }
        };

        double[] target = new double[] { a + 2.0 * b, 3.0 * a - b, a - b };
        double[] weights = new double[] { w0, w1, w2 };
        double[] start = new double[] { s0, s1 };

        VectorialPointValuePair vp;
        double rms;
        try {
            LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
            vp = opt.optimize(f, target, weights, start);
            rms = opt.getRMS();
        } catch (Exception e) {
            return;
        }

        String violation = null;
        double[] val = vp.getValueRef();
        for (int i = 0; i < target.length; ++i) {
            double x = val[i];
            double y = target[i];
            if (!closeEnough(x, y, 1.0e-8)) {
                violation = "value index=" + i + " actual=" + x + " expected=" + y;
                break;
            }
        }
        if (violation == null && Math.abs(rms) > 1.0e-8) {
            violation = "RMS actual=" + rms + " expected=0.0";
        }

        if (violation != null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:exact-linear-fit-has-zero-residual] relation violated: " + violation
            );
        }
    }

    private static double computeRmsFromValue(double[] value) {
        double sum = 0.0;
        for (int i = 0; i < value.length; ++i) {
            sum += value[i] * value[i];
        }
        return Math.sqrt(sum / value.length);
    }

    private static void assertClose(String oracleId, double actual, double expected, double tol, String detail) {
        if (!closeEnough(actual, expected, tol)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:" + oracleId + "] semantic mismatch: expected=" + expected +
                " actual=" + actual + " " + detail
            );
        }
    }

    private static boolean closeEnough(double actual, double expected, double tol) {
        double scale = Math.max(1.0, Math.max(Math.abs(actual), Math.abs(expected)));
        return Math.abs(actual - expected) <= tol * scale;
    }

    private static String keyFor(double[] start) {
        return Double.toString(start[0]) + "_" + Double.toString(start[1]);
    }

    private static final class FreudensteinRothFunction implements DifferentiableMultivariateVectorialFunction {
        public double[] value(double[] p) {
            double x1 = p[0];
            double x2 = p[1];
            double f1 = -13.0 + x1 + ((5.0 - x2) * x2 - 2.0) * x2;
            double f2 = -29.0 + x1 + ((x2 + 1.0) * x2 - 14.0) * x2;
            return new double[] { f1, f2 };
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] p) {
                    double x2 = p[1];
                    return new double[][] {
                        { 1.0, 10.0 * x2 - 3.0 * x2 * x2 - 2.0 },
                        { 1.0, 3.0 * x2 * x2 + 2.0 * x2 - 14.0 }
                    };
                }
            };
        }
    }
}

