package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Arrays;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final double[] SEED_START = new double[] { 0.3, 0.4 };
    private static final double SEED_EXPECTED_RMS = 11.1517793413499;
    private static final double[] SEED_EXPECTED_PARAMS = new double[] {
        0.2578330049, 0.257829976764542
    };

    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        JennrichSampsonFunction seedFunction = new JennrichSampsonFunction(10);

        runSeedOracle(seedFunction);
        runBoundaryExploration(seedFunction, data);
    }

    private static void runSeedOracle(JennrichSampsonFunction function) {
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (function.getN() + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setOrthoTolerance(2.22044604926e-16);

        try {
            VectorialPointValuePair optimum =
                optimizer.optimize(function, function.getTarget(), function.getWeight(), function.getStartPoint());

            double[] point = optimum.getPointRef();

            // Lifted from MinpackTest.testMinpackJennrichSampson:
            // expected theoretical min cost is exactly 11.1517793413499 for this exact setup.
            assertClose("seed-rms", optimizer.getRMS(), SEED_EXPECTED_RMS, 1.0e-10);

            // Lifted from MinpackTest.testMinpackJennrichSampson:
            // expected theoretical minimizing parameters are exactly the two literals below.
            assertClose("seed-param-0", point[0], SEED_EXPECTED_PARAMS[0], 1.0e-10);
            assertClose("seed-param-1", point[1], SEED_EXPECTED_PARAMS[1], 1.0e-10);

            // Independent post-condition:
            // VectorialPointValuePair stores the objective function value at the returned point.
            // Re-evaluating the real function at that same returned point must reproduce the pair's value.
            // A patch that merely alters control flow/early-return bookkeeping can violate this observable agreement.
            double[] reevaluated = function.value(point);
            double[] reported = optimum.getValueRef();
            if (!sameArray(reevaluated, reported, 1.0e-12)) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:returned-objective] semantic mismatch: value at returned point differs from pair value "
                        + "point=" + Arrays.toString(point)
                        + " reported=" + Arrays.toString(reported)
                        + " reevaluated=" + Arrays.toString(reevaluated));
            }

            // Independent consistency check:
            // getCovariances() is a fresh computation from the optimizer's current state; repeated invocations on the
            // same optimized state must agree, and covariance matrices are symmetric by construction (inverse of J^T J).
            // This check is outside the already-covered returned-point/RMS symptom family.
            try {
                double[][] c1 = optimizer.getCovariances();
                double[][] c2 = optimizer.getCovariances();
                if (!sameMatrix(c1, c2, 1.0e-12)) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:covariance-repeatability] consistency violation: repeated getCovariances() calls disagree "
                            + "first=" + deepToString(c1) + " second=" + deepToString(c2));
                }
                if (!isSymmetric(c1, 1.0e-12)) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:covariance-symmetry] consistency violation: covariance matrix is not symmetric "
                            + deepToString(c1));
                }
            } catch (FunctionEvaluationException e) {
                return;
            } catch (OptimizationException e) {
                return;
            }
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }
    }

    private static void runBoundaryExploration(JennrichSampsonFunction function, FuzzedDataProvider data) {
        double perturb0 = data.consumeInt(-1000, 1000) * 1.0e-6;
        double perturb1 = data.consumeInt(-1000, 1000) * 1.0e-6;
        double tolScaleA = 1.0 + (data.consumeInt(-1000, 1000) * 1.0e-6);
        double tolScaleB = 1.0 + (data.consumeInt(-1000, 1000) * 1.0e-6);
        double tolScaleC = 1.0 + (data.consumeInt(-1000, 1000) * 1.0e-6);

        double[] start = new double[] { SEED_START[0] + perturb0, SEED_START[1] + perturb1 };

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (function.getN() + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16) * tolScaleA);
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16) * tolScaleB);
        optimizer.setOrthoTolerance(2.22044604926e-16 * tolScaleC);

        try {
            VectorialPointValuePair optimum =
                optimizer.optimize(function, function.getTarget(), function.getWeight(), start);

            // Sound metamorphic check on fuzzed variants:
            // For any successful optimization result, the pair's reported objective value must equal a fresh real
            // evaluation of the same function at the returned point. If either side threw, we would skip instead.
            double[] point = optimum.getPointRef();
            double[] reevaluated = function.value(point);
            double[] reported = optimum.getValueRef();
            if (!sameArray(reevaluated, reported, 1.0e-10)) {
                throw new RuntimeException(
                    "[oracle:fuzzed-returned-objective] metamorphic violation: value(point) must equal returned pair value "
                        + "inputStart=" + Arrays.toString(start)
                        + " point=" + Arrays.toString(point)
                        + " lhs=" + Arrays.toString(reevaluated)
                        + " rhs=" + Arrays.toString(reported));
            }
        } catch (Throwable t) {
            return;
        }
    }

    private static void assertClose(String id, double actual, double expected, double tol) {
        if (Double.isNaN(actual) || Math.abs(actual - expected) > tol) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:" + id + "] semantic mismatch: expected=" + expected + " actual=" + actual);
        }
    }

    private static boolean sameArray(double[] a, double[] b, double tol) {
        if (a == b) {
            return true;
        }
        if (a == null || b == null || a.length != b.length) {
            return false;
        }
        for (int i = 0; i < a.length; i++) {
            if (Double.isNaN(a[i]) != Double.isNaN(b[i])) {
                return false;
            }
            if (!Double.isNaN(a[i]) && Math.abs(a[i] - b[i]) > tol) {
                return false;
            }
        }
        return true;
    }

    private static boolean sameMatrix(double[][] a, double[][] b, double tol) {
        if (a == b) {
            return true;
        }
        if (a == null || b == null || a.length != b.length) {
            return false;
        }
        for (int i = 0; i < a.length; i++) {
            if (!sameArray(a[i], b[i], tol)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isSymmetric(double[][] m, double tol) {
        if (m == null) {
            return false;
        }
        for (int i = 0; i < m.length; i++) {
            if (m[i] == null || m[i].length != m.length) {
                return false;
            }
            for (int j = i + 1; j < m.length; j++) {
                if (Math.abs(m[i][j] - m[j][i]) > tol) {
                    return false;
                }
            }
        }
        return true;
    }

    private static String deepToString(double[][] m) {
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int i = 0; i < m.length; i++) {
            if (i != 0) {
                sb.append(", ");
            }
            sb.append(Arrays.toString(m[i]));
        }
        sb.append(']');
        return sb.toString();
    }

    private static final class JennrichSampsonFunction implements DifferentiableMultivariateVectorialFunction {
        private final int m;

        JennrichSampsonFunction(int m) {
            this.m = m;
        }

        int getN() {
            return 2;
        }

        double[] getTarget() {
            return new double[m];
        }

        double[] getWeight() {
            double[] w = new double[m];
            Arrays.fill(w, 1.0);
            return w;
        }

        double[] getStartPoint() {
            return SEED_START.clone();
        }

        public double[] value(double[] point) throws FunctionEvaluationException, IllegalArgumentException {
            double[] values = new double[m];
            double x1 = point[0];
            double x2 = point[1];
            for (int i = 0; i < m; i++) {
                int k = i + 1;
                values[i] = 2.0 + 2.0 * k - Math.exp(k * x1) - Math.exp(k * x2);
            }
            return values;
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] point) throws FunctionEvaluationException, IllegalArgumentException {
                    double[][] j = new double[m][2];
                    double x1 = point[0];
                    double x2 = point[1];
                    for (int i = 0; i < m; i++) {
                        int k = i + 1;
                        j[i][0] = -k * Math.exp(k * x1);
                        j[i][1] = -k * Math.exp(k * x2);
                    }
                    return j;
                }
            };
        }
    }
}

