package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final class CaseExpectation {
        final double[] start;
        final double expectedRms;
        final double[] expectedPoint;

        CaseExpectation(double[] start, double expectedRms, double[] expectedPoint) {
            this.start = start;
            this.expectedRms = expectedRms;
            this.expectedPoint = expectedPoint;
        }
    }

    private static final class CaseResult {
        final double[] point;
        final double rms;
        final int iterations;

        CaseResult(double[] point, double rms, int iterations) {
            this.point = point;
            this.rms = rms;
            this.iterations = iterations;
        }
    }

    private static final double[] TARGET = new double[] { 0.0, 0.0 };
    private static final double[] WEIGHTS = new double[] { 1.0, 1.0 };
    private static final double SQRT_EPS = Math.sqrt(2.22044604926e-16);
    private static final double EPS = 2.22044604926e-16;

    private static final CaseExpectation[] SEED_CASES = new CaseExpectation[] {
        new CaseExpectation(
            new double[] { 0.5, -2.0 },
            20.0124960961895,
            new double[] { 11.4124844654993, -0.896827913731509 }
        ),
        new CaseExpectation(
            new double[] { 5.0, -20.0 },
            6.9988751744895,
            new double[] { 11.4121122022341, -0.8968550851268697 }
        ),
        new CaseExpectation(
            new double[] { 50.0, -200.0 },
            6.99887517242903,
            new double[] { 11.412069435091231, -0.8968582807605691 }
        )
    };

    private static LevenbergMarquardtOptimizer configuredOptimizer() {
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (2 + 1));
        optimizer.setCostRelativeTolerance(SQRT_EPS);
        optimizer.setParRelativeTolerance(SQRT_EPS);
        optimizer.setOrthoTolerance(EPS);
        return optimizer;
    }

    private static DifferentiableMultivariateVectorialFunction freudensteinRothFunction() {
        return new DifferentiableMultivariateVectorialFunction() {
            public double[] value(double[] p) {
                double x1 = p[0];
                double x2 = p[1];
                double f1 = -13.0 + x1 + ((5.0 - x2) * x2 - 2.0) * x2;
                double f2 = -29.0 + x1 + ((x2 + 1.0) * x2 - 14.0) * x2;
                return new double[] { f1, f2 };
            }

            public MultivariateMatrixFunction jacobian() {
                return new MultivariateMatrixFunction() {
                    public double[][] value(double[] p) {
                        double x2 = p[1];
                        return new double[][] {
                            { 1.0, 10.0 * x2 - 3.0 * x2 * x2 - 2.0 },
                            { 1.0, 3.0 * x2 * x2 + 2.0 * x2 - 14.0 }
                        };
                    }
                };
            }
        };
    }

    private static CaseResult runFreudensteinRoth(double[] start)
            throws FunctionEvaluationException, OptimizationException {
        LevenbergMarquardtOptimizer optimizer = configuredOptimizer();
        VectorialPointValuePair optimum =
            optimizer.optimize(freudensteinRothFunction(), TARGET, WEIGHTS, start.clone());
        return new CaseResult(optimum.getPointRef().clone(), optimizer.getRMS(), optimizer.getIterations());
    }

    private static boolean closeEnough(double actual, double expected, double relTol, double absTol) {
        double scale = Math.max(1.0, Math.max(Math.abs(actual), Math.abs(expected)));
        return Math.abs(actual - expected) <= Math.max(absTol, relTol * scale);
    }

    private static String pair(double a, double b) {
        return a + " vs " + b;
    }

    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        for (int i = 0; i < SEED_CASES.length; i++) {
            CaseExpectation c = SEED_CASES[i];
            final CaseResult result;
            try {
                result = runFreudensteinRoth(c.start);
            } catch (Throwable t) {
                return;
            }

            // Lifted from MinpackTest#testMinpackFreudensteinRoth: these three exact hard-coded
            // start points are asserted to converge to these exact hard-coded minima in the real test.
            if (!closeEnough(result.rms, c.expectedRms, 1.0e-10, 1.0e-10)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:seed-rms] semantic mismatch: case=" + i
                        + " expected RMS " + c.expectedRms + " but was " + result.rms);
            }
            for (int j = 0; j < c.expectedPoint.length; j++) {
                if (!closeEnough(result.point[j], c.expectedPoint[j], 1.0e-10, 1.0e-10)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:seed-param] semantic mismatch: case=" + i + " param=" + j
                            + " expected " + c.expectedPoint[j] + " but was " + result.point[j]);
                }
            }

            // Contract-based post-condition on exposed receiver state:
            // incrementIterationsCounter() throws if iterations exceed maxIterations, so after any
            // successful optimize() the reported getIterations() must lie within the configured bound.
            // A band-aid patch that returns through the patched branch with stale bookkeeping would break this.
            if (result.iterations < 1 || result.iterations > 300) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:iterations-bounds] consistency violation: case=" + i
                        + " iterations=" + result.iterations + " outside [1,300]");
            }
        }

        double fuzzStart0 = data.consumeInt(-200, 200);
        double fuzzStart1 = data.consumeInt(-200, 200);

        final CaseResult r1;
        final CaseResult r2;
        try {
            r1 = runFreudensteinRoth(new double[] { fuzzStart0, fuzzStart1 });
            r2 = runFreudensteinRoth(new double[] { fuzzStart0, fuzzStart1 });
        } catch (Throwable t) {
            return;
        }

        // Determinism / fresh-recomputation consistency:
        // optimize() has no RNG or mutable external input beyond the provided function, target, weights,
        // and start point, so two freshly-constructed optimizers on the identical problem must report the
        // same iteration count. This is a "second identically-constructed object" cross-check on hidden state.
        if (r1.iterations != r2.iterations) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:repeatable-iterations] consistency violation: same problem gave iterations "
                    + r1.iterations + " and " + r2.iterations);
        }

        // Same determinism argument for the optimized point and RMS on identical inputs.
        for (int j = 0; j < r1.point.length; j++) {
            if (!closeEnough(r1.point[j], r2.point[j], 1.0e-12, 1.0e-12)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:repeatable-point] metamorphic violation: param=" + j
                        + " same problem gave " + pair(r1.point[j], r2.point[j]));
            }
        }
        if (!closeEnough(r1.rms, r2.rms, 1.0e-12, 1.0e-12)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:repeatable-rms] metamorphic violation: same problem gave "
                    + pair(r1.rms, r2.rms));
        }
    }
}

