package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    private static final double EPS = 1.0e-8;

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        data.consumeRemainingAsBytes();

        JennrichSampsonModel function = new JennrichSampsonModel(
                10,
                new double[] { 0.3, 0.4 });

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (function.getN() + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setOrthoTolerance(2.22044604926e-16);

        final org.apache.commons.math.optimization.VectorialPointValuePair optimum;
        try {
            optimum = optimizer.optimize(
                    function,
                    function.getTarget(),
                    function.getWeight(),
                    function.getStartPoint());
        } catch (org.apache.commons.math.FunctionEvaluationException e) {
            return;
        } catch (org.apache.commons.math.optimization.OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        double[] point = optimum.getPointRef();
        if (point == null || point.length != 2) {
            return;
        }

        assertClose("jennrich-seed-param0", point[0], 0.2578330049, EPS);
        assertClose("jennrich-seed-param1", point[1], 0.257829976764542, EPS);
        assertClose("jennrich-seed-rms", optimizer.getRMS(), 11.1517793413499, EPS);

        // Contract basis:
        // getChiSquare() reports the chi-square value, while updateResidualsAndCost()
        // computes it from targetValues, residualsWeights, and the current objective.
        // Therefore the reported chi-square must agree with a fresh recomputation from
        // the returned point using the real function and the same target/weights.
        final double[] freshObjective;
        try {
            freshObjective = function.value(point);
        } catch (org.apache.commons.math.FunctionEvaluationException e) {
            return;
        } catch (RuntimeException e) {
            return;
        }

        double[] target = function.getTarget();
        double[] weight = function.getWeight();
        if (freshObjective.length != target.length || target.length != weight.length) {
            return;
        }

        double recomputedChiSquare = 0.0;
        for (int i = 0; i < freshObjective.length; i++) {
            double residual = target[i] - freshObjective[i];
            recomputedChiSquare += weight[i] * residual * residual;
        }

        double reportedChiSquare = optimizer.getChiSquare();
        double tol = Math.max(1.0e-9, Math.abs(recomputedChiSquare) * 1.0e-12);
        if (Math.abs(reportedChiSquare - recomputedChiSquare) > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:jennrich-chisquare-recompute] consistency violation: reported="
                            + reportedChiSquare
                            + " recomputed="
                            + recomputedChiSquare);
        }
    }

    private static void assertClose(String oracleId, double actual, double expected, double tol) {
        if (Double.isNaN(actual) || Double.isInfinite(actual) || Math.abs(actual - expected) > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:" + oracleId + "] semantic mismatch: expected=" + expected + " actual=" + actual);
        }
    }

    private static final class JennrichSampsonModel
            implements org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction {
        private final int m;
        private final double[] startPoint;
        private final double[] target;
        private final double[] weight;

        private JennrichSampsonModel(int m, double[] startPoint) {
            this.m = m;
            this.startPoint = startPoint.clone();
            this.target = new double[m];
            this.weight = new double[m];
            for (int i = 0; i < m; i++) {
                target[i] = 0.0;
                weight[i] = 1.0;
            }
        }

        int getN() {
            return startPoint.length;
        }

        double[] getStartPoint() {
            return startPoint.clone();
        }

        double[] getTarget() {
            return target.clone();
        }

        double[] getWeight() {
            return weight.clone();
        }

        public double[] value(double[] point) throws org.apache.commons.math.FunctionEvaluationException {
            if (point == null || point.length != 2) {
                throw new org.apache.commons.math.FunctionEvaluationException(point);
            }
            double[] values = new double[m];
            for (int i = 0; i < m; i++) {
                double idx = i + 1.0;
                values[i] = 2.0 + 2.0 * idx - Math.exp(idx * point[0]) - Math.exp(idx * point[1]);
            }
            return values;
        }

        public org.apache.commons.math.analysis.MultivariateMatrixFunction jacobian() {
            return new org.apache.commons.math.analysis.MultivariateMatrixFunction() {
                public double[][] value(double[] point) throws IllegalArgumentException {
                    if (point == null || point.length != 2) {
                        throw new IllegalArgumentException();
                    }
                    double[][] jac = new double[m][2];
                    for (int i = 0; i < m; i++) {
                        double idx = i + 1.0;
                        jac[i][0] = -idx * Math.exp(idx * point[0]);
                        jac[i][1] = -idx * Math.exp(idx * point[1]);
                    }
                    return jac;
                }
            };
        }
    }
}

