package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final double SQRT_EPS = Math.sqrt(2.22044604926e-16);

    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        checkFreudensteinRothSeeds();
        checkLinearCovarianceAndToleranceBoundary(data);
    }

    private static void checkFreudensteinRothSeeds() {
        checkFreudensteinRothCase(
                "fr1",
                new double[] { 0.5, -2.0 },
                6.99887517584575,
                new double[] { 11.4124844654993, -0.896827913731509 });
        checkFreudensteinRothCase(
                "fr2",
                new double[] { 5.0, -20.0 },
                6.9988751744895,
                new double[] { 11.4121122022341, -0.8968550851268697 });
        checkFreudensteinRothCase(
                "fr3",
                new double[] { 50.0, -200.0 },
                6.99887517242903,
                new double[] { 11.412069435091231, -0.8968582807605691 });
    }

    private static void checkFreudensteinRothCase(
            String id,
            double[] start,
            double expectedRms,
            double[] expectedPoint) {
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (2 + 1));
        optimizer.setCostRelativeTolerance(SQRT_EPS);
        optimizer.setParRelativeTolerance(SQRT_EPS);
        optimizer.setOrthoTolerance(2.22044604926e-16);

        VectorialPointValuePair optimum;
        try {
            optimum = optimizer.optimize(
                    FREUDENSTEIN_ROTH,
                    new double[] { 0.0, 0.0 },
                    new double[] { 1.0, 1.0 },
                    start.clone());
        } catch (FunctionEvaluationException e) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-no-exception] unexpected FunctionEvaluationException", e);
        } catch (OptimizationException e) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-no-exception] unexpected OptimizationException", e);
        } catch (IllegalArgumentException e) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-no-exception] unexpected IllegalArgumentException", e);
        }

        double actualRms = optimizer.getRMS();
        assertNear(id + "-rms", "expected RMS " + expectedRms + " but was " + actualRms,
                expectedRms, actualRms, 1e-10);

        double[] point = optimum.getPointRef();
        if (point.length != expectedPoint.length) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-point-length] semantic mismatch: expected point length "
                    + expectedPoint.length + " but was " + point.length);
        }
        assertNear(id + "-p0", "expected point[0] " + expectedPoint[0] + " but was " + point[0],
                expectedPoint[0], point[0], 1e-10);
        assertNear(id + "-p1", "expected point[1] " + expectedPoint[1] + " but was " + point[1],
                expectedPoint[1], point[1], 1e-10);

        // Contract of VectorialPointValuePair: it stores "a point and the vectorial value of an objective function at this point".
        // So after optimize succeeds, the returned value must equal a fresh evaluation of the same real function at the returned point.
        double[] returnedValue = optimum.getValueRef();
        double[] reevaluated;
        try {
            reevaluated = FREUDENSTEIN_ROTH.value(point);
        } catch (FunctionEvaluationException e) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-value-at-point] unexpected reevaluation failure", e);
        }
        if (returnedValue.length != reevaluated.length) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-value-at-point-length] semantic mismatch: returned value length "
                    + returnedValue.length + " but reevaluated length " + reevaluated.length);
        }
        for (int i = 0; i < returnedValue.length; i++) {
            double x = returnedValue[i];
            double y = reevaluated[i];
            if (!closeEnough(x, y, 1e-12)) {
                throw new FuzzerSecurityIssueLow("[oracle:" + id + "-value-at-point] consistency violation: returned value[" + i
                        + "]=" + x + " reevaluated=" + y);
            }
        }
    }

    private static void checkLinearCovarianceAndToleranceBoundary(FuzzedDataProvider data) {
        final int a = data.consumeInt(-5, 5);
        final int b = data.consumeInt(-5, 5);
        final int s0 = data.consumeInt(-10, 10);
        final int s1 = data.consumeInt(-10, 10);
        final int w1 = data.consumeInt(1, 5);
        final int w2 = data.consumeInt(1, 5);
        final int w3 = data.consumeInt(1, 5);

        final double[] target = new double[] {
                a + 2.0 * b,
                3.0 * a - b,
                a - b
        };
        final double[] weights = new double[] { w1, w2, w3 };
        final double[] start = new double[] { s0, s1 };

        // Strategy (c), flip the patched condition's boundary knobs:
        // doOptimize's changed branch tests costRelativeTolerance and parRelativeTolerance.
        // For this exactly solvable linear least-squares problem, the correct optimum and derived covariance
        // are fixed by construction and must remain correct for moderate tolerances around that boundary.
        double tolScale = 1.0 + (data.consumeInt(-20, 20) * 0.05);
        if (tolScale <= 0.05) {
            tolScale = 0.05;
        }
        double costTol = SQRT_EPS * tolScale;
        double parTol = SQRT_EPS * (2.0 - Math.min(1.95, tolScale));

        LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
        opt.setMaxIterations(300);
        opt.setCostRelativeTolerance(costTol);
        opt.setParRelativeTolerance(parTol);
        opt.setOrthoTolerance(2.22044604926e-16);

        VectorialPointValuePair vp;
        double[][] cov;
        try {
            vp = opt.optimize(LINEAR_3X2, target, weights, start);
            cov = opt.getCovariances();
        } catch (Throwable t) {
            return;
        }

        double[] p = vp.getPointRef();
        double[] v = vp.getValueRef();
        double[] expectedPoint = new double[] { a, b };

        if (!closeEnough(p[0], expectedPoint[0], 1e-8) || !closeEnough(p[1], expectedPoint[1], 1e-8)) {
            throw new FuzzerSecurityIssueLow("[oracle:linear-point-boundary] semantic mismatch: expected point=("
                    + expectedPoint[0] + "," + expectedPoint[1] + ") but was (" + p[0] + "," + p[1] + ")");
        }

        for (int i = 0; i < target.length; i++) {
            if (!closeEnough(v[i], target[i], 1e-8)) {
                throw new FuzzerSecurityIssueLow("[oracle:linear-value-boundary] semantic mismatch: expected value[" + i + "]="
                        + target[i] + " but was " + v[i]);
            }
        }

        // Independent cross-check not already in covered families:
        // getCovariances() reports the covariance matrix of optimized parameters.
        // For this constant full-rank linear model, that matrix is exactly inv(J^T W J),
        // which we recompute analytically from the model's own Jacobian and weights.
        double m00 = w1 * 1.0 * 1.0 + w2 * 3.0 * 3.0 + w3 * 1.0 * 1.0;
        double m01 = w1 * 1.0 * 2.0 + w2 * 3.0 * (-1.0) + w3 * 1.0 * (-1.0);
        double m11 = w1 * 2.0 * 2.0 + w2 * (-1.0) * (-1.0) + w3 * (-1.0) * (-1.0);
        double det = m00 * m11 - m01 * m01;
        if (det == 0.0 || Double.isNaN(det) || Double.isInfinite(det)) {
            return;
        }
        double[][] expectedCov = new double[][] {
                { m11 / det, -m01 / det },
                { -m01 / det, m00 / det }
        };

        if (cov == null || cov.length != 2 || cov[0].length != 2 || cov[1].length != 2) {
            throw new FuzzerSecurityIssueLow("[oracle:linear-covariance-shape] consistency violation: expected 2x2 covariance matrix");
        }

        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                double actual = cov[i][j];
                double expected = expectedCov[i][j];
                if (!closeEnough(actual, expected, 1e-8)) {
                    throw new FuzzerSecurityIssueLow("[oracle:linear-covariance-analytic] consistency violation: cov[" + i + "][" + j
                            + "] expected " + expected + " but was " + actual);
                }
            }
        }
    }

    private static boolean closeEnough(double expected, double actual, double relTol) {
        double scale = Math.max(1.0, Math.max(Math.abs(expected), Math.abs(actual)));
        return Math.abs(expected - actual) <= relTol * scale;
    }

    private static void assertNear(String oracleId, String detail, double expected, double actual, double relTol) {
        if (!closeEnough(expected, actual, relTol)) {
            throw new FuzzerSecurityIssueLow("[oracle:" + oracleId + "] semantic mismatch: " + detail);
        }
    }

    private static final DifferentiableMultivariateVectorialFunction FREUDENSTEIN_ROTH =
            new DifferentiableMultivariateVectorialFunction() {
                public double[] value(double[] p) {
                    double x1 = p[0];
                    double x2 = p[1];
                    double f1 = x1 - 13.0 + ((5.0 - x2) * x2 - 2.0) * x2;
                    double f2 = x1 - 29.0 + ((x2 + 1.0) * x2 - 14.0) * x2;
                    return new double[] { f1, f2 };
                }

                public MultivariateMatrixFunction jacobian() {
                    return new MultivariateMatrixFunction() {
                        public double[][] value(double[] p) {
                            double x2 = p[1];
                            return new double[][] {
                                    { 1.0, 10.0 * x2 - 3.0 * x2 * x2 - 2.0 },
                                    { 1.0, 3.0 * x2 * x2 + 2.0 * x2 - 14.0 }
                            };
                        }
                    };
                }
            };

    private static final DifferentiableMultivariateVectorialFunction LINEAR_3X2 =
            new DifferentiableMultivariateVectorialFunction() {
                public double[] value(double[] p) {
                    return new double[] {
                            p[0] + 2.0 * p[1],
                            3.0 * p[0] - p[1],
                            p[0] - p[1]
                    };
                }

                public MultivariateMatrixFunction jacobian() {
                    return new MultivariateMatrixFunction() {
                        public double[][] value(double[] p) {
                            return new double[][] {
                                    { 1.0, 2.0 },
                                    { 3.0, -1.0 },
                                    { 1.0, -1.0 }
                            };
                        }
                    };
                }
            };
}

