harness_source:
package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {

    private static final double EPS = 1e-8;

    private static final class FreudensteinRothFunction implements DifferentiableMultivariateVectorialFunction {
        private final double[] startPoint;

        private FreudensteinRothFunction(double[] startPoint) {
            this.startPoint = startPoint.clone();
        }

        public double[] getStartPoint() {
            return startPoint.clone();
        }

        public double[] getTarget() {
            return new double[] { 0.0, 0.0 };
        }

        public double[] getWeight() {
            return new double[] { 1.0, 1.0 };
        }

        public double[] value(double[] p) {
            final double x1 = p[0];
            final double x2 = p[1];
            final double f1 = -13.0 + x1 + ((5.0 - x2) * x2 - 2.0) * x2;
            final double f2 = -29.0 + x1 + ((x2 + 1.0) * x2 - 14.0) * x2;
            return new double[] { f1, f2 };
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] p) {
                    final double x2 = p[1];
                    return new double[][] {
                        { 1.0, 10.0 * x2 - 3.0 * x2 * x2 - 2.0 },
                        { 1.0, 3.0 * x2 * x2 + 2.0 * x2 - 14.0 }
                    };
                }
            };
        }
    }

    private static void assertNear(String oracleId, String what, double expected, double actual) {
        final double tol = EPS * Math.max(1.0, Math.max(Math.abs(expected), Math.abs(actual)));
        if (Double.isNaN(actual) || Math.abs(expected - actual) > tol) {
            throw new FuzzerSecurityIssueLow("[oracle:" + oracleId + "] semantic mismatch: " + what
                    + " expected=" + expected + " actual=" + actual);
        }
    }

    private static void assertArrayNear(String oracleId, String what, double[] expected, double[] actual) {
        if (actual == null || actual.length != expected.length) {
            throw new FuzzerSecurityIssueLow("[oracle:" + oracleId + "] semantic mismatch: " + what
                    + " expectedLength=" + expected.length
                    + " actualLength=" + (actual == null ? -1 : actual.length));
        }
        for (int i = 0; i < expected.length; i++) {
            assertNear(oracleId, what + "[" + i + "]", expected[i], actual[i]);
        }
    }

    private static double weightedChiSquare(double[] target, double[] value, double[] weights) {
        double sum = 0.0;
        for (int i = 0; i < target.length; i++) {
            final double residual = target[i] - value[i];
            sum += weights[i] * residual * residual;
        }
        return sum;
    }

    private static void runFreudensteinRothSeed(
            String oracleBase,
            double[] start,
            double expectedRms,
            double[] expectedPoint) {

        final FreudensteinRothFunction function = new FreudensteinRothFunction(start);
        final LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (2 + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setOrthoTolerance(2.22044604926e-16);

        final VectorialPointValuePair optimum;
        final double rms1;
        final double chi1;
        final int iterations1;
        try {
            optimum = optimizer.optimize(function, function.getTarget(), function.getWeight(), function.getStartPoint());
            rms1 = optimizer.getRMS();
            chi1 = optimizer.getChiSquare();
            iterations1 = optimizer.getIterations();
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        assertNear(oracleBase + "-rms", "optimizer.getRMS()", expectedRms, rms1);
        assertArrayNear(oracleBase + "-point", "optimum.getPointRef()", expectedPoint, optimum.getPointRef());

        final double[] returnedValue = optimum.getValueRef();
        final double[] reevaluatedValue;
        final double[][] cov;
        final double rms2;
        final double chi2;
        final int iterations2;
        try {
            reevaluatedValue = function.value(optimum.getPointRef());
            cov = optimizer.getCovariances();
            rms2 = optimizer.getRMS();
            chi2 = optimizer.getChiSquare();
            iterations2 = optimizer.getIterations();
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (RuntimeException e) {
            return;
        }

        // VectorialPointValuePair is documented to hold the objective value at the returned point.
        // Re-evaluating the same real function at that point is an independent way to obtain that quantity.
        assertArrayNear(oracleBase + "-value-at-point", "returned objective equals function.value(returnedPoint)",
                reevaluatedValue, returnedValue);

        // Chi-square is the sum of weighted squared residuals. Recomputing it from the optimizer's own
        // returned objective and the original target/weights is an independent consistency cross-check.
        final double recomputedChi = weightedChiSquare(function.getTarget(), returnedValue, function.getWeight());
        assertNear(oracleBase + "-chi-recompute", "getChiSquare()", recomputedChi, chi1);

        // Hidden-state reader check outside previously covered families:
        // getCovariances/getRMS/getChiSquare/getIterations are reader-style methods. A correct implementation
        // must not silently perturb already-optimized summary state when these are called after optimize().
        if (cov.length != 2 || cov[0].length != 2 || cov[1].length != 2) {
            throw new FuzzerSecurityIssueLow("[oracle:" + oracleBase + "-cov-shape] consistency violation: covariance shape="
                    + cov.length + "x" + cov[0].length);
        }
        if (iterations1 != iterations2) {
            throw new FuzzerSecurityIssueLow("[oracle:" + oracleBase + "-getter-iterations] consistency violation: iterations changed from "
                    + iterations1 + " to " + iterations2);
        }
        assertNear(oracleBase + "-getter-rms", "RMS stable across getters", rms1, rms2);
        assertNear(oracleBase + "-getter-chi", "ChiSquare stable across getters", chi1, chi2);
    }

    private static void runFuzzedFreudensteinRothConsistency(FuzzedDataProvider data) {
        final double s0 = data.consumeInt(-100, 100);
        final double s1 = data.consumeInt(-300, 300);

        final FreudensteinRothFunction function = new FreudensteinRothFunction(new double[] { s0, s1 });
        final LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(300);
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setOrthoTolerance(2.22044604926e-16);

        final VectorialPointValuePair optimum;
        final double chi1;
        final double rms1;
        final int iterations1;
        try {
            optimum = optimizer.optimize(function, function.getTarget(), function.getWeight(), function.getStartPoint());
            chi1 = optimizer.getChiSquare();
            rms1 = optimizer.getRMS();
            iterations1 = optimizer.getIterations();
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        final double[] returnedPoint = optimum.getPointRef();
        final double[] returnedValue = optimum.getValueRef();
        final double[] reevaluatedValue;
        final double[][] cov;
        final double chi2;
        final double rms2;
        final int iterations2;
        try {
            reevaluatedValue = function.value(returnedPoint);
            cov = optimizer.getCovariances();
            chi2 = optimizer.getChiSquare();
            rms2 = optimizer.getRMS();
            iterations2 = optimizer.getIterations();
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (RuntimeException e) {
            return;
        }

        // Returned value must equal objective evaluated at returned point.
        assertArrayNear("fuzz-value-at-point", "returned objective equals function.value(returnedPoint)",
                reevaluatedValue, returnedValue);

        // Cross-check chi-square by recomputing it from target/value/weights.
        final double recomputedChi = weightedChiSquare(function.getTarget(), returnedValue, function.getWeight());
        assertNear("fuzz-chi-recompute", "getChiSquare()", recomputedChi, chi1);

        // RMS in AbstractLeastSquaresOptimizer is the root of chi-square / rows.
        final double recomputedRms = Math.sqrt(recomputedChi / function.getTarget().length);
        assertNear("fuzz-rms-formula", "getRMS()", recomputedRms, rms1);

        // Reader methods should not mutate optimized summary state.
        if (cov.length != 2 || cov[0].length != 2 || cov[1].length != 2) {
            throw new FuzzerSecurityIssueLow("[oracle:fuzz-cov-shape] consistency violation: covariance shape="
                    + cov.length + "x" + cov[0].length);
        }
        if (iterations1 != iterations2) {
            throw new FuzzerSecurityIssueLow("[oracle:fuzz-getter-iterations] consistency violation: iterations changed from "
                    + iterations1 + " to " + iterations2);
