package org.apache.commons.math.ode.nonstiff;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import org.apache.commons.math.ode.DerivativeException;
import org.apache.commons.math.ode.FirstOrderDifferentialEquations;
import org.apache.commons.math.ode.IntegratorException;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        final double shift = data.consumeInt(-20, 20) / 10.0;
        final double scale = data.consumeInt(1, 5);
        final double t0 = shift;
        final double t = shift + 1.0;
        final double range = Math.abs(t - t0);

        final FirstOrderDifferentialEquations eq = new FirstOrderDifferentialEquations() {
            public int getDimension() {
                return 1;
            }

            public void computeDerivatives(double time, double[] state, double[] yDot) {
                final double x = time - shift;
                yDot[0] = 5.0 * scale * x * x * x * x;
            }
        };

        final double[] y0 = new double[] { 0.0 };
        final double expectedY = scale;

        for (int nSteps = 1; nSteps < 7; ++nSteps) {
            final AdamsMoultonIntegrator integ =
                new AdamsMoultonIntegrator(nSteps, 1.0e-6 * range, 0.1 * range, 1.0e-9, 1.0e-9);
            final double[] y = new double[1];
            final double stop;
            try {
                stop = integ.integrate(eq, t0, y0, t, y);
            } catch (DerivativeException e) {
                throw new RuntimeException(e);
            } catch (IntegratorException e) {
                throw new RuntimeException(e);
            }

            final int evaluations = integ.getEvaluations();

            if (nSteps < 4) {
                if (!(evaluations > 140)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:poly-evals-lowsteps] semantic mismatch: nSteps=" + nSteps
                            + " evaluations=" + evaluations + " expected > 140");
                }
            } else {
                if (!(evaluations < 90)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:poly-evals-highsteps] semantic mismatch: nSteps=" + nSteps
                            + " evaluations=" + evaluations + " expected < 90");
                }
            }

            // Contract guarantee: without user events, integrate(..., t, y) returns the requested stop time.
            final double stopTol = 1.0e-12 * Math.max(1.0, Math.max(Math.abs(stop), Math.abs(t)));
            if (Math.abs(stop - t) > stopTol) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:poly-stop-time] semantic mismatch: nSteps=" + nSteps
                        + " stop=" + stop + " target=" + t);
            }

            // Trusted oracle from constructed input: y' = 5*scale*(time-shift)^4 with y(t0)=0 and t=t0+1
            // has exact solution y(t)=scale*(t-shift)^5, so final y must equal scale exactly.
            final double yTol = 1.0e-7 * Math.max(1.0, Math.abs(expectedY));
            if (Math.abs(y[0] - expectedY) > yTol) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:poly-closed-form] semantic mismatch: nSteps=" + nSteps
                        + " finalY=" + y[0] + " expectedY=" + expectedY);
            }
        }
    }
}

