package org.apache.commons.math.ode.nonstiff;

import org.apache.commons.math.ode.FirstOrderDifferentialEquations;

public class FuzzHarness {

    private static double poly(double t) {
        return (((((t + 1.0) * t + 1.0) * t + 1.0) * t + 1.0) * t) + 1.0;
    }

    private static double dpoly(double t) {
        return ((((5.0 * t + 4.0) * t + 3.0) * t + 2.0) * t) + 1.0;
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        final double t0 = 0.0;
        final double t = 1.0;
        final double range = Math.abs(t - t0);

        final FirstOrderDifferentialEquations equations = new FirstOrderDifferentialEquations() {
            public int getDimension() {
                return 1;
            }

            public void computeDerivatives(double time, double[] state, double[] yDot) {
                yDot[0] = dpoly(time);
            }
        };

        int forced = data.consumeInt(0, 20);

        for (int nSteps = 1; nSteps < 7; ++nSteps) {
            AdamsMoultonIntegrator integ =
                new AdamsMoultonIntegrator(nSteps, 1.0e-6 * range, 0.1 * range, 1.0e-9, 1.0e-9);
            double[] y = new double[1];
            try {
                integ.integrate(equations, t0, new double[] { poly(t0) }, t, y);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }

            int evaluations = integ.getEvaluations();
            if (nSteps < 4) {
                if (!(evaluations > 140)) {
                    if (nSteps == 1) {
                        throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                            "[oracle:lifted-poly-evals-step1] semantic mismatch: evaluations=" +
                            evaluations + " for nSteps=1 expected > 140");
                    } else if (nSteps == 2) {
                        throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                            "[oracle:lifted-poly-evals-step2] semantic mismatch: evaluations=" +
                            evaluations + " for nSteps=2 expected > 140");
                    } else {
                        throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                            "[oracle:lifted-poly-evals-step3] semantic mismatch: evaluations=" +
                            evaluations + " for nSteps=3 expected > 140");
                    }
                }
            } else {
                if (!(evaluations < 90)) {
                    if (nSteps == 4) {
                        throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                            "[oracle:lifted-poly-evals-step4] semantic mismatch: evaluations=" +
                            evaluations + " for nSteps=4 expected < 90");
                    } else if (nSteps == 5) {
                        throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                            "[oracle:lifted-poly-evals-step5] semantic mismatch: evaluations=" +
                            evaluations + " for nSteps=5 expected < 90");
                    } else {
                        throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                            "[oracle:lifted-poly-evals-step6] semantic mismatch: evaluations=" +
                            evaluations + " for nSteps=6 expected < 90");
                    }
                }
            }

            double expected = poly(t);
            double err = Math.abs(y[0] - expected);
            double tol = 1.0e-8 * Math.max(1.0, Math.max(Math.abs(y[0]), Math.abs(expected)));
