                if (nSteps == 1) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:poly-final-state-step1] semantic mismatch: final=" + y[0] +
                        " expected=" + expected + " err=" + err + " tol=" + tol);
                } else if (nSteps == 2) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:poly-final-state-step2] semantic mismatch: final=" + y[0] +
                        " expected=" + expected + " err=" + err + " tol=" + tol);
                } else if (nSteps == 3) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:poly-final-state-step3] semantic mismatch: final=" + y[0] +
                        " expected=" + expected + " err=" + err + " tol=" + tol);
                } else if (nSteps == 4) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:poly-final-state-step4] semantic mismatch: final=" + y[0] +
                        " expected=" + expected + " err=" + err + " tol=" + tol);
                } else if (nSteps == 5) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:poly-final-state-step5] semantic mismatch: final=" + y[0] +
                        " expected=" + expected + " err=" + err + " tol=" + tol);
                } else {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:poly-final-state-step6] semantic mismatch: final=" + y[0] +
                        " expected=" + expected + " err=" + err + " tol=" + tol);
                }
            }
        }

        // Additional deterministic probe guided by fuzzer input to exercise the patched path with
