            new AdamsMoultonIntegrator(data.consumeInt(2, 6), 1.0e-6 * delta, 0.1 * delta, 1.0e-9, 1.0e-9);
        double[] y2 = new double[1];
        double stop;
        try {
            stop = integ2.integrate(equations, t0, new double[] { poly(t0) }, target, y2);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        double expected2 = poly(target);
        double err2 = Math.abs(y2[0] - expected2);
        double tol2 = 1.0e-8 * Math.max(1.0, Math.max(Math.abs(y2[0]), Math.abs(expected2)));
