                "[oracle:polynomial-stop-time] semantic mismatch: stop=" + stop + " target=" + target);
        }
        if (err2 > tol2) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:polynomial-closed-form] semantic mismatch: final=" + y2[0] +
                " expected=" + expected2 + " err=" + err2 + " tol=" + tol2);
        }
    }
}

