package org.apache.commons.math.ode.nonstiff;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import org.apache.commons.math.ode.DerivativeException;
import org.apache.commons.math.ode.FirstOrderDifferentialEquations;
import org.apache.commons.math.ode.IntegratorException;

public class FuzzHarness {

    private static final class QuinticPolynomialODE implements FirstOrderDifferentialEquations {
        private final double c0;
        private final double c1;
        private final double c2;
        private final double c3;
        private final double c4;
        private final double c5;

        QuinticPolynomialODE(double c0, double c1, double c2, double c3, double c4, double c5) {
            this.c0 = c0;
            this.c1 = c1;
            this.c2 = c2;
            this.c3 = c3;
            this.c4 = c4;
            this.c5 = c5;
        }

        public int getDimension() {
            return 1;
        }

        public void computeDerivatives(double t, double[] y, double[] yDot) {
            yDot[0] = c1 + 2.0 * c2 * t + 3.0 * c3 * t * t + 4.0 * c4 * t * t * t + 5.0 * c5 * t * t * t * t;
        }

        double value(double t) {
            return (((((c5 * t + c4) * t + c3) * t + c2) * t + c1) * t) + c0;
        }
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        double t0 = 0.0;
        double t = 1.0;
        double range = Math.abs(t - t0);

        int variant = data.consumeInt(0, 3);
        QuinticPolynomialODE pb;
        switch (variant) {
            case 0:
                pb = new QuinticPolynomialODE(1.0, -1.0, 0.5, -0.5, 1.0, -0.25);
                break;
            case 1:
                pb = new QuinticPolynomialODE(-0.5, 2.0, -1.5, 0.75, -0.25, 0.125);
                break;
            case 2:
                pb = new QuinticPolynomialODE(0.0, 1.0, 0.0, -2.0, 1.0, -0.2);
                break;
            default:
                pb = new QuinticPolynomialODE(
                    data.consumeInt(-5, 5) / 4.0,
                    data.consumeInt(-5, 5) / 4.0,
                    data.consumeInt(-5, 5) / 4.0,
                    data.consumeInt(-5, 5) / 4.0,
                    data.consumeInt(-5, 5) / 4.0,
                    data.consumeInt(-5, 5) / 4.0
                );
                break;
        }

        int[] evals = new int[7];

        for (int nSteps = 1; nSteps < 7; ++nSteps) {
            AdamsMoultonIntegrator integ =
                new AdamsMoultonIntegrator(nSteps, 1.0e-6 * range, 0.1 * range, 1.0e-9, 1.0e-9);
            double[] y = new double[1];
            double stop;
            try {
                stop = integ.integrate(pb, t0, new double[] { pb.value(t0) }, t, y);
            } catch (DerivativeException e) {
                throw new RuntimeException(e);
            } catch (IntegratorException e) {
                throw new RuntimeException(e);
            }

            double expected = pb.value(t);
            double tol = 1.0e-8 * Math.max(1.0, Math.max(Math.abs(expected), Math.abs(y[0])));

            if (Math.abs(stop - t) > 1.0e-12) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:stop-time] semantic mismatch: nSteps=" + nSteps + " stop=" + stop + " target=" + t);
            }

            if (Math.abs(y[0] - expected) > tol) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:closed-form-state] semantic mismatch: nSteps=" + nSteps +
                    " actual=" + y[0] + " expected=" + expected + " tol=" + tol);
            }

            evals[nSteps] = integ.getEvaluations();

            int r1 = integ.getEvaluations();
            int r2 = integ.getEvaluations();
            int r3 = integ.getEvaluations();
            if (r1 != r2 || r2 != r3) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:evaluations-readonly] semantic mismatch: nSteps=" + nSteps +
                    " first=" + r1 + " second=" + r2 + " third=" + r3);
            }
        }

        for (int nSteps = 1; nSteps < 7; ++nSteps) {
            if (nSteps < 4) {
                if (!(evals[nSteps] > 140)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:lifted-poly-evals-low] semantic mismatch: nSteps=" + nSteps +
                        " evaluations=" + evals[nSteps] + " expected > 140");
                }
            } else {
                if (!(evals[nSteps] < 90)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:lifted-poly-evals-high] semantic mismatch: nSteps=" + nSteps +
                        " evaluations=" + evals[nSteps] + " expected < 90");
                }
            }
        }

        // Flips the patched condition: after the starter finishes near the target time,
        // the remaining interval is tiny. A correct implementation must preserve the
        // efficiency ordering seen in the lifted test, with higher-step Adams-Moulton
        // configurations requiring markedly fewer derivative evaluations than low-step ones.
        if (!(evals[4] < evals[3] && evals[5] <= evals[4] + 10 && evals[6] <= evals[5] + 10)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:eval-ordering] semantic mismatch: e3=" + evals[3] +
                " e4=" + evals[4] + " e5=" + evals[5] + " e6=" + evals[6]);
        }
    }
}

