// relation: integrate-returns-requested-end-time
// holds because: For a successful integration with no event handler stopping early, `integrate(..., t, y)` returns the stop time; with only the built-in end-time checker, that stop time must be the requested target time `t`.
// valid input: Build a valid one-dimensional ODE with no events, choose `nSteps >= 2`, positive `minStep < maxStep`, distinct `t0` and `t`, and a one-element initial state array.
int nSteps = data.consumeInt(2, 6);
double minStep = data.consumeInt(1, 5) * 1.0e-3;
double maxStep = minStep * data.consumeInt(10, 100);
double t0 = data.consumeInt(-50, 50) / 10.0;
double delta = data.consumeInt(-50, 50) / 10.0;
if (delta == 0.0) {
  delta = 0.5;
}
double t = t0 + delta;
double[] y0 = new double[] { data.consumeInt(-100, 100) / 10.0 };
double[] y = new double[1];
double stop;
try {
  org.apache.commons.math.ode.FirstOrderDifferentialEquations eq = new org.apache.commons.math.ode.FirstOrderDifferentialEquations() {
    public int getDimension() { return 1; }
    public void computeDerivatives(double time, double[] state, double[] yDot) {
      yDot[0] = 0.0;
    }
  };
  org.apache.commons.math.ode.nonstiff.AdamsMoultonIntegrator integ =
      new org.apache.commons.math.ode.nonstiff.AdamsMoultonIntegrator(nSteps, minStep, maxStep, 1.0e-9, 1.0e-9);
  stop = integ.integrate(eq, t0, y0, t, y);
} catch (Exception e) {
  return;
}
double tol = 1.0e-9 * Math.max(1.0, Math.max(Math.abs(stop), Math.abs(t)));
if (Math.abs(stop - t) > tol) {
  throw new RuntimeException("relation integrate-returns-requested-end-time violated: stop=" + stop + " target=" + t);
}

