// relation: constant-derivative-exact-solution
// holds because: The Adams-Moulton class javadoc gives the step formulas for y_{n+1}; when the derivative is constant, every listed formula reduces to y_{n+1} = y_n + h*c. Therefore, for an ODE with constant derivative and no events, a correct implementation must return the exact affine solution at the requested target time.
// valid input: Choose dimension 1..4, nSteps 2..6, a nonzero time interval in either direction, arbitrary initial state, and a constant derivative vector. Use positive minStep and maxStep with minStep < maxStep so the constructor preconditions hold.
int dim = data.consumeInt(1, 4);
int nSteps = data.consumeInt(2, 6);
double t0 = data.consumeInt(-20, 20);
int deltaInt = data.consumeInt(-20, 20);
if (deltaInt == 0) deltaInt = 1;
double t = t0 + deltaInt;
double[] y0 = new double[dim];
double[] c = new double[dim];
for (int i = 0; i < dim; ++i) {
  y0[i] = data.consumeInt(-50, 50);
  c[i] = data.consumeInt(-20, 20);
}
double range = Math.abs(t - t0);
double minStep = 1.0e-6 * range + 1.0e-12;
double maxStep = range;
if (maxStep <= minStep) maxStep = minStep * 10.0;
org.apache.commons.math.ode.FirstOrderDifferentialEquations eq = new org.apache.commons.math.ode.FirstOrderDifferentialEquations() {
  public int getDimension() { return dim; }
  public void computeDerivatives(double time, double[] y, double[] yDot) {
    for (int i = 0; i < dim; ++i) {
      yDot[i] = c[i];
    }
  }
};
double[] y = new double[dim];
double stop;
try {
  org.apache.commons.math.ode.nonstiff.AdamsMoultonIntegrator integ =
      new org.apache.commons.math.ode.nonstiff.AdamsMoultonIntegrator(nSteps, minStep, maxStep, 1.0e-9, 1.0e-9);
  stop = integ.integrate(eq, t0, y0, t, y);
} catch (Exception e) {
  return;
}
double stopScale = Math.max(1.0, Math.max(Math.abs(stop), Math.abs(t)));
if (Math.abs(stop - t) > 1.0e-9 * stopScale) {
  throw new RuntimeException("relation constant-derivative-exact-solution violated: stopTime=" + stop + " target=" + t);
}
for (int i = 0; i < dim; ++i) {
  double expected = y0[i] + (t - t0) * c[i];
  double scale = Math.max(1.0, Math.max(Math.abs(y[i]), Math.abs(expected)));
  if (Math.abs(y[i] - expected) > 1.0e-9 * scale) {
    throw new RuntimeException("relation constant-derivative-exact-solution violated at index " + i + ": got=" + y[i] + " expected=" + expected);
  }
}

