package org.apache.commons.math.special;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static boolean differs(double actual, double expected, double tol) {
        return Math.abs(actual - expected) > tol;
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        data.consumeBoolean();

        double pinnedP;
        double pinnedQ;
        try {
            pinnedP = Gamma.regularizedGammaP(1.0, 1.0);
            pinnedQ = Gamma.regularizedGammaQ(1.0, 1.0);
        } catch (Exception e) {
            return;
        }

        {
            double expected = 0.632120558828558;
            double tol = 10e-15;
            // Trusted lifted oracle from GammaTest.testRegularizedGammaPositivePositive:
            // the real public API call Gamma.regularizedGammaP(1.0, 1.0) must equal
            // the hard-coded expected value 0.632120558828558 within 10e-15.
            if (differs(pinnedP, expected, tol)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:pinned-p-1-1] semantic mismatch: Gamma.regularizedGammaP(1.0,1.0)="
                        + pinnedP + " expected=" + expected + " tol=" + tol);
            }
        }

        {
            double expected = 1.0 - pinnedQ;
            double tol = 10e-15;
            // Trusted lifted oracle from the same helper method:
            // for the same valid input, the test asserts actualP == 1.0 - actualQ.
            // This also serves as the mandatory post-condition/metamorphic check:
            // a patch that merely masks or reroutes one branch while returning the
            // wrong related quantity violates this complement relation observably.
            if (differs(pinnedP, expected, tol)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:pinned-complement-1-1] semantic mismatch: P(1.0,1.0)="
                        + pinnedP + " but 1-Q(1.0,1.0)=" + expected + " tol=" + tol);
            }
        }

        double a = 0.1 + (data.consumeInt(0, 10000) / 100.0);
        double ratio = data.consumeInt(0, 1000) / 1000.0;
        double x = a * ratio;
        int epsPower = data.consumeInt(6, 12);
        double epsilon = Math.pow(10.0, -epsPower);
        int maxIterations = data.consumeInt(1000, 20000);

        double pExplicit;
        double qExplicit;
        try {
            pExplicit = Gamma.regularizedGammaP(a, x, epsilon, maxIterations);
            qExplicit = Gamma.regularizedGammaQ(a, x, epsilon, maxIterations);
        } catch (Exception e) {
            return;
        }

        {
            double lhs = pExplicit + qExplicit;
            double rhs = 1.0;
            double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(lhs), Math.abs(rhs)));
            // Documented contract / code relation: regularizedGammaQ is the complementary
            // quantity to regularizedGammaP, and the shown implementation directly uses
            // ret = 1.0 - regularizedGammaP(...) on valid inputs. For the same explicit
            // overload parameters, P(a,x,eps,iters) + Q(a,x,eps,iters) must therefore be 1.
            // Inputs are fenced valid by construction (a > 0, x >= 0, moderate epsilon,
            // moderate iteration cap), and x <= a ensures the series path in P is exercised.
            if (differs(lhs, rhs, tol)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:explicit-complement] metamorphic violation: P+Q must equal 1 for a="
                        + a + " x=" + x + " epsilon=" + epsilon + " maxIterations="
                        + maxIterations + " lhs=" + lhs + " rhs=" + rhs + " tol=" + tol);
            }
        }

        double pDefault;
        double qDefault;
        try {
            pDefault = Gamma.regularizedGammaP(a, x);
            qDefault = Gamma.regularizedGammaQ(a, x);
        } catch (Exception e) {
            return;
        }

        {
            double lhs = pDefault;
            double rhs = 1.0 - qDefault;
            double tol = 1e-12 * Math.max(1.0, Math.max(Math.abs(lhs), Math.abs(rhs)));
            // Second real-call consistency check through sibling overloads on the same API:
            // the no-arg-overload pair computes the same complementary quantities as above,
            // so the public default-overload results must also satisfy P(a,x) == 1 - Q(a,x)
            // for every valid input. This cross-check can catch a fix that special-cases only
            // one overload or one code path while leaving the reachable helper logic wrong.
            if (differs(lhs, rhs, tol)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:default-complement] consistency violation: P(a,x)=" + lhs
                        + " but 1-Q(a,x)=" + rhs + " for a=" + a + " x=" + x
                        + " tol=" + tol);
            }
        }
    }
