package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        final DiagnosticType fooType =
                DiagnosticType.error("TEST_FOO", "error description here");

        String fuzzLine = data.consumeAsciiString(64);
        if (fuzzLine.indexOf('\n') >= 0 || fuzzLine.indexOf('\r') >= 0) {
            fuzzLine = fuzzLine.replace('\n', ' ').replace('\r', ' ');
        }
        if (fuzzLine.length() == 0) {
            fuzzLine = "x";
        }

        boolean useGroundTruth = data.consumeBoolean();
        String sourceLine = useGroundTruth ? "assert (1;" : fuzzLine;
        int charno = useGroundTruth ? 10 : sourceLine.length();

        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        JSSourceFile input;
        try {
            input = JSSourceFile.fromCode("javascript/complex.js", sourceLine);
            compiler.init(new JSSourceFile[0], new JSSourceFile[] {input}, options);
        } catch (Throwable t) {
            return;
        }

        LightweightMessageFormatter formatter;
        try {
            formatter = new LightweightMessageFormatter(compiler);
        } catch (Throwable t) {
            return;
        }

        JSError error;
        try {
            error = JSError.make("javascript/complex.js", 1, charno, fooType);
        } catch (Throwable t) {
            return;
        }

        final String actual;
        try {
            actual = formatter.formatError(error);
        } catch (Throwable t) {
            return;
        }

        if (useGroundTruth) {
            String expected =
                    "javascript/complex.js:1: ERROR - error description here\n"
                            + "assert (1;\n"
                            + "          ^\n";
            String actualNorm = actual == null ? "null" : actual.replaceAll("\\s+", "");
            String expectedNorm = expected.replaceAll("\\s+", "");
            if (!expectedNorm.equals(actualNorm)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:testFormatErrorSpaceEndOfLine1] semantic mismatch: expected="
                                + expectedNorm
                                + " actual="
                                + actualNorm);
            }
        }

        try {
            String dynamicExpected =
                    "javascript/complex.js:1: ERROR - error description here\n"
                            + sourceLine
                            + "\n"
                            + sourceLine
                            + "^\n";
            String actualNorm = actual == null ? "null" : actual.replaceAll("\\s+", "");
            String expectedNorm = dynamicExpected.replaceAll("\\s+", "");
            /*
             * Contract justification: the patched method's own comment states
             * "charno == sourceExpert.length() means something is missing at the end of the line",
             * and the code appends padding plus "^\n" for LINE excerpts. By construction here,
             * excerpt is LINE (the public constructor defaults to LINE), sourceExcerpt is non-null,
             * and charno == sourceLine.length(), so every correct implementation must render the
             * caret-at-end line. A patch that merely skips the branch or deletes the append silently
             * violates this observable post-condition.
             */
            if (!expectedNorm.equals(actualNorm)) {
                throw new RuntimeException(
                        "[oracle:end-of-line-caret] metamorphic violation: caret at end-of-line missing or wrong input="
                                + sourceLine
                                + " lhs="
                                + actualNorm
                                + " rhs="
                                + expectedNorm);
            }
        } catch (Throwable t) {
            if (t instanceof RuntimeException) {
                throw (RuntimeException) t;
            }
            return;
        }

        try {
            /*
             * Contract justification: JSError.format(CheckLevel.ERROR, formatter) is the public
             * sibling API for formatting the same error at ERROR level, so for any correct
             * implementation it must agree with formatter.formatError(error) on the same objects.
             * This exercises the same real formatting path through an alternate public entrypoint.
             */
            String viaSibling = error.format(CheckLevel.ERROR, formatter);
            String lhs = actual == null ? "null" : actual.replaceAll("\\s+", "");
            String rhs = viaSibling == null ? "null" : viaSibling.replaceAll("\\s+", "");
            if (!lhs.equals(rhs)) {
                throw new RuntimeException(
                        "[oracle:sibling-api-agreement] metamorphic violation: formatError disagrees with JSError.format input="
                                + sourceLine
                                + " lhs="
                                + lhs
                                + " rhs="
                                + rhs);
            }
        } catch (Throwable t) {
            if (t instanceof RuntimeException) {
                throw (RuntimeException) t;
            }
        }
    }
}

