package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        final DiagnosticType FOO_TYPE =
                DiagnosticType.error("TEST_FOO", "error description here");

        try {
            Compiler compiler = new Compiler();
            CompilerOptions options = new CompilerOptions();
            JSSourceFile extern = JSSourceFile.fromCode("externs.js", "");
            JSSourceFile input =
                    JSSourceFile.fromCode("javascript/complex.js", "assert (1;");
            compiler.init(new JSSourceFile[] {extern}, new JSSourceFile[] {input}, options);

            JSError error = JSError.make("javascript/complex.js", 1, 10, FOO_TYPE);
            LightweightMessageFormatter formatter = new LightweightMessageFormatter(compiler);

            String actual = formatter.formatError(error);
            String expected =
                    "javascript/complex.js:1: ERROR - error description here\n"
                            + "assert (1;\n"
                            + "          ^\n";

            String normActual = actual == null ? "null" : actual.replaceAll("\\s+", "");
            String normExpected = expected.replaceAll("\\s+", "");

            if (!normExpected.equals(normActual)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:ground-truth] semantic mismatch: expected="
                                + expected
                                + " actual="
                                + actual);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }

        String prefix = data.consumeAsciiString(64);
        if (prefix == null) {
            return;
        }
        prefix = prefix.replace("\n", "").replace("\r", "");
        if (prefix.length() == 0) {
            prefix = "x";
        }

        try {
            Compiler compilerBase = new Compiler();
            CompilerOptions optionsBase = new CompilerOptions();
            compilerBase.init(
                    new JSSourceFile[] {JSSourceFile.fromCode("externs.js", "")},
                    new JSSourceFile[] {JSSourceFile.fromCode("javascript/complex.js", prefix)},
                    optionsBase);

            Compiler compilerExtended = new Compiler();
            CompilerOptions optionsExtended = new CompilerOptions();
            String extended = prefix + "X";
            compilerExtended.init(
                    new JSSourceFile[] {JSSourceFile.fromCode("externs.js", "")},
                    new JSSourceFile[] {JSSourceFile.fromCode("javascript/complex.js", extended)},
                    optionsExtended);

            JSError eolError =
                    JSError.make("javascript/complex.js", 1, prefix.length(), FOO_TYPE);

            String baseOut = new LightweightMessageFormatter(compilerBase).formatError(eolError);
            String extendedOut =
                    new LightweightMessageFormatter(compilerExtended).formatError(eolError);

            boolean baseHasCaret = baseOut != null && baseOut.indexOf('^') >= 0;
            boolean extendedHasCaret = extendedOut != null && extendedOut.indexOf('^') >= 0;

            // Contract justification: the method's own comment states
            // "charno == sourceExpert.length() means something is missing at the end of the line".
            // Therefore, for a fixed prefix and charno at that prefix's end, formatting the exact
            // prefix and formatting the same prefix with one extra visible character must both
            // render a caret marker for that position. A patch that merely makes the end-of-line
            // branch unreachable breaks this observable relation without throwing.
            if (extendedHasCaret && !baseHasCaret) {
                throw new RuntimeException(
                        "[oracle:eol-caret] metamorphic violation: extending source by one visible char preserved the pointed prefix end, so both outputs should render a caret; base="
                                + baseOut
                                + " extended="
                                + extendedOut
                                + " prefix="
                                + prefix);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }
    }
}

