package org.jfree.chart.axis;

import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.Stroke;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;

import org.jfree.chart.ChartFactory;
import org.jfree.chart.JFreeChart;
import org.jfree.chart.plot.CategoryPlot;
import org.jfree.chart.plot.PlotOrientation;
import org.jfree.data.category.DefaultCategoryDataset;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        JFreeChart chart = createChart();
        CategoryPlot plot = null;
        AxisSnapshot domainBefore = null;
        AxisSnapshot rangeBefore = null;
        try {
            plot = chart.getCategoryPlot();
            domainBefore = new AxisSnapshot(plot.getDomainAxis());
            rangeBefore = new AxisSnapshot(plot.getRangeAxis());
        } catch (Exception e) {
            return;
        }

        boolean success = false;
        Exception observed = null;
        try {
            BufferedImage image = new BufferedImage(200, 100, BufferedImage.TYPE_INT_RGB);
            Graphics2D g2 = image.createGraphics();
            try {
                chart.draw(g2, new Rectangle2D.Double(0, 0, 200, 100), null, null);
                success = true;
            } finally {
                g2.dispose();
            }
        } catch (Exception e) {
            observed = e;
            success = false;
        }
        if (!success) {
            throw new FuzzerSecurityIssueLow("[oracle:stacked-null-info-success] semantic mismatch: expected draw(..., null, null) to succeed as in StackedAreaChartTests.testDrawWithNullInfo, but observed exception " + observed, observed);
        }

        AxisSnapshot domainAfter;
        AxisSnapshot rangeAfter;
        try {
            domainAfter = new AxisSnapshot(plot.getDomainAxis());
            rangeAfter = new AxisSnapshot(plot.getRangeAxis());
        } catch (Exception e) {
            return;
        }

        // Contract justification: drawing is a rendering operation; the null/non-null
        // PlotRenderingInfo only controls auxiliary entity bookkeeping, not persistent axis
        // configuration. A band-aid patch that merely skips the failing branch must still not
        // mutate axis getters. This is a hidden-state/read-only post-condition on chart.draw,
        // distinct from previously covered direct drawLabel checks.
        if (!domainBefore.sameAs(domainAfter)) {
            throw new FuzzerSecurityIssueLow("[oracle:chart-draw-domain-axis-readonly] semantic mismatch: domain axis configuration changed after draw with null info");
        }
        if (!rangeBefore.sameAs(rangeAfter)) {
            throw new FuzzerSecurityIssueLow("[oracle:chart-draw-range-axis-readonly] semantic mismatch: range axis configuration changed after draw with null info");
        }

        // Consistency cross-check using a second independently constructed object:
        // two identically constructed charts must expose the same axis configuration after one
        // of them is merely rendered. This catches masked helper/state corruption even if the
        // top-level draw call no longer throws.
        JFreeChart freshChart;
        CategoryPlot freshPlot;
        AxisSnapshot freshDomain;
        AxisSnapshot freshRange;
        try {
            freshChart = createChart();
            freshPlot = freshChart.getCategoryPlot();
            freshDomain = new AxisSnapshot(freshPlot.getDomainAxis());
            freshRange = new AxisSnapshot(freshPlot.getRangeAxis());
        } catch (Exception e) {
            return;
        }
        if (!domainAfter.sameAs(freshDomain)) {
            throw new FuzzerSecurityIssueLow("[oracle:chart-draw-domain-axis-vs-fresh] consistency violation: rendered chart domain axis disagrees with a fresh identically constructed chart");
        }
        if (!rangeAfter.sameAs(freshRange)) {
            throw new FuzzerSecurityIssueLow("[oracle:chart-draw-range-axis-vs-fresh] consistency violation: rendered chart range axis disagrees with a fresh identically constructed chart");
        }

        // Additional valid-by-construction exercise of the patched path through real code:
        // vary image size moderately while still drawing through JFreeChart.draw with null info.
        int w = 50 + Math.abs(data.consumeInt(0, 450));
        int h = 50 + Math.abs(data.consumeInt(0, 250));
        try {
            BufferedImage image2 = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
            Graphics2D g2 = image2.createGraphics();
            try {
                chart.draw(g2, new Rectangle2D.Double(0.0, 0.0, w, h), null, null);
            } finally {
                g2.dispose();
            }
        } catch (Exception e) {
            throw new FuzzerSecurityIssueLow("[oracle:fuzzed-null-info-success] semantic mismatch: draw with null info failed for valid moderate size " + w + "x" + h, e);
        }
    }

    private static JFreeChart createChart() {
        DefaultCategoryDataset dataset = new DefaultCategoryDataset();
        dataset.addValue(1.0, "Series 1", "Category 1");
        dataset.addValue(4.0, "Series 1", "Category 2");
        dataset.addValue(3.0, "Series 1", "Category 3");
        dataset.addValue(5.0, "Series 2", "Category 1");
        dataset.addValue(7.0, "Series 2", "Category 2");
        dataset.addValue(6.0, "Series 2", "Category 3");
        dataset.addValue(4.0, "Series 3", "Category 1");
        dataset.addValue(3.0, "Series 3", "Category 2");
        dataset.addValue(2.0, "Series 3", "Category 3");
        return ChartFactory.createStackedAreaChart(
                "Stacked Area Chart",
                "Category",
                "Value",
                dataset,
                PlotOrientation.VERTICAL,
                true,
                true,
                false);
    }

    private static final class AxisSnapshot {
        private final String label;
        private final boolean visible;
        private final java.awt.Font labelFont;
        private final Paint labelPaint;
        private final org.jfree.chart.util.RectangleInsets labelInsets;
        private final double labelAngle;
        private final String labelToolTip;
        private final String labelURL;
        private final Paint axisLinePaint;
        private final Stroke axisLineStroke;
        private final java.awt.Font tickLabelFont;
        private final org.jfree.chart.util.RectangleInsets tickLabelInsets;
        private final Paint tickLabelPaint;
        private final double tickMarkInsideLength;
        private final double tickMarkOutsideLength;
        private final Paint tickMarkPaint;
        private final Stroke tickMarkStroke;
        private final double fixedDimension;
        private final org.jfree.chart.plot.Plot plot;

        AxisSnapshot(Axis axis) {
            this.label = axis.getLabel();
            this.visible = axis.isVisible();
            this.labelFont = axis.getLabelFont();
            this.labelPaint = axis.getLabelPaint();
            this.labelInsets = axis.getLabelInsets();
            this.labelAngle = axis.getLabelAngle();
            this.labelToolTip = axis.getLabelToolTip();
            this.labelURL = axis.getLabelURL();
            this.axisLinePaint = axis.getAxisLinePaint();
            this.axisLineStroke = axis.getAxisLineStroke();
            this.tickLabelFont = axis.getTickLabelFont();
            this.tickLabelInsets = axis.getTickLabelInsets();
            this.tickLabelPaint = axis.getTickLabelPaint();
            this.tickMarkInsideLength = axis.getTickMarkInsideLength();
            this.tickMarkOutsideLength = axis.getTickMarkOutsideLength();
            this.tickMarkPaint = axis.getTickMarkPaint();
            this.tickMarkStroke = axis.getTickMarkStroke();
            this.fixedDimension = axis.getFixedDimension();
            this.plot = axis.getPlot();
        }

        boolean sameAs(AxisSnapshot that) {
            return this.visible == that.visible
                    && safeEq(this.label, that.label)
                    && safeEq(this.labelFont, that.labelFont)
                    && safeEq(this.labelPaint, that.labelPaint)
                    && safeEq(this.labelInsets, that.labelInsets)
                    && Double.compare(this.labelAngle, that.labelAngle) == 0
                    && safeEq(this.labelToolTip, that.labelToolTip)
                    && safeEq(this.labelURL, that.labelURL)
                    && safeEq(this.axisLinePaint, that.axisLinePaint)
                    && safeEq(this.axisLineStroke, that.axisLineStroke)
                    && safeEq(this.tickLabelFont, that.tickLabelFont)
                    && safeEq(this.tickLabelInsets, that.tickLabelInsets)
                    && safeEq(this.tickLabelPaint, that.tickLabelPaint)
                    && Double.compare(this.tickMarkInsideLength, that.tickMarkInsideLength) == 0
                    && Double.compare(this.tickMarkOutsideLength, that.tickMarkOutsideLength) == 0
                    && safeEq(this.tickMarkPaint, that.tickMarkPaint)
                    && safeEq(this.tickMarkStroke, that.tickMarkStroke)
                    && Double.compare(this.fixedDimension, that.fixedDimension) == 0
                    && this.plot == that.plot;
        }
    }

    private static boolean safeEq(Object a, Object b) {
        return a == b || (a != null && a.equals(b));
    }
}

