package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        MannWhitneyUTest testStatistic = new MannWhitneyUTest();

        double regressionP;
        try {
            double[] d1 = new double[1500];
            double[] d2 = new double[1500];
            for (int i = 0; i < 1500; i++) {
                d1[i] = 2.0 * i;
                d2[i] = 2.0 * i + 1.0;
            }
            regressionP = testStatistic.mannWhitneyUTest(d1, d2);
        } catch (Throwable t) {
            return;
        }
        if (!(regressionP > 0.1)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:big-dataset-regression] semantic mismatch: mannWhitneyUTest(d1,d2)="
                    + regressionP + " but testBigDataSet requires result > 0.1");
        }

        int n = data.consumeInt(46341, 47000);
        double probabilityP;
        try {
            double[] x = new double[n];
            double[] y = new double[n];
            for (int i = 0; i < n; i++) {
                x[i] = i;
                y[i] = i + n + 1.0;
            }
            probabilityP = testStatistic.mannWhitneyUTest(x, y);
        } catch (Throwable t) {
            return;
        }
        // Contract justification: mannWhitneyUTest returns a two-sided asymptotic p-value / observed significance level,
