package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.util.FastMath;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        MannWhitneyUTest testStatistic = new MannWhitneyUTest();

        int shift = data.consumeInt(-1000, 1000);
        int boundaryN = data.consumeBoolean() ? 46340 : 46341;

        double liftedResult;
        try {
            double[] d1 = new double[1500];
            double[] d2 = new double[1500];
            for (int i = 0; i < 1500; i++) {
                d1[i] = 2.0 * i;
                d2[i] = 2.0 * i + 1.0;
            }
            liftedResult = testStatistic.mannWhitneyUTest(d1, d2);
        } catch (Throwable t) {
            return;
        }

        if (!(liftedResult > 0.1)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-big-dataset] semantic mismatch: expected result > 0.1 for the exact regression test input, got "
                            + liftedResult);
        }

        double reportedP;
        double reportedU;
        try {
            double[] x = new double[boundaryN];
            double[] y = new double[boundaryN];
            for (int i = 0; i < boundaryN; i++) {
                x[i] = 2.0 * i + shift;
                y[i] = 2.0 * i + 1.0 + shift;
            }

            reportedP = testStatistic.mannWhitneyUTest(x, y);
            reportedU = testStatistic.mannWhitneyU(x, y);
        } catch (Throwable t) {
            return;
        }

        int n1 = boundaryN;
        int n2 = boundaryN;
        double n1n2prod = (double) n1 * (double) n2;
        double uMin = n1n2prod - reportedU;
        double eu = n1n2prod / 2.0;
        double varU = n1n2prod * (n1 + n2 + 1.0) / 12.0;
        double z = (uMin - eu) / FastMath.sqrt(varU);
        double independentP = 2.0 * new NormalDistribution(0, 1).cumulativeProbability(z);

        /*
         * Sound consistency oracle: mannWhitneyUTest computes an asymptotic p-value
         * from the Mann-Whitney U statistic and the sample sizes. Recomputing that
         * same quantity independently from the public mannWhitneyU result plus the
         * same documented formula must agree for every correct implementation.
         * A band-aid that only masks one symptom but leaves the overflow/root cause
         * in the p-value computation breaks this equality.
         */
        if (Double.doubleToLongBits(reportedP) != Double.doubleToLongBits(independentP)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:boundary-consistency] consistency violation: n="
                            + boundaryN
                            + " shift=" + shift
                            + " reportedP=" + reportedP
                            + " independentP=" + independentP
                            + " reportedU=" + reportedU);
        }
    }
}

