package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math3.exception.ConvergenceException;
import org.apache.commons.math3.exception.MaxCountExceededException;
import org.apache.commons.math3.exception.NoDataException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.stat.ranking.NaNStrategy;
import org.apache.commons.math3.stat.ranking.TiesStrategy;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        MannWhitneyUTest defaultTest = new MannWhitneyUTest();
        MannWhitneyUTest explicitDefaultTest =
                new MannWhitneyUTest(NaNStrategy.FIXED, TiesStrategy.AVERAGE);

        double[] d1 = new double[1500];
        double[] d2 = new double[1500];
        for (int i = 0; i < 1500; i++) {
            d1[i] = 2 * i;
            d2[i] = 2 * i + 1;
        }

        try {
            double result = defaultTest.mannWhitneyUTest(d1, d2);
            if (!(result > 0.1)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:lifted-threshold] semantic mismatch: expected result > 0.1 for the lifted big dataset, actual=" + result);
            }

            double explicitResult = explicitDefaultTest.mannWhitneyUTest(d1, d2);
            if (Double.doubleToLongBits(result) != Double.doubleToLongBits(explicitResult)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:ctor-consistency-seed] consistency violation: default and explicit(FIXED,AVERAGE) constructors disagree on lifted dataset: default="
                                + result + " explicit=" + explicitResult);
            }
        } catch (NullArgumentException | NoDataException | ConvergenceException | MaxCountExceededException e) {
            throw new RuntimeException(e);
        }

        int len1 = data.consumeInt(1, 64);
        int len2 = data.consumeInt(1, 64);
        double[] x = new double[len1];
        double[] y = new double[len2];

        for (int i = 0; i < len1; i++) {
            x[i] = data.consumeInt(-1000, 1000);
        }
        for (int i = 0; i < len2; i++) {
            y[i] = data.consumeInt(-1000, 1000);
        }

        double pDefault;
        double pExplicit;
        double uXY;
        double uYX;
        try {
            pDefault = defaultTest.mannWhitneyUTest(x, y);
            pExplicit = explicitDefaultTest.mannWhitneyUTest(x, y);
            uXY = defaultTest.mannWhitneyU(x, y);
            uYX = defaultTest.mannWhitneyU(y, x);
        } catch (Throwable t) {
            return;
        }

        if (Double.doubleToLongBits(pDefault) != Double.doubleToLongBits(pExplicit)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:ctor-consistency-fuzz] consistency violation: default and explicit(FIXED,AVERAGE) constructors disagree input="
                            + summarize(x, y) + " default=" + pDefault + " explicit=" + pExplicit);
        }

        double expectedTotal = ((double) len1) * ((double) len2);
        double actualTotal = uXY + uYX;
        if (Math.abs(actualTotal - expectedTotal) > 1e-9) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:u-complement] consistency violation: U(x,y)+U(y,x) must equal n1*n2 input="
                            + summarize(x, y) + " lhs=" + actualTotal + " rhs=" + expectedTotal);
        }
    }

    private static String summarize(double[] x, double[] y) {
        StringBuilder sb = new StringBuilder();
        sb.append("x[");
        appendPrefix(sb, x);
        sb.append("],y[");
        appendPrefix(sb, y);
        sb.append("]");
        return sb.toString();
    }

    private static void appendPrefix(StringBuilder sb, double[] a) {
        sb.append("len=").append(a.length).append(":");
        int n = Math.min(a.length, 6);
        for (int i = 0; i < n; i++) {
            if (i != 0) {
                sb.append(',');
            }
            sb.append(a[i]);
        }
        if (a.length > n) {
            sb.append("...");
        }
    }
}

