package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Arrays;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.util.FastMath;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        MannWhitneyUTest testStatistic = new MannWhitneyUTest();

        double[] d1 = new double[1500];
        double[] d2 = new double[1500];
        for (int i = 0; i < 1500; i++) {
            d1[i] = 2.0 * i;
            d2[i] = 2.0 * i + 1.0;
        }

        double liftedP;
        try {
            liftedP = testStatistic.mannWhitneyUTest(d1, d2);
        } catch (Throwable t) {
            return;
        }
        if (!(liftedP > 0.1)) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-junit-big-dataset] semantic mismatch: mannWhitneyUTest(d1,d2)=" + liftedP + " expected > 0.1");
        }

        int n = data.consumeInt(46341, 47000);
        double[] x = new double[n];
        double[] y = new double[n];
        for (int i = 0; i < n; i++) {
            x[i] = 2.0 * i;
            y[i] = 2.0 * i + 1.0;
        }

        double[] xBefore = x.clone();
        double[] yBefore = y.clone();

        double apiP;
        try {
            apiP = testStatistic.mannWhitneyUTest(x, y);
        } catch (Throwable t) {
            return;
        }

        if (!Arrays.equals(x, xBefore) || !Arrays.equals(y, yBefore)) {
            throw new FuzzerSecurityIssueLow("[oracle:read-only-inputs] semantic mismatch: MannWhitneyUTest mutated input arrays");
        }

        double expectedP;
        try {
            /*
             * Sound oracle: for x[i]=2*i and y[i]=2*i+1, all values are distinct and the combined
             * order is exactly x0<y0<x1<y1<... . Therefore the Mann-Whitney U for x is known by
             * construction: U1 = count of pairs (xi > yj) = n(n-1)/2, so Umin = n(n-1)/2.
             * The public method under test is documented/implemented as the two-sided asymptotic
             * p-value using the normal approximation, so for this canonical family the expected
             * p-value is independently determined from that closed-form U and the same real library
             * distribution class used by Commons Math.
             */
            double nn = (double) n * (double) n;
            double uMin = ((double) n) * ((double) n - 1.0) / 2.0;
            double eu = nn / 2.0;
            double varU = nn * (2.0 * n + 1.0) / 12.0;
            double z = (uMin - eu) / FastMath.sqrt(varU);
            expectedP = 2.0 * new NormalDistribution(0.0, 1.0).cumulativeProbability(z);
        } catch (Throwable t) {
            return;
        }

        if (!(Double.doubleToLongBits(apiP) == Double.doubleToLongBits(expectedP))) {
            throw new FuzzerSecurityIssueLow("[oracle:canonical-parity-closed-form] consistency violation: API p-value disagrees with independently derived asymptotic p-value for canonical alternating ranks; n=" + n + " apiP=" + apiP + " expectedP=" + expectedP);
        }

        double apiP2;
        try {
            /*
             * Sound hidden-state/post-condition check: this API is a statistical query over the
             * provided samples. A correct implementation is read-only, so repeating the same query
             * on the same receiver and same unchanged inputs must return the same value.
             * A throw-deleting or state-corrupting patch could mask one call yet leave internal
             * state inconsistent across repeated calls.
             */
            apiP2 = testStatistic.mannWhitneyUTest(x, y);
        } catch (Throwable t) {
            return;
        }
        if (!(Double.doubleToLongBits(apiP) == Double.doubleToLongBits(apiP2))) {
            throw new FuzzerSecurityIssueLow("[oracle:repeatability-same-query] consistency violation: repeated mannWhitneyUTest on same receiver/input changed result; first=" + apiP + " second=" + apiP2 + " n=" + n);
        }
    }
}

