package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final class Circle implements DifferentiableMultivariateVectorialFunction {
        private final ArrayList<Point2D.Double> points;

        Circle() {
            points = new ArrayList<Point2D.Double>();
        }

        void addPoint(double px, double py) {
            points.add(new Point2D.Double(px, py));
        }

        int getN() {
            return points.size();
        }

        double getRadius(Point2D.Double center) {
            double r = 0.0;
            for (Point2D.Double p : points) {
                r += p.distance(center);
            }
            return r / points.size();
        }

        public double[] value(double[] variables) throws FunctionEvaluationException {
            Point2D.Double center = new Point2D.Double(variables[0], variables[1]);
            double radius = getRadius(center);
            double[] residuals = new double[points.size()];
            for (int i = 0; i < residuals.length; ++i) {
                residuals[i] = points.get(i).distance(center) - radius;
            }
            return residuals;
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] variables) throws FunctionEvaluationException {
                    Point2D.Double center = new Point2D.Double(variables[0], variables[1]);
                    double dRdX = 0.0;
                    double dRdY = 0.0;
                    for (Point2D.Double pk : points) {
                        double dk = pk.distance(center);
                        dRdX += (center.x - pk.x) / dk;
                        dRdY += (center.y - pk.y) / dk;
                    }
                    dRdX /= points.size();
                    dRdY /= points.size();

                    double[][] jacobian = new double[points.size()][2];
                    for (int i = 0; i < jacobian.length; ++i) {
                        Point2D.Double pi = points.get(i);
                        double di = pi.distance(center);
                        jacobian[i][0] = (center.x - pi.x) / di - dRdX;
                        jacobian[i][1] = (center.y - pi.y) / di - dRdY;
                    }
                    return jacobian;
                }
            };
        }
    }

    private static final class LinearTwoResiduals implements DifferentiableMultivariateVectorialFunction {
        public double[] value(double[] p) throws FunctionEvaluationException {
            return new double[] { p[0], p[0] };
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] p) throws FunctionEvaluationException {
                    return new double[][] { { 1.0 }, { 1.0 } };
                }
            };
        }
    }

    private static void checkClose(String id, String what, double expected, double actual, double tol) {
        if (!(Math.abs(expected - actual) <= tol)) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "] semantic mismatch: " + what
                    + " expected=" + expected + " actual=" + actual + " tol=" + tol);
        }
    }

    private static void checkTrue(String id, String what, boolean condition) {
        if (!condition) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "] semantic mismatch: " + what);
        }
    }

    private static void runLiftedCircleTest() throws FunctionEvaluationException, OptimizationException {
        Circle circle = new Circle();
        circle.addPoint(30.0, 68.0);
        circle.addPoint(50.0, -6.0);
        circle.addPoint(110.0, -20.0);
        circle.addPoint(35.0, 15.0);
        circle.addPoint(45.0, 97.0);

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        VectorialPointValuePair optimum =
                optimizer.optimize(circle,
                        new double[] { 0, 0, 0, 0, 0 },
                        new double[] { 1, 1, 1, 1, 1 },
                        new double[] { 98.680, 47.345 });

        checkTrue("lift-evals", "optimizer.getEvaluations() < 10, actual=" + optimizer.getEvaluations(),
                optimizer.getEvaluations() < 10);
        checkTrue("lift-jac-evals", "optimizer.getJacobianEvaluations() < 10, actual=" + optimizer.getJacobianEvaluations(),
                optimizer.getJacobianEvaluations() < 10);

        double rms = optimizer.getRMS();
        checkClose("lift-rms", "Math.sqrt(circle.getN()) * rms",
                1.768262623567235, Math.sqrt(circle.getN()) * rms, 1.0e-10);

        Point2D.Double center = new Point2D.Double(optimum.getPointRef()[0], optimum.getPointRef()[1]);
        checkClose("lift-radius", "circle.getRadius(center)",
                69.96016176931406, circle.getRadius(center), 1.0e-10);
        checkClose("lift-center-x", "center.x", 96.07590211815305, center.x, 1.0e-10);
        checkClose("lift-center-y", "center.y", 48.13516790438953, center.y, 1.0e-10);

        double[][] cov = optimizer.getCovariances();
        checkClose("lift-cov00", "cov[0][0]", 1.839, cov[0][0], 0.001);
        checkClose("lift-cov01", "cov[0][1]", 0.731, cov[0][1], 0.001);
        checkClose("lift-cov-sym", "cov[1][0]", cov[0][1], cov[1][0], 1.0e-14);
        checkClose("lift-cov11", "cov[1][1]", 0.786, cov[1][1], 0.001);

        double[] errors = optimizer.guessParametersErrors();
        checkClose("lift-err0", "errors[0]", 1.384, errors[0], 0.001);
        checkClose("lift-err1", "errors[1]", 0.905, errors[1], 0.001);

        // Documented guarantee: getRMS returns sqrt(c / n), where c is the minimized criterion.
        // Therefore getChiSquare() must equal n * getRMS()^2. A patch that silently corrupts
        // chi-square bookkeeping or makes the reader return stale state violates this even if no throw occurs.
        double chi1a = optimizer.getChiSquare();
        double rms1a = optimizer.getRMS();
        double evalBefore = optimizer.getEvaluations();
        double jacBefore = optimizer.getJacobianEvaluations();
        double iterBefore = optimizer.getIterations();
        double chi1b = optimizer.getChiSquare();
        double rms1b = optimizer.getRMS();
        checkClose("post-reader-chi-stable", "repeated getChiSquare()", chi1a, chi1b, 0.0);
        checkClose("post-reader-rms-stable", "repeated getRMS()", rms1a, rms1b, 0.0);
        checkClose("post-reader-evals-stable", "getEvaluations unchanged by readers", evalBefore, optimizer.getEvaluations(), 0.0);
        checkClose("post-reader-jac-stable", "getJacobianEvaluations unchanged by readers", jacBefore, optimizer.getJacobianEvaluations(), 0.0);
        checkClose("post-reader-iters-stable", "getIterations unchanged by readers", iterBefore, optimizer.getIterations(), 0.0);

        double expectedChi1 = circle.getN() * rms1a * rms1a;
        double tol1 = 1e-9 * Math.max(1.0, Math.max(Math.abs(chi1a), Math.abs(expectedChi1)));
        checkClose("post-chi-rms-1", "getChiSquare() == n * getRMS()^2", expectedChi1, chi1a, tol1);

        // Same state, but computed from the residual vector through the real model.
        double[] residuals1 = circle.value(optimum.getPointRef());
        double sumWeighted1 = 0.0;
        for (double residual : residuals1) {
            sumWeighted1 += residual * residual;
        }
        double tolResidual1 = 1e-9 * Math.max(1.0, Math.max(Math.abs(chi1a), Math.abs(sumWeighted1)));
        checkClose("post-weighted-sum-1", "chi-square equals weighted residual sum", sumWeighted1, chi1a, tolResidual1);

        double r = circle.getRadius(center);
        for (double d = 0; d < 2 * Math.PI; d += 0.01) {
            circle.addPoint(center.x + r * Math.cos(d), center.y + r * Math.sin(d));
        }
        double[] target = new double[circle.getN()];
        Arrays.fill(target, 0.0);
        double[] weights = new double[circle.getN()];
        Arrays.fill(weights, 2.0);

        optimum = optimizer.optimize(circle, target, weights, new double[] { 98.680, 47.345 });

        cov = optimizer.getCovariances();
        checkClose("lift2-cov00", "cov[0][0]", 0.0016, cov[0][0], 0.001);
        checkClose("lift2-cov01", "cov[0][1]", 3.2e-7, cov[0][1], 1.0e-9);
        checkClose("lift2-cov-sym", "cov[1][0]", cov[0][1], cov[1][0], 1.0e-14);
        checkClose("lift2-cov11", "cov[1][1]", 0.0016, cov[1][1], 0.001);

        errors = optimizer.guessParametersErrors();
        checkClose("lift2-err0", "errors[0]", 0.004, errors[0], 0.001);
        checkClose("lift2-err1", "errors[1]", 0.004, errors[1], 0.001);

        double chi2 = optimizer.getChiSquare();
        double rms2 = optimizer.getRMS();
        double expectedChi2 = circle.getN() * rms2 * rms2;
        double tol2 = 1e-9 * Math.max(1.0, Math.max(Math.abs(chi2), Math.abs(expectedChi2)));
        checkClose("post-chi-rms-2", "getChiSquare() == n * getRMS()^2", expectedChi2, chi2, tol2);

        double[] residuals2 = circle.value(optimum.getPointRef());
        double sumWeighted2 = 0.0;
        for (double residual : residuals2) {
            sumWeighted2 += 2.0 * residual * residual;
        }
        double tolResidual2 = 1e-9 * Math.max(1.0, Math.max(Math.abs(chi2), Math.abs(sumWeighted2)));
        checkClose("post-weighted-sum-2", "chi-square equals weighted residual sum", sumWeighted2, chi2, tolResidual2);
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        try {
            runLiftedCircleTest();
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        }

        int t1 = data.consumeInt(-50, 50);
        int t2 = data.consumeInt(-50, 50);
        int w1i = data.consumeInt(1, 20);
        int w2i = data.consumeInt(1, 20);
        int s = data.consumeInt(-50, 50);

        LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
        LinearTwoResiduals f = new LinearTwoResiduals();

        VectorialPointValuePair result;
        double chi;
        double rms;
        try {
            result = opt.optimize(
                    f,
                    new double[] { (double) t1, (double) t2 },
                    new double[] { (double) w1i, (double) w2i },
                    new double[] { (double) s });
            chi = opt.getChiSquare();
            rms = opt.getRMS();
        } catch (Exception e) {
            return;
        }

        double x = result.getPointRef()[0];
        double expectedWeighted = ((double) w1i) * (t1 - x) * (t1 - x) + ((double) w2i) * (t2 - x) * (t2 - x);
        double tolWeighted = 1e-9 * Math.max(1.0, Math.max(Math.abs(chi), Math.abs(expectedWeighted)));
        if (!(Math.abs(chi - expectedWeighted) <= tolWeighted)) {
            throw new FuzzerSecurityIssueLow("relation chiSquare_matches_weighted_residual_sum violated: chi="
                    + chi + " expected=" + expectedWeighted + " x=" + x
                    + " t1=" + t1 + " t2=" + t2 + " w1=" + w1i + " w2=" + w2i);
        }

        // Documented guarantee: getRMS is sqrt(c/n), so for this 2-residual problem
        // chi-square must equal 2 * getRMS()^2. This catches silent wrong bookkeeping.
        double expectedFromRms = 2.0 * rms * rms;
        double tolRms = 1e-9 * Math.max(1.0, Math.max(Math.abs(chi), Math.abs(expectedFromRms)));
        if (!(Math.abs(chi - expectedFromRms) <= tolRms)) {
            throw new FuzzerSecurityIssueLow("relation chiSquare_equals_n_times_rms_squared violated: chi="
                    + chi + " expected=" + expectedFromRms + " rms=" + rms
                    + " t1=" + t1 + " t2=" + t2 + " w1=" + w1i + " w2=" + w2i);
        }

        // Hidden-state reader check: repeated get* readers must not mutate observable counters.
        int evalsBefore = opt.getEvaluations();
        int jacBefore = opt.getJacobianEvaluations();
        int itersBefore = opt.getIterations();
        double chiAgain = opt.getChiSquare();
        double rmsAgain = opt.getRMS();
        if (chiAgain != chi || rmsAgain != rms
                || opt.getEvaluations() != evalsBefore
                || opt.getJacobianEvaluations() != jacBefore
                || opt.getIterations() != itersBefore) {
            throw new FuzzerSecurityIssueLow("relation reader_non_mutation violated: chi=" + chi + " chiAgain=" + chiAgain
                    + " rms=" + rms + " rmsAgain=" + rmsAgain
                    + " evalsBefore=" + evalsBefore + " evalsAfter=" + opt.getEvaluations()
                    + " jacBefore=" + jacBefore + " jacAfter=" + opt.getJacobianEvaluations()
                    + " itersBefore=" + itersBefore + " itersAfter=" + opt.getIterations());
        }
    }
}

