package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Arrays;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        runLiftedCircleFittingOracle();
        runGeneralizedLinearRelations(data);
    }

    private static void runLiftedCircleFittingOracle() {
        try {
            Circle circle = new Circle();
            circle.addPoint(30.0, 68.0);
            circle.addPoint(50.0, -6.0);
            circle.addPoint(110.0, -20.0);
            circle.addPoint(35.0, 15.0);
            circle.addPoint(45.0, 97.0);

            LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
            VectorialPointValuePair optimum =
                    optimizer.optimize(
                            circle,
                            new double[] {0, 0, 0, 0, 0},
                            new double[] {1, 1, 1, 1, 1},
                            new double[] {98.680, 47.345});

            if (!(optimizer.getEvaluations() < 10)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-evals] semantic mismatch: expected optimizer.getEvaluations() < 10 but was "
                                + optimizer.getEvaluations());
            }
            if (!(optimizer.getJacobianEvaluations() < 10)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-jac-evals] semantic mismatch: expected optimizer.getJacobianEvaluations() < 10 but was "
                                + optimizer.getJacobianEvaluations());
            }

            int evalsBeforeGetters = optimizer.getEvaluations();
            int jacBeforeGetters = optimizer.getJacobianEvaluations();
            double chi = optimizer.getChiSquare();
            double rms = optimizer.getRMS();
            int evalsAfterGetters = optimizer.getEvaluations();
            int jacAfterGetters = optimizer.getJacobianEvaluations();
            // Contract justification: these are public get* readers with no mutating semantics in their docs,
            // so merely reading chi-square/RMS must not change observable optimizer counters.
            if (evalsBeforeGetters != evalsAfterGetters || jacBeforeGetters != jacAfterGetters) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:getters-readonly] semantic mismatch: read-only getters changed counters evals "
                                + evalsBeforeGetters + "->" + evalsAfterGetters
                                + ", jacobian " + jacBeforeGetters + "->" + jacAfterGetters);
            }

            assertApprox(
                    "circle-rms",
                    Math.sqrt(circle.getN()) * rms,
                    1.768262623567235,
                    1.0e-10,
                    "sqrt(circle.getN()) * optimizer.getRMS()");
            Point2D.Double center = new Point2D.Double(optimum.getPointRef()[0], optimum.getPointRef()[1]);
            assertApprox(
                    "circle-radius",
                    circle.getRadius(center),
                    69.96016176931406,
                    1.0e-10,
                    "circle.getRadius(center)");
            assertApprox(
                    "circle-center-x",
                    center.x,
                    96.07590211815305,
                    1.0e-10,
                    "center.x");
            assertApprox(
                    "circle-center-y",
                    center.y,
                    48.13516790438953,
                    1.0e-10,
                    "center.y");

            double[][] cov = optimizer.getCovariances();
            assertApprox("circle-cov-00", cov[0][0], 1.839, 0.001, "cov[0][0]");
            assertApprox("circle-cov-01", cov[0][1], 0.731, 0.001, "cov[0][1]");
            assertApprox("circle-cov-sym-1", cov[1][0], cov[0][1], 1.0e-14, "cov[1][0] vs cov[0][1]");
            assertApprox("circle-cov-11", cov[1][1], 0.786, 0.001, "cov[1][1]");

            double[] errors = optimizer.guessParametersErrors();
            assertApprox("circle-err-0", errors[0], 1.384, 0.001, "errors[0]");
            assertApprox("circle-err-1", errors[1], 0.905, 0.001, "errors[1]");

            // Contract justification: getChiSquare is documented as the weighted sum of squared residuals,
            // and getRMS is documented as sqrt(c/n) for the same criterion c; a patch that deletes or corrupts
            // the bookkeeping line can leave both methods callable but make their observable values disagree.
            double expectedChi = weightedResidualSum(circle, optimum.getPointRef(), new double[] {1, 1, 1, 1, 1});
            assertRelative(
                    "circle-chi-weighted-sum",
                    chi,
                    expectedChi,
                    "optimizer.getChiSquare() vs explicit weighted residual sum");
            double expectedFromRms = circle.getN() * rms * rms;
            assertRelative(
                    "circle-chi-rms",
                    chi,
                    expectedFromRms,
                    "optimizer.getChiSquare() vs circle.getN()*rms*rms");

            double r = circle.getRadius(center);
            for (double d = 0; d < 2 * Math.PI; d += 0.01) {
                circle.addPoint(center.x + r * Math.cos(d), center.y + r * Math.sin(d));
            }
            double[] target = new double[circle.getN()];
            Arrays.fill(target, 0.0);
            double[] weights = new double[circle.getN()];
            Arrays.fill(weights, 2.0);

            VectorialPointValuePair optimum2 =
                    optimizer.optimize(circle, target, weights, new double[] {98.680, 47.345});

            cov = optimizer.getCovariances();
            assertApprox("circle2-cov-00", cov[0][0], 0.0016, 0.001, "cov[0][0]");
            assertApprox("circle2-cov-01", cov[0][1], 3.2e-7, 1.0e-9, "cov[0][1]");
            assertApprox("circle2-cov-sym-1", cov[1][0], cov[0][1], 1.0e-14, "cov[1][0] vs cov[0][1]");
            assertApprox("circle2-cov-11", cov[1][1], 0.0016, 0.001, "cov[1][1]");

            errors = optimizer.guessParametersErrors();
            assertApprox("circle2-err-0", errors[0], 0.004, 0.001, "errors[0]");
            assertApprox("circle2-err-1", errors[1], 0.004, 0.001, "errors[1]");

            double chi2 = optimizer.getChiSquare();
            double rms2 = optimizer.getRMS();
            double expectedChi2 = weightedResidualSum(circle, optimum2.getPointRef(), weights);
            assertRelative(
                    "circle2-chi-weighted-sum",
                    chi2,
                    expectedChi2,
                    "optimizer.getChiSquare() vs explicit weighted residual sum after perfect measurements");
            double expectedFromRms2 = circle.getN() * rms2 * rms2;
            assertRelative(
                    "circle2-chi-rms",
                    chi2,
                    expectedFromRms2,
                    "optimizer.getChiSquare() vs circle.getN()*rms*rms after perfect measurements");
        } catch (FunctionEvaluationException e) {
            throw new RuntimeException(e);
        } catch (OptimizationException e) {
            throw new RuntimeException(e);
        }
    }

    private static void runGeneralizedLinearRelations(FuzzedDataProvider data) {
        int t1 = data.consumeInt(-50, 50);
        int t2 = data.consumeInt(-50, 50);
        int w1 = data.consumeInt(1, 20);
        int w2 = data.consumeInt(1, 20);
        int s = data.consumeInt(-50, 50);

        LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
        SimpleDuplicatedVariableFunction f = new SimpleDuplicatedVariableFunction();

        VectorialPointValuePair result;
        double chi;
        double rms;
        int evalsBefore;
        int jacBefore;
        int evalsAfter;
        int jacAfter;

        try {
            result = opt.optimize(
                    f,
                    new double[] {(double) t1, (double) t2},
                    new double[] {(double) w1, (double) w2},
                    new double[] {(double) s});
            evalsBefore = opt.getEvaluations();
            jacBefore = opt.getJacobianEvaluations();
            chi = opt.getChiSquare();
            rms = opt.getRMS();
            evalsAfter = opt.getEvaluations();
            jacAfter = opt.getJacobianEvaluations();
        } catch (Exception e) {
            return;
        }

        if (evalsBefore != evalsAfter || jacBefore != jacAfter) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:linear-getters-readonly] semantic mismatch: getChiSquare/getRMS changed counters evals "
                            + evalsBefore + "->" + evalsAfter + ", jacobian " + jacBefore + "->" + jacAfter);
        }

        double x = result.getPointRef()[0];
        double expectedWeightedSum =
                ((double) w1) * (t1 - x) * (t1 - x) + ((double) w2) * (t2 - x) * (t2 - x);
        // Contract justification: getChiSquare is documented as the sum of weight[i] * residual[i]^2.
        if (!closeRelative(chi, expectedWeightedSum)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:linear-chi-weighted-sum] relation chiSquare_matches_weighted_residual_sum violated: input="
                            + " t1=" + t1 + " t2=" + t2 + " w1=" + w1 + " w2=" + w2 + " s=" + s
                            + " chi=" + chi + " expected=" + expectedWeightedSum + " x=" + x);
        }

        double expectedFromRms = 2.0 * rms * rms;
        // Contract justification: getRMS says RMS = sqrt(c/n) for the minimized criterion c, so c = n*RMS^2.
        if (!closeRelative(chi, expectedFromRms)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:linear-chi-rms] relation chiSquare_equals_n_times_rms_squared violated: input="
                            + " t1=" + t1 + " t2=" + t2 + " w1=" + w1 + " w2=" + w2 + " s=" + s
                            + " chi=" + chi + " expected=" + expectedFromRms + " rms=" + rms);
        }
    }

    private static double weightedResidualSum(
            DifferentiableMultivariateVectorialFunction f, double[] point, double[] weights)
            throws FunctionEvaluationException {
        double[] values = f.value(point);
        double sum = 0.0;
        for (int i = 0; i < values.length && i < weights.length; i++) {
            sum += weights[i] * values[i] * values[i];
        }
        return sum;
    }

    private static void assertApprox(
            String oracleId, double actual, double expected, double tol, String what) {
        if (!(Math.abs(actual - expected) <= tol)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:" + oracleId + "] semantic mismatch: " + what + " expected " + expected + " but was " + actual);
        }
    }

    private static void assertRelative(String oracleId, double actual, double expected, String what) {
        if (!closeRelative(actual, expected)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:" + oracleId + "] semantic mismatch: " + what + " expected " + expected + " but was " + actual);
        }
    }

    private static boolean closeRelative(double a, double b) {
        double tol = 1.0e-9 * Math.max(1.0, Math.max(Math.abs(a), Math.abs(b)));
        return Math.abs(a - b) <= tol;
    }

    private static final class SimpleDuplicatedVariableFunction
            implements DifferentiableMultivariateVectorialFunction {
        public double[] value(double[] p) {
            return new double[] {p[0], p[0]};
        }

