package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.analysis.SinFunction;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        SinFunction f = new SinFunction();

        // Lifted oracle 1 from BrentSolverTest.testBadEndpoints:
        // solver.solve(f, 1, -1) must throw IllegalArgumentException for a bad interval.
        try {
            new BrentSolver().solve(f, 1.0, -1.0);
            throw new FuzzerSecurityIssueLow("[oracle:lifted-bad-interval] semantic mismatch: solve(f,1,-1) completed normally");
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:lifted-bad-interval] semantic mismatch: wrong exception for solve(f,1,-1): " + t.getClass().getName(),
                t);
        }

        // Lifted oracle 2 from BrentSolverTest.testBadEndpoints:
        // solver.solve(f, 1, 1.5) must throw IllegalArgumentException for non-bracketing endpoints.
        try {
            new BrentSolver().solve(f, 1.0, 1.5);
            throw new FuzzerSecurityIssueLow("[oracle:lifted-two-arg-nonbracketing] semantic mismatch: solve(f,1,1.5) completed normally");
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:lifted-two-arg-nonbracketing] semantic mismatch: wrong exception for solve(f,1,1.5): " + t.getClass().getName(),
                t);
        }

        // Lifted oracle 3 from BrentSolverTest.testBadEndpoints, and the ground-truth failing case:
        // solver.solve(f, 1, 1.5, 1.2) must throw IllegalArgumentException.
        try {
            new BrentSolver().solve(f, 1.0, 1.5, 1.2);
            throw new FuzzerSecurityIssueLow("[oracle:lifted-four-arg-nonbracketing] semantic mismatch: solve(f,1,1.5,1.2) completed normally");
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:lifted-four-arg-nonbracketing] semantic mismatch: wrong exception for solve(f,1,1.5,1.2): " + t.getClass().getName(),
                t);
        }

        // Generalized same-sign positive interval inside (0, pi):
        // documented contract says the 4-arg overload throws IllegalArgumentException
        // if the values at min, initial, max have the same sign.
        // For sin(x), every x in (0, pi) has positive value, so all three signs match by construction.
        double left = 0.1 + (data.consumeInt(0, 100) / 100.0);
        double width = 0.2 + (data.consumeInt(0, 100) / 100.0);
        double right = left + width;
        if (right >= 3.0) {
            right = 3.0;
            if (right - left < 0.2) {
                left = right - 0.2;
            }
        }
        double initial = left + (right - left) * (data.consumeInt(1, 99) / 100.0);

        try {
            new BrentSolver().solve(f, left, right);
            throw new FuzzerSecurityIssueLow("[oracle:sibling-two-arg-rejects-same-sign] semantic mismatch: solve(f," + left + "," + right + ") completed normally on a same-sign interval");
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:sibling-two-arg-rejects-same-sign] semantic mismatch: wrong exception for solve(f," + left + "," + right + "): " + t.getClass().getName(),
                t);
        }

        try {
            new BrentSolver().solve(f, left, right, initial);
            throw new FuzzerSecurityIssueLow("[oracle:sibling-four-arg-rejects-same-sign] semantic mismatch: solve(f," + left + "," + right + "," + initial + ") completed normally on three same-sign points");
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:sibling-four-arg-rejects-same-sign] semantic mismatch: wrong exception for solve(f," + left + "," + right + "," + initial + "): " + t.getClass().getName(),
                t);
        }

        // Mandatory metamorphic/post-condition check:
        // The overloads solve(f,min,max) and solve(f,min,max,initial) are documented to solve the same problem.
        // On a genuinely bracketing interval, they must agree on the root. A patch that merely deletes
        // the rejection path or corrupts helper state can still leave one overload inconsistent with the other.
        double min = 3.0;
        double max = 4.0;
        double goodInitial = min + (max - min) * (data.consumeInt(1, 99) / 100.0);

        double fourArgResult;
        double twoArgResult;
        BrentSolver solverA = new BrentSolver();
        BrentSolver solverB = new BrentSolver();
        try {
            fourArgResult = solverA.solve(f, min, max, goodInitial);
            twoArgResult = solverB.solve(f, min, max);
        } catch (Throwable t) {
            return;
        }

        double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(fourArgResult), Math.abs(twoArgResult)));
        if (Math.abs(fourArgResult - twoArgResult) > tol) {
            throw new FuzzerSecurityIssueLow("[oracle:overload-agreement] metamorphic violation: solve(f,min,max,initial) and solve(f,min,max) disagree on same bracketing interval; fourArg=" + fourArgResult + " twoArg=" + twoArgResult + " min=" + min + " max=" + max + " initial=" + goodInitial);
        }

        // Shared-state consistency check:
        // solve(...) returns the computed root and also stores it so getResult() reports the same value.
        // This follows from the solver implementation's setResult(...) / getResult() contract.
        double stored = solverA.getResult();
        if (Double.doubleToLongBits(stored) != Double.doubleToLongBits(fourArgResult)) {
            throw new FuzzerSecurityIssueLow("[oracle:result-state-consistency] consistency violation: returned result and getResult() differ; returned=" + fourArgResult + " stored=" + stored);
        }

        // Additional state check around a rejecting call:
        // solve(...) reads functionValueAccuracy but does not document changing it.
        // A failed validation path should therefore preserve the value set by the caller.
        BrentSolver solverC = new BrentSolver();
        double acc = 1.0e-6 + (data.consumeInt(0, 1000) / 1.0e9);
        solverC.setFunctionValueAccuracy(acc);
        double before = solverC.getFunctionValueAccuracy();
        try {
            solverC.solve(f, left, right, initial);
        } catch (Throwable t) {
            // rejection: ignore, then check whether the supposedly read-only accuracy setting was preserved
        }
        double after = solverC.getFunctionValueAccuracy();
        if (Double.doubleToLongBits(before) != Double.doubleToLongBits(after)) {
            throw new FuzzerSecurityIssueLow("[oracle:function-value-accuracy-stable] consistency violation: functionValueAccuracy changed across solve; before=" + before + " after=" + after);
        }
    }
}

