        boolean missingTwoArgNonBracket = false;
        boolean missingFourArgNonBracket = false;

        try {
            new BrentSolver().solve(f, 1.0, -1.0);
            missingBadInterval = true;
        } catch (IllegalArgumentException expected) {
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-bad-interval-class] wrong exception class", t);
