        }

        try {
            new BrentSolver().solve(f, 1.0, 1.5);
            missingTwoArgNonBracket = true;
        } catch (IllegalArgumentException expected) {
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-two-arg-nonbracketing-class] wrong exception class", t);
        }
        if (missingTwoArgNonBracket) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-two-arg-nonbracketing-class] semantic mismatch: solve(f, 1, 1.5) completed normally");
        }

        try {
            new BrentSolver().solve(f, 1.0, 1.5, 1.2);
            missingFourArgNonBracket = true;
        } catch (IllegalArgumentException expected) {
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-four-arg-nonbracketing-class] wrong exception class", t);
        }
        if (missingFourArgNonBracket) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-four-arg-nonbracketing-class] semantic mismatch: solve(f, 1, 1.5, 1.2) completed normally");
        }

        final double absAcc = Math.pow(10.0, -(2 + data.consumeInt(0, 6)));

        double minRootActual;
        double minRootReported;
        double minRootExpected;
        try {
            BrentSolver solver = new BrentSolver();
            solver.setAbsoluteAccuracy(absAcc);

            minRootExpected = Math.PI;
            final double max = 4.0;
            final double initial = 3.5;
            minRootActual = solver.solve(f, minRootExpected, max, initial);
            minRootReported = solver.getResult();
        } catch (Throwable t) {
            return;
