                            + maxRootExpected + " but got " + maxRootActual);
        }
        if (Double.doubleToLongBits(maxRootReported) != Double.doubleToLongBits(maxRootActual)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:endpoint-max-result-state] consistency violation: getResult()="
                            + maxRootReported + " returned=" + maxRootActual);
        }
    }
