// holds because: ClassUtils.getPackageName(Class<?> cls) returns getPackageName(cls.getName()) for non-null cls according to its visible implementation and matching overload documentation, so the Class and String overloads must agree on equivalent inputs.
// valid input: Choose one valid Class from a small fuzzed set that includes ordinary classes, inner classes, object arrays, and primitive arrays: String.class, java.util.Map.Entry.class, String[][].class, or int[].class.
int pick = data.consumeInt(0, 3);
Class<?> cls;
if (pick == 0) {
    cls = String.class;
} else if (pick == 1) {
    cls = java.util.Map.Entry.class;
} else if (pick == 2) {
    cls = String[][].class;
} else {
    cls = int[].class;
}
String a;
String b;
try {
    a = ClassUtils.getPackageName(cls);
    b = ClassUtils.getPackageName(cls.getName());
} catch (Exception e) {
    return;
}
if (!a.equals(b)) {
    throw new RuntimeException("relation packageName_class_overload_agrees_with_string_overload violated: " + a + " vs " + b + " for " + cls);
}

