package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.Locale;

public class FuzzHarness {
    private static boolean sameLocale(Locale a, Locale b) {
        return a == b || (a != null && a.equals(b));
    }

    private static boolean sameString(String a, String b) {
        return a == b || (a != null && a.equals(b));
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        Locale realDefaultLocale = Locale.getDefault();

        FastDateFormat format1;
        FastDateFormat format2;
        FastDateFormat format3;
        try {
            Locale.setDefault(Locale.US);
            format1 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL, Locale.GERMANY);
            format2 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
            Locale.setDefault(Locale.GERMANY);
            format3 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
        } catch (Throwable t) {
            try {
                Locale.setDefault(realDefaultLocale);
            } catch (Throwable ignored) {
            }
            return;
        }
        try {
            Locale.setDefault(realDefaultLocale);
        } catch (Throwable ignored) {
        }

        // Lifted verbatim from the failing test: explicit Locale.GERMANY must be preserved.
        if (format1.getLocale() != Locale.GERMANY) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-format1-locale] semantic mismatch: expected same locale de_DE for format1, got=" + format1.getLocale());
        }
        // Lifted verbatim from the failing test: the first default-locale lookup under Locale.US must retain Locale.US.
        if (format2.getLocale() != Locale.US) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-format2-locale] semantic mismatch: expected same locale en_US for format2, got=" + format2.getLocale());
        }
        // Lifted verbatim from the failing test: after changing the default locale, a new default-locale lookup must use Locale.GERMANY.
        if (format3.getLocale() != Locale.GERMANY) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-format3-locale] semantic mismatch: expected same locale de_DE for format3, got=" + format3.getLocale());
        }
        // Lifted verbatim from the failing test: distinct logical inputs/default environments must not alias to the same formatter instance.
        if (format1 == format2) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct formatter instances but got identical references");
        }
        // Lifted verbatim from the failing test: changing the default locale must produce a distinct formatter instance.
        if (format2 == format3) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct formatter instances after default-locale change but got identical references");
        }

        int[] styles = new int[] {
            FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT
        };
        Locale[] locales = new Locale[] {
            Locale.US, Locale.GERMANY, Locale.FRANCE
        };

        int dateStyle = styles[data.consumeInt(0, styles.length - 1)];
        int timeStyle = styles[data.consumeInt(0, styles.length - 1)];
        Locale chosen = locales[data.consumeInt(0, locales.length - 1)];

        FastDateFormat dtDefault;
        FastDateFormat dtExplicit;
        String jdkPattern;
        Locale old = Locale.getDefault();
        try {
            Locale.setDefault(chosen);
            dtDefault = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
            dtExplicit = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, chosen);
            jdkPattern = ((SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle, chosen)).toPattern();
        } catch (Throwable t) {
            try {
                Locale.setDefault(old);
            } catch (Throwable ignored) {
            }
            return;
        }
        try {
            Locale.setDefault(old);
        } catch (Throwable ignored) {
        }

        // Contract: getDateTimeInstance(int,int) uses the current default locale; the sibling overload with that same explicit locale
        // must therefore agree on locale and localized pattern. A patch that silently skips/rewrites cache bookkeeping breaks this without throwing.
        if (!sameLocale(dtDefault.getLocale(), dtExplicit.getLocale()) || !sameString(dtDefault.getPattern(), dtExplicit.getPattern())) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:datetime-sibling-agreement] metamorphic violation: default-locale and explicit-locale overloads disagree for chosen="
                    + chosen + " dateStyle=" + dateStyle + " timeStyle=" + timeStyle
                    + " defaultLocale=" + dtDefault.getLocale() + " explicitLocale=" + dtExplicit.getLocale()
                    + " defaultPattern=" + dtDefault.getPattern() + " explicitPattern=" + dtExplicit.getPattern());
        }

        // Consistency cross-check: FastDateFormat.getDateTimeInstance internally derives its pattern from
        // DateFormat.getDateTimeInstance(...).toPattern(); recomputing that pattern independently must match the formatter's reported pattern.
        if (!sameString(dtExplicit.getPattern(), jdkPattern)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:datetime-pattern-recompute] consistency violation: formatter pattern disagrees with independently recomputed JDK localized pattern"
                    + " chosen=" + chosen + " dateStyle=" + dateStyle + " timeStyle=" + timeStyle
                    + " fastPattern=" + dtExplicit.getPattern() + " jdkPattern=" + jdkPattern);
        }

        int dateOnlyStyle = styles[data.consumeInt(0, styles.length - 1)];
        Locale chosenDateLocale = locales[data.consumeInt(0, locales.length - 1)];
        FastDateFormat d1;
        FastDateFormat d2;
        Locale old2 = Locale.getDefault();
        try {
            Locale.setDefault(chosenDateLocale);
            d1 = FastDateFormat.getDateInstance(dateOnlyStyle);
            d2 = FastDateFormat.getDateInstance(dateOnlyStyle, chosenDateLocale);
        } catch (Throwable t) {
            try {
                Locale.setDefault(old2);
            } catch (Throwable ignored) {
            }
            return;
        }
        try {
            Locale.setDefault(old2);
        } catch (Throwable ignored) {
        }

        // Contract from sibling overloads: when the supplied locale equals the current default locale,
        // getDateInstance(style) and getDateInstance(style, locale) must agree on locale and localized pattern.
        if (!sameLocale(d1.getLocale(), d2.getLocale()) || !sameString(d1.getPattern(), d2.getPattern())) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:date-sibling-agreement] metamorphic violation: date overloads disagree for chosen="
                    + chosenDateLocale + " style=" + dateOnlyStyle
                    + " aLocale=" + d1.getLocale() + " bLocale=" + d2.getLocale()
                    + " aPattern=" + d1.getPattern() + " bPattern=" + d2.getPattern());
        }

        int explicitStyle = styles[data.consumeInt(0, styles.length - 1)];
        Locale explicit = locales[data.consumeInt(0, locales.length - 1)];
        Locale other = locales[(data.consumeInt(0, locales.length - 2) + (explicit == locales[0] ? 1 : 0)) % locales.length];
        if (explicit.equals(other)) {
            other = Locale.US.equals(explicit) ? Locale.GERMANY : Locale.US;
        }

        FastDateFormat explicitDateFormat;
        Locale old3 = Locale.getDefault();
        try {
            Locale.setDefault(other);
            explicitDateFormat = FastDateFormat.getDateInstance(explicitStyle, explicit);
        } catch (Throwable t) {
            try {
                Locale.setDefault(old3);
            } catch (Throwable ignored) {
            }
            return;
        }
        try {
            Locale.setDefault(old3);
        } catch (Throwable ignored) {
        }

        // Contract: getDateInstance(style, locale) uses the specified locale, so the result's locale must be that explicit locale,
        // not whichever default locale happened to be installed during the call.
        if (!sameLocale(explicitDateFormat.getLocale(), explicit)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:date-explicit-overrides-default] semantic mismatch: explicit locale did not override default"
                    + " explicit=" + explicit + " defaultDuringCall=" + other + " got=" + explicitDateFormat.getLocale());
        }
    }
}

