// relation: dateInstance_defaultLocaleSiblingAgreement
// holds because: getDateInstance(int style) is documented as getting a date formatter using the specified style in the default time zone and locale; getDateInstance(int style, Locale locale) is the sibling that uses the specified locale in the default time zone. Therefore, when the supplied locale equals the current default locale, the two overloads must agree on the formatter's locale and localized pattern.
// valid input: Choose a valid date style from {FULL, LONG, MEDIUM, SHORT}. Choose one concrete locale from a small fixed set such as Locale.US, Locale.GERMANY, or Locale.FRANCE, then temporarily install it as the default locale before both calls.
int[] styles = new int[]{FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT};
int style = styles[data.consumeInt(0, 3)];
Locale[] locales = new Locale[]{Locale.US, Locale.GERMANY, Locale.FRANCE};
Locale chosen = locales[data.consumeInt(0, locales.length - 1)];
Locale old = Locale.getDefault();
FastDateFormat a;
FastDateFormat b;
try {
    Locale.setDefault(chosen);
    a = FastDateFormat.getDateInstance(style);
    b = FastDateFormat.getDateInstance(style, chosen);
} catch (Exception e) {
    try { Locale.setDefault(old); } catch (Exception ignored) {}
    return;
}
try { Locale.setDefault(old); } catch (Exception ignored) {}
boolean sameLocale = (a.getLocale() == b.getLocale()) || (a.getLocale() != null && a.getLocale().equals(b.getLocale()));
boolean samePattern = (a.getPattern() == null ? b.getPattern() == null : a.getPattern().equals(b.getPattern()));
if (!sameLocale || !samePattern) {
    throw new RuntimeException("relation dateInstance_defaultLocaleSiblingAgreement violated: locale/pattern disagree for style=" + style + " chosen=" + chosen + " aLocale=" + a.getLocale() + " bLocale=" + b.getLocale() + " aPattern=" + a.getPattern() + " bPattern=" + b.getPattern());
}

