package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        StrBuilder lifted = new StrBuilder("onetwothree");
        lifted.deleteFirst("three");
        boolean liftedContains = lifted.contains('h');
        if (liftedContains != false) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lang295-contains] semantic mismatch: expected sb.contains('h') == false after deleteFirst(\"three\") on \"onetwothree\", actual=" + liftedContains);
        }
        int liftedIndex = lifted.indexOf('h');
        if (liftedIndex != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lang295-indexOf] semantic mismatch: expected sb.indexOf('h') == -1 after deleteFirst(\"three\") on \"onetwothree\", actual=" + liftedIndex);
        }

        boolean liftedConsistency = lifted.contains('h');
        int liftedConsistencyIndex = lifted.indexOf('h');
        if (liftedConsistency != (liftedConsistencyIndex >= 0)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-indexof-seed] consistency violation: contains('h')=" + liftedConsistency
                    + " but indexOf('h')=" + liftedConsistencyIndex);
        }

        char ch1 = (char) data.consumeInt(32, 126);
        String raw1 = data.consumeAsciiString(20);
        boolean relDeletedActual;
        try {
            String base = raw1.replace(String.valueOf(ch1), "");
            StrBuilder sb = new StrBuilder(base);
            sb.append(ch1);
            sb.deleteFirst(ch1);
            relDeletedActual = sb.contains(ch1);
        } catch (Exception e) {
            return;
        }
        if (relDeletedActual) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:deleted-sole-occurrence] semantic mismatch: contains returned true after deleting sole occurrence of '" + ch1 + "'");
        }

        String s2 = data.consumeAsciiString(30);
        char ch2 = (char) data.consumeInt(32, 126);
        boolean containsChar;
        boolean containsString;
        try {
            StrBuilder sb = new StrBuilder(s2);
            containsChar = sb.contains(ch2);
            containsString = sb.contains(String.valueOf(ch2));
        } catch (Exception e) {
            return;
        }
        if (containsChar != containsString) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-overload-agreement] metamorphic violation: contains(char)=" + containsChar
                    + " vs contains(String)=" + containsString + " for char '" + ch2 + "'");
        }

        String s3 = data.consumeAsciiString(30);
        char ch3 = (char) data.consumeInt(32, 126);
        boolean contains3;
        int index3;
        try {
            StrBuilder sb = new StrBuilder(s3);
            contains3 = sb.contains(ch3);
            index3 = sb.indexOf(ch3);
        } catch (Exception e) {
            return;
        }
        if (contains3 != (index3 >= 0)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-indexof-agreement] consistency violation: contains('" + ch3 + "')=" + contains3
                    + " but indexOf('" + ch3 + "')=" + index3 + " for input=" + s3);
        }

        char ch4 = (char) data.consumeInt(32, 126);
        String raw4 = data.consumeAsciiString(20);
        int beforeLength;
        int beforeCapacity;
        String beforeString;
        int beforeIndex;
        boolean contains4;
        int afterLength;
        int afterCapacity;
        String afterString;
        int afterIndex;
        try {
            String base = raw4.replace(String.valueOf(ch4), "");
            StrBuilder sb = new StrBuilder(base);
            sb.ensureCapacity(base.length() + 16);
            sb.append(ch4);
            sb.deleteFirst(ch4);
            beforeLength = sb.length();
            beforeCapacity = sb.capacity();
            beforeString = sb.toString();
            beforeIndex = sb.indexOf(ch4);
            contains4 = sb.contains(ch4);
            afterLength = sb.length();
            afterCapacity = sb.capacity();
            afterString = sb.toString();
            afterIndex = sb.indexOf(ch4);
        } catch (Exception e) {
            return;
        }
        if (beforeLength != afterLength || beforeCapacity != afterCapacity || !beforeString.equals(afterString) || beforeIndex != afterIndex) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-readonly] post-condition violation: contains(char) must be observationally read-only; before(length="
                    + beforeLength + ",capacity=" + beforeCapacity + ",index=" + beforeIndex + ",string=" + beforeString
                    + ") after(length=" + afterLength + ",capacity=" + afterCapacity + ",index=" + afterIndex + ",string=" + afterString
                    + "), queried='" + ch4 + "', result=" + contains4);
        }
    }
}

