package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        boolean liftedChecked = false;
        boolean actualContains = false;
        int actualIndex = 0;
        try {
            StrBuilder sb = new StrBuilder("onetwothree");
            sb.deleteFirst("three");
            actualContains = sb.contains('h');
            actualIndex = sb.indexOf('h');
            liftedChecked = true;
        } catch (Throwable ignored) {
        }
        if (liftedChecked && actualContains != false) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:testLang295-contains] semantic mismatch: expected sb.contains('h') == false after deleting \"three\" from \"onetwothree\", got " + actualContains
            );
        }
        if (liftedChecked && actualIndex != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:testLang295-indexOf] semantic mismatch: expected sb.indexOf('h') == -1 after deleting \"three\" from \"onetwothree\", got " + actualIndex
            );
        }

        boolean readonlyChecked = false;
        int beforeLength = 0;
        int afterLength = 0;
        int beforeCapacity = 0;
        int afterCapacity = 0;
        String beforeString = null;
        String afterString = null;
        int beforeIndex = 0;
        int afterIndex = 0;
        char probe = 0;
        try {
            String stateSeed = data.consumeAsciiString(20);
            if (stateSeed.length() == 0) {
                stateSeed = "abc";
            }
            probe = (char) data.consumeInt(32, 126);

            StrBuilder sb = new StrBuilder(stateSeed);
            beforeLength = sb.length();
            beforeCapacity = sb.capacity();
            beforeString = sb.toString();
            beforeIndex = sb.indexOf(probe);

            sb.contains(probe);

            afterLength = sb.length();
            afterCapacity = sb.capacity();
            afterString = sb.toString();
            afterIndex = sb.indexOf(probe);
            readonlyChecked = true;
        } catch (Throwable ignored) {
        }
        if (readonlyChecked && beforeLength != afterLength) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-readonly-length] semantic mismatch: contains(char) changed length from " + beforeLength + " to " + afterLength
            );
        }
        if (readonlyChecked && beforeCapacity != afterCapacity) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-readonly-capacity] semantic mismatch: contains(char) changed capacity from " + beforeCapacity + " to " + afterCapacity
            );
        }
        if (readonlyChecked && !beforeString.equals(afterString)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-readonly-string] semantic mismatch: contains(char) changed contents from \"" + beforeString + "\" to \"" + afterString + "\""
            );
        }
        if (readonlyChecked && beforeIndex != afterIndex) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-readonly-index] semantic mismatch: contains(char) changed indexOf('" + probe + "') from " + beforeIndex + " to " + afterIndex
            );
        }

        boolean rel1Actual = false;
        boolean rel1Checked = false;
        char rel1Ch = 0;
        try {
            rel1Ch = (char) data.consumeInt(32, 126);
            String raw = data.consumeAsciiString(20);
            String base = raw.replace(String.valueOf(rel1Ch), "");

            StrBuilder sb = new StrBuilder(base);
            sb.append(rel1Ch);
            sb.deleteFirst(rel1Ch);
            rel1Actual = sb.contains(rel1Ch);
            rel1Checked = true;
        } catch (Throwable ignored) {
        }
        if (rel1Checked && rel1Actual) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "relation contains_deleted_char_when_capacity_exceeds_length violated: contains returned true after deleting sole occurrence of '" + rel1Ch + "'"
            );
        }

        boolean rel2A = false;
        boolean rel2B = false;
        boolean rel2Checked = false;
        char rel2Ch = 0;
        String rel2S = null;
        try {
            rel2S = data.consumeAsciiString(30);
            rel2Ch = (char) data.consumeInt(32, 126);

            StrBuilder sb = new StrBuilder(rel2S);
            rel2A = sb.contains(rel2Ch);
            rel2B = sb.contains(String.valueOf(rel2Ch));
            rel2Checked = true;
        } catch (Throwable ignored) {
        }
        if (rel2Checked && rel2A != rel2B) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "relation contains_char_agrees_with_contains_string violated: " + rel2A + " vs " + rel2B + " for char '" + rel2Ch + "' in \"" + rel2S + "\""
            );
        }

        boolean tokChecked = false;
        String tokLeft = null;
        String tokRight = null;
        try {
            String t1 = data.consumeAsciiString(8).replaceAll("\\s+", "");
            String t2 = data.consumeAsciiString(8).replaceAll("\\s+", "");
            if (t1.length() == 0) {
                t1 = "aa";
            }
            if (t2.length() == 0) {
                t2 = "bb";
            }
            String suffix = " " + data.consumeAsciiString(6).replaceAll("\\s+", "");
            if (suffix.length() == 1) {
                suffix = " tail";
            }

            StrBuilder sb = new StrBuilder(t1 + " " + t2 + suffix);
            sb.deleteFirst(suffix);

            StrTokenizer fromBuilder = sb.asTokenizer();
            StrTokenizer fromString = new StrTokenizer(sb.toString());

            StringBuffer lhs = new StringBuffer();
            StringBuffer rhs = new StringBuffer();

            while (fromBuilder.hasNext()) {
                Object next = fromBuilder.next();
                if (lhs.length() > 0) {
                    lhs.append('|');
                }
                lhs.append(String.valueOf(next));
            }

            while (fromString.hasNext()) {
                Object next = fromString.next();
                if (rhs.length() > 0) {
                    rhs.append('|');
                }
                rhs.append(String.valueOf(next));
            }

            tokLeft = lhs.toString();
            tokRight = rhs.toString();
            tokChecked = true;
        } catch (Throwable ignored) {
        }
        if (tokChecked && !tokLeft.equals(tokRight)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:tokenizer-agreement] consistency violation: asTokenizer()/hasNext()/next() disagreed with tokenizing the builder's current String contents lhs="
                    + tokLeft + " rhs=" + tokRight
            );
        }

        boolean twinChecked = false;
        boolean twinA = false;
        boolean twinB = false;
        char twinCh = 0;
        String twinBase = null;
        try {
            twinCh = (char) data.consumeInt(32, 126);
            String raw = data.consumeAsciiString(16);
            twinBase = raw.replace(String.valueOf(twinCh), "");
            if (twinBase.length() == 0) {
                twinBase = "seed";
            }

            StrBuilder a = new StrBuilder(twinBase);
            a.append(twinCh);
            a.deleteFirst(twinCh);

            StrBuilder b = new StrBuilder(twinBase);
            b.append(twinCh);
            b.deleteFirst(twinCh);

            twinA = a.contains(twinCh);
            twinB = b.contains(twinCh);
            twinChecked = true;
        } catch (Throwable ignored) {
        }
        if (twinChecked && twinA != twinB) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:fresh-recompute] consistency violation: identically-constructed builders disagreed on contains('"
                    + twinCh + "') for base \"" + twinBase + "\": " + twinA + " vs " + twinB
            );
        }
    }
}

