                "relation first-dot-found-from-start violated: " + ns + " -> " + i1 + " vs " + i2);
        }

        String left = data.consumeAsciiString(6).replace(".", "");
        String right = data.consumeAsciiString(6).replace(".", "");
        if (left.isEmpty()) {
            left = "apps";
        }
        if (right.isEmpty()) {
            right = "bar";
        }
        ns = left + "." + right;
        int idx;
        String parent;
        try {
            idx = ns.indexOf('.');
            parent = ns.substring(0, idx);
        } catch (Exception e) {
            return;
        }
