            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-independent-modules4] semantic mismatch: expected=" +
                fixedExpectedNorm + " actual=" + fixedActualNorm);
        }

        String fixedApps = normalizeJs("var apps = {};");
        String fixedAppsFoo = normalizeJs("apps.foo = {};");
        String fixedAppsFooBar = normalizeJs("apps.foo.bar = {};");
        int pApps = fixedActualNorm.indexOf(fixedApps);
        int pAppsFoo = fixedActualNorm.indexOf(fixedAppsFoo);
        int pAppsFooBar = fixedActualNorm.indexOf(fixedAppsFooBar);
