        String seg1 = sanitizeIdent(data.consumeAsciiString(6), "mid");
        String seg2 = sanitizeIdent(data.consumeAsciiString(6), "LeafA");
        String seg3 = sanitizeIdent(data.consumeAsciiString(6), "LeafB");
