        String provide1 = "goog.provide('" + seg0 + "." + seg1 + "." + seg2 + "');";
        String provide2 = "goog.provide('" + seg0 + "." + seg1 + "." + seg3 + "');";
        String fuzzActual = compileStarOutput(provide0, provide1, provide2);
        if (fuzzActual == null) {
