            "var " + seg0 + " = {};" +
            seg0 + "." + seg1 + " = {};" +
            seg0 + "." + seg1 + "." + seg2 + " = {};" +
            seg0 + "." + seg1 + "." + seg3 + " = {};");
        if (!fuzzExpectedNorm.equals(fuzzActualNorm)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:constructed-star] semantic mismatch: expected=" +
                fuzzExpectedNorm + " actual=" + fuzzActualNorm);
        }

        String parentDecl = normalizeJs(seg0 + "." + seg1 + " = {};");
        String child1Decl = normalizeJs(seg0 + "." + seg1 + "." + seg2 + " = {};");
        String child2Decl = normalizeJs(seg0 + "." + seg1 + "." + seg3 + " = {};");
        int pParent = fuzzActualNorm.indexOf(parentDecl);
        int pChild1 = fuzzActualNorm.indexOf(child1Decl);
        int pChild2 = fuzzActualNorm.indexOf(child2Decl);
        /* Same documented guarantee as above: replace() inserts the implicit parent namespace
         * after its own parent namespace, so the created parent declaration must be observable
         * before either child leaf declaration in the final source. */
