            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:constructed-order] semantic mismatch: parent=" + pParent +
                " child1=" + pChild1 + " child2=" + pChild2 + " source=" + fuzzActualNorm);
        }
    }

    private static String compileStarOutput(String rootCode, String child1Code, String child2Code) {
        try {
            Compiler compiler = new Compiler();
            CompilerOptions options = new CompilerOptions();
            options.closurePass = true;

            List<JSSourceFile> externs = new ArrayList<JSSourceFile>();
            externs.add(JSSourceFile.fromCode("externs.js", ""));

            JSModule root = new JSModule("m0");
            root.add(JSSourceFile.fromCode("m0.js", rootCode));

            JSModule child1 = new JSModule("m1");
            child1.add(JSSourceFile.fromCode("m1.js", child1Code));
            child1.addDependency(root);

            JSModule child2 = new JSModule("m2");
            child2.add(JSSourceFile.fromCode("m2.js", child2Code));
            child2.addDependency(root);

            List<JSModule> modules = new ArrayList<JSModule>();
            modules.add(root);
            modules.add(child1);
            modules.add(child2);

            Result result = compiler.compileModules(externs, modules, options);
            if (result == null) {
                return null;
            }
            return compiler.toSource();
        } catch (Throwable t) {
            return null;
        }
    }

    private static String normalizeJs(String s) {
        return s == null ? null : s.replaceAll("\\s+", "");
    }

    private static String sanitizeIdent(String s, String fallback) {
        if (s == null) {
            return fallback;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length() && sb.length() < 12; i++) {
            char ch = s.charAt(i);
            boolean ok = (ch >= 'a' && ch <= 'z')
                || (ch >= 'A' && ch <= 'Z')
                || (ch >= '0' && ch <= '9')
                || ch == '_'
                || ch == '$';
            if (ok) {
                sb.append(ch);
            }
        }
        if (sb.length() == 0) {
            sb.append(fallback);
        }
        char first = sb.charAt(0);
        if (first >= '0' && first <= '9') {
            sb.insert(0, 'a');
        }
        return sb.toString();
    }
}

