        List<JSModule> modules = new ArrayList<JSModule>();

        JSModule previousRoot = null;
        for (int i = 0; i < moduleSources.length; i++) {
            JSModule module = new JSModule("m" + i);
            module.add(JSSourceFile.fromCode("m" + i + ".js", moduleSources[i]));
            if (i > 0 && previousRoot != null) {
                module.addDependency(previousRoot);
