        StringBuilder out = new StringBuilder();
        if (s != null) {
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if ((c >= 'a' && c <= 'z')
                    || (c >= 'A' && c <= 'Z')
                    || (c >= '0' && c <= '9')
                    || c == '_' || c == '$') {
                    out.append(c);
                }
            }
        }
        if (out.length() == 0) {
            out.append(fallback);
        }
        char first = out.charAt(0);
        if (!((first >= 'a' && first <= 'z')
            || (first >= 'A' && first <= 'Z')
            || first == '_' || first == '$')) {
            out.insert(0, 'a');
        }
        return out.toString();
    }
