package org.apache.commons.math3.distribution;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        reproduceLiftedSeedOracles();
        checkOverflowSafeMeanOracle(data);
        checkSampleWithinSupportRelation(data);
        checkSupportLowerFormulaRelation(data);
    }

    private static void reproduceLiftedSeedOracles() {
        final int N = 43130568;
        final int m = 42976365;
        final int n = 50;
        final HypergeometricDistribution dist;
        try {
            dist = new HypergeometricDistribution(N, m, n);
        } catch (Exception e) {
            return;
        }

        for (int i = 0; i < 100; i++) {
            final int sample;
            try {
                sample = dist.sample();
            } catch (Exception e) {
                return;
            }

            if (!(0 <= sample)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:seed-sample-nonnegative] semantic mismatch: sample=" + sample +
                    " expected 0 <= sample for N=" + N + " m=" + m + " n=" + n + " iteration=" + i);
            }
            if (!(sample <= n)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:seed-sample-upper] semantic mismatch: sample=" + sample +
                    " expected sample <= n=" + n + " for N=" + N + " m=" + m + " iteration=" + i);
            }
        }
    }

    private static void checkOverflowSafeMeanOracle(FuzzedDataProvider data) {
        final int N = data.consumeInt(100000, 1000000);
        final int m = data.consumeInt(Math.max(50000, N / 2), N);
        final int minOverflowN = (Integer.MAX_VALUE / m) + 1;
        if (minOverflowN > N) {
            return;
        }
        final int n = data.consumeInt(minOverflowN, N);

        final HypergeometricDistribution dist;
        final int beforePopulation;
        final int beforeSuccesses;
        final int beforeSampleSize;
        final int beforeLower;
        final int beforeUpper;
        final boolean beforeConnected;
        final double beforeVariance;
        final double actualMean;
        final int afterPopulation;
        final int afterSuccesses;
        final int afterSampleSize;
        final int afterLower;
        final int afterUpper;
        final boolean afterConnected;
        final double afterVariance;
        final double expectedMean;
        try {
            dist = new HypergeometricDistribution(N, m, n);

            beforePopulation = dist.getPopulationSize();
            beforeSuccesses = dist.getNumberOfSuccesses();
            beforeSampleSize = dist.getSampleSize();
            beforeLower = dist.getSupportLowerBound();
            beforeUpper = dist.getSupportUpperBound();
            beforeConnected = dist.isSupportConnected();
            beforeVariance = dist.getNumericalVariance();

            actualMean = dist.getNumericalMean();

            afterPopulation = dist.getPopulationSize();
            afterSuccesses = dist.getNumberOfSuccesses();
            afterSampleSize = dist.getSampleSize();
            afterLower = dist.getSupportLowerBound();
            afterUpper = dist.getSupportUpperBound();
            afterConnected = dist.isSupportConnected();
            afterVariance = dist.getNumericalVariance();

            expectedMean = ((double) beforeSampleSize) * ((double) beforeSuccesses) / (double) beforePopulation;
        } catch (Exception e) {
            return;
        }

        // Documented guarantee: for a hypergeometric distribution with population size N, number of
        // successes m, and sample size n, the mean is n * m / N. Computing that formula from the
        // object's own getters is an independent oracle for getNumericalMean, and it still detects
        // a band-aid that only suppresses the known sample() symptom while leaving the same root
        // cause (integer overflow before widening) in the mean path.
        if (Double.compare(actualMean, expectedMean) != 0) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:mean-formula] semantic mismatch: actualMean=" + actualMean +
                " expectedMean=" + expectedMean +
                " population=" + beforePopulation +
                " successes=" + beforeSuccesses +
                " sampleSize=" + beforeSampleSize);
        }

        // Read-only hidden-state check: getNumericalMean() is a query; the exposed state read before
        // and after should remain unchanged on every correct implementation.
        if (beforePopulation != afterPopulation ||
            beforeSuccesses != afterSuccesses ||
            beforeSampleSize != afterSampleSize ||
            beforeLower != afterLower ||
            beforeUpper != afterUpper ||
            beforeConnected != afterConnected ||
            Double.compare(beforeVariance, afterVariance) != 0) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:getNumericalMean-readonly] semantic mismatch: state changed across getNumericalMean()" +
                " before(population=" + beforePopulation +
                ",successes=" + beforeSuccesses +
                ",sampleSize=" + beforeSampleSize +
                ",lower=" + beforeLower +
                ",upper=" + beforeUpper +
                ",connected=" + beforeConnected +
                ",variance=" + beforeVariance +
                ") after(population=" + afterPopulation +
                ",successes=" + afterSuccesses +
                ",sampleSize=" + afterSampleSize +
                ",lower=" + afterLower +
                ",upper=" + afterUpper +
                ",connected=" + afterConnected +
                ",variance=" + afterVariance + ")");
        }

        // Consistency check: a distribution's mean must lie within its own support bounds. This uses
        // the object's stated limits as an independent quantity, so it still catches a wrong mean if
        // a patch merely stops sample() from returning the known bad value.
        if (actualMean < beforeLower || actualMean > beforeUpper) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:mean-within-support] consistency violation: mean=" + actualMean +
                " lower=" + beforeLower + " upper=" + beforeUpper +
                " population=" + beforePopulation +
                " successes=" + beforeSuccesses +
                " sampleSize=" + beforeSampleSize);
        }
    }

    private static void checkSampleWithinSupportRelation(FuzzedDataProvider data) {
        final int N = data.consumeInt(1, 1000000);
        final int m = data.consumeInt(0, N);
        final int n = data.consumeInt(0, N);

        int sample;
        int lower;
        int upper;
        try {
            HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);
            sample = dist.sample();
            lower = dist.getSupportLowerBound();
            upper = dist.getSupportUpperBound();
        } catch (Exception e) {
            return;
        }

        // A sample drawn from a distribution must lie in that distribution's support.
        if (sample < lower || sample > upper) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:sample-within-support] relation sample_within_support_bounds violated: sample=" + sample +
                " lower=" + lower + " upper=" + upper +
                " N=" + N + " m=" + m + " n=" + n);
        }
    }

    private static void checkSupportLowerFormulaRelation(FuzzedDataProvider data) {
        final int N = data.consumeInt(1, 1000000);
        final int m = data.consumeInt(0, N);
        final int n = data.consumeInt(0, N);

        int actual;
        int expected;
        try {
            HypergeometricDistribution dist = new HypergeometricDistribution(N, m, n);
            actual = dist.getSupportLowerBound();
            expected = Math.max(0, n + m - N);
        } catch (Exception e) {
            return;
        }

        // Contract/invariant for hypergeometric support: lower bound is max(0, n + m - N).
        if (actual != expected) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:support-lower-formula] relation support_lower_matches_documented_formula violated: actual=" +
                actual + " expected=" + expected + " N=" + N + " m=" + m + " n=" + n);
        }
    }
}

