            lifted.deleteFirst("three");

            boolean actualContains = lifted.contains('h');
            if (actualContains != false) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-contains] semantic mismatch: expected false for contains('h') after deleteFirst(\"three\"), got " + actualContains);
            }

            int actualIndex = lifted.indexOf('h');
            if (actualIndex != -1) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-indexof] semantic mismatch: expected -1 for indexOf('h') after deleteFirst(\"three\"), got " + actualIndex);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }

        String prefix = data.consumeString(32);
        String suffix = data.consumeString(32);
        char probe = (char) data.consumeInt(0, Character.MAX_VALUE);
        int extraCapacity = data.consumeInt(0, 64);
        int startIndex = data.consumeInt(-8, 96);

        try {
            StrBuilder sb = new StrBuilder(prefix + suffix);
            sb.ensureCapacity(sb.length() + extraCapacity);

            if (suffix.length() > 0) {
                sb.deleteFirst(suffix);
            } else {
                sb.setLength(prefix.length());
            }

            String active = new String(sb.toCharArray());

            boolean reportedContains = sb.contains(probe);
            boolean independentContains = active.indexOf(probe) >= 0;
            if (reportedContains != independentContains) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:contains-vs-active] consistency violation: probe=" + (int) probe
                        + " reported=" + reportedContains
                        + " independent=" + independentContains
                        + " activeLen=" + active.length()
                        + " capacity=" + sb.capacity());
            }

            int reportedIndex0 = sb.indexOf(probe);
            int independentIndex0 = active.indexOf(probe);
            if (reportedIndex0 != independentIndex0) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:indexof-vs-active] consistency violation: probe=" + (int) probe
                        + " reported=" + reportedIndex0
                        + " independent=" + independentIndex0
                        + " activeLen=" + active.length()
                        + " capacity=" + sb.capacity());
            }

            int normalizedStart = startIndex < 0 ? 0 : startIndex;
            int reportedIndexStart = sb.indexOf(probe, startIndex);
            int independentIndexStart = normalizedStart >= active.length() ? -1 : active.indexOf(probe, normalizedStart);
            if (reportedIndexStart != independentIndexStart) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:indexof-start-vs-active] consistency violation: probe=" + (int) probe
                        + " start=" + startIndex
                        + " reported=" + reportedIndexStart
                        + " independent=" + independentIndexStart
                        + " activeLen=" + active.length()
                        + " capacity=" + sb.capacity());
            }

            if (reportedContains != (reportedIndex0 >= 0)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:contains-indexof-agree] metamorphic violation: contains(char) must agree with indexOf(char)>=0 for the same builder/probe, probe="
                        + (int) probe + " contains=" + reportedContains + " indexOf=" + reportedIndex0);
            }

            sb.minimizeCapacity();
            String minimizedActive = new String(sb.toCharArray());
            boolean minimizedContains = sb.contains(probe);
            int minimizedIndex = sb.indexOf(probe, startIndex);
            boolean minimizedIndependentContains = minimizedActive.indexOf(probe) >= 0;
            int minimizedIndependentIndex = normalizedStart >= minimizedActive.length() ? -1 : minimizedActive.indexOf(probe, normalizedStart);

            if (minimizedContains != minimizedIndependentContains) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:minimized-contains] consistency violation: probe=" + (int) probe
                        + " reported=" + minimizedContains
                        + " independent=" + minimizedIndependentContains
                        + " activeLen=" + minimizedActive.length()
                        + " capacity=" + sb.capacity());
            }

            if (minimizedIndex != minimizedIndependentIndex) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:minimized-indexof] consistency violation: probe=" + (int) probe
                        + " start=" + startIndex
                        + " reported=" + minimizedIndex
                        + " independent=" + minimizedIndependentIndex
                        + " activeLen=" + minimizedActive.length()
                        + " capacity=" + sb.capacity());
            }

            StrTokenizer tok = sb.asTokenizer();
            boolean tokenizerEmpty = !tok.hasNext();
            boolean builderEmpty = sb.isEmpty();
            if (tokenizerEmpty != builderEmpty) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:tokenizer-emptiness] consistency violation: tokenizer hasNext disagrees with builder isEmpty, hasNext="
                        + (!tokenizerEmpty) + " isEmpty=" + builderEmpty + " contentLen=" + sb.length());
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }
    }
}

