package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    private static final DiagnosticType FOO_TYPE =
            DiagnosticType.error("TEST_FOO", "error description here");

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String sourceName = "javascript/complex.js";

        try {
            LightweightMessageFormatter formatter = makeFormatter(sourceName, "assert (1;");
            JSError error = JSError.make(sourceName, 1, 10, FOO_TYPE);
            String actual = formatter.formatError(error);
            String expected = "javascript/complex.js:1: ERROR - error description here\n"
                    + "assert (1;\n"
                    + "          ^\n";

            if (!normalize(actual).equals(normalize(expected))) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:seed-test] semantic mismatch: expected=" + normalize(expected)
                                + " actual=" + normalize(actual));
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }

        String fuzzLine = data.consumeAsciiString(32);
        if (fuzzLine == null) {
            return;
        }
        fuzzLine = fuzzLine.replace("\n", "").replace("\r", "");
        if (fuzzLine.length() == 0) {
            fuzzLine = "x";
        }
        if (isAllWhitespace(fuzzLine)) {
            fuzzLine = fuzzLine + "x";
        }

        try {
            LightweightMessageFormatter formatter = makeFormatter(sourceName, fuzzLine);
            int len = fuzzLine.length();

            JSError atEnd = JSError.make(sourceName, 1, len, FOO_TYPE);
            JSError beforeEnd = JSError.make(sourceName, 1, len - 1, FOO_TYPE);

            String endMsg = formatter.formatError(atEnd);
            String beforeEndMsg = formatter.formatError(beforeEnd);

            // Contract from LightweightMessageFormatter.format():
            // "charno == sourceExcerpt.length() means something is missing at the end of the line".
            // Therefore, for excerpt LINE, both charno == len-1 and charno == len must render the same
            // non-whitespace content; they differ only in caret indentation, which normalization removes.
            String normEnd = normalize(endMsg);
            String normBeforeEnd = normalize(beforeEndMsg);
            if (!normEnd.equals(normBeforeEnd)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:boundary-flip] metamorphic violation: len and len-1 should differ only in whitespace "
                                + "input=" + fuzzLine + " len=" + len
                                + " lhs=" + normEnd + " rhs=" + normBeforeEnd);
            }

            // Independent post-condition on the patched boundary:
            // when charno == sourceExcerpt.length(), the formatter should still append the caret line,
            // because the code comment explicitly defines this case as "missing at the end of the line".
            if (endMsg.indexOf('^') < 0) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:end-caret] semantic mismatch: missing caret for end-of-line case "
                                + "input=" + fuzzLine + " msg=" + normalize(endMsg));
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }
    }

    private static LightweightMessageFormatter makeFormatter(String sourceName, String sourceCode) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        JSSourceFile[] externs = new JSSourceFile[0];
        JSSourceFile[] inputs = new JSSourceFile[] { JSSourceFile.fromCode(sourceName, sourceCode) };
        compiler.init(externs, inputs, options);
        return new LightweightMessageFormatter(compiler);
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static boolean isAllWhitespace(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (!Character.isWhitespace(s.charAt(i))) {
                return false;
            }
        }
        return true;
    }
}

