package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static final DiagnosticType FOO_TYPE =
            DiagnosticType.error("TEST_FOO", "error description here");

    private static SourceExcerptProvider source(final String source) {
        return new SourceExcerptProvider() {
            public String getSourceLine(String sourceName, int lineNumber) {
                return source;
            }

            public Region getSourceRegion(String sourceName, int lineNumber) {
                throw new UnsupportedOperationException();
            }
        };
    }

    private static String normalize(String s) {
        return s == null ? null : s.replaceAll("\\s+", "");
    }

    private static String caretLineFor(String s) {
        StringBuilder caret = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            caret.append(Character.isWhitespace(c) ? c : ' ');
        }
        caret.append("^\n");
        return caret.toString();
    }

    private static void throwMismatch(String id, String what, String expected, String actual) {
        throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:" + id + "] semantic mismatch: " + what
                        + " expected=" + String.valueOf(expected)
                        + " actual=" + String.valueOf(actual));
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        // Lifted oracle from LightweightMessageFormatterTest::testFormatErrorSpaceEndOfLine2.
        JSError liftedError = JSError.make("javascript/complex.js", 6, 7, FOO_TYPE);
        LightweightMessageFormatter liftedFormatter = new LightweightMessageFormatter(source("if (foo"));
        String liftedActual = liftedFormatter.formatError(liftedError);
        String liftedExpected =
                "javascript/complex.js:6: ERROR - error description here\n"
                        + "if (foo\n"
                        + "       ^\n";
        if (!normalize(liftedExpected).equals(normalize(liftedActual))) {
            throwMismatch("lifted-test", "formatError(end-of-line caret)", liftedExpected, liftedActual);
        }

        // Independent post-condition: with a source line available and charno at end-of-line,
        // the formatter must render a caret marker line whose non-whitespace content is "^".
        // This follows from the method's own contract comments:
        // "padding equal to the excerpt and arrow at the end" and
        // "charno == sourceExcerpt.length() means something is missing at the end of the line".
        // A band-aid patch that simply suppresses the buggy branch would violate this observable.
        String[] liftedLines = liftedActual.split("\n", -1);
        String liftedMarker = liftedLines.length >= 3 ? liftedLines[2].trim() : "";
        if (!"^".equals(liftedMarker)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-marker] semantic mismatch: expected caret-only marker line at end-of-line, actual="
                            + liftedActual);
        }

        // Strategy (a): drive a different reachable public function in the same family.
        // For any correct implementation, formatWarning is the same formatter path with WARNING
        // level selected, so when charno == source length it must also include the end-of-line caret.
        String fuzzSource = data.consumeAsciiString(40);
        if (fuzzSource.length() == 0) {
            fuzzSource = "x";
        }

        LightweightMessageFormatter warningFormatter;
        JSError warningError;
        String warningActual;
        try {
            warningFormatter = new LightweightMessageFormatter(source(fuzzSource));
            warningError = JSError.make(
                    "javascript/complex.js",
                    1,
                    fuzzSource.length(),
                    FOO_TYPE);
            warningActual = warningFormatter.formatWarning(warningError);
        } catch (Throwable t) {
            warningActual = null;
        }
        if (warningActual != null) {
            String warningExpected =
                    "javascript/complex.js:1: WARNING - error description here\n"
                            + fuzzSource + "\n"
                            + caretLineFor(fuzzSource);
            if (!normalize(warningExpected).equals(normalize(warningActual))) {
                throwMismatch("warning-boundary", "formatWarning(end-of-line caret)", warningExpected, warningActual);
            }
            String[] warningLines = warningActual.split("\n", -1);
            String warningMarker = warningLines.length >= 3 ? warningLines[2].trim() : "";
            if (!"^".equals(warningMarker)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:warning-marker] semantic mismatch: expected caret-only marker line in warning output, actual="
                                + warningActual);
            }
        }

