        // for excerpt LINE and charno == sourceExcerpt.length(), the output must include
        // the source line plus a caret line at the end. Valid by construction.
        LightweightMessageFormatter errorFormatter;
        JSError errorAtBoundary;
        String errorActual;
        try {
            errorFormatter = new LightweightMessageFormatter(source(fuzzSource));
            errorAtBoundary = JSError.make(
                    "x.js",
                    1,
                    fuzzSource.length(),
                    DiagnosticType.error("ID", "desc"));
            errorActual = errorFormatter.formatError(errorAtBoundary);
        } catch (Throwable t) {
            errorActual = null;
        }
        if (errorActual != null) {
            String errorExpected =
                    "x.js:1: ERROR - desc\n"
                            + fuzzSource + "\n"
                            + caretLineFor(fuzzSource);
            if (!normalize(errorExpected).equals(normalize(errorActual))) {
                throwMismatch("error-boundary", "formatError(fuzzed end-of-line caret)", errorExpected, errorActual);
