package org.jfree.chart.axis;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.Stroke;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import java.util.Date;
import java.util.Objects;
import org.jfree.chart.ChartFactory;
import org.jfree.chart.ChartRenderingInfo;
import org.jfree.chart.JFreeChart;
import org.jfree.chart.entity.EntityCollection;
import org.jfree.chart.entity.StandardEntityCollection;
import org.jfree.chart.plot.CategoryPlot;
import org.jfree.chart.plot.PlotRenderingInfo;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.RectangleInsets;
import org.jfree.data.gantt.Task;
import org.jfree.data.gantt.TaskSeries;
import org.jfree.data.gantt.TaskSeriesCollection;
import org.jfree.data.time.SimpleTimePeriod;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        String seriesName = data.consumeString(12);
        if (seriesName == null || seriesName.length() == 0) {
            seriesName = "S";
        }
        String taskName = data.consumeString(12);
        if (taskName == null || taskName.length() == 0) {
            taskName = "T";
        }
        String title = data.consumeString(24);
        if (title == null || title.length() == 0) {
            title = "Chart";
        }
        String domainLabel = data.consumeString(16);
        if (domainLabel == null || domainLabel.length() == 0) {
            domainLabel = "Domain";
        }
        String rangeLabel = data.consumeString(16);
        if (rangeLabel == null || rangeLabel.length() == 0) {
            rangeLabel = "Range";
        }

        long start = data.consumeInt(-100000, 100000);
        long len = data.consumeInt(1, 100000);
        long end = start + len;

        TaskSeriesCollection dataset = new TaskSeriesCollection();
        TaskSeries series = new TaskSeries(seriesName);
        series.add(new Task(taskName, new SimpleTimePeriod(new Date(start), new Date(end))));
        dataset.add(series);

        JFreeChart chart;
        try {
            chart = ChartFactory.createGanttChart(title, domainLabel, rangeLabel, dataset, false, false, false);
        } catch (Throwable t) {
            return;
        }

        boolean success = false;
        BufferedImage image = new BufferedImage(200, 100, BufferedImage.TYPE_INT_RGB);
        Graphics2D g2 = image.createGraphics();
        try {
            chart.draw(g2, new Rectangle2D.Double(0.0, 0.0, 200.0, 100.0), null, null);
            success = true;
        } catch (Exception e) {
            success = false;
        } finally {
            g2.dispose();
        }
        if (!success) {
            throw new FuzzerSecurityIssueLow("[oracle:gantt-null-info] semantic mismatch: Gantt chart draw with null rendering info should succeed, but success was false");
        }

        CategoryPlot plot;
        try {
            plot = (CategoryPlot) chart.getPlot();
        } catch (Throwable t) {
            return;
        }
        if (plot == null || !(plot.getDomainAxis() instanceof CategoryAxis)) {
            return;
        }
        CategoryAxis domain = (CategoryAxis) plot.getDomainAxis();

        Font f1 = domain.getLabelFont();
        RectangleInsets i1 = domain.getLabelInsets();
        Paint p1 = domain.getLabelPaint();
        Paint alp1 = domain.getAxisLinePaint();
        Stroke als1 = domain.getAxisLineStroke();
        Font tf1 = domain.getTickLabelFont();
        RectangleInsets ti1 = domain.getTickLabelInsets();
        Paint tp1 = domain.getTickLabelPaint();
        float in1 = domain.getTickMarkInsideLength();
        float out1 = domain.getTickMarkOutsideLength();
        Paint tmp1 = domain.getTickMarkPaint();
        Stroke tms1 = domain.getTickMarkStroke();
        double ang1 = domain.getLabelAngle();
        String lab1 = domain.getLabel();
        String tip1 = domain.getLabelToolTip();
        String url1 = domain.getLabelURL();
        double fd1 = domain.getFixedDimension();

        boolean drawOk = true;
        BufferedImage image2 = new BufferedImage(220, 120, BufferedImage.TYPE_INT_RGB);
        Graphics2D g22 = image2.createGraphics();
        try {
            chart.draw(g22, new Rectangle2D.Double(0.0, 0.0, 220.0, 120.0), null, null);
        } catch (Exception e) {
            drawOk = false;
        } finally {
            g22.dispose();
        }
        if (!drawOk) {
            return;
        }

        boolean same = Objects.equals(f1, domain.getLabelFont())
                && Objects.equals(i1, domain.getLabelInsets())
                && Objects.equals(p1, domain.getLabelPaint())
                && Objects.equals(alp1, domain.getAxisLinePaint())
                && Objects.equals(als1, domain.getAxisLineStroke())
                && Objects.equals(tf1, domain.getTickLabelFont())
                && Objects.equals(ti1, domain.getTickLabelInsets())
                && Objects.equals(tp1, domain.getTickLabelPaint())
                && in1 == domain.getTickMarkInsideLength()
                && out1 == domain.getTickMarkOutsideLength()
                && Objects.equals(tmp1, domain.getTickMarkPaint())
                && Objects.equals(tms1, domain.getTickMarkStroke())
                && ang1 == domain.getLabelAngle()
                && Objects.equals(lab1, domain.getLabel())
                && Objects.equals(tip1, domain.getLabelToolTip())
                && Objects.equals(url1, domain.getLabelURL())
                && fd1 == domain.getFixedDimension();
        if (!same) {
            throw new FuzzerSecurityIssueLow("[oracle:draw-readonly-style] semantic mismatch: axis readable style/state changed across chart.draw with null info");
        }

        String fuzzTip = data.consumeString(24);
        String fuzzUrl = data.consumeString(24);
        domain.setLabelToolTip(fuzzTip);
        domain.setLabelURL(fuzzUrl);
        if (!Objects.equals(fuzzTip, domain.getLabelToolTip())) {
            throw new FuzzerSecurityIssueLow("[oracle:tooltip-roundtrip] semantic mismatch: getLabelToolTip disagrees with last setLabelToolTip value");
        }
        if (!Objects.equals(fuzzUrl, domain.getLabelURL())) {
            throw new FuzzerSecurityIssueLow("[oracle:url-roundtrip] semantic mismatch: getLabelURL disagrees with last setLabelURL value");
        }

        String drawLabelText = data.consumeString(20);
        if (drawLabelText == null || drawLabelText.length() == 0) {
            drawLabelText = "Axis";
        }

        RectangleEdge edge;
        switch (data.consumeInt(0, 3)) {
            case 0:
                edge = RectangleEdge.TOP;
                break;
            case 1:
                edge = RectangleEdge.BOTTOM;
                break;
            case 2:
                edge = RectangleEdge.LEFT;
                break;
            default:
                edge = RectangleEdge.RIGHT;
                break;
        }

        StandardEntityCollection entities = new StandardEntityCollection();
        ChartRenderingInfo owner = new ChartRenderingInfo(entities);
        PlotRenderingInfo plotState = new PlotRenderingInfo(owner);
        Rectangle2D plotArea = new Rectangle2D.Double(0.0, 0.0, 200.0, 100.0);
        Rectangle2D dataArea = new Rectangle2D.Double(10.0, 10.0, 180.0, 80.0);
        AxisState state = new AxisState(data.consumeInt(20, 180));

        int beforeCount;
        int afterCount;
        BufferedImage image3 = new BufferedImage(240, 140, BufferedImage.TYPE_INT_RGB);
        Graphics2D g23 = image3.createGraphics();
        try {
            EntityCollection ec = owner.getEntityCollection();
            if (ec == null) {
                g23.dispose();
                return;
            }
            beforeCount = ec.getEntityCount();
            domain.drawLabel(drawLabelText, g23, plotArea, dataArea, edge, state, plotState);
            afterCount = ec.getEntityCount();
        } catch (Throwable t) {
            g23.dispose();
            return;
        } finally {
            g23.dispose();
        }

        /*
         * Contract from Axis.drawLabel body shown in the patch:
         * when plotState != null, hotspot != null, owner != null, and owner.getEntityCollection() != null,
         * the method adds a new AxisLabelEntity to that collection.
         * We establish every guard here with real library objects; a band-aid patch that merely skips
         * the bookkeeping branch would leave draw() non-throwing but violate this observable post-condition.
         */
        if (afterCount != beforeCount + 1) {
            throw new FuzzerSecurityIssueLow("[oracle:axis-label-entity-added] semantic mismatch: drawLabel should add exactly one axis-label entity when owner and entity collection are present, before="
                    + beforeCount + " after=" + afterCount + " edge=" + edge + " label=" + drawLabelText);
        }
    }
}

