package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        final int threshold = CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD;

        String actualSeed;
        try {
            actualSeed = parsePrint("x- -0", false, threshold);
        } catch (Throwable t) {
            return;
        }
        checkNormalizedEquals(
                "lifted-seed",
                "x- -0.0",
                actualSeed,
                "parsePrint(\"x- -0\", false, CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD)");

        String actualEquivalent;
        try {
            actualEquivalent = parsePrint("x- -0.0", false, threshold);
        } catch (Throwable t) {
            return;
        }
        checkNormalizedEquals(
                "equiv-zero-spelling",
                "x- -0.0",
                actualEquivalent,
                "parsePrint(\"x- -0.0\", false, CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD)");

        String ident = makeIdentifier(data.consumeAsciiString(24));
        if (ident.length() == 0) {
            ident = "x";
        }
        String js = ident + "- -0";
        String expected = ident + "- -0.0";
        String actualChosen;
        try {
            actualChosen = parsePrint(js, false, threshold);
        } catch (Throwable t) {
            return;
        }
        checkNormalizedEquals(
                "chosen-ident-negzero",
                expected,
                actualChosen,
                "parsePrint(" + quoteForMsg(js) + ", false, CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD)");

        String ident2 = makeIdentifier(data.consumeAsciiString(16));
        if (ident2.length() == 0) {
            ident2 = "y";
        }
        Node ast = buildSubNegZeroAst(ident2);
        String printed;
        try {
            printed = new CodePrinter.Builder(ast)
                    .setPrettyPrint(data.consumeBoolean())
                    .setLineLengthThreshold(threshold)
                    .build();
        } catch (Throwable t) {
            return;
        }
        if (printed == null) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:ast-build] semantic mismatch: CodePrinter.Builder returned null");
        }

        String actualAst;
        try {
            actualAst = new CodePrinter.Builder(buildSubNegZeroAst(ident2))
                    .setPrettyPrint(false)
                    .setLineLengthThreshold(threshold)
                    .build();
        } catch (Throwable t) {
            return;
        }
        // Contract from CodeConsumer.addNumber comment: spacing is required to prevent
        // misparsing of "x- -4" as "x--4". The same must hold for negative zero in the
        // same syntactic position, so the printed source must preserve the separated '- -'.
        checkNormalizedEquals(
                "ast-negzero-shape",
                ident2 + "- -0.0;",
                actualAst,
                "CodePrinter.Builder(AST(NAME-SUB-NEG-0)).build()");
    }

    private static String parsePrint(String js, boolean prettyPrint, int lineThreshold) {
        Node root = parse(js);
        return new CodePrinter.Builder(root)
                .setPrettyPrint(prettyPrint)
                .setLineLengthThreshold(lineThreshold)
                .build();
    }

    private static Node parse(String js) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        compiler.initOptions(options);
        Node root = compiler.parseTestCode(js);
        if (root == null) {
            throw new IllegalStateException("parse returned null for: " + js);
        }
        return root;
    }

    private static void checkNormalizedEquals(String oracleId, String expected, String actual, String what) {
        String ne = normalize(expected);
        String na = normalize(actual);
        if (!ne.equals(na)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:" + oracleId + "] violated semantic mismatch: " + what
                            + " expected=" + quoteForMsg(expected)
                            + " actual=" + quoteForMsg(actual));
        }
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static String makeIdentifier(String raw) {
        if (raw == null || raw.length() == 0) {
            return "x";
        }
        StringBuilder sb = new StringBuilder();
        char first = raw.charAt(0);
        if (isIdentStart(first)) {
            sb.append(first);
        } else {
            sb.append('a');
            if (isIdentPart(first)) {
                sb.append(first);
            }
        }
        for (int i = 1; i < raw.length() && sb.length() < 24; i++) {
            char c = raw.charAt(i);
            sb.append(isIdentPart(c) ? c : 'a');
        }
        String s = sb.toString();
        if (isKeyword(s)) {
            s = s + "a";
        }
        return s;
    }

    private static boolean isIdentStart(char c) {
        return c == '$' || c == '_' || Character.isLetter(c);
    }

    private static boolean isIdentPart(char c) {
        return isIdentStart(c) || Character.isDigit(c);
    }

    private static boolean isKeyword(String s) {
        return "break".equals(s) || "case".equals(s) || "catch".equals(s) || "continue".equals(s)
                || "debugger".equals(s) || "default".equals(s) || "delete".equals(s) || "do".equals(s)
                || "else".equals(s) || "finally".equals(s) || "for".equals(s) || "function".equals(s)
                || "if".equals(s) || "in".equals(s) || "instanceof".equals(s) || "new".equals(s)
                || "return".equals(s) || "switch".equals(s) || "this".equals(s) || "throw".equals(s)
                || "try".equals(s) || "typeof".equals(s) || "var".equals(s) || "void".equals(s)
                || "while".equals(s) || "with".equals(s) || "null".equals(s) || "true".equals(s)
                || "false".equals(s);
    }

    private static Node buildSubNegZeroAst(String ident) {
        Node name = Node.newString(Token.NAME, ident);
        Node zero = Node.newNumber(0.0);
        Node negZeroExpr = new Node(Token.NEG, zero);
        Node sub = new Node(Token.SUB, name, negZeroExpr);
        Node expr = new Node(Token.EXPR_RESULT, sub);
        return new Node(Token.SCRIPT, expr);
    }

    private static String quoteForMsg(String s) {
        return "\"" + s + "\"";
    }
}

