package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.jstype.JSType;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String helperName = sanitizeIdentifier(data.consumeAsciiString(10), "u");
        String functionName = sanitizeIdentifier(data.consumeAsciiString(10), "f");
        String paramName = sanitizeIdentifier(data.consumeAsciiString(10), "b");
        String altParamName = sanitizeIdentifier(data.consumeAsciiString(10), "c");

        if (helperName.equals(functionName)) {
            helperName = helperName + "H";
        }
        if (paramName.equals(altParamName)) {
            altParamName = altParamName + "2";
        }

        String js =
                "/** @return {boolean} */ function " + helperName + "() { return true; }" +
                "/** @param {boolean} " + paramName + "\n@return {?boolean} */" +
                "function " + functionName + "(" + paramName + ") { if (" + helperName + "()) { " +
                paramName + " = null; } return " + paramName + "; }";

        String jsRenamed =
                "/** @return {boolean} */ function " + helperName + "() { return true; }" +
                "/** @param {boolean} " + altParamName + "\n@return {?boolean} */" +
                "function " + functionName + "2(" + altParamName + ") { if (" + helperName + "()) { " +
                altParamName + " = null; } return " + altParamName + "; }";

        ParamInfo info = analyzeFunctionParameter(js, functionName, paramName);
        ParamInfo infoRenamed = analyzeFunctionParameter(jsRenamed, functionName + "2", altParamName);

        // Lifted oracle from the patched method itself: when a function parameter has an
        // explicit JSDoc type, declareArguments must define the slot with inferred=false.
        // The diff changes exactly this observable property.
        if (info.jsDocType == null) {
            return;
        }
        if (info.inferred) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:declared-param-not-inferred] semantic mismatch: parameter "
                            + paramName + " had explicit JSDoc type " + info.jsDocType
                            + " but Var.isTypeInferred() was true");
        }

        // Consistency cross-check: the declared variable's type should agree with the JSDoc
        // parameter node's type because declareArguments passes jsDocParameter.getJSType()
        // into defineSlot for that exact parameter.
        if (info.varType == null || !info.jsDocType.equals(info.varType)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:param-type-consistency] consistency violation: jsDocType="
                            + String.valueOf(info.jsDocType) + " varType=" + String.valueOf(info.varType));
        }

        // Metamorphic relation: consistent alpha-renaming of the parameter preserves the same
        // explicit-typed-parameter shape, so the renamed parameter must also be non-inferred.
        if (infoRenamed.jsDocType == null) {
            return;
        }
        if (infoRenamed.inferred) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:alpha-renamed-param-not-inferred] metamorphic violation: renamed parameter "
                            + altParamName + " had explicit JSDoc type " + infoRenamed.jsDocType
                            + " but Var.isTypeInferred() was true");
        }

        // Same consistency check on the alpha-renamed sibling.
        if (infoRenamed.varType == null || !infoRenamed.jsDocType.equals(infoRenamed.varType)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:alpha-renamed-type-consistency] consistency violation: jsDocType="
                            + String.valueOf(infoRenamed.jsDocType) + " varType=" + String.valueOf(infoRenamed.varType));
        }
    }

    private static ParamInfo analyzeFunctionParameter(String js, String functionName, String paramName) {
        Compiler compiler = new Compiler();
        Node script = compiler.parseTestCode(js);
        TypedScopeCreator creator = newTypedScopeCreator(compiler);

        Scope globalScope = invokeCreateScope(creator, script, null);
        Node functionNode = findNamedFunction(script, functionName);
        if (functionNode == null) {
            throw new RuntimeException("Function node not found: " + functionName);
        }
        Scope functionScope = invokeCreateScope(creator, functionNode, globalScope);
        Scope.Var var = functionScope.getVar(paramName);
        if (var == null) {
            throw new RuntimeException("Parameter var not found: " + paramName);
        }

        JSType jsDocType = null;
        JSType varType = var.getType();

        if (functionNode.getJSType() != null) {
            Node params = ((com.google.javascript.rhino.jstype.FunctionType) functionNode.getJSType()).getParametersNode();
            if (params != null && params.getFirstChild() != null) {
                jsDocType = params.getFirstChild().getJSType();
            }
        }

        return new ParamInfo(var.isTypeInferred(), jsDocType, varType);
    }

    private static TypedScopeCreator newTypedScopeCreator(Compiler compiler) {
        Constructor[] ctors = TypedScopeCreator.class.getDeclaredConstructors();
        for (int i = 0; i < ctors.length; i++) {
            Constructor ctor = ctors[i];
            Object[] args = buildArgs(ctor.getParameterTypes(), compiler);
            if (args == null) {
                continue;
            }
            try {
                ctor.setAccessible(true);
                return (TypedScopeCreator) ctor.newInstance(args);
            } catch (InstantiationException e) {
                throw new RuntimeException(e);
            } catch (IllegalAccessException e) {
                throw new RuntimeException(e);
            } catch (InvocationTargetException e) {
                throw rethrowInvocationTarget(e);
            }
        }
        throw new RuntimeException("No usable TypedScopeCreator constructor found");
    }

    private static Object[] buildArgs(Class[] types, Compiler compiler) {
        Object[] args = new Object[types.length];
        for (int i = 0; i < types.length; i++) {
            Class t = types[i];
            if (AbstractCompiler.class.isAssignableFrom(t) || Compiler.class.isAssignableFrom(t)) {
                args[i] = compiler;
            } else if (CodingConvention.class.isAssignableFrom(t)) {
                args[i] = compiler.getCodingConvention();
            } else if (com.google.javascript.rhino.jstype.JSTypeRegistry.class.isAssignableFrom(t)) {
                args[i] = compiler.getTypeRegistry();
            } else if (t == boolean.class || t == Boolean.class) {
                args[i] = Boolean.FALSE;
            } else if (t == String.class) {
                args[i] = "testcode";
            } else if (!t.isPrimitive()) {
                args[i] = null;
            } else {
                return null;
            }
        }
        return args;
    }

    private static Scope invokeCreateScope(TypedScopeCreator creator, Node node, Scope parent) {
        try {
            Method m = TypedScopeCreator.class.getDeclaredMethod("createScope", Node.class, Scope.class);
            m.setAccessible(true);
            return (Scope) m.invoke(creator, node, parent);
        } catch (NoSuchMethodException e) {
            throw new RuntimeException(e);
        } catch (IllegalAccessException e) {
            throw new RuntimeException(e);
        } catch (InvocationTargetException e) {
            throw rethrowInvocationTarget(e);
        }
    }

    private static RuntimeException rethrowInvocationTarget(InvocationTargetException e) {
        Throwable cause = e.getCause();
        if (cause instanceof RuntimeException) {
            return (RuntimeException) cause;
        }
        if (cause instanceof Error) {
            throw (Error) cause;
        }
        return new RuntimeException(cause);
    }

    private static Node findNamedFunction(Node root, String functionName) {
        if (root == null) {
            return null;
        }
        if (root.getType() == com.google.javascript.rhino.Token.FUNCTION) {
            Node name = root.getFirstChild();
            if (name != null && functionName.equals(name.getString())) {
                return root;
            }
        }
        for (Node c = root.getFirstChild(); c != null; c = c.getNext()) {
            Node found = findNamedFunction(c, functionName);
            if (found != null) {
                return found;
            }
        }
        return null;
    }

    private static String sanitizeIdentifier(String s, String fallback) {
        if (s == null || s.length() == 0) {
            return fallback;
        }
        StringBuilder out = new StringBuilder();
        char first = s.charAt(0);
        if (Character.isLetter(first) || first == '_' || first == '$') {
            out.append(first);
        } else {
            out.append(fallback.charAt(0));
        }
        for (int i = 1; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLetterOrDigit(c) || c == '_' || c == '$') {
                out.append(c);
            } else {
                out.append('x');
            }
        }
        if (out.length() == 0) {
            return fallback;
        }
        return out.toString();
    }

    private static final class ParamInfo {
        final boolean inferred;
        final JSType jsDocType;
        final JSType varType;

        ParamInfo(boolean inferred, JSType jsDocType, JSType varType) {
            this.inferred = inferred;
            this.jsDocType = jsDocType;
            this.varType = varType;
        }
    }
}

