package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Arrays;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        runLiftedTestOracles();
        runGeneralizedCircleChecks(data);
    }

    private static void runLiftedTestOracles() {
        try {
            Circle circle = new Circle();
            circle.addPoint(30.0, 68.0);
            circle.addPoint(50.0, -6.0);
            circle.addPoint(110.0, -20.0);
            circle.addPoint(35.0, 15.0);
            circle.addPoint(45.0, 97.0);

            LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
            VectorialPointValuePair optimum =
                    optimizer.optimize(
                            circle,
                            new double[] {0, 0, 0, 0, 0},
                            new double[] {1, 1, 1, 1, 1},
                            new double[] {98.680, 47.345});

            if (!(optimizer.getEvaluations() < 10)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-evaluations] semantic mismatch: expected optimizer.getEvaluations() < 10 but was "
                                + optimizer.getEvaluations());
            }
            if (!(optimizer.getJacobianEvaluations() < 10)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-jacobian-evaluations] semantic mismatch: expected optimizer.getJacobianEvaluations() < 10 but was "
                                + optimizer.getJacobianEvaluations());
            }

            double rms = optimizer.getRMS();
            double actualCircleRms = Math.sqrt(circle.getN()) * rms;
            if (Double.isNaN(actualCircleRms) || Math.abs(actualCircleRms - 1.768262623567235) > 1.0e-10) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-rms] semantic mismatch: Math.sqrt(circle.getN()) * rms expected=1.768262623567235 actual="
                                + actualCircleRms
                                + " tol=1.0E-10");
            }

            Point2D.Double center = new Point2D.Double(optimum.getPointRef()[0], optimum.getPointRef()[1]);

            double actualRadius = circle.getRadius(center);
            if (Double.isNaN(actualRadius) || Math.abs(actualRadius - 69.96016176931406) > 1.0e-10) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-radius] semantic mismatch: circle.getRadius(center) expected=69.96016176931406 actual="
                                + actualRadius
                                + " tol=1.0E-10");
            }

            if (Double.isNaN(center.x) || Math.abs(center.x - 96.07590211815305) > 1.0e-10) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-center-x] semantic mismatch: center.x expected=96.07590211815305 actual="
                                + center.x
                                + " tol=1.0E-10");
            }

            if (Double.isNaN(center.y) || Math.abs(center.y - 48.13516790438953) > 1.0e-10) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-center-y] semantic mismatch: center.y expected=48.13516790438953 actual="
                                + center.y
                                + " tol=1.0E-10");
            }

            double[][] cov = optimizer.getCovariances();

            if (Double.isNaN(cov[0][0]) || Math.abs(cov[0][0] - 1.839) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-cov00] semantic mismatch: cov[0][0] expected=1.839 actual="
                                + cov[0][0]
                                + " tol=0.001");
            }
            if (Double.isNaN(cov[0][1]) || Math.abs(cov[0][1] - 0.731) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-cov01] semantic mismatch: cov[0][1] expected=0.731 actual="
                                + cov[0][1]
                                + " tol=0.001");
            }
            if (Double.isNaN(cov[1][0]) || Math.abs(cov[1][0] - cov[0][1]) > 1.0e-14) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-cov-symmetric-1] semantic mismatch: cov[1][0] expected="
                                + cov[0][1]
                                + " actual="
                                + cov[1][0]
                                + " tol=1.0E-14");
            }
            if (Double.isNaN(cov[1][1]) || Math.abs(cov[1][1] - 0.786) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-cov11] semantic mismatch: cov[1][1] expected=0.786 actual="
                                + cov[1][1]
                                + " tol=0.001");
            }

            double[] errors = optimizer.guessParametersErrors();
            if (Double.isNaN(errors[0]) || Math.abs(errors[0] - 1.384) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-errors0] semantic mismatch: errors[0] expected=1.384 actual="
                                + errors[0]
                                + " tol=0.001");
            }
            if (Double.isNaN(errors[1]) || Math.abs(errors[1] - 0.905) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-errors1] semantic mismatch: errors[1] expected=0.905 actual="
                                + errors[1]
                                + " tol=0.001");
            }

            double r = circle.getRadius(center);
            for (double d = 0; d < 2 * Math.PI; d += 0.01) {
                circle.addPoint(center.x + r * Math.cos(d), center.y + r * Math.sin(d));
            }
            double[] target = new double[circle.getN()];
            Arrays.fill(target, 0.0);
            double[] weights = new double[circle.getN()];
            Arrays.fill(weights, 2.0);

            optimizer.optimize(circle, target, weights, new double[] {98.680, 47.345});

            cov = optimizer.getCovariances();
            if (Double.isNaN(cov[0][0]) || Math.abs(cov[0][0] - 0.0016) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-dense-cov00] semantic mismatch: cov[0][0] expected=0.0016 actual="
                                + cov[0][0]
                                + " tol=0.001");
            }
            if (Double.isNaN(cov[0][1]) || Math.abs(cov[0][1] - 3.2e-7) > 1.0e-9) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-dense-cov01] semantic mismatch: cov[0][1] expected=3.2E-7 actual="
                                + cov[0][1]
                                + " tol=1.0E-9");
            }
            if (Double.isNaN(cov[1][0]) || Math.abs(cov[1][0] - cov[0][1]) > 1.0e-14) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-dense-cov-symmetric-1] semantic mismatch: cov[1][0] expected="
                                + cov[0][1]
                                + " actual="
                                + cov[1][0]
                                + " tol=1.0E-14");
            }
            if (Double.isNaN(cov[1][1]) || Math.abs(cov[1][1] - 0.0016) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-dense-cov11] semantic mismatch: cov[1][1] expected=0.0016 actual="
                                + cov[1][1]
                                + " tol=0.001");
            }

            errors = optimizer.guessParametersErrors();
            if (Double.isNaN(errors[0]) || Math.abs(errors[0] - 0.004) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-dense-errors0] semantic mismatch: errors[0] expected=0.004 actual="
                                + errors[0]
                                + " tol=0.001");
            }
            if (Double.isNaN(errors[1]) || Math.abs(errors[1] - 0.004) > 0.001) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-dense-errors1] semantic mismatch: errors[1] expected=0.004 actual="
                                + errors[1]
                                + " tol=0.001");
            }

            // Contract justification: get* methods are documented as readers ("Get ..."), so they must be
            // observationally read-only. A patch that merely avoids the wrong computation by skipping/altering
            // bookkeeping could leave hidden state mutations here; rereading should yield the same values.
            double chiBefore = optimizer.getChiSquare();
            double rmsBefore = optimizer.getRMS();
            int evalBefore = optimizer.getEvaluations();
            int jacEvalBefore = optimizer.getJacobianEvaluations();
            double[][] covBefore = optimizer.getCovariances();
            double[] errBefore = optimizer.guessParametersErrors();

            double chiAfter = optimizer.getChiSquare();
            double rmsAfter = optimizer.getRMS();
            int evalAfter = optimizer.getEvaluations();
            int jacEvalAfter = optimizer.getJacobianEvaluations();
            double[][] covAfter = optimizer.getCovariances();
            double[] errAfter = optimizer.guessParametersErrors();

            if (Double.doubleToLongBits(chiBefore) != Double.doubleToLongBits(chiAfter)
                    || Double.doubleToLongBits(rmsBefore) != Double.doubleToLongBits(rmsAfter)
                    || evalBefore != evalAfter
                    || jacEvalBefore != jacEvalAfter
                    || !sameMatrixBits(covBefore, covAfter)
                    || !sameArrayBits(errBefore, errAfter)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:getters-read-only] semantic mismatch: repeated documented getters changed observable optimizer state");
            }

            // Contract justification: getChiSquare is defined as the weighted sum of squared residuals, and
            // getRMS is documented as sqrt(c/n). Therefore chiSquare must equal n * RMS^2 for any completed
            // optimization state; a throw-deleting or bookkeeping-skipping patch would break this relation.
            double rhs = circle.getN() * optimizer.getRMS() * optimizer.getRMS();
            double tol = 1.0e-12 * Math.max(1.0, Math.max(Math.abs(optimizer.getChiSquare()), Math.abs(rhs)));
            if (Math.abs(optimizer.getChiSquare() - rhs) > tol) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:circle-rms-chi] semantic mismatch: chiSquare="
                                + optimizer.getChiSquare()
                                + " rhs=n*rms^2="
                                + rhs);
            }
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            return;
        }
    }

    private static void runGeneralizedCircleChecks(FuzzedDataProvider data) {
        int n = data.consumeInt(3, 12);
        double cx = data.consumeInt(-200, 200);
        double cy = data.consumeInt(-200, 200);
        double radius = data.consumeInt(10, 150);
        double noise = data.consumeInt(0, 20) / 100.0;
        double startX = cx + data.consumeInt(-50, 50);
        double startY = cy + data.consumeInt(-50, 50);
        int weightInt = data.consumeInt(1, 20);
        double weight = (double) weightInt;

        Circle circle = new Circle();
        for (int i = 0; i < n; i++) {
            double angle = (2.0 * Math.PI * i) / n;
            double radial = radius + ((i % 2 == 0) ? noise : -noise);
            circle.addPoint(cx + radial * Math.cos(angle), cy + radial * Math.sin(angle));
        }

        LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
        double chi;
        double rms;
        VectorialPointValuePair vp;
        double[][] cov1;
        double[][] cov2;
        double[] err1;
        double[] err2;
        try {
            double[] target = new double[circle.getN()];
            Arrays.fill(target, 0.0);
            double[] weights = new double[circle.getN()];
            Arrays.fill(weights, weight);

            vp = opt.optimize(circle, target, weights, new double[] {startX, startY});
            chi = opt.getChiSquare();
            rms = opt.getRMS();
            cov1 = opt.getCovariances();
            cov2 = opt.getCovariances();
            err1 = opt.guessParametersErrors();
            err2 = opt.guessParametersErrors();
        } catch (Exception e) {
            return;
        }

        // Contract justification: getChiSquare computes the weighted sum of squared residuals for the current
        // residual state. Using the real optimized point and the real function value, the optimizer's reader
        // must agree with that weighted sum.
        double[] value = vp.getValueRef();
        double expectedChi = 0.0;
        for (int i = 0; i < value.length; i++) {
            double residual = value[i];
            expectedChi += weight * residual * residual;
        }
        double tolChi = 1.0e-6 * Math.max(1.0, Math.max(Math.abs(chi), Math.abs(expectedChi)));
        if (Math.abs(chi - expectedChi) > tolChi) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:chi-weighted-residuals] semantic mismatch: chi="
                            + chi
                            + " expectedWeightedResidualSum="
                            + expectedChi);
        }

        // Contract justification: getRMS is documented as sqrt(c/n), where c is the minimized criterion.
        // Therefore n * RMS^2 must equal that criterion for every successful optimization.
        double rhs = circle.getN() * rms * rms;
        double tolRms = 1.0e-6 * Math.max(1.0, Math.max(Math.abs(chi), Math.abs(rhs)));
        if (Math.abs(chi - rhs) > tolRms) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:rms-chi-general] semantic mismatch: chi=" + chi + " rhs=n*rms^2=" + rhs);
        }

        // Contract justification: covariance matrices are symmetric in this API and the lifted test asserts
        // that symmetry. Repeated read-only calls should also be stable.
        if (cov1.length >= 2 && cov1[0].length >= 2 && cov1[1].length >= 2) {
            double symTol = 1.0e-12 * Math.max(1.0, Math.max(Math.abs(cov1[0][1]), Math.abs(cov1[1][0])));
            if (Math.abs(cov1[0][1] - cov1[1][0]) > symTol) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:covariance-symmetry] semantic mismatch: cov[0][1]="
                                + cov1[0][1]
                                + " cov[1][0]="
                                + cov1[1][0]);
            }
        }
        if (!sameMatrixBits(cov1, cov2) || !sameArrayBits(err1, err2)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:repeatable-getters-general] semantic mismatch: repeated getCovariances()/guessParametersErrors() calls disagreed");
        }
    }

    private static boolean sameArrayBits(double[] a, double[] b) {
        if (a == b) {
            return true;
        }
        if (a == null || b == null || a.length != b.length) {
            return false;
        }
        for (int i = 0; i < a.length; i++) {
            if (Double.doubleToLongBits(a[i]) != Double.doubleToLongBits(b[i])) {
                return false;
            }
        }
        return true;
    }

    private static boolean sameMatrixBits(double[][] a, double[][] b) {
        if (a == b) {
            return true;
        }
        if (a == null || b == null || a.length != b.length) {
            return false;
        }
        for (int i = 0; i < a.length; i++) {
            if (!sameArrayBits(a[i], b[i])) {
                return false;
            }
        }
        return true;
    }
}

class Circle implements DifferentiableMultivariateVectorialFunction {
    private final ArrayList<Point2D.Double> points;

    public Circle() {
        points = new ArrayList<Point2D.Double>();
    }

    public void addPoint(double px, double py) {
        points.add(new Point2D.Double(px, py));
    }

    public int getN() {
        return points.size();
    }

    public double getRadius(Point2D.Double center) {
        double r = 0;
        for (Point2D.Double point : points) {
            r += point.distance(center);
        }
        return r / points.size();
    }

    public double[] value(double[] variables) {
        Point2D.Double center = new Point2D.Double(variables[0], variables[1]);
        double radius = getRadius(center);
        double[] residuals = new double[points.size()];
        for (int i = 0; i < residuals.length; ++i) {
            residuals[i] = points.get(i).distance(center) - radius;
        }
        return residuals;
    }

    public MultivariateMatrixFunction jacobian() {
        return new MultivariateMatrixFunction() {
            public double[][] value(double[] variables) {
                Point2D.Double center = new Point2D.Double(variables[0], variables[1]);

                double dRdX = 0;
                double dRdY = 0;
                for (Point2D.Double pk : points) {
                    double dk = pk.distance(center);
                    dRdX += (center.x - pk.x) / dk;
                    dRdY += (center.y - pk.y) / dk;
                }
                dRdX /= points.size();
                dRdY /= points.size();

                double[][] jacobian = new double[points.size()][2];
                for (int i = 0; i < jacobian.length; ++i) {
                    Point2D.Double pi = points.get(i);
                    double di = pi.distance(center);
                    jacobian[i][0] = (center.x - pi.x) / di - dRdX;
                    jacobian[i][1] = (center.y - pi.y) / di - dRdY;
                }

                return jacobian;
            }
        };
    }
}

