package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Arrays;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final class Circle implements DifferentiableMultivariateVectorialFunction {
        private final ArrayList<Point2D.Double> points;

        Circle() {
            points = new ArrayList<Point2D.Double>();
        }

        void addPoint(double px, double py) {
            points.add(new Point2D.Double(px, py));
        }

        int getN() {
            return points.size();
        }

        double getRadius(Point2D.Double center) {
            double r = 0.0;
            for (Point2D.Double point : points) {
                r += point.distance(center);
            }
            return r / points.size();
        }

        public double[] value(double[] variables) {
            Point2D.Double center = new Point2D.Double(variables[0], variables[1]);
            double radius = getRadius(center);
            double[] residuals = new double[points.size()];
            for (int i = 0; i < residuals.length; ++i) {
                residuals[i] = points.get(i).distance(center) - radius;
            }
            return residuals;
        }

        public MultivariateMatrixFunction jacobian() {
            return new CircleJacobian(this);
        }
    }

    private static final class CircleJacobian implements MultivariateMatrixFunction {
        private final Circle circle;

        CircleJacobian(Circle circle) {
            this.circle = circle;
        }

        public double[][] value(double[] variables) {
            Point2D.Double center = new Point2D.Double(variables[0], variables[1]);
            double dRdX = 0.0;
            double dRdY = 0.0;
            int n = circle.points.size();
            for (Point2D.Double pk : circle.points) {
                double dk = pk.distance(center);
                dRdX += (center.x - pk.x) / dk;
                dRdY += (center.y - pk.y) / dk;
            }
            dRdX /= n;
            dRdY /= n;

            double[][] jacobian = new double[n][2];
            for (int i = 0; i < n; ++i) {
                Point2D.Double pi = circle.points.get(i);
                double di = pi.distance(center);
                jacobian[i][0] = (center.x - pi.x) / di - dRdX;
                jacobian[i][1] = (center.y - pi.y) / di - dRdY;
            }
            return jacobian;
        }
    }

    private static void fail(String id, String msg) {
        throw new FuzzerSecurityIssueLow("[oracle:" + id + "] semantic mismatch: " + msg);
    }

    private static void assertTrueOrFail(String id, boolean condition, String msg) {
        if (!condition) {
            fail(id, msg);
        }
    }

    private static void assertApprox(String id, double expected, double actual, double tol, String what) {
        if (!(Math.abs(expected - actual) <= tol)) {
            fail(id, what + " expected=" + expected + " actual=" + actual + " tol=" + tol);
        }
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        try {
            Circle circle = new Circle();
            circle.addPoint(30.0, 68.0);
            circle.addPoint(50.0, -6.0);
            circle.addPoint(110.0, -20.0);
            circle.addPoint(35.0, 15.0);
            circle.addPoint(45.0, 97.0);

            LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
            VectorialPointValuePair optimum =
                    optimizer.optimize(
                            circle,
                            new double[] {0, 0, 0, 0, 0},
                            new double[] {1, 1, 1, 1, 1},
                            new double[] {98.680, 47.345});

            assertTrueOrFail("circlefit-evaluations", optimizer.getEvaluations() < 10,
                    "optimizer.getEvaluations() < 10 violated, actual=" + optimizer.getEvaluations());
            assertTrueOrFail("circlefit-jacobian-evaluations", optimizer.getJacobianEvaluations() < 10,
                    "optimizer.getJacobianEvaluations() < 10 violated, actual=" + optimizer.getJacobianEvaluations());

            double rms = optimizer.getRMS();
            assertApprox("circlefit-rms", 1.768262623567235, Math.sqrt(circle.getN()) * rms, 1.0e-10,
                    "Math.sqrt(circle.getN()) * optimizer.getRMS()");

            Point2D.Double center = new Point2D.Double(optimum.getPointRef()[0], optimum.getPointRef()[1]);
            assertApprox("circlefit-radius", 69.96016176931406, circle.getRadius(center), 1.0e-10,
                    "circle.getRadius(center)");
            assertApprox("circlefit-center-x", 96.07590211815305, center.x, 1.0e-10, "center.x");
            assertApprox("circlefit-center-y", 48.13516790438953, center.y, 1.0e-10, "center.y");

            double[][] cov = optimizer.getCovariances();
            assertApprox("circlefit-cov00", 1.839, cov[0][0], 0.001, "cov[0][0]");
            assertApprox("circlefit-cov01", 0.731, cov[0][1], 0.001, "cov[0][1]");
            assertApprox("circlefit-cov-symmetric-1", cov[0][1], cov[1][0], 1.0e-14, "cov[0][1] vs cov[1][0]");
            assertApprox("circlefit-cov11", 0.786, cov[1][1], 0.001, "cov[1][1]");

            double[] errors = optimizer.guessParametersErrors();
            assertApprox("circlefit-errors0", 1.384, errors[0], 0.001, "errors[0]");
            assertApprox("circlefit-errors1", 0.905, errors[1], 0.001, "errors[1]");

            double chiBefore = optimizer.getChiSquare();
            double chiAgain = optimizer.getChiSquare();
            int evalBefore = optimizer.getEvaluations();
            int jacBefore = optimizer.getJacobianEvaluations();
            double rmsAgain = optimizer.getRMS();
            int evalAfter = optimizer.getEvaluations();
            int jacAfter = optimizer.getJacobianEvaluations();

            assertApprox("getter-idempotence-chi", chiBefore, chiAgain, 0.0,
                    "repeated getChiSquare() changed result");
            assertApprox("getter-idempotence-rms", rms, rmsAgain, 0.0,
                    "getRMS() changed between repeated reads");
            assertTrueOrFail("getter-no-mutate-evals", evalBefore == evalAfter,
                    "read-only getters changed evaluations from " + evalBefore + " to " + evalAfter);
            assertTrueOrFail("getter-no-mutate-jac", jacBefore == jacAfter,
                    "read-only getters changed jacobianEvaluations from " + jacBefore + " to " + jacAfter);

            // Contract-based post-condition: getRMS() is documented as sqrt(c/n), where c is the
            // minimized criterion and n is the number of measurements; getChiSquare() reports that
            // weighted criterion. Therefore n * RMS^2 must equal ChiSquare after any successful
            // optimization. A patch that merely suppresses failure or silently computes the wrong
            // criterion violates this observable relation.
            assertApprox("rms-chi-agree-first", chiBefore, circle.getN() * rms * rms,
                    1.0e-12 * Math.max(1.0, Math.max(Math.abs(chiBefore), Math.abs(circle.getN() * rms * rms))),
                    "circle.getN() * rms^2 vs chiSquare after first optimize");

            double r = circle.getRadius(center);
            for (double d = 0; d < 2 * Math.PI; d += 0.01) {
                circle.addPoint(center.x + r * Math.cos(d), center.y + r * Math.sin(d));
            }
            double[] target = new double[circle.getN()];
            Arrays.fill(target, 0.0);
            double[] weights = new double[circle.getN()];
            Arrays.fill(weights, 2.0);

            optimizer.optimize(circle, target, weights, new double[] {98.680, 47.345});

            cov = optimizer.getCovariances();
            assertApprox("circlefit-dense-cov00", 0.0016, cov[0][0], 0.001, "cov[0][0] after dense points");
            assertApprox("circlefit-dense-cov01", 3.2e-7, cov[0][1], 1.0e-9, "cov[0][1] after dense points");
            assertApprox("circlefit-dense-cov-symmetric-1", cov[0][1], cov[1][0], 1.0e-14,
                    "cov[0][1] vs cov[1][0] after dense points");
            assertApprox("circlefit-dense-cov11", 0.0016, cov[1][1], 0.001, "cov[1][1] after dense points");

            errors = optimizer.guessParametersErrors();
            assertApprox("circlefit-dense-errors0", 0.004, errors[0], 0.001, "errors[0] after dense points");
            assertApprox("circlefit-dense-errors1", 0.004, errors[1], 0.001, "errors[1] after dense points");

            double denseChi = optimizer.getChiSquare();
            double denseRms = optimizer.getRMS();
            assertApprox("rms-chi-agree-second", denseChi, circle.getN() * denseRms * denseRms,
                    1.0e-12 * Math.max(1.0, Math.max(Math.abs(denseChi), Math.abs(circle.getN() * denseRms * denseRms))),
                    "circle.getN() * rms^2 vs chiSquare after dense optimize");
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        } catch (RuntimeException e) {
            throw e;
        }

        int w1 = data.consumeInt(1, 20);
        int w2 = data.consumeInt(1, 20);
        int t1 = data.consumeInt(-50, 50);
        int t2 = data.consumeInt(-50, 50);
        int s = data.consumeInt(-20, 20);

        LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
        DifferentiableMultivariateVectorialFunction f = new DifferentiableMultivariateVectorialFunction() {
            public double[] value(double[] p) {
                double x = p[0];
                return new double[] {x, 2.0 * x};
            }

            public MultivariateMatrixFunction jacobian() {
                return new MultivariateMatrixFunction() {
                    public double[][] value(double[] p) {
                        return new double[][] {{1.0}, {2.0}};
                    }
                };
            }
        };

        double chi = 0.0;
        double expected = 0.0;
        double rhs = 0.0;
        boolean ok = false;
        try {
            VectorialPointValuePair vp =
                    opt.optimize(f, new double[] {t1, t2}, new double[] {w1, w2}, new double[] {s});
            chi = opt.getChiSquare();
            double[] v = vp.getValueRef();
            expected = w1 * (v[0] - t1) * (v[0] - t1) + w2 * (v[1] - t2) * (v[1] - t2);
            double rr = opt.getRMS();
            rhs = 2.0 * rr * rr;
            ok = true;
        } catch (Exception e) {
            return;
        }

        if (ok) {
            double tol1 = 1.0e-6 * Math.max(1.0, Math.max(Math.abs(chi), Math.abs(expected)));
            if (Math.abs(chi - expected) > tol1) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:chiSquare_matches_weighted_squared_residuals] semantic mismatch: chiSquare="
                                + chi + " expectedWeightedResidualSum=" + expected + " w1=" + w1 + " w2=" + w2
                                + " t1=" + t1 + " t2=" + t2 + " start=" + s);
            }

            double tol2 = 1.0e-6 * Math.max(1.0, Math.max(Math.abs(chi), Math.abs(rhs)));
            if (Math.abs(chi - rhs) > tol2) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:rms_squared_times_measurement_count_equals_chiSquare] semantic mismatch: chiSquare="
                                + chi + " rhs=2*rms^2=" + rhs + " w1=" + w1 + " w2=" + w2
                                + " t1=" + t1 + " t2=" + t2 + " start=" + s);
            }
        }
    }
}

