package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final double MACHINE_EPS = 2.22044604926e-16;
    private static final double SQRT_EPS = Math.sqrt(MACHINE_EPS);

    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        runJennrichSampsonLiftedOracle();

        int startDelta0 = data.consumeInt(-100, 100);
        int startDelta1 = data.consumeInt(-100, 100);
        int tolScaleCost = data.consumeInt(0, 20);
        int tolScalePar = data.consumeInt(0, 20);
        int orthoScale = data.consumeInt(0, 20);
        int maxIterScale = data.consumeInt(1, 10);

        double[] variedStart = new double[] {
            0.3 + startDelta0 * 1.0e-4,
            0.4 + startDelta1 * 1.0e-4
        };

        double costTol = SQRT_EPS * (0.5 + 0.1 * tolScaleCost);
        double parTol = SQRT_EPS * (0.5 + 0.1 * tolScalePar);
        double orthoTol = MACHINE_EPS * (0.5 + 0.1 * orthoScale);

        runBoundaryVariant(variedStart, costTol, parTol, orthoTol, 300 * maxIterScale);
    }

    private static void runJennrichSampsonLiftedOracle() {
        JennrichSampsonProblem function = new JennrichSampsonProblem(10, new double[] { 0.3, 0.4 });

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (function.getN() + 1));
        optimizer.setCostRelativeTolerance(SQRT_EPS);
        optimizer.setParRelativeTolerance(SQRT_EPS);
        optimizer.setOrthoTolerance(MACHINE_EPS);

        final VectorialPointValuePair optimum;
        try {
            optimum = optimizer.optimize(function, function.getTarget(), function.getWeight(), function.getStartPoint());
        } catch (OptimizationException e) {
            throw new FuzzerSecurityIssueLow("[oracle:jennrich-seed-no-exception] semantic mismatch: optimize threw OptimizationException for the exact Minpack seed: " + e, e);
        } catch (FunctionEvaluationException e) {
            throw new FuzzerSecurityIssueLow("[oracle:jennrich-seed-no-exception] semantic mismatch: optimize threw FunctionEvaluationException for the exact Minpack seed: " + e, e);
        }

        double[] point = optimum.getPointRef();
        if (point.length < 2) {
            throw new FuzzerSecurityIssueLow("[oracle:jennrich-seed-shape] semantic mismatch: optimum point dimension=" + point.length);
        }

        if (Math.abs(point[0] - 0.2578330049) > 1.0e-8) {
            throw new FuzzerSecurityIssueLow("[oracle:jennrich-p0] semantic mismatch: expected first parameter 0.2578330049 but was " + point[0]);
        }
        if (Math.abs(point[1] - 0.257829976764542) > 1.0e-8) {
            throw new FuzzerSecurityIssueLow("[oracle:jennrich-p1] semantic mismatch: expected second parameter 0.257829976764542 but was " + point[1]);
        }

        double rms = optimizer.getRMS();
        if (Math.abs(rms - 11.1517793413499) > 1.0e-8) {
            throw new FuzzerSecurityIssueLow("[oracle:jennrich-rms] semantic mismatch: expected RMS 11.1517793413499 but was " + rms);
        }

        // Contract from AbstractLeastSquaresOptimizer javadoc:
        // RMS is sqrt(c / n), where c is the chi-square criterion reported by getChiSquare().
        // If the patched convergence branch returns with inconsistent shared state, these must disagree.
        double chi = optimizer.getChiSquare();
        double recomputedChi = rms * rms * 10.0;
        if (!closeEnough(chi, recomputedChi, 1.0e-10)) {
            throw new FuzzerSecurityIssueLow("[oracle:rms-chi] consistency violation: chiSquare=" + chi + " recomputed=" + recomputedChi);
        }

        final double[] actualValue;
        try {
            actualValue = function.value(point);
        } catch (FunctionEvaluationException e) {
            return;
        }

        double[] returnedValue = optimum.getValueRef();
        if (actualValue.length != returnedValue.length) {
            throw new FuzzerSecurityIssueLow("[oracle:value-length] semantic mismatch: returned value length=" + returnedValue.length + " recomputed length=" + actualValue.length);
        }
        for (int i = 0; i < actualValue.length; i++) {
            if (!closeEnough(actualValue[i], returnedValue[i], 1.0e-12)) {
                throw new FuzzerSecurityIssueLow("[oracle:value-consistency] consistency violation at index " + i + ": returned=" + returnedValue[i] + " recomputed=" + actualValue[i]);
            }
        }

        JennrichSampsonProblem function2 = new JennrichSampsonProblem(10, new double[] { 0.3, 0.4 });
        LevenbergMarquardtOptimizer optimizer2 = new LevenbergMarquardtOptimizer();
        optimizer2.setMaxIterations(100 * (function2.getN() + 1));
        optimizer2.setCostRelativeTolerance(SQRT_EPS);
        optimizer2.setParRelativeTolerance(SQRT_EPS);
        optimizer2.setOrthoTolerance(MACHINE_EPS);

        final VectorialPointValuePair optimum2;
        try {
            optimum2 = optimizer2.optimize(function2, function2.getTarget(), function2.getWeight(), function2.getStartPoint());
        } catch (OptimizationException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        }

        double[] point2 = optimum2.getPointRef();
        if (point2.length != point.length) {
            throw new FuzzerSecurityIssueLow("[oracle:repeatability-shape] semantic mismatch: first point dimension=" + point.length + " second point dimension=" + point2.length);
        }
        for (int i = 0; i < point.length; i++) {
            if (!closeEnough(point[i], point2[i], 1.0e-12)) {
                throw new FuzzerSecurityIssueLow("[oracle:repeatability] metamorphic violation: identical optimizations disagree at index " + i + " first=" + point[i] + " second=" + point2[i]);
            }
        }
    }

    private static void runBoundaryVariant(double[] start, double costTol, double parTol, double orthoTol, int maxIterations) {
        JennrichSampsonProblem function = new JennrichSampsonProblem(10, start);

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(maxIterations);
        optimizer.setCostRelativeTolerance(costTol);
        optimizer.setParRelativeTolerance(parTol);
        optimizer.setOrthoTolerance(orthoTol);

        final VectorialPointValuePair optimum;
        try {
            optimum = optimizer.optimize(function, function.getTarget(), function.getWeight(), function.getStartPoint());
        } catch (OptimizationException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        }

        // Same documented RMS/ChiSquare relation as above while flipping inputs around the patched condition.
        double rms = optimizer.getRMS();
        double chi = optimizer.getChiSquare();
        double recomputedChi = rms * rms * 10.0;
        if (!closeEnough(chi, recomputedChi, 1.0e-8)) {
            throw new FuzzerSecurityIssueLow("[oracle:boundary-rms-chi] consistency violation: start0=" + start[0] + " start1=" + start[1] + " chiSquare=" + chi + " recomputed=" + recomputedChi);
        }

        final double[] actualValue;
        try {
            actualValue = function.value(optimum.getPointRef());
        } catch (FunctionEvaluationException e) {
            return;
        }

        double[] returnedValue = optimum.getValueRef();
        if (actualValue.length != returnedValue.length) {
            throw new FuzzerSecurityIssueLow("[oracle:boundary-value-length] semantic mismatch: returned value length=" + returnedValue.length + " recomputed length=" + actualValue.length);
        }
        for (int i = 0; i < actualValue.length; i++) {
            if (!closeEnough(actualValue[i], returnedValue[i], 1.0e-10)) {
                throw new FuzzerSecurityIssueLow("[oracle:boundary-value] consistency violation at index " + i + ": returned=" + returnedValue[i] + " recomputed=" + actualValue[i]);
            }
        }
    }

    private static boolean closeEnough(double a, double b, double relTol) {
        if (Double.doubleToLongBits(a) == Double.doubleToLongBits(b)) {
            return true;
        }
        double scale = Math.max(1.0, Math.max(Math.abs(a), Math.abs(b)));
        return Math.abs(a - b) <= relTol * scale;
    }

    private static final class JennrichSampsonProblem implements DifferentiableMultivariateVectorialFunction {
        private final int m;
        private final double[] startPoint;
        private final double[] target;
        private final double[] weight;
        private final MultivariateMatrixFunction jacobian;

        private JennrichSampsonProblem(int m, double[] startPoint) {
            this.m = m;
            this.startPoint = startPoint.clone();
            this.target = new double[m];
            this.weight = new double[m];
            for (int i = 0; i < m; i++) {
                int k = i + 1;
                this.target[i] = 2.0 + 2.0 * k;
                this.weight[i] = 1.0;
            }
            this.jacobian = new MultivariateMatrixFunction() {
                public double[][] value(double[] point) throws FunctionEvaluationException, IllegalArgumentException {
                    if (point == null || point.length != 2) {
                        throw new FunctionEvaluationException(point == null ? new double[0] : point, "dimension mismatch");
                    }
                    double[][] j = new double[m][2];
                    for (int i = 0; i < m; i++) {
                        int k = i + 1;
                        j[i][0] = k * Math.exp(k * point[0]);
                        j[i][1] = k * Math.exp(k * point[1]);
                    }
                    return j;
                }
            };
        }

        public int getN() {
            return 2;
        }

        public double[] getTarget() {
            return target.clone();
        }

        public double[] getWeight() {
            return weight.clone();
        }

        public double[] getStartPoint() {
            return startPoint.clone();
        }

        public double[] value(double[] point) throws FunctionEvaluationException, IllegalArgumentException {
            if (point == null || point.length != 2) {
                throw new FunctionEvaluationException(point == null ? new double[0] : point, "dimension mismatch");
            }
            double[] values = new double[m];
            for (int i = 0; i < m; i++) {
                int k = i + 1;
                values[i] = Math.exp(k * point[0]) + Math.exp(k * point[1]);
            }
            return values;
        }

        public MultivariateMatrixFunction jacobian() {
            return jacobian;
        }
    }
}

