package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import org.apache.commons.math.analysis.SinFunction;
import org.apache.commons.math.analysis.UnivariateRealFunction;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        UnivariateRealFunction f = new SinFunction();
        BrentSolver solver = new BrentSolver();

        boolean threw;

        // Lifted oracle 1: bad interval must throw IllegalArgumentException.
        threw = false;
        try {
            solver.solve(f, 1.0, -1.0);
        } catch (IllegalArgumentException expected) {
            threw = true;
        } catch (Throwable t) {
            return;
        }
        if (!threw) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:bad-interval] semantic mismatch: expected IllegalArgumentException for solve(f, 1, -1)");
        }

        // Lifted oracle 2: non-bracketing interval must throw IllegalArgumentException.
        threw = false;
        try {
            solver.solve(f, 1.0, 1.5);
        } catch (IllegalArgumentException expected) {
            threw = true;
        } catch (Throwable t) {
            return;
        }
        if (!threw) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:no-bracket-2arg] semantic mismatch: expected IllegalArgumentException for solve(f, 1, 1.5)");
        }

        // Establish observable solver state via a successful solve.
        double ok;
        try {
            ok = solver.solve(f, -1.0, 1.0, 0.0);
        } catch (Throwable t) {
            return;
        }
        if (ok != 0.0) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:known-root] semantic mismatch: solve(f, -1, 1, 0) returned " + ok + " instead of 0.0");
        }

        double reported;
        try {
            reported = solver.getResult();
        } catch (Throwable t) {
            return;
        }
        // State-coupling check: setResult(...) during successful solve must agree with getResult().
        if (reported != ok) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:result-state] consistency violation: returned=" + ok + " getResult()=" + reported);
        }

        // Lifted oracle 3: non-bracketing interval with initial guess must throw IllegalArgumentException.
        threw = false;
        try {
            solver.solve(f, 1.0, 1.5, 1.2);
        } catch (IllegalArgumentException expected) {
            threw = true;
        } catch (Throwable t) {
            return;
        }
        if (!threw) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:no-bracket-3arg] semantic mismatch: expected IllegalArgumentException for solve(f, 1, 1.5, 1.2)");
        }

        // Mandatory independent post-condition:
        // solve(...) starts with clearResult(), so a rejected solve must leave no computed result.
        boolean cleared = false;
        try {
            solver.getResult();
        } catch (IllegalStateException expected) {
            cleared = true;
        } catch (Throwable t) {
            return;
        }
        if (!cleared) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:clear-result] consistency violation: rejected solve left a stale observable result");
        }

        // Additional state-coupling check: setter/getter on functionValueAccuracy must agree.
        double acc = (Math.abs(data.consumeInt(-1000000, 1000000)) + 1) / 1000000.0;
        try {
            solver.setFunctionValueAccuracy(acc);
        } catch (Throwable t) {
            return;
        }
        double readBack;
        try {
            readBack = solver.getFunctionValueAccuracy();
        } catch (Throwable t) {
            return;
        }
        if (Double.doubleToLongBits(acc) != Double.doubleToLongBits(readBack)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:accuracy-state] consistency violation: set=" + acc + " get=" + readBack);
        }

        // Generalized non-bracketing family: for any initial strictly between 1 and 1.5,
        // sin(x) is positive throughout [1, 1.5], so solve(f, 1, 1.5, initial) must reject.
        int milli = data.consumeInt(1, 499);
        double initial = 1.0 + (milli / 1000.0);
        threw = false;
        try {
            solver.solve(f, 1.0, 1.5, initial);
        } catch (IllegalArgumentException expected) {
            threw = true;
        } catch (Throwable t) {
            return;
        }
        if (!threw) {
            throw new RuntimeException(
                "[oracle:no-bracket-family] violated: non-bracketing family accepted input=" + initial);
        }

        // Overload agreement on a known-answer input: both overloads must solve the same root.
        double a;
        double b;
        try {
            BrentSolver s1 = new BrentSolver();
            BrentSolver s2 = new BrentSolver();
            a = s1.solve(f, -1.0, 1.0, 0.0);
            b = s2.solve(f, -1.0, 1.0);
        } catch (Throwable t) {
            return;
        }
        if (a != 0.0 || b != 0.0 || a != b) {
            throw new RuntimeException(
                "[oracle:overload-agreement] violated: solve(f,-1,1,0)=" + a + " solve(f,-1,1)=" + b);
        }
    }
}

