package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.SinFunction;
import org.apache.commons.math.analysis.UnivariateRealFunction;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        UnivariateRealFunction f = new SinFunction();

        // Lifted from BrentSolverTest.testBadEndpoints: bad interval must throw.
        try {
            new BrentSolver().solve(f, 1.0, -1.0);
            throw new FuzzerSecurityIssueLow(
                    "[oracle:bad-interval] semantic mismatch: solve(f,1,-1) did not throw IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        } catch (MaxIterationsExceededException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        }

        // Lifted from BrentSolverTest.testBadEndpoints: non-bracketing interval must throw.
        try {
            new BrentSolver().solve(f, 1.0, 1.5);
            throw new FuzzerSecurityIssueLow(
                    "[oracle:no-bracket-2arg] semantic mismatch: solve(f,1,1.5) did not throw IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        } catch (MaxIterationsExceededException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        }

        // Lifted from BrentSolverTest.testBadEndpoints: 3-arg overload must agree and also reject non-bracketing input.
        try {
            new BrentSolver().solve(f, 1.0, 1.5, 1.2);
            throw new FuzzerSecurityIssueLow(
                    "[oracle:no-bracket-3arg] semantic mismatch: solve(f,1,1.5,1.2) did not throw IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        } catch (MaxIterationsExceededException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        }

        // Shared-state consistency check required by the solver API:
        // setFunctionValueAccuracy writes functionValueAccuracy and getFunctionValueAccuracy reads the same field,
        // so a correct implementation must report exactly what was established by the setter/constructor.
        double accuracy = Math.pow(10.0, -data.consumeInt(1, 12));
        BrentSolver accuracySolver = new BrentSolver();
        accuracySolver.setFunctionValueAccuracy(accuracy);
        double reportedAccuracy = accuracySolver.getFunctionValueAccuracy();
        if (Double.doubleToLongBits(reportedAccuracy) != Double.doubleToLongBits(accuracy)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:accuracy-state] consistency violation: set/get functionValueAccuracy disagree set="
                            + accuracy + " got=" + reportedAccuracy);
        }

        // Post-condition on successful solve through the patched public API:
        // solve(...) stores the computed answer via setResult(...); getResult() reads that same stored field,
        // so after a successful call they must agree. A patch that only deletes/changes a throw can still leave
        // this observable state inconsistent.
        try {
            BrentSolver rootSolver = new BrentSolver();
            double returned = rootSolver.solve(f, -1.0, 1.0, 0.0);
            double stored = rootSolver.getResult();
            if (Math.abs(returned - stored) > 0.0) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:result-state] consistency violation: returned=" + returned + " getResult()=" + stored);
            }
            if (Math.abs(returned) > 1.0e-12) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:exact-root] semantic mismatch: solve(sin,-1,1,0) expected 0.0 got " + returned);
            }
        } catch (IllegalArgumentException e) {
            return;
        } catch (MaxIterationsExceededException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        }

        // Independent sibling-agreement oracle:
        // The same-name overloads solve(f,min,max) and solve(f,min,max,initial) are documented to agree where their
        // docs match. For a non-bracketing interval entirely below zero, both must reject. This catches a band-aid
        // that special-cases only positive initial guesses.
        boolean twoArgRejected;
        try {
            new BrentSolver().solve(f, -1.5, -1.0);
            twoArgRejected = false;
        } catch (IllegalArgumentException expected) {
            twoArgRejected = true;
        } catch (MaxIterationsExceededException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        }

        boolean threeArgRejected;
        try {
            new BrentSolver().solve(f, -1.5, -1.0, -1.2);
            threeArgRejected = false;
        } catch (IllegalArgumentException expected) {
            threeArgRejected = true;
        } catch (MaxIterationsExceededException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        }

        if (twoArgRejected != threeArgRejected || !twoArgRejected) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:overload-agreement] metamorphic violation: non-bracketing overloads disagree on rejection "
                            + "twoArgRejected=" + twoArgRejected + " threeArgRejected=" + threeArgRejected);
        }

        // Exploratory reachability through the real public API on fuzzed, moderate inputs.
        // No assertion here unless a trusted relation above applies.
        double base = data.consumeInt(-1000, 1000) / 100.0;
        double width = data.consumeInt(1, 100) / 100.0;
        double min = base;
        double max = base + width;
        double initial = min + (max - min) / 2.0;
        try {
            new BrentSolver().solve(f, min, max, initial);
        } catch (IllegalArgumentException ignored) {
        } catch (MaxIterationsExceededException ignored) {
        } catch (FunctionEvaluationException ignored) {
        }
    }
}

