package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.analysis.SinFunction;
import org.apache.commons.math.analysis.UnivariateRealFunction;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        UnivariateRealFunction f = new SinFunction();

        // Independent hidden-state oracle: setFunctionValueAccuracy/getFunctionValueAccuracy share
        // the same field in UnivariateRealSolverImpl, so the getter must report exactly what the setter stored.
        BrentSolver accuracySolver = new BrentSolver();
        double requestedAccuracy = data.consumeBoolean() ? 1.0e-6 : 1.0e-12;
        accuracySolver.setFunctionValueAccuracy(requestedAccuracy);
        double reportedAccuracy = accuracySolver.getFunctionValueAccuracy();
        if (Double.doubleToLongBits(requestedAccuracy) != Double.doubleToLongBits(reportedAccuracy)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:function-value-accuracy] semantic mismatch: setFunctionValueAccuracy(" +
                requestedAccuracy + ") but getFunctionValueAccuracy() returned " + reportedAccuracy);
        }

        // Lifted oracle #1 from BrentSolverTest.testBadEndpoints:
        // solver.solve(f, 1, -1) must throw IllegalArgumentException for a bad interval.
        BrentSolver badIntervalSolver = new BrentSolver();
        boolean badIntervalNoThrow = false;
        Throwable badIntervalWrong = null;
        try {
            badIntervalSolver.solve(f, 1.0, -1.0);
            badIntervalNoThrow = true;
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            badIntervalWrong = t;
        }
        if (badIntervalWrong != null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:bad-interval] semantic mismatch: expected IllegalArgumentException for solve(f, 1, -1) but got " +
                badIntervalWrong.getClass().getName(), badIntervalWrong);
        }
        if (badIntervalNoThrow) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:bad-interval] semantic mismatch: solve(f, 1, -1) completed normally");
        }

        // Lifted oracle #2 from BrentSolverTest.testBadEndpoints:
        // solver.solve(f, 1, 1.5) must throw IllegalArgumentException for a non-bracketing interval.
        BrentSolver noBracket2ArgSolver = new BrentSolver();
        boolean noBracket2ArgNoThrow = false;
        Throwable noBracket2ArgWrong = null;
        try {
            noBracket2ArgSolver.solve(f, 1.0, 1.5);
            noBracket2ArgNoThrow = true;
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            noBracket2ArgWrong = t;
        }
        if (noBracket2ArgWrong != null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:no-bracket-2arg] semantic mismatch: expected IllegalArgumentException for solve(f, 1, 1.5) but got " +
                noBracket2ArgWrong.getClass().getName(), noBracket2ArgWrong);
        }
        if (noBracket2ArgNoThrow) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:no-bracket-2arg] semantic mismatch: solve(f, 1, 1.5) completed normally");
        }

        // Lifted oracle #3 from BrentSolverTest.testBadEndpoints:
        // solver.solve(f, 1, 1.5, 1.2) must throw IllegalArgumentException because the function values
        // at min, initial, and max all have the same sign. This is the exact buggy case.
        BrentSolver noBracket3ArgSolver = new BrentSolver();
        boolean noBracket3ArgNoThrow = false;
        Throwable noBracket3ArgWrong = null;
        try {
            noBracket3ArgSolver.solve(f, 1.0, 1.5, 1.2);
            noBracket3ArgNoThrow = true;
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            noBracket3ArgWrong = t;
        }
        if (noBracket3ArgWrong != null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:no-bracket-3arg] semantic mismatch: expected IllegalArgumentException for solve(f, 1, 1.5, 1.2) but got " +
                noBracket3ArgWrong.getClass().getName(), noBracket3ArgWrong);
        }
        if (noBracket3ArgNoThrow) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:no-bracket-3arg] semantic mismatch: solve(f, 1, 1.5, 1.2) completed normally");
        }

        // Synthesized invariant from the documented contract:
        // solve(UnivariateRealFunction,double,double,double) throws IllegalArgumentException if the values
        // of the function at the three points have the same sign. For sin on [1+2kπ, 1.5+2kπ] with initial 1.2+2kπ,
        // all three values are positive and min < initial < max by construction.
        int kSameSign = data.consumeInt(0, 2);
        double shiftSameSign = 2.0 * Math.PI * kSameSign;
        double sameSignMin = 1.0 + shiftSameSign;
        double sameSignMax = 1.5 + shiftSameSign;
        double sameSignInitial = 1.2 + shiftSameSign;
        BrentSolver sameSignSolver = new BrentSolver();
        boolean sameSignNoThrow = false;
        Throwable sameSignWrong = null;
        try {
            sameSignSolver.solve(f, sameSignMin, sameSignMax, sameSignInitial);
            sameSignNoThrow = true;
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            sameSignWrong = t;
        }
        if (sameSignWrong != null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:three-same-sign] semantic mismatch: expected IllegalArgumentException for solve(f, " +
                sameSignMin + ", " + sameSignMax + ", " + sameSignInitial + ") but got " +
                sameSignWrong.getClass().getName(), sameSignWrong);
        }
        if (sameSignNoThrow) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:three-same-sign] semantic mismatch: solve(f, " + sameSignMin + ", " +
                sameSignMax + ", " + sameSignInitial + ") completed normally");
        }

        // Oracle from a known answer, plus state-coupling post-condition:
        // On [2kπ, 2kπ+1] for sin, the unique root is exactly the left endpoint min.
        // A correct solver must return that endpoint, and getResult() must agree with the
        // value solve(...) just established because both expose the same stored result.
        int kEndpoint = data.consumeInt(0, 2);
        double endpointMin = 2.0 * Math.PI * kEndpoint;
        double endpointMax = endpointMin + 1.0;
        double endpointInitial = endpointMin + 0.5;
        BrentSolver endpointSolver = new BrentSolver();
        double endpointResult;
        try {
            endpointResult = endpointSolver.solve(f, endpointMin, endpointMax, endpointInitial);
        } catch (Throwable t) {
            endpointResult = Double.NaN;
        }
        if (!Double.isNaN(endpointResult)) {
            double tol = 1.0e-9 * Math.max(1.0, Math.max(Math.abs(endpointResult), Math.abs(endpointMin)));
            if (Math.abs(endpointResult - endpointMin) > tol) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:endpoint-root] semantic mismatch: solve(f, " + endpointMin + ", " +
                    endpointMax + ", " + endpointInitial + ") returned " + endpointResult +
                    " but expected endpoint root " + endpointMin);
            }
            double storedResult = endpointSolver.getResult();
            if (Double.doubleToLongBits(storedResult) != Double.doubleToLongBits(endpointResult)) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:getResult-agrees] consistency violation: solve(...) returned " +
                    endpointResult + " but getResult() reported " + storedResult);
            }
        }

        // Sibling-agreement/metamorphic oracle:
        // The solve(f,min,max) and solve(f,min,max,initial) overloads do the same job on the same
        // logical problem, so on an interval with a unique root they must agree on that root.
        // We construct the interval around the known root π+2kπ of sin.
        int kPi = data.consumeInt(0, 2);
        double shiftPi = 2.0 * Math.PI * kPi;
        double piMin = 3.0 + shiftPi;
        double piMax = 4.0 + shiftPi;
        double piInitial = 3.2 + shiftPi;
        BrentSolver piSolverA = new BrentSolver();
        BrentSolver piSolverB = new BrentSolver();
        double rA;
        double rB;
        try {
            rA = piSolverA.solve(f, piMin, piMax);
            rB = piSolverB.solve(f, piMin, piMax, piInitial);
        } catch (Throwable t) {
            return;
        }
        double expectedPi = Math.PI + shiftPi;
        double tolPi = 1.0e-8 * Math.max(1.0, Math.abs(expectedPi));
        if (Math.abs(rA - expectedPi) > tolPi) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:pi-root-2arg] semantic mismatch: solve(f, " + piMin + ", " + piMax +
                ") returned " + rA + " but expected " + expectedPi);
        }
        if (Math.abs(rB - expectedPi) > tolPi) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:pi-root-3arg] semantic mismatch: solve(f, " + piMin + ", " + piMax + ", " +
                piInitial + ") returned " + rB + " but expected " + expectedPi);
        }
        if (Math.abs(rA - rB) > tolPi) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:overload-agreement] metamorphic violation: solve(f,min,max)=" + rA +
                " disagrees with solve(f,min,max,initial)=" + rB +
                " for min=" + piMin + ", max=" + piMax + ", initial=" + piInitial);
        }
    }
}

