        int kSameSign = data.consumeInt(0, 2);
        double shiftSameSign = 2.0 * Math.PI * kSameSign;
        double sameSignMin = 1.0 + shiftSameSign;
        double sameSignMax = 1.5 + shiftSameSign;
        double sameSignInitial = 1.2 + shiftSameSign;
        BrentSolver sameSignSolver = new BrentSolver();
        boolean sameSignNoThrow = false;
        Throwable sameSignWrong = null;
        try {
            sameSignSolver.solve(f, sameSignMin, sameSignMax, sameSignInitial);
            sameSignNoThrow = true;
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            sameSignWrong = t;
        }
        if (sameSignWrong != null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:three-same-sign] semantic mismatch: expected IllegalArgumentException for solve(f, " +
                sameSignMin + ", " + sameSignMax + ", " + sameSignInitial + ") but got " +
                sameSignWrong.getClass().getName(), sameSignWrong);
        }
        if (sameSignNoThrow) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:three-same-sign] semantic mismatch: solve(f, " + sameSignMin + ", " +
                sameSignMax + ", " + sameSignInitial + ") completed normally");
        }

        // Oracle from a known answer, plus state-coupling post-condition:
        // On [2kπ, 2kπ+1] for sin, the unique root is exactly the left endpoint min.
        // A correct solver must return that endpoint, and getResult() must agree with the
        // value solve(...) just established because both expose the same stored result.
        int kEndpoint = data.consumeInt(0, 2);
        double endpointMin = 2.0 * Math.PI * kEndpoint;
        double endpointMax = endpointMin + 1.0;
        double endpointInitial = endpointMin + 0.5;
        BrentSolver endpointSolver = new BrentSolver();
        double endpointResult;
        try {
            endpointResult = endpointSolver.solve(f, endpointMin, endpointMax, endpointInitial);
        } catch (Throwable t) {
            endpointResult = Double.NaN;
        }
        if (!Double.isNaN(endpointResult)) {
            double tol = 1.0e-9 * Math.max(1.0, Math.max(Math.abs(endpointResult), Math.abs(endpointMin)));
            if (Math.abs(endpointResult - endpointMin) > tol) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:endpoint-root] semantic mismatch: solve(f, " + endpointMin + ", " +
                    endpointMax + ", " + endpointInitial + ") returned " + endpointResult +
                    " but expected endpoint root " + endpointMin);
            }
            double storedResult = endpointSolver.getResult();
            if (Double.doubleToLongBits(storedResult) != Double.doubleToLongBits(endpointResult)) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:getResult-agrees] consistency violation: solve(...) returned " +
                    endpointResult + " but getResult() reported " + storedResult);
            }
        }

        // Sibling-agreement/metamorphic oracle:
        // The solve(f,min,max) and solve(f,min,max,initial) overloads do the same job on the same
        // logical problem, so on an interval with a unique root they must agree on that root.
        // We construct the interval around the known root π+2kπ of sin.
        int kPi = data.consumeInt(0, 2);
        double shiftPi = 2.0 * Math.PI * kPi;
        double piMin = 3.0 + shiftPi;
        double piMax = 4.0 + shiftPi;
        double piInitial = 3.2 + shiftPi;
        BrentSolver piSolverA = new BrentSolver();
        BrentSolver piSolverB = new BrentSolver();
        double rA;
        double rB;
        try {
            rA = piSolverA.solve(f, piMin, piMax);
            rB = piSolverB.solve(f, piMin, piMax, piInitial);
        } catch (Throwable t) {
            return;
        }
        double expectedPi = Math.PI + shiftPi;
        double tolPi = 1.0e-8 * Math.max(1.0, Math.abs(expectedPi));
        if (Math.abs(rA - expectedPi) > tolPi) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:pi-root-2arg] semantic mismatch: solve(f, " + piMin + ", " + piMax +
                ") returned " + rA + " but expected " + expectedPi);
        }
        if (Math.abs(rB - expectedPi) > tolPi) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:pi-root-3arg] semantic mismatch: solve(f, " + piMin + ", " + piMax + ", " +
                piInitial + ") returned " + rB + " but expected " + expectedPi);
        }
        if (Math.abs(rA - rB) > tolPi) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:overload-agreement] metamorphic violation: solve(f,min,max)=" + rA +
                " disagrees with solve(f,min,max,initial)=" + rB +
                " for min=" + piMin + ", max=" + piMax + ", initial=" + piInitial);
        }
    }
}

