// relation: exactEndpointRootReturnedOnUniqueRootInterval
// holds because: The solver returns "the value where the function is zero". On an interval [2kπ, 1+2kπ] for sin, the only zero in the interval is the left endpoint, so any correct implementation must return that endpoint.
// valid input: Use the real sine function with min=2kπ, max=1+2kπ, initial=0.5+2kπ where k is a small nonnegative integer from fuzz data. The interval is valid, the initial point is interior, and the unique root is exactly min.
int k = data.consumeInt(0, 2);
double min = 2.0 * Math.PI * k;
double max = min + 1.0;
double initial = min + 0.5;
org.apache.commons.math.analysis.UnivariateRealFunction f = new org.apache.commons.math.analysis.SinFunction();
org.apache.commons.math.analysis.solvers.BrentSolver solver = new org.apache.commons.math.analysis.solvers.BrentSolver();
double r;
try {
    r = solver.solve(f, min, max, initial);
} catch (Exception e) {
    return;
}
if (!(Math.abs(r - min) <= 1e-9 * Math.max(1.0, Math.max(Math.abs(r), Math.abs(min))))) {
    throw new RuntimeException("relation exactEndpointRootReturnedOnUniqueRootInterval violated: " + r + " vs expected " + min);
}

