package org.apache.commons.math.optimization.linear;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.ArrayList;
import java.util.Collection;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        liftedMath288Recheck();
        constructedKnownOptimumOracle(data);
        equivalentConstraintScalingOracle(data);
        objectiveFunctionFormulaInvariant(data);
        optimizeValueMatchesReturnedPointInvariant(data);
    }

    private static void liftedMath288Recheck() {
        org.apache.commons.math.optimization.RealPointValuePair solution;
        try {
            LinearObjectiveFunction f =
                    new LinearObjectiveFunction(new double[] { 7, 3, 0, 0 }, 0);
            Collection<LinearConstraint> constraints = new ArrayList<LinearConstraint>();
            constraints.add(new LinearConstraint(new double[] { 3, 0, -5, 0 }, Relationship.LEQ, 0.0));
            constraints.add(new LinearConstraint(new double[] { 2, 0, 0, -5 }, Relationship.LEQ, 0.0));
            constraints.add(new LinearConstraint(new double[] { 0, 3, 0, -5 }, Relationship.LEQ, 0.0));
            constraints.add(new LinearConstraint(new double[] { 1, 0, 0, 0 }, Relationship.LEQ, 1.0));
            constraints.add(new LinearConstraint(new double[] { 0, 1, 0, 0 }, Relationship.LEQ, 1.0));
            solution = new SimplexSolver().optimize(
                    f, constraints, org.apache.commons.math.optimization.GoalType.MAXIMIZE, true);
        } catch (Exception e) {
            return;
        }

        double actual = solution.getValue();
        if (Math.abs(actual - 10.0) > 0.0000001d) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:math288-lifted] semantic mismatch: expected solution.getValue()==10.0 but was " + actual);
        }
    }

    private static void constructedKnownOptimumOracle(FuzzedDataProvider data) {
        int ux = data.consumeInt(1, 5);
        int uy = data.consumeInt(1, 5);
        int a = data.consumeInt(1, 10);
        int b = data.consumeInt(1, 10);
        int constant = data.consumeInt(-20, 20);

        org.apache.commons.math.optimization.RealPointValuePair solution;
        double expectedValue = a * (double) ux + b * (double) uy + constant;
        try {
            LinearObjectiveFunction f =
                    new LinearObjectiveFunction(new double[] { a, b, 0, 0 }, constant);
            Collection<LinearConstraint> constraints = new ArrayList<LinearConstraint>();
            constraints.add(new LinearConstraint(new double[] { 3, 0, -5, 0 }, Relationship.LEQ, 0.0));
            constraints.add(new LinearConstraint(new double[] { 2, 0, 0, -5 }, Relationship.LEQ, 0.0));
            constraints.add(new LinearConstraint(new double[] { 0, 3, 0, -5 }, Relationship.LEQ, 0.0));
            constraints.add(new LinearConstraint(new double[] { 1, 0, 0, 0 }, Relationship.LEQ, ux));
            constraints.add(new LinearConstraint(new double[] { 0, 1, 0, 0 }, Relationship.LEQ, uy));
            solution = new SimplexSolver().optimize(
                    f, constraints, org.apache.commons.math.optimization.GoalType.MAXIMIZE, true);
        } catch (Exception e) {
            return;
        }

        double actualValue = solution.getValue();
        double[] point = solution.getPoint();
        double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(actualValue), Math.abs(expectedValue)));

        // By construction, with non-negative variables and only upper bounds on x and y plus auxiliary
        // constraints that can always be satisfied by increasing z and w, maximizing positive a*x+b*y
        // must pick x=ux and y=uy. A patch that merely hides the known symptom but still chooses the
        // wrong pivot row will violate this observable optimum.
        if (Math.abs(actualValue - expectedValue) > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:constructed-optimum] semantic mismatch: expected optimum value "
                            + expectedValue + " but was " + actualValue + " for ux=" + ux + " uy=" + uy
                            + " a=" + a + " b=" + b + " constant=" + constant);
        }
        if (point != null && point.length >= 2) {
            if (Math.abs(point[0] - ux) > 1e-8 || Math.abs(point[1] - uy) > 1e-8) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:constructed-point] semantic mismatch: expected point[0..1]=("
                                + ux + "," + uy + ") but was (" + point[0] + "," + point[1] + ")");
            }
        }
    }

    private static void equivalentConstraintScalingOracle(FuzzedDataProvider data) {
        int ux = data.consumeInt(1, 5);
        int uy = data.consumeInt(1, 5);
        int a = data.consumeInt(1, 10);
        int b = data.consumeInt(1, 10);
        int constant = data.consumeInt(-20, 20);
        int scale = data.consumeInt(1, 5);

        Double lhs = null;
        Double rhs = null;
        try {
            LinearObjectiveFunction f =
                    new LinearObjectiveFunction(new double[] { a, b, 0, 0 }, constant);

            Collection<LinearConstraint> c1 = new ArrayList<LinearConstraint>();
            c1.add(new LinearConstraint(new double[] { 3, 0, -5, 0 }, Relationship.LEQ, 0.0));
            c1.add(new LinearConstraint(new double[] { 2, 0, 0, -5 }, Relationship.LEQ, 0.0));
            c1.add(new LinearConstraint(new double[] { 0, 3, 0, -5 }, Relationship.LEQ, 0.0));
            c1.add(new LinearConstraint(new double[] { 1, 0, 0, 0 }, Relationship.LEQ, ux));
            c1.add(new LinearConstraint(new double[] { 0, 1, 0, 0 }, Relationship.LEQ, uy));

            Collection<LinearConstraint> c2 = new ArrayList<LinearConstraint>();
            c2.add(new LinearConstraint(new double[] { 3 * scale, 0, -5 * scale, 0 }, Relationship.LEQ, 0.0));
            c2.add(new LinearConstraint(new double[] { 2 * scale, 0, 0, -5 * scale }, Relationship.LEQ, 0.0));
            c2.add(new LinearConstraint(new double[] { 0, 3 * scale, 0, -5 * scale }, Relationship.LEQ, 0.0));
            c2.add(new LinearConstraint(new double[] { scale, 0, 0, 0 }, Relationship.LEQ, ux * (double) scale));
            c2.add(new LinearConstraint(new double[] { 0, scale, 0, 0 }, Relationship.LEQ, uy * (double) scale));

            lhs = new SimplexSolver().optimize(
                    f, c1, org.apache.commons.math.optimization.GoalType.MAXIMIZE, true).getValue();
            rhs = new SimplexSolver().optimize(
                    f, c2, org.apache.commons.math.optimization.GoalType.MAXIMIZE, true).getValue();
        } catch (Exception e) {
            return;
        }

        double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(lhs), Math.abs(rhs)));
        // Scaling every coefficient and RHS of a LEQ constraint by the same positive factor preserves the
        // feasible region exactly, so a correct optimizer must return the same optimum value on both LPs.
        if (Math.abs(lhs - rhs) > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:constraint-scaling] metamorphic violation: equivalent scaled constraints changed optimum lhs="
                            + lhs + " rhs=" + rhs + " scale=" + scale);
        }
    }

    private static void objectiveFunctionFormulaInvariant(FuzzedDataProvider data) {
        double[] coeffs = new double[] {
                data.consumeInt(-20, 20), data.consumeInt(-20, 20), data.consumeInt(-20, 20)
        };
        double constant = data.consumeInt(-20, 20);
        double[] point = new double[] {
                data.consumeInt(-20, 20), data.consumeInt(-20, 20), data.consumeInt(-20, 20)
        };

        Double actual = null;
        try {
            LinearObjectiveFunction f = new LinearObjectiveFunction(coeffs, constant);
            actual = f.getValue(point);
        } catch (Exception e) {
            return;
        }

        double expected = coeffs[0] * point[0] + coeffs[1] * point[1] + coeffs[2] * point[2] + constant;
        double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(actual), Math.abs(expected)));
        if (Math.abs(actual - expected) > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:objective-formula] relation violated: actual=" + actual + " expected=" + expected);
        }
    }

    private static void optimizeValueMatchesReturnedPointInvariant(FuzzedDataProvider data) {
        int ux = data.consumeInt(1, 10);
        int uy = data.consumeInt(1, 10);
        int sum = data.consumeInt(1, ux + uy);
        double[] obj = new double[] { data.consumeInt(-10, 10), data.consumeInt(-10, 10) };
        double constant = data.consumeInt(-10, 10);

        org.apache.commons.math.optimization.RealPointValuePair sol;
        Double recomputed;
        try {
            LinearObjectiveFunction f = new LinearObjectiveFunction(obj, constant);
            Collection<LinearConstraint> constraints = new ArrayList<LinearConstraint>();
            constraints.add(new LinearConstraint(new double[] { 1, 0 }, Relationship.LEQ, ux));
            constraints.add(new LinearConstraint(new double[] { 0, 1 }, Relationship.LEQ, uy));
            constraints.add(new LinearConstraint(new double[] { 1, 1 }, Relationship.LEQ, sum));
            sol = new SimplexSolver().optimize(
                    f, constraints, org.apache.commons.math.optimization.GoalType.MAXIMIZE, true);
            recomputed = f.getValue(sol.getPoint());
        } catch (Exception e) {
            return;
        }

        double reported = sol.getValue();
        double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(reported), Math.abs(recomputed)));
        // RealPointValuePair is documented as holding a point and the objective value at that point, so the
        // solver's reported value must agree with re-evaluating the same objective on the returned point.
        if (Math.abs(reported - recomputed) > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:value-point-agreement] consistency violation: reported=" + reported
                            + " recomputed=" + recomputed);
        }
    }
}

