package org.apache.commons.math.special;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static boolean approxEquals(double expected, double actual, double tol) {
        return Math.abs(expected - actual) <= tol;
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        double actualPSeed;
        double actualQSeed;
        try {
            // Lifted exactly from GammaTest.testRegularizedGammaPositivePositive via helper testRegularizedGamma():
            // expected = 0.632120558828558, a = 1.0, x = 1.0, tolerance = 10e-15.
            actualPSeed = Gamma.regularizedGammaP(1.0, 1.0);
            actualQSeed = Gamma.regularizedGammaQ(1.0, 1.0);
        } catch (Exception e) {
            return;
        }

        // Trusted oracle copied from the test helper: TestUtils.assertEquals(expected, actualP, 10e-15).
        if (!approxEquals(0.632120558828558, actualPSeed, 10e-15)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:gamma-positive-positive] semantic mismatch: Gamma.regularizedGammaP(1.0, 1.0) expected=0.632120558828558 actual=" + actualPSeed);
        }

        // Trusted oracle copied from the test helper: TestUtils.assertEquals(actualP, 1.0 - actualQ, 10e-15).
        // Contract justification: Gamma.regularizedGammaQ is documented/implemented as Q(a,x) = 1 - P(a,x),
        // so deleting/skipping computation in one branch would break this observable complement relation.
        double seedComplement = 1.0 - actualQSeed;
        if (!approxEquals(actualPSeed, seedComplement, 10e-15)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-complement] semantic mismatch: p=" + actualPSeed + " 1-q=" + seedComplement);
        }

        // Metamorphic relation from the documented contract:
        // regularizedGammaQ(a,x,epsilon,maxIterations) returns Q(a,x) = 1 - P(a,x),
        // so for shared valid inputs and identical tuning, P and Q must sum to 1.
        // Inputs are fenced to moderate positive ranges by construction.
        double a = data.consumeInt(1, 60) / 4.0;
        double x = data.consumeInt(0, 60) / 4.0;
        double epsilon = Math.pow(10.0, -data.consumeInt(6, 12));
        int maxIterations = data.consumeInt(1000, 100000);

        double p;
        double q;
        try {
            p = Gamma.regularizedGammaP(a, x, epsilon, maxIterations);
            q = Gamma.regularizedGammaQ(a, x, epsilon, maxIterations);
        } catch (Exception e) {
            return;
        }

        double sum = p + q;
        double tol = 1e-9 * Math.max(1.0, Math.abs(sum));
        if (!(Math.abs(sum - 1.0) <= tol)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:p-q-same-tuning] metamorphic violation: P(a,x,eps,it)+Q(a,x,eps,it) must equal 1"
                    + " a=" + a
                    + " x=" + x
                    + " epsilon=" + epsilon
                    + " maxIterations=" + maxIterations
                    + " p=" + p
                    + " q=" + q
                    + " sum=" + sum);
        }
    }
}

