package org.apache.commons.math.special;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        double actualPSeed;
        double actualQSeed;
        try {
            actualPSeed = Gamma.regularizedGammaP(1.0, 1.0);
            actualQSeed = Gamma.regularizedGammaQ(1.0, 1.0);
        } catch (Exception e) {
            return;
        }

        double expectedSeedP = 0.632120558828558;
        double tolSeed = 10e-15;

        if (!(Math.abs(expectedSeedP - actualPSeed) <= tolSeed)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:gamma-test-expected] semantic mismatch: Gamma.regularizedGammaP(1.0, 1.0) expected="
                    + expectedSeedP + " actual=" + actualPSeed);
        }

        double expectedComplement = 1.0 - actualQSeed;
        if (!(Math.abs(actualPSeed - expectedComplement) <= tolSeed)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:gamma-test-complement] semantic mismatch: regularizedGammaP(1.0,1.0)="
                    + actualPSeed + " but 1-regularizedGammaQ(1.0,1.0)=" + expectedComplement);
        }

        double a = data.consumeInt(1, 60) / 4.0;
        double x = data.consumeInt(0, 60) / 4.0;
        double epsilon = Math.pow(10.0, -data.consumeInt(6, 12));
        int maxIterations = data.consumeInt(1000, 100000);

        double pTuned;
        double qTuned;
        try {
            pTuned = Gamma.regularizedGammaP(a, x, epsilon, maxIterations);
            qTuned = Gamma.regularizedGammaQ(a, x, epsilon, maxIterations);
        } catch (Exception e) {
            return;
        }

        double sum = pTuned + qTuned;
        double tolSum = 1e-9 * Math.max(1.0, Math.abs(sum));
        // Contract guarantee: Q(a, x) is the regularized upper incomplete gamma function and P(a, x)
        // is its complement, so for the same a/x/epsilon/maxIterations a correct implementation must
        // satisfy P(a, x) + Q(a, x) = 1. A band-aid that merely silences the known symptom but leaves
        // one computation path wrong will violate this cross-check.
        if (!(Math.abs(sum - 1.0) <= tolSum)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:pq-complement-same-tuning] metamorphic violation: p+q must equal 1 for shared tuning;"
                    + " a=" + a + " x=" + x + " eps=" + epsilon + " maxIt=" + maxIterations
                    + " p=" + pTuned + " q=" + qTuned + " sum=" + sum);
        }

        int branchSelector = data.consumeInt(0, 2);
        double aCf;
        double xCf;
        if (branchSelector == 0) {
            aCf = 1.0 + (data.consumeInt(0, 56) / 4.0);
            xCf = aCf + 0.25 + (data.consumeInt(0, 56) / 4.0);
        } else if (branchSelector == 1) {
            aCf = 2.0 + (data.consumeInt(0, 52) / 4.0);
            xCf = aCf + 1.0;
        } else {
            aCf = 5.0 + (data.consumeInt(0, 40) / 4.0);
            xCf = aCf + 2.0 + (data.consumeInt(0, 20) / 4.0);
        }

        double qDefault;
        double qExplicit;
        try {
            qDefault = Gamma.regularizedGammaQ(aCf, xCf);
            qExplicit = Gamma.regularizedGammaQ(aCf, xCf, 1.0e-15, Integer.MAX_VALUE);
        } catch (Exception e) {
            return;
        }

        double tolOverload = 1e-12 * Math.max(1.0, Math.max(Math.abs(qDefault), Math.abs(qExplicit)));
        // Sibling-agreement check: the 2-arg overload is implemented by delegating to the 4-arg overload
        // with the library's default tuning. Recomputing Q on valid x>a>=1 inputs steers execution through
        // the continued-fraction path (regularizedGammaQ -> ContinuedFraction.evaluate/getA/getB/logGamma),
        // and both overloads must agree up to numerical tolerance on the same mathematical quantity.
        if (!(Math.abs(qDefault - qExplicit) <= tolOverload)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:q-overload-agreement-cf] consistency violation: Gamma.regularizedGammaQ overloads disagree;"
                    + " a=" + aCf + " x=" + xCf + " default=" + qDefault + " explicit=" + qExplicit);
        }
    }
}

