import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Locale;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        Locale realDefaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(Locale.US);
            FastDateFormat format1 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL, Locale.GERMANY);
            FastDateFormat format2 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
            Locale.setDefault(Locale.GERMANY);
            FastDateFormat format3 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);

            if (format1.getLocale() != Locale.GERMANY) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-locale] semantic mismatch: expected same locale de_DE but was " + format1.getLocale());
            }
            if (format2.getLocale() != Locale.US) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-locale] semantic mismatch: expected same locale en_US but was " + format2.getLocale());
            }
            if (format3.getLocale() != Locale.GERMANY) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format3-locale] semantic mismatch: expected same locale de_DE but was " + format3.getLocale());
            }
            if (format1 == format2) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct formatter instances but both were same");
            }
            if (format2 == format3) {
                throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct formatter instances across default-locale change but both were same");
            }
        } finally {
            Locale.setDefault(realDefaultLocale);
        }

        int style = data.consumeInt(0, 3);
        Locale oldDefault1 = Locale.getDefault();
        Locale firstLocale;
        Locale secondLocale;
        try {
            Locale.setDefault(Locale.US);
            firstLocale = FastDateFormat.getDateInstance(style).getLocale();
            Locale.setDefault(Locale.GERMANY);
            secondLocale = FastDateFormat.getDateInstance(style).getLocale();
        } catch (Throwable t) {
            Locale.setDefault(oldDefault1);
            return;
        } finally {
            Locale.setDefault(oldDefault1);
        }
        // Contract: getDateInstance(int style) uses the current default locale, so changing the JVM default
        // locale between two calls must change the returned formatter's locale accordingly.
        if (!Locale.US.equals(firstLocale) || !Locale.GERMANY.equals(secondLocale)) {
            throw new FuzzerSecurityIssueLow("[oracle:dateInstance_tracks_current_default_locale] relation violated: first=" + firstLocale + ", second=" + secondLocale + ", style=" + style);
        }

        Locale[] locales = new Locale[] {Locale.US, Locale.GERMANY, Locale.FRANCE, Locale.JAPAN};
        Locale forced = locales[data.consumeInt(0, locales.length - 1)];
        Locale oldDefault2 = Locale.getDefault();
        FastDateFormat dateNoArg;
        FastDateFormat dateExplicit;
        try {
            Locale.setDefault(forced);
            dateNoArg = FastDateFormat.getDateInstance(style);
            dateExplicit = FastDateFormat.getDateInstance(style, Locale.getDefault());
        } catch (Throwable t) {
            Locale.setDefault(oldDefault2);
            return;
        } finally {
            Locale.setDefault(oldDefault2);
        }
        // Contract: getDateInstance(style) uses the default locale, while getDateInstance(style, locale)
        // uses the specified locale. With locale == Locale.getDefault(), both overloads must select the same formatter.
        if (!dateNoArg.getLocale().equals(dateExplicit.getLocale())
                || !dateNoArg.getPattern().equals(dateExplicit.getPattern())) {
            throw new FuzzerSecurityIssueLow("[oracle:dateInstance_noarg_matches_explicit_default_locale] consistency violation: noarg="
                    + dateNoArg.getLocale() + "/" + dateNoArg.getPattern()
                    + " explicit=" + dateExplicit.getLocale() + "/" + dateExplicit.getPattern()
                    + " style=" + style + " forced=" + forced);
        }

        int dateStyle = data.consumeInt(0, 3);
        int timeStyle = data.consumeInt(0, 3);
        Locale forcedDateTimeLocale = locales[data.consumeInt(0, locales.length - 1)];
        Locale oldDefault3 = Locale.getDefault();
        FastDateFormat dtNoArg;
        FastDateFormat dtExplicit;
        try {
            Locale.setDefault(forcedDateTimeLocale);
            dtNoArg = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
            dtExplicit = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.getDefault());
        } catch (Throwable t) {
            Locale.setDefault(oldDefault3);
            return;
        } finally {
            Locale.setDefault(oldDefault3);
        }
        // Contract: the no-locale and explicit-locale overloads describe the same formatter selection when
        // the explicit locale is the current default locale.
        if (!dtNoArg.getLocale().equals(dtExplicit.getLocale())
                || !dtNoArg.getPattern().equals(dtExplicit.getPattern())) {
            throw new FuzzerSecurityIssueLow("[oracle:dateTimeInstance_noarg_matches_explicit_default_locale] consistency violation: noarg="
                    + dtNoArg.getLocale() + "/" + dtNoArg.getPattern()
                    + " explicit=" + dtExplicit.getLocale() + "/" + dtExplicit.getPattern()
                    + " dateStyle=" + dateStyle + " timeStyle=" + timeStyle + " forced=" + forcedDateTimeLocale);
        }
    }
}

