harness_source:
package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Locale;
import java.util.TimeZone;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        liftedDateTimeOracle();
        generalizedDateTimeRelations(data);
        generalizedDateRelations(data);
    }

    private static void liftedDateTimeOracle() {
        Locale realDefaultLocale = Locale.getDefault();
        FastDateFormat format1;
        FastDateFormat format2;
        FastDateFormat format3;
        try {
            Locale.setDefault(Locale.US);
            format1 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL, Locale.GERMANY);
            format2 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
            Locale.setDefault(Locale.GERMANY);
            format3 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
        } finally {
            Locale.setDefault(realDefaultLocale);
        }

        if (format1.getLocale() != Locale.GERMANY) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-locale] semantic mismatch: expected same locale de_DE but was " + format1.getLocale());
        }
        if (format2.getLocale() != Locale.US) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-locale] semantic mismatch: expected same locale en_US but was " + format2.getLocale());
        }
        if (format3.getLocale() != Locale.GERMANY) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format3-locale] semantic mismatch: expected same locale de_DE but was " + format3.getLocale());
        }
        if (format1 == format2) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct formatter instances but both were same");
        }
        if (format2 == format3) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct formatter instances but both were same");
        }
    }

    private static void generalizedDateTimeRelations(FuzzedDataProvider data) {
        int style = data.consumeInt(0, 3);
        Locale[] locales = new Locale[] {Locale.US, Locale.GERMANY, Locale.FRANCE, Locale.JAPAN};
        Locale forced = locales[data.consumeInt(0, locales.length - 1)];
        TimeZone[] zones = new TimeZone[] {
            TimeZone.getTimeZone("UTC"),
            TimeZone.getTimeZone("GMT+01:00"),
            TimeZone.getTimeZone("America/New_York"),
            TimeZone.getTimeZone("Asia/Tokyo")
        };
        TimeZone zone = zones[data.consumeInt(0, zones.length - 1)];

        Locale oldDefault = Locale.getDefault();
        FastDateFormat implicit = null;
        FastDateFormat explicit = null;
        FastDateFormat first = null;
        FastDateFormat second = null;
        FastDateFormat firstTz = null;
        FastDateFormat secondTz = null;
        try {
            try {
                Locale.setDefault(forced);
                implicit = FastDateFormat.getDateTimeInstance(style, style);
                explicit = FastDateFormat.getDateTimeInstance(style, style, Locale.getDefault());
            } catch (Exception e) {
                return;
            }

            try {
                Locale.setDefault(Locale.US);
                first = FastDateFormat.getDateTimeInstance(style, style);
                Locale.setDefault(Locale.GERMANY);
                second = FastDateFormat.getDateTimeInstance(style, style);
            } catch (Exception e) {
                return;
            }

            try {
                Locale.setDefault(Locale.US);
                firstTz = FastDateFormat.getDateTimeInstance(style, style, zone);
                Locale.setDefault(Locale.GERMANY);
                secondTz = FastDateFormat.getDateTimeInstance(style, style, zone);
            } catch (Exception e) {
                return;
            }
        } finally {
            Locale.setDefault(oldDefault);
        }

        /* Contract: getDateTimeInstance(dateStyle,timeStyle) uses the default locale,
           while getDateTimeInstance(dateStyle,timeStyle,Locale) uses the specified locale.
           With the explicit locale set to Locale.getDefault() at call time, both overloads
           must select the same formatter; a patch that ignores current default locale breaks this. */
        if (!sameLocaleAndPattern(implicit, explicit)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:datetime-noarg-matches-explicit-default] metamorphic violation: implicit locale/pattern="
                    + describe(implicit) + " explicit locale/pattern=" + describe(explicit));
        }

        /* Contract: each no-locale getDateTimeInstance call uses the locale current at that call.
           Therefore changing Locale.setDefault between two calls must be reflected in getLocale()
           of the returned formatters. A cache key bug or deleted bookkeeping silently violates this. */
        if (!Locale.US.equals(first.getLocale()) || !Locale.GERMANY.equals(second.getLocale())) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:datetime-tracks-current-default-locale] metamorphic violation: first="
                    + first.getLocale() + " second=" + second.getLocale());
        }

        /* Same contract as above, but through the overload with an explicit TimeZone.
           The time zone should not cause the locale-sensitive cache selection to forget
           the current default locale between calls. */
        if (!Locale.US.equals(firstTz.getLocale()) || !Locale.GERMANY.equals(secondTz.getLocale())) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:datetime-timezone-overload-tracks-default-locale] metamorphic violation: zone="
                    + zone.getID() + " first=" + firstTz.getLocale() + " second=" + secondTz.getLocale());
        }
    }

    private static void generalizedDateRelations(FuzzedDataProvider data) {
        int style = data.consumeInt(0, 3);
        Locale[] locales = new Locale[] {Locale.US, Locale.GERMANY, Locale.FRANCE, Locale.JAPAN};
        Locale forced = locales[data.consumeInt(0, locales.length - 1)];

        Locale oldDefault = Locale.getDefault();
        FastDateFormat first = null;
        FastDateFormat second = null;
        FastDateFormat a = null;
        FastDateFormat b = null;
        try {
            try {
                Locale.setDefault(Locale.US);
                first = FastDateFormat.getDateInstance(style);
                Locale.setDefault(Locale.GERMANY);
                second = FastDateFormat.getDateInstance(style);
            } catch (Exception e) {
                return;
            }

            try {
                Locale.setDefault(forced);
                a = FastDateFormat.getDateInstance(style);
                b = FastDateFormat.getDateInstance(style, Locale.getDefault());
            } catch (Exception e) {
                return;
            }
        } finally {
            Locale.setDefault(oldDefault);
        }

        /* Contract from FastDateFormat API: getDateInstance(int style) uses the default locale.
           So after switching JVM default locale between calls, each formatter must report the
           locale current at its own creation. This additionally exercises the other patched factory. */
        if (!Locale.US.equals(first.getLocale()) || !Locale.GERMANY.equals(second.getLocale())) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:date-tracks-current-default-locale] metamorphic violation: first="
                    + first.getLocale() + " second=" + second.getLocale());
        }

        /* Sibling-agreement check: getDateInstance(style) and getDateInstance(style, Locale.getDefault())
           describe the same selection when evaluated under the same default locale, so locale and pattern
           must agree for any correct implementation. */
        if (!sameLocaleAndPattern(a, b)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:date-noarg-matches-explicit-default] metamorphic violation: implicit locale/pattern="
                    + describe(a) + " explicit locale/pattern=" + describe(b));
        }
    }

    private static boolean sameLocaleAndPattern(FastDateFormat a, FastDateFormat b) {
        if (a == null || b == null) {
            return false;
        }
        Locale la = a.getLocale();
        Locale lb = b.getLocale();
        String pa = a.getPattern();
        String pb = b.getPattern();
        return ((la == null && lb == null) || (la != null && la.equals(lb)))
            && ((pa == null && pb == null) || (pa != null && pa.equals(pb)));
    }

    private static String describe(FastDateFormat f) {
        if (f == null) {
            return "null";
        }
        return String.valueOf(f.getLocale()) + "/" + String.valueOf(f.getPattern());
    }
}

