package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.ArrayList;
import java.util.List;

public class FuzzHarness {
    private static String stripDelim(String s, char delim) {
        if (s == null) {
            return "x";
        }
        String t = s.replace(String.valueOf(delim), "");
        return t.length() == 0 ? "x" : t;
    }

    private static List collectTokens(StrTokenizer tok) {
        ArrayList out = new ArrayList();
        while (tok.hasNext()) {
            out.add(String.valueOf(tok.next()));
        }
        return out;
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        {
            StrBuilder sb = new StrBuilder("onetwothree");
            sb.deleteFirst("three");

            boolean actualContains = sb.contains('h');
            if (actualContains != false) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lang295-contains] semantic mismatch: expected false for sb.contains('h') after deleteFirst(\"three\"), got "
                        + actualContains);
            }

            int actualIndex = sb.indexOf('h');
            if (actualIndex != -1) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lang295-indexof] semantic mismatch: expected -1 for sb.indexOf('h') after deleteFirst(\"three\"), got "
                        + actualIndex);
            }
        }

        {
            char p = (char) ('a' + data.consumeInt(0, 25));
            char q = (char) ('a' + ((p - 'a' + 1 + data.consumeInt(0, 24)) % 26));
            int prefixLen = data.consumeInt(0, 20);
            int suffixTailLen = data.consumeInt(0, 20);
            StringBuilder psb = new StringBuilder();
            for (int i = 0; i < prefixLen; i++) {
                psb.append(p);
            }
            String prefix = psb.toString();
            String suffix = q + data.consumeAsciiString(suffixTailLen);

            boolean result = false;
            int len = -1;
            boolean applicable = false;
            try {
                StrBuilder sb = new StrBuilder(prefix + suffix);
                sb.deleteFirst(suffix);
                result = sb.contains(q);
                len = sb.length();
                applicable = true;
            } catch (Exception e) {
            }
            if (applicable && result) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:deleted-suffix-char] semantic mismatch: contains returned true for deleted-only char "
                        + q + " after deleteFirst; length=" + len + " prefix=[" + prefix + "] suffix=[" + suffix + "]");
            }
        }

        {
            String s = data.consumeAsciiString(data.consumeInt(0, 40));
            char ch = (char) ('a' + data.consumeInt(0, 25));
            boolean a = false;
            boolean b = false;
            boolean applicable = false;
            try {
                StrBuilder sb = new StrBuilder(s);
                a = sb.contains(ch);
                b = sb.contains(String.valueOf(ch));
                applicable = true;
            } catch (Exception e) {
            }
            if (applicable && a != b) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:contains-overload-agreement] metamorphic violation: contains(char) != contains(String) for one-char string; char="
                        + ch + " builder=[" + s + "] lhs=" + a + " rhs=" + b);
            }
        }

        {
            String seed = data.consumeAsciiString(data.consumeInt(1, 20));
            char needle = (char) ('a' + data.consumeInt(0, 25));
            int beforeCapacity = -1;
            int afterCapacity = -1;
            int beforeLength = -1;
            int afterLength = -1;
            String beforeString = null;
            String afterString = null;
            boolean applicable = false;
            try {
                StrBuilder sb = new StrBuilder(seed);
                beforeCapacity = sb.capacity();
                beforeLength = sb.length();
                beforeString = sb.toString();
                sb.contains(needle);
                afterCapacity = sb.capacity();
                afterLength = sb.length();
                afterString = sb.toString();
                applicable = true;
            } catch (Exception e) {
            }
            if (applicable) {
                if (beforeLength != afterLength || !beforeString.equals(afterString)) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:contains-readonly-content] metamorphic violation: contains(char) is a query ('return true if the builder contains the character') and must not change the builder's content/length; seed=["
                            + seed + "] needle=" + needle + " beforeLength=" + beforeLength + " afterLength=" + afterLength
                            + " before=[" + beforeString + "] after=[" + afterString + "]");
                }
                if (beforeCapacity != afterCapacity) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:contains-readonly-capacity] metamorphic violation: contains(char) is a read-only query and should not observably mutate capacity; seed=["
                            + seed + "] needle=" + needle + " beforeCapacity=" + beforeCapacity + " afterCapacity=" + afterCapacity);
                }
            }
        }

        {
            char delim = '|';
            String left = stripDelim(data.consumeAsciiString(data.consumeInt(1, 12)), delim);
            String right = stripDelim(data.consumeAsciiString(data.consumeInt(1, 12)), delim);
            String extra = stripDelim(data.consumeAsciiString(data.consumeInt(1, 12)), delim);

            List lhs = null;
            List rhs = null;
            String finalString = null;
            boolean applicable = false;
            try {
                StrBuilder sb = new StrBuilder(left + delim + right + delim + extra);
                sb.deleteFirst(String.valueOf(delim) + right + delim + extra);
                finalString = sb.toString();

                StrTokenizer fromBuilder = sb.asTokenizer();
                fromBuilder.setDelimiterChar(delim);
                lhs = collectTokens(fromBuilder);

                StrTokenizer fromString = new StrTokenizer(finalString, delim);
                rhs = collectTokens(fromString);
                applicable = true;
            } catch (Exception e) {
            }
            if (applicable && !lhs.equals(rhs)) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:tokenizer-builder-vs-string] consistency violation: tokenizer iteration (hasNext/next) over StrBuilder disagrees with tokenizing the builder's own toString(); finalString=["
                        + finalString + "] builderTokens=" + lhs + " stringTokens=" + rhs);
            }
        }
    }
}

