package org.jfree.data.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        try {
            TimePeriodValues s = new TimePeriodValues("Test");

            int actual0 = s.getMaxMiddleIndex();
            if (actual0 != -1) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-empty] semantic mismatch: expected=-1 actual=" + actual0);
            }

            s.add(new SimpleTimePeriod(100L, 200L), 1.0);
            int actual1 = s.getMaxMiddleIndex();
            if (actual1 != 0) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-after-1] semantic mismatch: expected=0 actual=" + actual1);
            }
            assertMaxMiddleMatchesSeriesState(s, "post-after-1");

            s.add(new SimpleTimePeriod(300L, 400L), 2.0);
            int actual2 = s.getMaxMiddleIndex();
            if (actual2 != 1) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-after-2] semantic mismatch: expected=1 actual=" + actual2);
            }
            assertMaxMiddleMatchesSeriesState(s, "post-after-2");

            s.add(new SimpleTimePeriod(0L, 50L), 3.0);
            int actual3 = s.getMaxMiddleIndex();
            if (actual3 != 1) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-after-3] semantic mismatch: expected=1 actual=" + actual3);
            }
            assertMaxMiddleMatchesSeriesState(s, "post-after-3");

            s.add(new SimpleTimePeriod(150L, 200L), 4.0);
            int actual4 = s.getMaxMiddleIndex();
            if (actual4 != 1) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-after-4] semantic mismatch: expected=1 actual=" + actual4);
            }
            assertMaxMiddleMatchesSeriesState(s, "post-after-4");

            // Documented overload family: all add(...) overloads add equivalent items to the series.
            // Building the same content through another real overload must preserve the observable
            // "index of the time period with the maximum middle milliseconds".
            TimePeriodValues sOverload = new TimePeriodValues("Test");
            sOverload.add(new TimePeriodValue(new SimpleTimePeriod(100L, 200L), 1.0));
            sOverload.add(new TimePeriodValue(new SimpleTimePeriod(300L, 400L), 2.0));
            sOverload.add(new TimePeriodValue(new SimpleTimePeriod(0L, 50L), 3.0));
            sOverload.add(new TimePeriodValue(new SimpleTimePeriod(150L, 200L), 4.0));
            int overloadIdx = sOverload.getMaxMiddleIndex();
            if (overloadIdx != 1) {
                throw new RuntimeException(
                    "[oracle:overload-agreement] metamorphic violation: equivalent add overload built same logical series but getMaxMiddleIndex differed expected=1 actual="
                        + overloadIdx);
            }
            assertMaxMiddleMatchesSeriesState(sOverload, "post-overload");

            // Generalization from a known answer: construct a family where item 1 must have the
            // greatest middle time but item 3 has the greatest end time. A buggy implementation
            // that reports maxEndIndex instead of maxMiddleIndex violates the documented getter contract.
            long base = data.consumeInt(-100000, 100000);
            long gap = data.consumeInt(10, 1000);
            long width1 = data.consumeInt(2, 200);
            long width2 = data.consumeInt(2, 200);
            long width3 = data.consumeInt(2, 200);
            long width4 = data.consumeInt(2, 200);

            long s1Start = base;
            long s1End = s1Start + width1;

            long s2Start = base + 4 * gap;
            long s2End = s2Start + width2;

            long s3Start = base - 4 * gap;
            long s3End = s3Start + width3;

            long s4Start = s2End + 10 * gap;
            long s4End = s4Start + width4;

            if (middle(s2Start, s2End) > middle(s4Start, s4End)) {
                // If this rare case happens due to chosen widths/gaps, we still exercised the API
                // above through the trusted lifted test; skip the derived assertion for this input.
                return;
            }

            TimePeriodValues g = new TimePeriodValues("Generated");
            g.add(new SimpleTimePeriod(s1Start, s1End), 1.0);
            g.add(new SimpleTimePeriod(s2Start, s2End), 2.0);
            g.add(new SimpleTimePeriod(s3Start, s3End), 3.0);
            g.add(new SimpleTimePeriod(s4Start, s4End), 4.0);

            int generatedIdx = g.getMaxMiddleIndex();
            if (generatedIdx != 1) {
                throw new RuntimeException(
                    "[oracle:constructed-family] metamorphic violation: constructed series fixes max-middle index at 1 but getter returned "
                        + generatedIdx);
            }

            // Post-condition from the getter's own contract:
            // "Returns the index of the time period with the maximum middle milliseconds."
            // So the returned index must point to an item whose midpoint is >= every item's midpoint.
            // A patch that merely suppresses bookkeeping or returns some other index silently breaks this.
            assertMaxMiddleMatchesSeriesState(g, "post-generated");
        } catch (IllegalArgumentException e) {
            return;
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }
    }

    private static void assertMaxMiddleMatchesSeriesState(TimePeriodValues series, String oracleId) {
        try {
            int actualIndex = series.getMaxMiddleIndex();
            int itemCount = series.getItemCount();
            int expectedIndex = -1;
            long expectedMiddle = Long.MIN_VALUE;
            for (int i = 0; i < itemCount; i++) {
                TimePeriod p = series.getTimePeriod(i);
                long m = middle(p.getStart().getTime(), p.getEnd().getTime());
                if (expectedIndex < 0 || m > expectedMiddle) {
                    expectedMiddle = m;
                    expectedIndex = i;
                }
            }
            if (actualIndex != expectedIndex) {
                throw new RuntimeException(
                    "[oracle:" + oracleId + "] metamorphic violation: getMaxMiddleIndex disagrees with series contents actual="
                        + actualIndex + " expected=" + expectedIndex + " itemCount=" + itemCount);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }
    }

    private static long middle(long start, long end) {
        return start / 2L + end / 2L + ((start & 1L) + (end & 1L)) / 2L;
    }
}

