package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String w0 = fuzzWhitespace(data, 3);
        String w1 = fuzzWhitespace(data, 3);
        String w2 = fuzzWhitespace(data, 3);
        String w3 = fuzzWhitespace(data, 3);
        String w4 = fuzzWhitespace(data, 3);
        String w5 = fuzzWhitespace(data, 3);

        String src0 = "goog.provide" + w0 + "(" + w1 + "'apps'" + w2 + ")" + w3 + ";";
        String src1 = "goog.provide" + w0 + "(" + w4 + "'apps.foo.bar.B'" + w2 + ")" + w5 + ";";
        String src2 = "goog.provide" + w1 + "(" + w4 + "'apps.foo.bar.C'" + w3 + ")" + w5 + ";";

        Compiler compiler1;
        try {
            compiler1 = compileStarModules(src0, src1, src2);
        } catch (Throwable t) {
            return;
        }

        String actual1;
        try {
            actual1 = normalizeCode(compiler1.toSource());
        } catch (Throwable t) {
            return;
        }

        String expected = normalizeCode(
            "var apps = {};apps.foo = {};apps.foo.bar = {}" +
            "apps.foo.bar.B = {};" +
            "apps.foo.bar.C = {};"
        );

        if (!expected.equals(actual1)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:lifted-pairs] semantic mismatch: expected=" + expected + " actual=" + actual1);
        }

        Compiler compiler2;
        try {
            compiler2 = compileStarModules(src0, src1, src2);
        } catch (Throwable t) {
            return;
        }

        String actual2;
        try {
            actual2 = normalizeCode(compiler2.toSource());
        } catch (Throwable t) {
            return;
        }

        // Two fresh compilations of the same module graph must rewrite to the same output.
        if (!actual1.equals(actual2)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:fresh-recompute] consistency violation: first=" + actual1 + " second=" + actual2);
        }

        List<String> firstModuleOrder;
        try {
            firstModuleOrder = statementNamesOfFirstModule(compiler1);
        } catch (Throwable t) {
            return;
        }

        int appsPos = firstModuleOrder.indexOf("apps");
        int appsFooPos = firstModuleOrder.indexOf("apps.foo");
        int appsFooBarPos = firstModuleOrder.indexOf("apps.foo.bar");

        // replace() inserts a child namespace after its parent namespace via addChildAfter(..., parentName.replacementNode),
        // so a correct rewrite must leave parent namespaces observable before children in the first module.
        if (!(appsPos != -1 && appsFooPos != -1 && appsFooBarPos != -1
                && appsPos < appsFooPos && appsFooPos < appsFooBarPos)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:parent-before-child] semantic mismatch: first-module-order=" + firstModuleOrder);
        }

        Node relName;
        Node relVar;
        try {
            relName = new Node(Token.NAME);
            relVar = new Node(Token.VAR, relName);
        } catch (Exception e) {
            return;
        }
        if (!(relVar.getFirstChild() == relName
                && relName.getParent() == relVar
                && relName.getNext() == null
                && relVar.getType() == Token.VAR)) {
            throw new FuzzerSecurityIssueLow(
                "relation var-node-has-single-name-child violated: varType="
                    + relVar.getType() + " firstChild=" + relVar.getFirstChild());
        }

        Node c1;
        Node c2;
        Node c3;
        Node parent;
        try {
            c1 = new Node(Token.EXPR_RESULT);
            c2 = new Node(Token.EXPR_RESULT);
            c3 = new Node(Token.EXPR_RESULT);
            parent = new Node(Token.BLOCK, c1, c2);
            parent.addChildAfter(c3, c1);
        } catch (Exception e) {
            return;
        }
        if (!(c1.getNext() == c3 && c3.getNext() == c2 && c3.getParent() == parent)) {
            throw new FuzzerSecurityIssueLow(
                "relation addChildAfter-places-node-immediately-after-target violated: c1.next="
                    + c1.getNext() + " c3.next=" + c3.getNext());
        }
    }

    private static Compiler compileStarModules(String src0, String src1, String src2) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        options.closurePass = true;

        List<JSSourceFile> externs = Collections.emptyList();

        JSModule m0 = new JSModule("m0");
        m0.add(JSSourceFile.fromCode("m0.js", src0));

        JSModule m1 = new JSModule("m1");
        m1.addDependency(m0);
        m1.add(JSSourceFile.fromCode("m1.js", src1));

        JSModule m2 = new JSModule("m2");
        m2.addDependency(m0);
        m2.add(JSSourceFile.fromCode("m2.js", src2));

        List<JSModule> modules = new ArrayList<JSModule>();
        modules.add(m0);
        modules.add(m1);
        modules.add(m2);

        compiler.compileModules(externs, modules, options);
        return compiler;
    }

    private static List<String> statementNamesOfFirstModule(Compiler compiler) {
        List<String> out = new ArrayList<String>();
        Node root = compiler.getRoot();
        if (root == null) {
            return out;
        }
        Node jsRoot = root.getLastChild();
        if (jsRoot == null) {
            return out;
        }
        Node firstScript = jsRoot.getFirstChild();
        if (firstScript == null) {
            return out;
        }
        for (Node stmt = firstScript.getFirstChild(); stmt != null; stmt = stmt.getNext()) {
            String qn = extractStatementQualifiedName(stmt);
            if (qn != null) {
                out.add(qn);
            }
        }
        return out;
    }

    private static String extractStatementQualifiedName(Node stmt) {
        if (stmt == null) {
            return null;
        }
        if (stmt.getType() == Token.VAR) {
            Node name = stmt.getFirstChild();
            if (name != null) {
                return name.getString();
            }
            return null;
        }
        if (stmt.getType() == Token.EXPR_RESULT) {
            Node expr = stmt.getFirstChild();
            if (expr != null) {
                Node lhs = expr.getFirstChild();
                if (lhs != null) {
                    return lhs.getQualifiedName();
                }
            }
        }
        return null;
    }

    private static String normalizeCode(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static String fuzzWhitespace(FuzzedDataProvider data, int maxUnits) {
        int n = data.consumeInt(0, maxUnits);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            switch (data.consumeInt(0, 3)) {
                case 0:
                    sb.append(' ');
                    break;
                case 1:
                    sb.append('\n');
                    break;
                case 2:
                    sb.append('\t');
                    break;
                default:
                    sb.append('\r');
                    break;
            }
        }
        return sb.toString();
    }
}

