            char c = midRaw.charAt(i);
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
                sbMid.append(Character.toLowerCase(c));
            }
        }
        for (int i = 0; i < leafRaw.length(); i++) {
            char c = leafRaw.charAt(i);
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
