        String longB = "C";
        String longNsRoot = longRoot;
        String longNsMid = longRoot + "." + longMid;
        String longNsLeaf = longNsMid + "." + longLeaf;
        String longNsA = longNsLeaf + "." + longA;
        String longNsB = longNsLeaf + "." + longB;

