package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static final DiagnosticType FOO_TYPE =
            DiagnosticType.error("TEST_FOO", "error description here");

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        // Lifted trusted oracle from LightweightMessageFormatterTest.testFormatErrorSpaceEndOfLine2.
        {
            JSError error = JSError.make("javascript/complex.js", 6, 7, FOO_TYPE);
            LightweightMessageFormatter formatter = formatter("if (foo");
            String actual = formatter.formatError(error);
            String expected = "javascript/complex.js:6: ERROR - error description here\n"
                    + "if (foo\n"
                    + "       ^\n";
            if (!normalize(expected).equals(normalize(actual))) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:testFormatErrorSpaceEndOfLine2] semantic mismatch: expected="
                                + quote(expected) + " actual=" + quote(actual));
            }
        }

        // Additional trusted exact oracle from the screened invariant candidate:
        // LINE mode with source info available and charno == sourceExcerpt.length()
        // must render the end-of-line caret, per the method's own comment.
        {
            JSError error = JSError.make("javascript/complex.js", 1, 10, FOO_TYPE);
            LightweightMessageFormatter formatter = formatter("assert (1;");
            String actual = formatter.formatError(error);
            String expected = "javascript/complex.js:1: ERROR - error description here\n"
                    + "assert (1;\n"
