package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import java.util.ArrayList;
import java.util.List;

public class FuzzHarness {
    private static final String EXPECTED_WARNING =
            "inconsistent return type\n" +
            "found   : number\n" +
            "required: string";

    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        String seedJs =
                "/** @constructor */ function F() {}" +
                "/** @type {number} */ F.prototype.bar = 3;" +
                "/** @param {!F} f */ function g(f) {" +
                "  /** @return {string} */" +
                "  function h() {" +
                "    return f.bar;" +
                "  }" +
                "}";

        try {
            List<String> seedWarnings = compileAndGetWarningDescriptions(seedJs);
            if (!containsNormalized(seedWarnings, EXPECTED_WARNING)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:testScoping12-seed] semantic mismatch: expected warning missing for seed input; warnings=" + seedWarnings);
            }
        } catch (Throwable t) {
            if (t instanceof com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) {
                throw (com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) t;
            }
            return;
        }

        String ctorName = toIdentifier(data.consumeAsciiString(12), "F");
        String paramName = toIdentifier(data.consumeAsciiString(12), "f");
        String outerName = toIdentifier(data.consumeAsciiString(12), "g");
        String innerName = toIdentifier(data.consumeAsciiString(12), "h");

        String alphaEquivalentJs =
                "/** @constructor */ function " + ctorName + "() {}" +
                "/** @type {number} */ " + ctorName + ".prototype.bar = 3;" +
                "/** @param {!" + ctorName + "} " + paramName + " */ function " + outerName + "(" + paramName + ") {" +
                "  /** @return {string} */" +
                "  function " + innerName + "() {" +
                "    return " + paramName + ".bar;" +
                "  }" +
                "}";

        try {
            List<String> alphaWarnings = compileAndGetWarningDescriptions(alphaEquivalentJs);
            if (!containsNormalized(alphaWarnings, EXPECTED_WARNING)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:alpha-rename] metamorphic violation: alpha-renaming bound identifiers must not change the type error; warnings=" + alphaWarnings);
            }
        } catch (Throwable t) {
            if (t instanceof com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) {
                throw (com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) t;
            }
            return;
        }

        try {
            List<String> first = compileAndGetWarningDescriptions(alphaEquivalentJs);
            List<String> second = compileAndGetWarningDescriptions(alphaEquivalentJs);
            String firstNorm = normalizeList(first);
            String secondNorm = normalizeList(second);
            // Recompiling identical source with fresh compiler instances must yield the same warning set.
            if (!firstNorm.equals(secondNorm)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:fresh-recompute] consistency violation: identical source produced different warnings across fresh compilations; first="
                                + first + " second=" + second);
            }
        } catch (Throwable t) {
            if (t instanceof com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) {
                throw (com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) t;
            }
        }
    }

    private static List<String> compileAndGetWarningDescriptions(String js) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        try {
            options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.WARNING);
        } catch (Throwable t) {
            return new ArrayList<String>();
        }

        List<JSSourceFile> externs = new ArrayList<JSSourceFile>();
        externs.add(JSSourceFile.fromCode("externs.js", ""));

        List<JSSourceFile> inputs = new ArrayList<JSSourceFile>();
        inputs.add(JSSourceFile.fromCode("input.js", js));

        compiler.compile(externs, inputs, options);

        JSError[] warnings = compiler.getWarnings();
        List<String> descriptions = new ArrayList<String>();
        if (warnings != null) {
            for (int i = 0; i < warnings.length; i++) {
                JSError warning = warnings[i];
                if (warning != null && warning.description != null) {
                    descriptions.add(warning.description);
                }
            }
        }
        return descriptions;
    }

    private static boolean containsNormalized(List<String> warnings, String expected) {
        String expectedNorm = normalize(expected);
        for (int i = 0; i < warnings.size(); i++) {
            if (expectedNorm.equals(normalize(warnings.get(i)))) {
                return true;
            }
        }
        return false;
    }

    private static String normalizeList(List<String> warnings) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < warnings.size(); i++) {
            if (i != 0) {
                sb.append('|');
            }
            sb.append(normalize(warnings.get(i)));
        }
        return sb.toString();
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static String toIdentifier(String raw, String fallback) {
        if (raw == null) {
            return fallback;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < raw.length(); i++) {
            char c = raw.charAt(i);
            boolean ok = (c >= 'a' && c <= 'z')
                    || (c >= 'A' && c <= 'Z')
                    || c == '_'
                    || (i > 0 && c >= '0' && c <= '9');
            if (ok) {
                sb.append(c);
            }
        }
        if (sb.length() == 0) {
            sb.append(fallback);
        }
        char first = sb.charAt(0);
        if (!((first >= 'a' && first <= 'z') || (first >= 'A' && first <= 'Z') || first == '_')) {
            sb.insert(0, 'a');
        }
        return sb.toString();
    }
}

package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.exception.NullArgumentException;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        MannWhitneyUTest testStatistic = new MannWhitneyUTest();

        double[] d1 = new double[1500];
        double[] d2 = new double[1500];
        for (int i = 0; i < 1500; i++) {
            d1[i] = 2.0 * i;
            d2[i] = 2.0 * i + 1.0;
        }

        final double fixedResult;
        try {
            fixedResult = testStatistic.mannWhitneyUTest(d1, d2);
        } catch (Throwable t) {
            return;
        }
        if (!(fixedResult > 0.1)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:big-dataset] semantic mismatch: expected result > 0.1, got " + fixedResult);
        }

        int n = data.consumeInt(46341, 60000);
        double[] x = new double[n];
        double[] y = new double[n];
        for (int i = 0; i < n; i++) {
            x[i] = 2.0 * i;
            y[i] = 2.0 * i + 1.0;
        }

        final double p;
        final double u1;
        try {
            p = testStatistic.mannWhitneyUTest(x, y);
            u1 = testStatistic.mannWhitneyU(x, y);
        } catch (Throwable t) {
            return;
        }

        // Contract/implementation basis: mannWhitneyUTest(x, y) is the asymptotic p-value associated with
        // the same samples whose U statistic is returned by mannWhitneyU(x, y). Recomputing the documented
        // normal-approximation formula from the public U result gives the same quantity through an
        // independent path, so a correct implementation must agree.
        double n1n2 = ((double) n) * ((double) n);
        double uMin = Math.min(u1, n1n2 - u1);
        double eu = n1n2 / 2.0;
        double varU = n1n2 * (2.0 * n + 1.0) / 12.0;
        double z = (uMin - eu) / Math.sqrt(varU);
        double expected = 2.0 * new NormalDistribution(0, 1).cumulativeProbability(z);
        double scale = Math.max(1.0, Math.max(Math.abs(p), Math.abs(expected)));
        double tol = 1e-6 * scale;
        if (!(Math.abs(p - expected) <= tol)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:u-formula] consistency violation: p-value disagrees with public-U recomputation"
                    + " n=" + n
                    + " p=" + p
                    + " expected=" + expected
                    + " u1=" + u1
                    + " uMin=" + uMin);
        }

        final double pxy;
        final double pyx;
        try {
            pxy = testStatistic.mannWhitneyUTest(x, y);
            pyx = testStatistic.mannWhitneyUTest(y, x);
        } catch (Throwable t) {
            return;
        }

        // The two-sided p-value is based on Umin = min(U1, U2); swapping samples exchanges U1 and U2 but
        // leaves Umin unchanged, so the public API must return the same p-value for (x, y) and (y, x).
        double symmetryScale = Math.max(1.0, Math.max(Math.abs(pxy), Math.abs(pyx)));
        double symmetryTol = 1e-12 * symmetryScale;
        if (!(Math.abs(pxy - pyx) <= symmetryTol)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:symmetry] metamorphic violation: swapping samples changed p-value"
                    + " n=" + n
                    + " p(x,y)=" + pxy
                    + " p(y,x)=" + pyx);
        }

        double[] nonNullY = new double[Math.max(1, data.consumeInt(1, 8))];
        for (int i = 0; i < nonNullY.length; i++) {
            nonNullY[i] = data.consumeInt(-1000, 1000);
        }

        try {
            testStatistic.mannWhitneyUTest(null, nonNullY);
        } catch (NullArgumentException expectedNull) {
            return;
        } catch (Throwable t) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:null-x] invariant violation: expected NullArgumentException", t);
        }

        throw new FuzzerSecurityIssueLow(
            "[oracle:null-x] invariant violation: expected NullArgumentException, but call completed normally");
    }
}

