package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.exception.NullArgumentException;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        MannWhitneyUTest testStatistic = new MannWhitneyUTest();

        // Lifted oracle from MannWhitneyUTestTest.testBigDataSet verbatim in substance:
        // d1[i] = 2 * i; d2[i] = 2 * i + 1; result = testStatistic.mannWhitneyUTest(d1, d2);
        // Assert.assertTrue(result > 0.1);
        double liftedResult;
        try {
            double[] d1 = new double[1500];
            double[] d2 = new double[1500];
            for (int i = 0; i < 1500; i++) {
                d1[i] = 2.0 * i;
                d2[i] = 2.0 * i + 1.0;
            }
            liftedResult = testStatistic.mannWhitneyUTest(d1, d2);
        } catch (Throwable e) {
            return;
        }
        if (!(liftedResult > 0.1)) {
            throw new FuzzerSecurityIssueLow("[oracle:big-dataset] semantic mismatch: expected mannWhitneyUTest(d1,d2) > 0.1 for the lifted 1500/1500 ordered samples, actual=" + liftedResult);
        }

        // Independent consistency/metamorphic check.
        // Contract justification: mannWhitneyUTest(x, y) is the asymptotic p-value associated with the
        // Mann-Whitney U statistic for the same samples, so it must agree with the normal-approximation
        // formula computed from the publicly returned mannWhitneyU(x, y). A patch that merely silences
        // the known symptom but leaves the n1*n2 overflow/root-cause in the reachable computation will
        // still violate this equality.
        int n = data.consumeInt(46341, 50000);
        double relationP;
        double relationU1;
        try {
            double[] x = new double[n];
            double[] y = new double[n];
            for (int i = 0; i < n; i++) {
                x[i] = 2.0 * i;
                y[i] = 2.0 * i + 1.0;
            }
            relationP = testStatistic.mannWhitneyUTest(x, y);
            relationU1 = testStatistic.mannWhitneyU(x, y);
        } catch (Throwable e) {
            return;
        }
        double n1n2 = ((double) n) * ((double) n);
        double uMin = Math.min(relationU1, n1n2 - relationU1);
        double eu = n1n2 / 2.0;
        double varU = n1n2 * (2.0 * n + 1.0) / 12.0;
        double z = (uMin - eu) / Math.sqrt(varU);
        double expectedP = 2.0 * new NormalDistribution(0, 1).cumulativeProbability(z);
        double tol = 1e-6 * Math.max(1.0, Math.max(Math.abs(relationP), Math.abs(expectedP)));
        if (!(Math.abs(relationP - expectedP) <= tol)) {
            throw new FuzzerSecurityIssueLow("[oracle:u-formula-large-product] consistency violation: mannWhitneyUTest=" + relationP + " expectedFromPublicUAndDocumentedFormula=" + expectedP + " n=" + n + " u=" + relationU1);
        }

        // Invariant from documented precondition/@throws:
        // mannWhitneyUTest throws NullArgumentException if x or y are null.
        boolean nullViolation = false;
        String nullWhat = null;
        try {
            int len = Math.max(1, data.consumeInt(1, 8));
            double[] y = new double[len];
            for (int i = 0; i < len; i++) {
                y[i] = data.consumeInt(-1000, 1000);
            }
            try {
                testStatistic.mannWhitneyUTest(null, y);
                nullViolation = true;
                nullWhat = "completed normally";
            } catch (NullArgumentException ok) {
            } catch (Throwable e) {
                nullViolation = true;
                nullWhat = "wrong exception class " + e.getClass().getName();
            }
        } catch (Throwable e) {
            return;
        }
        if (nullViolation) {
            throw new FuzzerSecurityIssueLow("[oracle:null-first-sample] invariant violation: " + nullWhat);
        }
    }
}

