double t1 = (double) data.consumeInt(-20, 20);
if (t0 == t1) return;
double w0 = (double) data.consumeInt(1, 10);
double w1 = (double) data.consumeInt(1, 10);
double s = (double) data.consumeInt(-20, 20);
org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction f = new org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction() {
    public double[] value(double[] point) throws org.apache.commons.math.FunctionEvaluationException, IllegalArgumentException {
        return new double[] { point[0], point[0] };
    }
    public org.apache.commons.math.analysis.MultivariateMatrixFunction jacobian() {
        return new org.apache.commons.math.analysis.MultivariateMatrixFunction() {
            public double[][] value(double[] point) throws org.apache.commons.math.FunctionEvaluationException, IllegalArgumentException {
                return new double[][] { { 1.0 }, { 1.0 } };
            }
        };
    }
};
org.apache.commons.math.optimization.general.LevenbergMarquardtOptimizer optimizer;
org.apache.commons.math.optimization.VectorialPointValuePair optimum;
double chi;
