    optimizer = new org.apache.commons.math.optimization.general.LevenbergMarquardtOptimizer();
    optimum = optimizer.optimize(f, new double[] { t0, t1 }, new double[] { w0, w1 }, new double[] { s });
    chi = optimizer.getChiSquare();
} catch (Exception e) { return; }
double[] v = optimum.getValueRef();
double expected = w0 * (t0 - v[0]) * (t0 - v[0]) + w1 * (t1 - v[1]) * (t1 - v[1]);
double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(chi), Math.abs(expected)));
