harness_source:
package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {

    private static final int M = 10;
    private static final double[] SEED_START = new double[] { 0.3, 0.4 };
    private static final double EXPECTED_RMS = 11.1517793413499;
    private static final double[] EXPECTED_POINT = new double[] {
        0.2578330049, 0.257829976764542
    };

    private static final class JennrichSampsonFunction
            implements DifferentiableMultivariateVectorialFunction {

        private final int m;

        JennrichSampsonFunction(int m) {
            this.m = m;
        }

        public double[] value(double[] point) throws FunctionEvaluationException, IllegalArgumentException {
            if (point == null || point.length != 2) {
                throw new IllegalArgumentException("point dimension must be 2");
            }
            double x1 = point[0];
            double x2 = point[1];
            double[] v = new double[m];
            for (int i = 0; i < m; i++) {
                double k = i + 1.0;
                v[i] = 2.0 + 2.0 * k - Math.exp(k * x1) - Math.exp(k * x2);
            }
            return v;
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] point) throws FunctionEvaluationException, IllegalArgumentException {
                    if (point == null || point.length != 2) {
                        throw new IllegalArgumentException("point dimension must be 2");
                    }
                    double x1 = point[0];
                    double x2 = point[1];
                    double[][] j = new double[m][2];
                    for (int i = 0; i < m; i++) {
                        double k = i + 1.0;
                        j[i][0] = -k * Math.exp(k * x1);
                        j[i][1] = -k * Math.exp(k * x2);
                    }
                    return j;
                }
            };
        }
    }

    private static double[] zeros(int n) {
        return new double[n];
    }

    private static double[] ones(int n) {
        double[] v = new double[n];
        for (int i = 0; i < n; i++) {
            v[i] = 1.0;
        }
        return v;
    }

    private static boolean close(double expected, double actual, double tol) {
        return Math.abs(expected - actual) <= tol;
    }

    private static void requireClose(String oracleId, String what, double expected, double actual, double tol) {
        if (!close(expected, actual, tol)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:" + oracleId + "] semantic mismatch: " + what +
                " expected=" + expected + " actual=" + actual + " tol=" + tol
            );
        }
    }

    private static LevenbergMarquardtOptimizer newOptimizer(double costTolScale, double parTolScale) {
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        double base = Math.sqrt(2.22044604926e-16);
        if (!(costTolScale > 0.0) || Double.isNaN(costTolScale) || Double.isInfinite(costTolScale)) {
            costTolScale = 1.0;
        }
        if (!(parTolScale > 0.0) || Double.isNaN(parTolScale) || Double.isInfinite(parTolScale)) {
            parTolScale = 1.0;
        }
        optimizer.setMaxIterations(100 * (2 + 1));
        optimizer.setCostRelativeTolerance(base * costTolScale);
        optimizer.setParRelativeTolerance(base * parTolScale);
        optimizer.setOrthoTolerance(2.22044604926e-16);
        return optimizer;
    }

    private static void checkStateConsistency(
            String oracleId,
            JennrichSampsonFunction function,
            LevenbergMarquardtOptimizer optimizer,
            VectorialPointValuePair optimum) throws FunctionEvaluationException {

        double[] point = optimum.getPointRef();
        double[] storedValue = optimum.getValueRef();
        double[] recomputedValue = function.value(point);

        if (storedValue.length != recomputedValue.length) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:" + oracleId + "] consistency violation: objective length mismatch stored=" +
                storedValue.length + " recomputed=" + recomputedValue.length
            );
        }

        /* Contract used: VectorialPointValuePair stores the objective function value at the point.
         * Therefore optimum.getValueRef() must equal a fresh real evaluation function.value(optimum.getPointRef()).
         * A patch that returns early with stale objective bookkeeping would violate this even if no exception occurs. */
        for (int i = 0; i < storedValue.length; i++) {
            requireClose(oracleId, "value[" + i + "]", recomputedValue[i], storedValue[i], 1.0e-12);
        }

        double independentChiSquare = 0.0;
        for (int i = 0; i < recomputedValue.length; i++) {
            independentChiSquare += recomputedValue[i] * recomputedValue[i];
        }

        /* Contracts used from AbstractLeastSquaresOptimizer:
         * - getChiSquare() reports the chi-square value from current weighted residuals.
         * - getRMS() is documented as sqrt(c / n), where c is the criterion and n the number of measurements.
         * With unit weights and zero target, both quantities can be recomputed independently from the returned objective. */
        double reportedChiSquare = optimizer.getChiSquare();
        requireClose(oracleId, "chiSquare", independentChiSquare, reportedChiSquare, 1.0e-8);

        double reportedRms = optimizer.getRMS();
        double independentRms = Math.sqrt(independentChiSquare / recomputedValue.length);
        requireClose(oracleId, "rms", independentRms, reportedRms, 1.0e-10);
    }

    private static VectorialPointValuePair runSeedOracle(double costTolScale, double parTolScale)
            throws FunctionEvaluationException, OptimizationException {

        JennrichSampsonFunction function = new JennrichSampsonFunction(M);
        LevenbergMarquardtOptimizer optimizer = newOptimizer(costTolScale, parTolScale);
        VectorialPointValuePair optimum =
            optimizer.optimize(function, zeros(M), ones(M), SEED_START.clone());

        requireClose("seed-rms", "optimizer.getRMS()", EXPECTED_RMS, optimizer.getRMS(), 1.0e-8);
        requireClose("seed-p0", "optimum.getPointRef()[0]", EXPECTED_POINT[0], optimum.getPointRef()[0], 1.0e-8);
        requireClose("seed-p1", "optimum.getPointRef()[1]", EXPECTED_POINT[1], optimum.getPointRef()[1], 1.0e-8);

        checkStateConsistency("seed-state", function, optimizer, optimum);
        return optimum;
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        try {
            runSeedOracle(1.0, 1.0);
        } catch (FunctionEvaluationException e) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-no-exception] semantic mismatch: unexpected FunctionEvaluationException " + e
            );
        } catch (OptimizationException e) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-no-exception] semantic mismatch: unexpected OptimizationException " + e
            );
        }

        int which = data.consumeInt(0, 2);
        double costTolScale = 1.0 + (data.consumeInt(-200, 200) * 1.0e-3);
        double parTolScale = 1.0 + (data.consumeInt(-200, 200) * 1.0e-3);
        if (costTolScale <= 0.0) {
            costTolScale = 1.0;
        }
        if (parTolScale <= 0.0) {
            parTolScale = 1.0;
        }

        try {
            if (which == 0) {
                VectorialPointValuePair a = runSeedOracle(costTolScale, parTolScale);
                VectorialPointValuePair b = runSeedOracle(parTolScale, costTolScale);

                /* Metamorphic relation for the same documented test setup:
                 * small perturbations of the stopping tolerances around the test's values should not change the
                 * converged optimum for this well-known benchmark problem. This flips the patched convergence
                 * condition while keeping a trusted oracle: both real API calls solve the same objective. */
                requireClose("tolerance-flip-p0", "p0 across nearby tolerances",
                        a.getPointRef()[0], b.getPointRef()[0], 1.0e-8);
                requireClose("tolerance-flip-p1", "p1 across nearby tolerances",
                        a.getPointRef()[1], b.getPointRef()[1], 1.0e-8);
                requireClose("tolerance-flip-rms", "RMS across nearby tolerances",
                        EXPECTED_RMS, EXPECTED_RMS, 0.0);
            } else if (which == 1) {
                JennrichSampsonFunction function = new JennrichSampsonFunction(M);
                LevenbergMarquardtOptimizer optimizer = newOptimizer(costTolScale, parTolScale);
                VectorialPointValuePair optimum =
                    optimizer.optimize(function, zeros(M), ones(M), SEED_START.clone());
                checkStateConsistency("nearby-state-1", function, optimizer, optimum);
            } else {
                JennrichSampsonFunction function = new JennrichSampsonFunction(M);
                LevenbergMarquardtOptimizer optimizer = newOptimizer(parTolScale, costTolScale);
                VectorialPointValuePair optimum =
                    optimizer.optimize(function, zeros(M), ones(M), SEED_START.clone());
                checkStateConsistency("nearby-state-2", function, optimizer, optimum);
            }
        } catch (FunctionEvaluationException ignored) {
            return;
        } catch (OptimizationException ignored) {
            return;
        }
    }
}

