package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.analysis.SinFunction;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        SinFunction sin = new SinFunction();

        // Shared-state consistency check: setFunctionValueAccuracy writes the field and
        // getFunctionValueAccuracy reads the same field, so they must agree exactly.
        BrentSolver stateSolver = new BrentSolver();
        double requestedAccuracy = (1.0 + data.consumeInt(0, 1000)) * 1.0e-15;
        double observedAccuracy;
        try {
            stateSolver.setFunctionValueAccuracy(requestedAccuracy);
            observedAccuracy = stateSolver.getFunctionValueAccuracy();
        } catch (Throwable ignored) {
            return;
        }
        if (Double.doubleToLongBits(requestedAccuracy) != Double.doubleToLongBits(observedAccuracy)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:functionValueAccuracy] consistency violation: set=" + requestedAccuracy
                    + " get=" + observedAccuracy);
        }

        // Lifted oracle 1 from BrentSolverTest.testBadEndpoints:
        // solver.solve(f, 1, -1) must throw IllegalArgumentException for a bad interval.
        {
            BrentSolver solver = new BrentSolver();
            boolean completedNormally = false;
            Throwable wrong = null;
            try {
                solver.solve(sin, 1.0, -1.0);
                completedNormally = true;
            } catch (IllegalArgumentException expected) {
                // expected
            } catch (Throwable t) {
                wrong = t;
            }
            if (completedNormally) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:bad-interval] semantic mismatch: expected IllegalArgumentException, got completed normally");
            }
            if (wrong != null) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:bad-interval] semantic mismatch: expected IllegalArgumentException, got "
                        + wrong.getClass().getName(),
                    wrong);
            }
        }

        // Lifted oracle 2 from BrentSolverTest.testBadEndpoints:
        // solver.solve(f, 1, 1.5) must throw IllegalArgumentException for non-bracketing endpoints.
        {
            BrentSolver solver = new BrentSolver();
            boolean completedNormally = false;
            Throwable wrong = null;
            try {
                solver.solve(sin, 1.0, 1.5);
                completedNormally = true;
            } catch (IllegalArgumentException expected) {
                // expected
            } catch (Throwable t) {
                wrong = t;
            }
            if (completedNormally) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:no-bracket-2arg] semantic mismatch: expected IllegalArgumentException, got completed normally");
            }
            if (wrong != null) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:no-bracket-2arg] semantic mismatch: expected IllegalArgumentException, got "
                        + wrong.getClass().getName(),
                    wrong);
            }
        }

        // Lifted oracle 3 from BrentSolverTest.testBadEndpoints:
        // solver.solve(f, 1, 1.5, 1.2) must throw IllegalArgumentException for non-bracketing values.
        {
            BrentSolver solver = new BrentSolver();
            boolean completedNormally = false;
            Throwable wrong = null;
            try {
                solver.solve(sin, 1.0, 1.5, 1.2);
                completedNormally = true;
            } catch (IllegalArgumentException expected) {
                // expected
            } catch (Throwable t) {
                wrong = t;
            }
            if (completedNormally) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:no-bracket-3arg-seed] semantic mismatch: expected IllegalArgumentException, got completed normally");
            }
            if (wrong != null) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:no-bracket-3arg-seed] semantic mismatch: expected IllegalArgumentException, got "
                        + wrong.getClass().getName(),
                    wrong);
            }
        }

        // Generalisation of the lifted non-bracketing seed using the same real function and same-sign property.
        // The contract states solve(f,min,max,initial) throws IllegalArgumentException if the values of the
        // function at the three points have the same sign. For sin(x) on [1, 1.5], sin is positive throughout.
        {
            int milli = data.consumeInt(1001, 1499);
            double initial = milli / 1000.0;
            BrentSolver solver = new BrentSolver();
            boolean completedNormally = false;
            Throwable wrong = null;
            try {
                solver.solve(sin, 1.0, 1.5, initial);
                completedNormally = true;
            } catch (IllegalArgumentException expected) {
                // expected
            } catch (Throwable t) {
                wrong = t;
            }
            if (completedNormally) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:three-same-sign-family] semantic mismatch: expected IllegalArgumentException for initial="
                        + initial + ", got completed normally");
            }
            if (wrong != null) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:three-same-sign-family] semantic mismatch: expected IllegalArgumentException for initial="
                        + initial + ", got " + wrong.getClass().getName(),
                    wrong);
            }
        }

        // Post-condition / hidden-state consistency check:
        // After a successful solve call, getResult() must report the same root value that solve returned,
        // because solve stores the result via setResult and getResult reads the same field.
        double returned;
        double reported;
        {
            BrentSolver solver = new BrentSolver();
            try {
                returned = solver.solve(sin, -1.0, 1.0);
                reported = solver.getResult();
            } catch (Throwable ignored) {
                return;
            }
        }
        if (Double.doubleToLongBits(returned) != Double.doubleToLongBits(reported)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:getResult-after-solve] consistency violation: solve returned "
                    + returned + " but getResult reported " + reported);
        }

        // Sibling-agreement metamorphic relation using the real public API:
        // For a bracketed interval with the unique root of sin(x) at 0 in [-1,1], the overloads
        // solve(f,min,max,initial) and solve(f,min,max) solve the same one-root problem and must agree.
        {
            double initial = data.consumeInt(1, 900) / 1000.0;
            BrentSolver solverWithInitial = new BrentSolver();
            BrentSolver solverWithoutInitial = new BrentSolver();
            double a;
            double b;
            try {
                a = solverWithInitial.solve(sin, -1.0, 1.0, initial);
                b = solverWithoutInitial.solve(sin, -1.0, 1.0);
            } catch (Throwable ignored) {
                return;
            }
            double scale = Math.max(1.0, Math.max(Math.abs(a), Math.abs(b)));
            if (Math.abs(a - b) > 1.0e-9 * scale) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:overload-agreement] metamorphic violation: solve(f,-1,1," + initial + ")="
                        + a + " vs solve(f,-1,1)=" + b);
            }
        }
    }
}

