package org.apache.commons.math.ode.nonstiff;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.ode.DerivativeException;
import org.apache.commons.math.ode.FirstOrderDifferentialEquations;
import org.apache.commons.math.ode.IntegratorException;

public class FuzzHarness {

    private static final class PolynomialProblem implements FirstOrderDifferentialEquations {
        public int getDimension() {
            return 1;
        }

        public void computeDerivatives(double t, double[] y, double[] yDot) throws DerivativeException {
            yDot[0] = 3.0 * t * t + 2.0 * t + 1.0;
        }
    }

    private static void fail(String id, String msg) {
        throw new FuzzerSecurityIssueLow("[oracle:" + id + "] semantic mismatch: " + msg);
    }

    private static void check(boolean cond, String id, String msg) {
        if (!cond) {
            fail(id, msg);
        }
    }

    private static void checkClose(double actual, double expected, double tol, String id, String what) {
        if (!(Math.abs(actual - expected) <= tol)) {
            fail(id, what + " actual=" + actual + " expected=" + expected + " tol=" + tol);
        }
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        int extraRuns = data.consumeInt(0, 2);
        boolean reverse = data.consumeBoolean();
        int chosenNSteps = data.consumeInt(1, 6);

        final FirstOrderDifferentialEquations equations = new PolynomialProblem();
        final double t0 = 0.0;
        final double t = 1.0;
        final double range = Math.abs(t - t0);
        final double expectedY = 3.0;

        try {
            for (int i = 0; i < 6; i++) {
                int nSteps = reverse ? (6 - i) : (1 + i);

                AdamsMoultonIntegrator integ =
                    new AdamsMoultonIntegrator(nSteps, 1.0e-6 * range, 0.1 * range, 1.0e-9, 1.0e-9);
                double[] y = new double[] { 0.0 };
                double stop = integ.integrate(equations, t0, new double[] { 0.0 }, t, y);

                /* Post-condition: integrate(..., t, y) returns the stop time, and with no events
                   registered the built-in end-time checker should make that stop time equal the
                   requested target t, not some stale starter step boundary. */
                checkClose(stop, t, Math.ulp(t) * 8.0, "stop-time-" + nSteps,
                    "returned stop time differs from requested final time for nSteps=" + nSteps);

                /* For this polynomial ODE, the exact solution is y(t)=t^3+t^2+t, so at t=1 the
                   result must be 3. This uses only the real integrator result as the observable. */
                checkClose(y[0], expectedY, 1.0e-6, "final-state-" + nSteps,
                    "final state differs from exact polynomial solution for nSteps=" + nSteps);

                /* Lifted from the target test: for the polynomial problem, nSteps < 4 implies
                   getEvaluations() > 140, otherwise getEvaluations() < 90. */
                int evals = integ.getEvaluations();
                if (nSteps < 4) {
                    check(evals > 140, "lifted-evals-" + nSteps,
                        "getEvaluations()=" + evals + " expected > 140 for nSteps=" + nSteps);
                } else {
                    check(evals < 90, "lifted-evals-" + nSteps,
                        "getEvaluations()=" + evals + " expected < 90 for nSteps=" + nSteps);
                }
            }
        } catch (DerivativeException e) {
            return;
        } catch (IntegratorException e) {
            return;
        }

        try {
            AdamsMoultonIntegrator a =
                new AdamsMoultonIntegrator(chosenNSteps, 1.0e-6 * range, 0.1 * range, 1.0e-9, 1.0e-9);
            AdamsMoultonIntegrator b =
                new AdamsMoultonIntegrator(chosenNSteps, 1.0e-6 * range, 0.1 * range, 1.0e-9, 1.0e-9);

            double[] yA = new double[] { 0.0 };
            double[] yB = new double[] { 0.0 };

            double stopA = a.integrate(equations, t0, new double[] { 0.0 }, t, yA);
            double stopB = b.integrate(equations, t0, new double[] { 0.0 }, t, yB);

            /* Consistency check: two fresh, identically-constructed integrators run on the same
               problem must agree on observable outputs. A bookkeeping-only "fix" that merely masks
               one path can break this determinism. */
            checkClose(stopA, stopB, 0.0, "determinism-stop",
                "identical integrations returned different stop times");
            check(a.getEvaluations() == b.getEvaluations(), "determinism-evals",
                "identical integrations returned different evaluation counts: " +
                a.getEvaluations() + " vs " + b.getEvaluations());
            checkClose(yA[0], yB[0], 0.0, "determinism-state",
                "identical integrations returned different final states");

            for (int i = 0; i < extraRuns; i++) {
                AdamsMoultonIntegrator c =
                    new AdamsMoultonIntegrator(chosenNSteps, 1.0e-6 * range, 0.1 * range, 1.0e-9, 1.0e-9);
                double[] yC = new double[] { 0.0 };
                double stopC = c.integrate(equations, t0, new double[] { 0.0 }, t, yC);
                checkClose(stopC, t, Math.ulp(t) * 8.0, "extra-stop-" + i,
                    "extra deterministic run returned wrong stop time");
                checkClose(yC[0], expectedY, 1.0e-6, "extra-state-" + i,
                    "extra deterministic run returned wrong final state");
            }
        } catch (DerivativeException e) {
            return;
        } catch (IntegratorException e) {
            return;
        }
    }
}

