            pExplicit = Gamma.regularizedGammaP(a, x, 10e-15, Integer.MAX_VALUE);
        } catch (Exception e) {
            return;
        }

        if (!withinRel(pDefault, pExplicit, 1e-15)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:p-overload-agreement] consistency violation: overloads of regularizedGammaP must agree"
                    + " a=" + a + " x=" + x + " default=" + pDefault + " explicit=" + pExplicit);
        }

        /*
         * Symmetric sibling-agreement for Q as another real call path through the same reachable region.
         */
        double qDefault;
