package org.apache.commons.lang;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String actual;

        actual = ClassUtils.getPackageName(String.class);
        if (!"java.lang".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-string-class] semantic mismatch: ClassUtils.getPackageName(String.class) expected=java.lang actual=" + actual);
        }

        actual = ClassUtils.getPackageName(java.util.Map.Entry.class);
        if (!"java.util".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-map-entry-class] semantic mismatch: ClassUtils.getPackageName(Map.Entry.class) expected=java.util actual=" + actual);
        }

        actual = ClassUtils.getPackageName((Class) null);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-null-class] semantic mismatch: ClassUtils.getPackageName((Class)null) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(String[].class);
        if (!"java.lang".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-string-array-class] semantic mismatch: ClassUtils.getPackageName(String[].class) expected=java.lang actual=" + actual);
        }

        actual = ClassUtils.getPackageName(boolean[].class);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-boolean-array-class] semantic mismatch: ClassUtils.getPackageName(boolean[].class) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(byte[].class);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-byte-array-class] semantic mismatch: ClassUtils.getPackageName(byte[].class) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(char[].class);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-char-array-class] semantic mismatch: ClassUtils.getPackageName(char[].class) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(short[].class);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-short-array-class] semantic mismatch: ClassUtils.getPackageName(short[].class) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(int[].class);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-int-array-class] semantic mismatch: ClassUtils.getPackageName(int[].class) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(long[].class);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-long-array-class] semantic mismatch: ClassUtils.getPackageName(long[].class) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(float[].class);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-float-array-class] semantic mismatch: ClassUtils.getPackageName(float[].class) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(double[].class);
        if (!"".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-double-array-class] semantic mismatch: ClassUtils.getPackageName(double[].class) expected='' actual=" + actual);
        }

        actual = ClassUtils.getPackageName(String[][].class);
        if (!"java.lang".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-string-2d-array-class] semantic mismatch: ClassUtils.getPackageName(String[][].class) expected=java.lang actual=" + actual);
        }

        actual = ClassUtils.getPackageName(String[][][].class);
        if (!"java.lang".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-string-3d-array-class] semantic mismatch: ClassUtils.getPackageName(String[][][].class) expected=java.lang actual=" + actual);
        }

        actual = ClassUtils.getPackageName(String[][][][].class);
        if (!"java.lang".equals(actual)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:pkg-string-4d-array-class] semantic mismatch: ClassUtils.getPackageName(String[][][][].class) expected=java.lang actual=" + actual);
        }

        Class<?> pkgCls;
        switch (data.consumeInt(0, 4)) {
            case 0:
                pkgCls = String[].class;
                break;
            case 1:
                pkgCls = String[][].class;
                break;
            case 2:
                pkgCls = int[][].class;
                break;
            case 3:
                pkgCls = java.util.Map.Entry[].class;
                break;
            default:
                pkgCls = String[][][][].class;
                break;
        }
        String pkgA;
        String pkgB;
        try {
            pkgA = ClassUtils.getPackageName(pkgCls);
            pkgB = ClassUtils.getPackageName(pkgCls.getName());
        } catch (Throwable t) {
            return;
        }
        // Contract justification: both overloads are documented as getting the package name;
        // for any real Class<?> cls, cls.getName() is the equivalent class-name input, so a
        // correct implementation must return the same package from both overloads. A patch
        // that merely avoids the buggy branch or silently computes a different representation
        // violates this observable post-condition without throwing.
        if (!pkgA.equals(pkgB)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:package-overload-agreement] metamorphic violation: getPackageName(Class) vs getPackageName(String) class="
                    + pkgCls + " lhs=" + pkgA + " rhs=" + pkgB);
        }

        Class<?> shortCls;
        switch (data.consumeInt(0, 4)) {
            case 0:
                shortCls = String[].class;
                break;
            case 1:
                shortCls = String[][].class;
                break;
            case 2:
                shortCls = int[].class;
                break;
            case 3:
                shortCls = java.util.Map.Entry[].class;
                break;
            default:
                shortCls = java.util.Map.Entry[][].class;
                break;
        }
        String shortA;
        String shortB;
        try {
            shortA = ClassUtils.getShortClassName(shortCls);
            shortB = ClassUtils.getShortClassName(shortCls.getName());
        } catch (Throwable t) {
            return;
        }
        // Contract justification: both overloads are documented as getting the class name
        // minus the package name; supplying cls or cls.getName() is the same logical input.
        // This sibling-agreement check exercises the same patched delegation style on array
        // classes and catches silent wrong-output fixes that do not throw.
        if (!shortA.equals(shortB)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:short-overload-agreement] metamorphic violation: getShortClassName(Class) vs getShortClassName(String) class="
                    + shortCls + " lhs=" + shortA + " rhs=" + shortB);
        }

        Class<?> canonicalCls;
        switch (data.consumeInt(0, 3)) {
            case 0:
                canonicalCls = String[].class;
                break;
            case 1:
                canonicalCls = String[][].class;
                break;
            case 2:
                canonicalCls = java.util.Map.Entry[][].class;
                break;
            default:
                canonicalCls = int[][].class;
                break;
        }
        String canonicalPkg;
        String plainPkg;
        try {
            canonicalPkg = ClassUtils.getPackageCanonicalName(canonicalCls);
            plainPkg = ClassUtils.getPackageName(canonicalCls);
        } catch (Throwable t) {
            return;
        }
        // Contract justification: for a real Class input, getPackageCanonicalName(Class)
        // and getPackageName(Class) are both "get package name" queries over the same class;
        // array classes are exactly the boundary this patch corrects, so they must agree on
        // the observable package component for correct implementations.
        if (!canonicalPkg.equals(plainPkg)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:package-canonical-agreement] metamorphic violation: getPackageCanonicalName(Class) vs getPackageName(Class) class="
                    + canonicalCls + " lhs=" + canonicalPkg + " rhs=" + plainPkg);
        }
    }
}

