package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.Date;
import java.util.Locale;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        Locale realDefaultLocale = Locale.getDefault();
        try {
            /*
             * Lifted exactly from FastDateFormatTest.test_changeDefault_Locale_DateInstance.
             * This reproduces the ground-truth setup and all assertions from the test.
             */
            Locale.setDefault(Locale.US);
            FastDateFormat format1 = FastDateFormat.getDateInstance(FastDateFormat.FULL, Locale.GERMANY);
            FastDateFormat format2 = FastDateFormat.getDateInstance(FastDateFormat.FULL);
            Locale.setDefault(Locale.GERMANY);
            FastDateFormat format3 = FastDateFormat.getDateInstance(FastDateFormat.FULL);

            if (format1.getLocale() != Locale.GERMANY) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format1-locale] semantic mismatch: expected Locale.GERMANY, actual=" + format1.getLocale());
            }
            if (format2.getLocale() != Locale.US) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format2-locale] semantic mismatch: expected Locale.US, actual=" + format2.getLocale());
            }
            if (format3.getLocale() != Locale.GERMANY) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format3-locale] semantic mismatch: expected Locale.GERMANY, actual=" + format3.getLocale());
            }
            if (format1 == format2) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct formatter instances");
            }
            if (format2 == format3) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct formatter instances");
            }

            /*
             * Independent post-condition / metamorphic oracle:
             * The javadoc and overload bodies state that getDateInstance(style) gets a date formatter
             * "in the default time zone and locale", while getDateInstance(style, Locale locale) gets
             * one using the specified locale in the default time zone. Therefore, after setting the
             * process default locale to L, getDateInstance(style) and getDateInstance(style, L) must
             * describe the same locale-specific date formatting behavior. A band-aid patch that merely
             * hides the known symptom but still routes through the wrong getInstance(...) path will
             * violate this equivalence.
             */
            try {
                Locale[] locales = new Locale[] {
                    Locale.US, Locale.GERMANY, Locale.FRANCE, Locale.JAPAN, Locale.ITALY
                };
                int style = new int[] {
                    FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT
                }[data.consumeInt(0, 3)];
                Locale chosen = locales[data.consumeInt(0, locales.length - 1)];
                Locale.setDefault(chosen);

                FastDateFormat implicit = FastDateFormat.getDateInstance(style);
                FastDateFormat explicit = FastDateFormat.getDateInstance(style, chosen);
                Date probe = new Date((long) data.consumeInt(-1_000_000, 1_000_000) * 1000L);

                if (implicit.getLocale() != chosen) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:date-default-locale] metamorphic violation: expected implicit locale="
                            + chosen + " actual=" + implicit.getLocale() + " style=" + style);
                }
                if (explicit.getLocale() != chosen) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:date-explicit-locale] metamorphic violation: expected explicit locale="
                            + chosen + " actual=" + explicit.getLocale() + " style=" + style);
                }

                String implicitPattern = implicit.getPattern();
                String explicitPattern = explicit.getPattern();
                if (!implicitPattern.equals(explicitPattern)) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:date-pattern-equivalence] metamorphic violation: style=" + style
                            + " locale=" + chosen
                            + " implicitPattern=" + implicitPattern
                            + " explicitPattern=" + explicitPattern);
                }

                String implicitFormatted = implicit.format(probe);
                String explicitFormatted = explicit.format(probe);
                if (!implicitFormatted.equals(explicitFormatted)) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:date-format-equivalence] metamorphic violation: style=" + style
                            + " locale=" + chosen
                            + " millis=" + probe.getTime()
                            + " implicit=" + implicitFormatted
                            + " explicit=" + explicitFormatted);
                }
            } catch (IllegalArgumentException e) {
                return;
            } catch (RuntimeException e) {
                throw e;
            } catch (Throwable t) {
                return;
            }

            /*
             * Reach the other patched function as well.
             * Same documented guarantee: getDateTimeInstance(dateStyle, timeStyle) uses the default
             * locale, so after Locale.setDefault(L) it must agree with the explicit-locale overload.
             * If either side throws for a fuzzed input, the relation does not apply and we skip.
             */
            try {
                Locale[] locales = new Locale[] {
                    Locale.US, Locale.GERMANY, Locale.FRANCE, Locale.JAPAN
                };
                int[] styles = new int[] {
                    FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT
                };
                Locale chosen = locales[data.consumeInt(0, locales.length - 1)];
                int dateStyle = styles[data.consumeInt(0, styles.length - 1)];
                int timeStyle = styles[data.consumeInt(0, styles.length - 1)];
                Locale.setDefault(chosen);

                FastDateFormat implicitDt = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
                FastDateFormat explicitDt = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, chosen);
                Date probe = new Date((long) data.consumeInt(-1_000_000, 1_000_000) * 1000L);

                if (implicitDt.getLocale() != chosen) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:datetime-default-locale] metamorphic violation: expected implicit locale="
                            + chosen + " actual=" + implicitDt.getLocale()
                            + " dateStyle=" + dateStyle + " timeStyle=" + timeStyle);
                }

                String a = implicitDt.format(probe);
                String b = explicitDt.format(probe);
                if (!a.equals(b)) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:datetime-format-equivalence] metamorphic violation: locale=" + chosen
                            + " dateStyle=" + dateStyle + " timeStyle=" + timeStyle
                            + " millis=" + probe.getTime()
                            + " implicit=" + a + " explicit=" + b);
                }
            } catch (IllegalArgumentException e) {
                return;
            } catch (RuntimeException e) {
                throw e;
            } catch (Throwable t) {
                return;
            }
        } finally {
            Locale.setDefault(realDefaultLocale);
        }
    }
}

