package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        checkLiftedDateTimeInstanceOracle();
        checkDateInstanceTracksDefaultLocaleChanges(data);
        checkGetInstanceSiblingAgreement();
    }

    private static void checkLiftedDateTimeInstanceOracle() {
        Locale realDefaultLocale = Locale.getDefault();
        FastDateFormat format1;
        FastDateFormat format2;
        FastDateFormat format3;
        try {
            Locale.setDefault(Locale.US);
            format1 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL, Locale.GERMANY);
            format2 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
            Locale.setDefault(Locale.GERMANY);
            format3 = FastDateFormat.getDateTimeInstance(FastDateFormat.FULL, FastDateFormat.FULL);
        } catch (Throwable t) {
            Locale.setDefault(realDefaultLocale);
            return;
        } finally {
            Locale.setDefault(realDefaultLocale);
        }

        /* Lifted verbatim from FastDateFormatTest.test_changeDefault_Locale_DateTimeInstance:
           getDateTimeInstance(dateStyle,timeStyle,Locale) must preserve the explicit locale,
           and getDateTimeInstance(dateStyle,timeStyle) must use the default locale in effect
           at each call time rather than a stale cached one. */
        if (format1.getLocale() != Locale.GERMANY) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-locale] semantic mismatch: expected Locale.GERMANY but was " + format1.getLocale());
        }
        if (format2.getLocale() != Locale.US) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-locale] semantic mismatch: expected Locale.US but was " + format2.getLocale());
        }
        if (format3.getLocale() != Locale.GERMANY) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format3-locale] semantic mismatch: expected Locale.GERMANY but was " + format3.getLocale());
        }
        if (format1 == format2) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct instances for explicit Germany vs default-US call");
        }
        if (format2 == format3) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct instances across default-locale change");
        }
    }

    private static void checkDateInstanceTracksDefaultLocaleChanges(FuzzedDataProvider data) {
        int[] styles = new int[] {
            FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT
        };
        int style = styles[data.consumeInt(0, styles.length - 1)];
        String[] ids = TimeZone.getAvailableIDs();
        if (ids == null || ids.length == 0) {
            return;
        }
        TimeZone tz = TimeZone.getTimeZone(ids[data.consumeInt(0, ids.length - 1)]);

        Locale original = Locale.getDefault();
        FastDateFormat usFmt;
        FastDateFormat deFmt;
        try {
            Locale.setDefault(Locale.US);
            usFmt = FastDateFormat.getDateInstance(style, tz);
            Locale.setDefault(Locale.GERMANY);
            deFmt = FastDateFormat.getDateInstance(style, tz);
        } catch (Throwable t) {
            Locale.setDefault(original);
            return;
        } finally {
            Locale.setDefault(original);
        }

        /* Metamorphic post-condition: getDateInstance(int, TimeZone) is documented to omit only
           the locale argument, so it must use the default locale at each call time. A patch that
           merely deletes/changes cache bookkeeping can silently return a stale formatter instead. */
        if (usFmt.getLocale() != Locale.US || deFmt.getLocale() != Locale.GERMANY) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:dateinstance-default-locale] metamorphic violation: style=" + style
                    + " tz=" + tz.getID()
                    + " usLocale=" + usFmt.getLocale()
                    + " deLocale=" + deFmt.getLocale());
        }
    }

    private static void checkGetInstanceSiblingAgreement() {
        Locale originalLocale = Locale.getDefault();
        TimeZone originalTimeZone = TimeZone.getDefault();
        FastDateFormat noArg;
        FastDateFormat explicitPattern;
        String left;
        String right;
        String pattern;
        try {
            pattern = new SimpleDateFormat().toPattern();
            noArg = FastDateFormat.getInstance();
            explicitPattern = FastDateFormat.getInstance(pattern);
            Date probe = new Date(123456789L);
            left = noArg.format(probe);
            right = explicitPattern.format(probe);
        } catch (Throwable t) {
            Locale.setDefault(originalLocale);
            TimeZone.setDefault(originalTimeZone);
            return;
        } finally {
            Locale.setDefault(originalLocale);
            TimeZone.setDefault(originalTimeZone);
        }

        /* Sibling-agreement check over the real API: FastDateFormat.getInstance() is specified by
           its own implementation to delegate to getInstance(getDefaultPattern(), null, null).
           Under the same ambient defaults, both overloads must therefore format the same instant
           identically; this reaches getInstance and catches a fix that only special-cases the
           date-time factory while leaving the shared root cause in getInstance-related selection. */
        if (!left.equals(right)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:getinstance-sibling-agreement] consistency violation: pattern=" + pattern
                    + " lhs=" + left
                    + " rhs=" + right);
        }
    }
}

