package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        try {
            StrBuilder sb = new StrBuilder("onetwothree");
            sb.deleteFirst("three");

            boolean actualContains = sb.contains('h');
            if (actualContains != false) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:testLang295-contains] semantic mismatch: expected sb.contains('h') == false after deleting \"three\" from \"onetwothree\", but was " + actualContains
                );
            }

            int actualIndex = sb.indexOf('h');
            if (actualIndex != -1) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:testLang295-indexOf] semantic mismatch: expected sb.indexOf('h') == -1 after deleting \"three\" from \"onetwothree\", but was " + actualIndex
                );
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            return;
        }

        checkContainsVsIndexOf(data);
        checkDeletedUniqueCharNotContained(data);
        checkContainsCharAgreesWithSingleCharString(data);
        checkContainsIsReadOnly(data);
    }

    private static void checkContainsVsIndexOf(FuzzedDataProvider data) {
        String base = data.consumeString(32);
        String needleSource = data.consumeString(8);
        char ch = needleSource.length() > 0 ? needleSource.charAt(0) : (char) data.consumeInt(0, Character.MAX_VALUE);

        boolean containsResult;
        int indexResult;
        try {
            StrBuilder sb = new StrBuilder(base);
            if (data.consumeBoolean()) {
                sb.deleteFirst(data.consumeString(8));
            }
            containsResult = sb.contains(ch);
            indexResult = sb.indexOf(ch);
        } catch (Exception e) {
            return;
        }

        // Consistency check: `contains(char)` answers presence, `indexOf(char)` independently
        // reports the first position or -1 if absent; therefore contains(ch) == (indexOf(ch) >= 0)
        // for every correct implementation.
        boolean expectedAgreement = indexResult >= 0;
        if (containsResult != expectedAgreement) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-vs-indexOf] consistency violation: contains(" + (int) ch + ")=" + containsResult
                    + " but indexOf(" + (int) ch + ")=" + indexResult + " on input=" + base
            );
        }
    }

    private static void checkDeletedUniqueCharNotContained(FuzzedDataProvider data) {
        int n = data.consumeInt(0, 32);
        char keep = 'a';
        char marker = (char) data.consumeInt(0, Character.MAX_VALUE);
        if (marker == keep) {
            marker = 'b';
        }

        StringBuilder seed = new StringBuilder();
        for (int i = 0; i < n; i++) {
            seed.append(keep);
        }
        seed.append(marker);

        boolean actual;
        try {
            StrBuilder sb = new StrBuilder(seed.toString());
            sb.deleteFirst(String.valueOf(marker));
            actual = sb.contains(marker);
        } catch (Exception e) {
            return;
        }

        // Invariant from the documented meaning of contains(char): after deleteFirst removes
        // the sole occurrence of marker, the builder no longer contains marker.
        if (actual) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:deletedUniqueCharNotContained] relation violated: removed char still reported as contained, marker="
                    + (int) marker + " seed=" + seed.toString()
            );
        }
    }

    private static void checkContainsCharAgreesWithSingleCharString(FuzzedDataProvider data) {
        String s = data.consumeString(32);
        char ch = (char) data.consumeInt(0, Character.MAX_VALUE);

        boolean a;
        boolean b;
        try {
            StrBuilder sb = new StrBuilder(s);
            a = sb.contains(ch);
            b = sb.contains(String.valueOf(ch));
        } catch (Exception e) {
            return;
        }

        // Sibling-overload agreement: contains(char) and contains(String) with a one-character
        // string ask whether the same character is present, so they must return the same boolean.
        if (a != b) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:containsCharAgreesWithSingleCharString] metamorphic violation: contains(char)="
                    + a + " vs contains(String)=" + b + " for ch=" + (int) ch + " input=" + s
            );
        }
    }

    private static void checkContainsIsReadOnly(FuzzedDataProvider data) {
        String s = data.consumeString(32);
        char ch = (char) data.consumeInt(0, Character.MAX_VALUE);

        int beforeLength;
        String beforeString;
        int beforeIndex;
        int afterLength;
        String afterString;
        int afterIndex;
        try {
            StrBuilder sb = new StrBuilder(s);
            beforeLength = sb.length();
            beforeString = sb.toString();
            beforeIndex = sb.indexOf(ch);
            sb.contains(ch);
            afterLength = sb.length();
            afterString = sb.toString();
            afterIndex = sb.indexOf(ch);
        } catch (Exception e) {
            return;
        }

        // Hidden-state check: contains(char) is a read-only query by contract ("Checks if the
        // string builder contains the specified char"), so it must not change content, length,
        // or later search results.
        if (beforeLength != afterLength) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-readonly-length] consistency violation: contains(char) changed length from "
                    + beforeLength + " to " + afterLength + " input=" + s
            );
        }
        if (!beforeString.equals(afterString)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-readonly-content] consistency violation: contains(char) changed content from "
                    + beforeString + " to " + afterString
            );
        }
        if (beforeIndex != afterIndex) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-readonly-index] consistency violation: contains(char) changed indexOf result from "
                    + beforeIndex + " to " + afterIndex + " for ch=" + (int) ch + " input=" + s
            );
        }
    }
}

