    private static void checkPrefixOrdering(
        String normalizedOutput, String root, String mid, String leaf, String oracleShortId) {
        String rootDecl = "var" + root + "={};";
        String parentDecl = root + "." + mid + "={};";
        String nsDecl = root + "." + mid + "." + leaf + "={};";
        String bDecl = root + "." + mid + "." + leaf + ".B={};";
        String cDecl = root + "." + mid + "." + leaf + ".C={};";

        int iRoot = normalizedOutput.indexOf(rootDecl);
