package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.ArrayList;
import java.util.List;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        // Lifted oracle from ProcessClosurePrimitivesTest.testProvideInIndependentModules4.
        // Setup replicated from the test: no additionalCode, no additionalEndCode, no extra namespace.
        try {
            String actual = normalize(compileModuleStar("apps"));
            String expected = normalize("var apps = {};apps.foo = {};apps.foo.bar = {}"
                    + "apps.foo.bar.B = {};"
                    + "apps.foo.bar.C = {};");
            if (!expected.equals(actual)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:seed-regression] semantic mismatch: expected="
                                + expected + " actual=" + actual);
            }

            // Independent post-condition / consistency check.
            // The class contract says prefix namespaces are "registered in order from shortest to longest",
            // and replace() inserts an implicitly provided namespace after its parent namespace.
            // Therefore any correct implementation must emit "...<root>.foo={};" before
            // "...<root>.foo.bar={};" for this star-module setup. A band-aid that only suppresses
            // the original symptom but still misorders namespace insertion violates this.
            int fooPos = actual.indexOf(normalize("apps.foo = {};"));
            int fooBarPos = actual.indexOf(normalize("apps.foo.bar = {};"));
            if (fooPos == -1 || fooBarPos == -1 || fooPos >= fooBarPos) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:seed-order] consistency violation: apps.foo must precede apps.foo.bar in output actual="
                                + actual + " fooPos=" + fooPos + " fooBarPos=" + fooBarPos);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }

        // Strategy (c): flip the patched condition around the indexOf('.', '.') boundary.
        // Build identifiers whose first '.' is before, at, and after index 46. For a correct
        // implementation the parent-before-child order holds for all such names.
        String fuzzRoot = makeIdentifier(data.consumeAsciiString(64));
        if (fuzzRoot.length() == 0) {
            fuzzRoot = "a";
        }
        int mode = data.consumeInt(0, 2);
        if (mode == 0) {
            fuzzRoot = fitLength(fuzzRoot, 45);
        } else if (mode == 1) {
            fuzzRoot = fitLength(fuzzRoot, 46);
        } else {
            fuzzRoot = fitLength(fuzzRoot, 47);
        }

        try {
            String actual = normalize(compileModuleStar(fuzzRoot));
            String foo = normalize(fuzzRoot + ".foo = {};");
            String fooBar = normalize(fuzzRoot + ".foo.bar = {};");
            int fooPos = actual.indexOf(foo);
            int fooBarPos = actual.indexOf(fooBar);
            if (fooPos == -1 || fooBarPos == -1 || fooPos >= fooBarPos) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:boundary-order] metamorphic violation: parent namespace must precede child namespace"
                                + " root=" + fuzzRoot
                                + " output=" + actual
                                + " fooPos=" + fooPos
                                + " fooBarPos=" + fooBarPos);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }
    }

    private static String compileModuleStar(String rootNs) {
        Compiler compiler = new Compiler();

        CompilerOptions options = new CompilerOptions();
        options.closurePass = true;
        options.setCodingConvention(new ClosureCodingConvention());

        List<JSSourceFile> externs = new ArrayList<JSSourceFile>();
        externs.add(JSSourceFile.fromCode("externs.js", ""));

        JSModule m0 = new JSModule("m0");
        JSModule m1 = new JSModule("m1");
        JSModule m2 = new JSModule("m2");
        m1.addDependency(m0);
        m2.addDependency(m0);

        m0.add(JSSourceFile.fromCode("m0.js",
                "goog.provide('" + rootNs + "');"));
        m1.add(JSSourceFile.fromCode("m1.js",
                "goog.provide('" + rootNs + ".foo.bar.B');"));
        m2.add(JSSourceFile.fromCode("m2.js",
                "goog.provide('" + rootNs + ".foo.bar.C');"));

        List<JSModule> modules = new ArrayList<JSModule>();
        modules.add(m0);
        modules.add(m1);
        modules.add(m2);

        compiler.compileModules(externs, modules, options);
        return compiler.toSource();
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static String makeIdentifier(String raw) {
        if (raw == null || raw.length() == 0) {
            return "a";
        }
        StringBuilder sb = new StringBuilder();
        char first = raw.charAt(0);
        if (!Character.isLetter(first) && first != '_' && first != '$') {
            sb.append('a');
        } else {
            sb.append(first);
        }
        for (int i = 1; i < raw.length(); i++) {
            char c = raw.charAt(i);
            if (Character.isLetterOrDigit(c) || c == '_' || c == '$') {
                sb.append(c);
            } else {
                sb.append('a');
            }
        }
        if (sb.length() == 0) {
            sb.append('a');
        }
        return sb.toString();
    }

    private static String fitLength(String base, int len) {
        StringBuilder sb = new StringBuilder(base);
        if (sb.length() > len) {
            return sb.substring(0, len);
        }
        while (sb.length() < len) {
            sb.append('a');
        }
        return sb.toString();
    }
}

