package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import java.util.ArrayList;
import java.util.List;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String liftedOut;
        try {
            liftedOut = compileIndependentProvideStar("apps", "foo", "bar", false);
        } catch (Throwable t) {
            return;
        }
        if (liftedOut == null) {
            return;
        }

        String expectedLifted =
                "var apps = {};apps.foo = {};apps.foo.bar = {}"
                        + "apps.foo.bar.B = {};"
                        + "apps.foo.bar.C = {};";
        String normLifted = normalizeCode(liftedOut);
        String normExpectedLifted = normalizeCode(expectedLifted);

        if (!normExpectedLifted.equals(normLifted)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-test] semantic mismatch: expected="
                            + normExpectedLifted + " actual=" + normLifted);
        }

        int iApps = indexOfEither(normLifted, "varapps={}", "varapps={};");
        int iFoo = indexOfEither(normLifted, "apps.foo={}", "apps.foo={};");
        int iBar = indexOfEither(normLifted, "apps.foo.bar={}", "apps.foo.bar={};");
        int iB = indexOfEither(normLifted, "apps.foo.bar.B={}", "apps.foo.bar.B={};");
        int iC = indexOfEither(normLifted, "apps.foo.bar.C={}", "apps.foo.bar.C={};");
        if (!(iApps >= 0 && iFoo >= 0 && iBar >= 0 && iB >= 0 && iC >= 0
                && iApps < iFoo && iFoo < iBar && iBar < iB && iBar < iC)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:seed-prefix-order] semantic mismatch: prefix declarations out of order in " + normLifted);
        }

        String p1 = makeIdent(data.consumeAsciiString(4), "apps", "a");
        String p2 = makeIdent(data.consumeAsciiString(4), "foo", "b");
        String p3 = makeIdent(data.consumeAsciiString(4), "bar", "c");

        String out1;
        String out2;
        try {
            out1 = compileIndependentProvideStar(p1, p2, p3, false);
            out2 = compileIndependentProvideStar(p1, p2, p3, true);
        } catch (Throwable t) {
            return;
        }
        if (out1 == null || out2 == null) {
            return;
        }

        String n1 = normalizeCode(out1);
        String n2 = normalizeCode(out2);

        if (!n1.equals(n2)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:deterministic-permutation] metamorphic violation: permuting independent child modules changed output lhs="
                            + n1 + " rhs=" + n2);
        }

        String rootDecl = "var" + p1 + "={}";
        String parentDecl = p1 + "." + p2 + "={}";
        String nsDecl = p1 + "." + p2 + "." + p3 + "={}";
        int iRoot = indexOfEither(n1, rootDecl, rootDecl + ";");
        int iParent = indexOfEither(n1, parentDecl, parentDecl + ";");
        int iNs = indexOfEither(n1, nsDecl, nsDecl + ";");

        /*
         * Contract justification:
         * replace() inserts a dotted provided namespace after its parent namespace's
         * replacementNode ("Add it after the parent namespace"). Therefore root must
         * appear before root.mid, and root.mid before root.mid.leaf in the generated
         * declarations. A band-aid patch that skips the real insertion logic would
         * still violate this observable post-condition.
         */
        if (!(iRoot >= 0 && iParent >= 0 && iNs >= 0 && iRoot < iParent && iParent < iNs)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:general-prefix-order] semantic mismatch: root/parent/child declaration order wrong output=" + n1);
        }
    }

    private static String compileIndependentProvideStar(
            String root, String mid, String leaf, boolean swapChildren) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        options.closurePass = true;

        List<JSSourceFile> externs = new ArrayList<JSSourceFile>();
        externs.add(JSSourceFile.fromCode(
                "externs.js",
                "var goog={provide:function(){},require:function(){}};"));

        String ns = root + "." + mid + "." + leaf;
        JSModule m0 = new JSModule("m0");
        JSModule m1 = new JSModule("m1");
        JSModule m2 = new JSModule("m2");

        m1.addDependency(m0);
        m2.addDependency(m0);

        m0.add(JSSourceFile.fromCode("m0.js", "goog.provide('" + root + "');"));
        if (!swapChildren) {
            m1.add(JSSourceFile.fromCode("m1.js", "goog.provide('" + ns + ".B');"));
            m2.add(JSSourceFile.fromCode("m2.js", "goog.provide('" + ns + ".C');"));
        } else {
            m1.add(JSSourceFile.fromCode("m1.js", "goog.provide('" + ns + ".C');"));
            m2.add(JSSourceFile.fromCode("m2.js", "goog.provide('" + ns + ".B');"));
        }

        List<JSModule> modules = new ArrayList<JSModule>();
        modules.add(m0);
        modules.add(m1);
        modules.add(m2);

        compiler.compileModules(externs, modules, options);
        return compiler.toSource();
    }

    private static String makeIdent(String raw, String fallback, String prefix) {
        String s = raw.replaceAll("[^A-Za-z0-9_]", "");
        if (s.length() == 0) {
            s = fallback;
        }
        s = prefix + s;
        char c = s.charAt(0);
        if (!Character.isLetter(c) && c != '_' && c != '$') {
            s = prefix + fallback;
        }
        return s;
    }

    private static String normalizeCode(String s) {
        if (s == null) {
            return "";
        }
        return s.replaceAll("\\s+", "");
    }

    private static int indexOfEither(String s, String a, String b) {
        int i = s.indexOf(a);
        if (i >= 0) {
            return i;
        }
        return s.indexOf(b);
    }
}

