package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        DiagnosticType fooType = DiagnosticType.error("TEST_FOO", "error description here");

        try {
            CompilerOptions options = new CompilerOptions();
            Compiler compiler = new Compiler();
            JSSourceFile[] externs = new JSSourceFile[] {};
            JSSourceFile[] inputs = new JSSourceFile[] {
                JSSourceFile.fromCode("javascript/complex.js", "assert (1;")
            };
            compiler.init(externs, inputs, options);

            LightweightMessageFormatter formatter = new LightweightMessageFormatter(compiler);
            JSError error = JSError.make("javascript/complex.js", 1, 10, fooType);

            String actual = formatter.formatError(error);
            String expected =
                "javascript/complex.js:1: ERROR - error description here\n" +
                "assert (1;\n" +
                "          ^\n";

            String normActual = actual == null ? null : actual.replaceAll("\\s+", "");
            String normExpected = expected.replaceAll("\\s+", "");

            if (normActual == null || !normActual.equals(normExpected)) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:ground-truth] semantic mismatch: expected=" + normExpected + " actual=" + normActual);
            }

            // Contract/oracle: JSError.format(CheckLevel.ERROR, formatter) is the
            // sibling API for formatting an error at ERROR level, so for the same
            // JSError and formatter it must agree with formatter.formatError(error).
            String viaSibling = error.format(CheckLevel.ERROR, formatter);
            String normSibling = viaSibling == null ? null : viaSibling.replaceAll("\\s+", "");
            if (normActual == null ? normSibling != null : !normActual.equals(normSibling)) {
                throw new RuntimeException(
                    "[oracle:sibling-api] metamorphic violation: formatError must agree with JSError.format(ERROR, formatter)"
                        + " lhs=" + normActual + " rhs=" + normSibling);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }

        String fuzzLine = data.consumeAsciiString(40);
        if (fuzzLine == null) {
            return;
        }
        fuzzLine = fuzzLine.replace('\n', ' ').replace('\r', ' ');
        if (fuzzLine.length() == 0) {
            fuzzLine = "x";
        }
        if (fuzzLine.trim().length() == 0) {
            fuzzLine = "x" + fuzzLine;
        }

        int mode = data.consumeInt(0, 2);
        String sourceName = "fuzz.js";
        int charno;
        if (mode == 0) {
            charno = fuzzLine.length();
        } else if (mode == 1) {
            charno = data.consumeInt(0, fuzzLine.length());
        } else {
            charno = fuzzLine.length();
        }

        try {
            CompilerOptions options = new CompilerOptions();
            Compiler compiler = new Compiler();
            JSSourceFile[] externs = new JSSourceFile[] {};
            JSSourceFile[] inputs = new JSSourceFile[] {
                JSSourceFile.fromCode(sourceName, fuzzLine)
            };
            compiler.init(externs, inputs, options);

            LightweightMessageFormatter formatter = new LightweightMessageFormatter(compiler);
            JSError error = JSError.make(sourceName, 1, charno, fooType);
            String actual = formatter.formatError(error);

            // Contract/oracle from the patched method's own comment/body:
            // for LINE excerpts, "charno == sourceExcerpt.length() means something is
            // missing at the end of the line", and the formatter emits a caret line
            // padded to the excerpt. A patch that simply skips the branch would violate
            // this observable output property without throwing.
            if (charno == fuzzLine.length()) {
                StringBuilder expected = new StringBuilder();
                expected.append(sourceName).append(":1: ERROR - error description here\n");
                expected.append(fuzzLine).append('\n');
                for (int i = 0; i < fuzzLine.length(); i++) {
                    char c = fuzzLine.charAt(i);
                    if (Character.isWhitespace(c)) {
                        expected.append(c);
                    } else {
                        expected.append(' ');
                    }
                }
                expected.append("^\n");

                String normActual = actual == null ? null : actual.replaceAll("\\s+", "");
                String normExpected = expected.toString().replaceAll("\\s+", "");
                if (normActual == null || !normActual.equals(normExpected)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:eol-caret] semantic mismatch: expected=" + normExpected + " actual=" + normActual
                            + " line=" + fuzzLine + " charno=" + charno);
                }
            }

            // Same sibling-API consistency check on fuzzed input.
            String viaSibling = error.format(CheckLevel.ERROR, formatter);
            String normActual = actual == null ? null : actual.replaceAll("\\s+", "");
            String normSibling = viaSibling == null ? null : viaSibling.replaceAll("\\s+", "");
            if (normActual == null ? normSibling != null : !normActual.equals(normSibling)) {
                throw new RuntimeException(
                    "[oracle:sibling-api-fuzz] metamorphic violation: formatError must agree with JSError.format(ERROR, formatter)"
                        + " input=" + fuzzLine + " charno=" + charno + " lhs=" + normActual + " rhs=" + normSibling);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }
    }
}

