package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        final DiagnosticType fooType = DiagnosticType.error("TEST_FOO", "error description here");

        String liftedActual;
        try {
            final String sourceLine = "if (foo";
            SourceExcerptProvider source = new SourceExcerptProvider() {
                public String getSourceLine(String sourceName, int lineNumber) {
                    return sourceLine;
                }

                public Region getSourceRegion(String sourceName, int lineNumber) {
                    throw new UnsupportedOperationException();
                }
            };
            JSError error = JSError.make("javascript/complex.js", 6, 7, fooType);
            LightweightMessageFormatter formatter = new LightweightMessageFormatter(source);
            liftedActual = formatter.formatError(error);
        } catch (Throwable t) {
            return;
        }

        String liftedExpected =
                "javascript/complex.js:6: ERROR - error description here\n"
                        + "if (foo\n"
                        + "       ^\n";
        if (!liftedExpected.replaceAll("\\s+", "").equals(liftedActual.replaceAll("\\s+", ""))) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-testFormatErrorSpaceEndOfLine2] semantic mismatch: expected="
                            + liftedExpected + " actual=" + liftedActual);
        }

        String line = data.consumeRemainingAsString().replace('\n', ' ').replace('\r', ' ');
        if (line.length() == 0) {
            line = "x";
        }

        int charno;
        if (data.remainingBytes() > 0) {
            charno = data.consumeInt(0, line.length());
        } else {
            charno = line.length();
        }

        final String finalLine = line;
        String formatErrorOut;
        String formatWarningOut;
        String formatErrorAgain;
        String endOfLineOut;

        try {
            SourceExcerptProvider source = new SourceExcerptProvider() {
                public String getSourceLine(String sourceName, int lineNumber) {
                    return finalLine;
                }

                public Region getSourceRegion(String sourceName, int lineNumber) {
                    throw new UnsupportedOperationException();
                }
            };
            LightweightMessageFormatter formatter = new LightweightMessageFormatter(source);
            JSError error = JSError.make("file.js", 1, charno, fooType);
            formatErrorOut = formatter.formatError(error);
            formatWarningOut = formatter.formatWarning(error);
            formatErrorAgain = formatter.formatError(error);

            JSError endOfLineError =
                    JSError.make("javascript/complex.js", 1, finalLine.length(), fooType);
            endOfLineOut = formatter.formatError(endOfLineError);
        } catch (Throwable t) {
            return;
        }

        // formatError and formatWarning both delegate to the same formatter logic and differ only
        // in the severity label chosen by getLevelName; all other visible content must agree.
        String normalizedError = formatErrorOut.replace(": ERROR - ", ": LEVEL - ").replaceAll("\\s+", "");
        String normalizedWarning = formatWarningOut.replace(": WARNING - ", ": LEVEL - ").replaceAll("\\s+", "");
        if (!normalizedError.equals(normalizedWarning)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:error-warning-agree] semantic mismatch: error="
                            + formatErrorOut + " warning=" + formatWarningOut);
        }

        // formatError is a pure formatting query over the same JSError/source setup; a correct
        // implementation must not mutate hidden state that changes a repeated result.
        if (!formatErrorOut.replaceAll("\\s+", "").equals(formatErrorAgain.replaceAll("\\s+", ""))) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:formatError-idempotent] semantic mismatch: first="
                            + formatErrorOut + " second=" + formatErrorAgain);
        }

        // The code comment in LightweightMessageFormatter.format states:
        // "charno == sourceExcerpt.length() means something is missing at the end of the line".
        // For LINE excerpts, correct formatting therefore includes a caret positioned after the
        // full line when charno equals the line length.
        StringBuilder spaces = new StringBuilder();
        for (int i = 0; i < finalLine.length(); i++) {
            spaces.append(' ');
        }
        String expectedEndOfLine =
                "javascript/complex.js:1: ERROR - error description here\n"
                        + finalLine + "\n"
                        + spaces.toString() + "^\n";
        if (!expectedEndOfLine.replaceAll("\\s+", "").equals(endOfLineOut.replaceAll("\\s+", ""))) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:end-of-line-caret] semantic mismatch: expected="
                            + expectedEndOfLine + " actual=" + endOfLineOut);
        }
    }
}

