String raw = data.consumeRemainingAsString();
String line = raw.replace('\n', ' ').replace('\r', ' ');
if (line.length() == 0) line = "x";
int charno = data.consumeInt(0, line.length());
final String finalLine = line;
String fe;
String fw;
try {
  com.google.javascript.jscomp.SourceExcerptProvider src = new com.google.javascript.jscomp.SourceExcerptProvider() {
    public String getSourceLine(String sourceName, int lineNumber) { return finalLine; }
    public com.google.javascript.jscomp.Region getSourceRegion(String sourceName, int lineNumber) { throw new UnsupportedOperationException(); }
  };
  com.google.javascript.jscomp.LightweightMessageFormatter formatter = new com.google.javascript.jscomp.LightweightMessageFormatter(src);
  com.google.javascript.jscomp.DiagnosticType type = com.google.javascript.jscomp.DiagnosticType.error("TEST_FOO", "plain description");
  com.google.javascript.jscomp.JSError error = com.google.javascript.jscomp.JSError.make("file.js", 1, charno, type);
  fe = formatter.formatError(error);
  fw = formatter.formatWarning(error);
} catch (Exception e) { return; }
String ne = fe.replace(": ERROR - ", ": LEVEL - ");
String nw = fw.replace(": WARNING - ", ": LEVEL - ");
if (!ne.equals(nw)) throw new RuntimeException("relation formatError_warning_only_level_differs violated: error=" + fe + " warning=" + fw);

