package org.jfree.chart.axis;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import org.jfree.chart.ChartFactory;
import org.jfree.chart.JFreeChart;
import org.jfree.chart.plot.CategoryPlot;
import org.jfree.chart.plot.PlotOrientation;
import org.jfree.data.category.DefaultCategoryDataset;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        String title = data.consumeString(16);
        if (title.length() == 0) {
            title = "T";
        }
        String categoryAxisLabel = data.consumeString(16);
        if (categoryAxisLabel.length() == 0) {
            categoryAxisLabel = "Category";
        }
        String valueAxisLabel = data.consumeString(16);
        if (valueAxisLabel.length() == 0) {
            valueAxisLabel = "Value";
        }
        String rowKey = data.consumeAsciiString(8);
        if (rowKey.length() == 0) {
            rowKey = "r";
        }
        String columnKey = data.consumeAsciiString(8);
        if (columnKey.length() == 0) {
            columnKey = "c";
        }
        int iv = data.consumeInt(-1000000, 1000000);
        double expectedDatasetValue = (double) iv;

        DefaultCategoryDataset ds;
        Number gotDatasetValue;
        try {
            ds = new DefaultCategoryDataset();
            ds.setValue(expectedDatasetValue, rowKey, columnKey);
            gotDatasetValue = ds.getValue((Comparable) rowKey, (Comparable) columnKey);
        } catch (Exception e) {
            return;
        }
        if (gotDatasetValue == null || gotDatasetValue.doubleValue() != expectedDatasetValue) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:dataset-roundtrip] semantic mismatch: expected=" + expectedDatasetValue
                    + " got=" + gotDatasetValue);
        }

        JFreeChart chart;
        CategoryPlot plot;
        Axis domainAxis;
        Axis rangeAxis;
        try {
            chart = ChartFactory.createBarChart3D(
                title,
                categoryAxisLabel,
                valueAxisLabel,
                ds,
                PlotOrientation.VERTICAL,
                true,
                true,
                false
            );
            plot = chart.getCategoryPlot();
            domainAxis = plot.getDomainAxis();
            rangeAxis = plot.getRangeAxis();
        } catch (Exception e) {
            return;
        }

        String tooltip = data.consumeString(16);
        String url = data.consumeAsciiString(16);
        try {
            domainAxis.setLabelToolTip(tooltip);
            domainAxis.setLabelURL(url);
        } catch (Exception e) {
            return;
        }
        String actualTooltip;
        String actualUrl;
        try {
            actualTooltip = domainAxis.getLabelToolTip();
            actualUrl = domainAxis.getLabelURL();
        } catch (Exception e) {
            return;
        }
        if ((tooltip == null ? actualTooltip != null : !tooltip.equals(actualTooltip))) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:axis-tooltip-state] semantic mismatch: expected=" + tooltip
                    + " got=" + actualTooltip);
        }
        if ((url == null ? actualUrl != null : !url.equals(actualUrl))) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:axis-url-state] semantic mismatch: expected=" + url
                    + " got=" + actualUrl);
        }

        Axis domainSnapshot;
        Axis rangeSnapshot;
        RenderingHints beforeHints;
        try {
            domainSnapshot = (Axis) domainAxis.clone();
            rangeSnapshot = (Axis) rangeAxis.clone();
            beforeHints = chart.getRenderingHints();
        } catch (Exception e) {
            return;
        }

        Exception drawFailure = null;
        try {
            BufferedImage image = new BufferedImage(200, 100, BufferedImage.TYPE_INT_RGB);
            Graphics2D g2 = image.createGraphics();
            chart.draw(g2, new Rectangle2D.Double(0, 0, 200, 100), null, null);
            g2.dispose();
        } catch (Exception e) {
            drawFailure = e;
        }
        if (drawFailure != null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:bar3d-null-info] semantic mismatch: draw(g2, Rectangle2D.Double(0,0,200,100), null, null) threw "
                    + drawFailure.getClass().getName(),
                drawFailure);
        }

        RenderingHints afterHints;
        boolean domainEqAfter;
        boolean domainEqSymmetric;
        boolean rangeEqAfter;
        boolean rangeEqSymmetric;
        try {
            afterHints = chart.getRenderingHints();
            domainEqAfter = domainAxis.equals(domainSnapshot);
            domainEqSymmetric = domainSnapshot.equals(domainAxis);
            rangeEqAfter = rangeAxis.equals(rangeSnapshot);
            rangeEqSymmetric = rangeSnapshot.equals(rangeAxis);
        } catch (Exception e) {
            return;
        }

        // Contract: drawing with null ChartRenderingInfo, as in the lifted test, is still just rendering.
        // JFreeChart.getRenderingHints() is documented to return rendering hints for the chart and they are never null.
        // A throw-deleting or bookkeeping-skipping patch must not corrupt this persistent chart state.
        if (beforeHints == null || afterHints == null) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:rendering-hints-nonnull] consistency violation: before=" + beforeHints
                    + " after=" + afterHints);
        }

        // Contract: drawLabel() reads axis configuration (font/insets/paint/angle/tooltip/url) and only conditionally
        // adds an entity when all guards are met; with null info there is no documented axis-configuration mutation.
        // Cross-check against a fresh clone made before draw: two identically-constructed Axis instances must remain equal.
        if (!domainEqAfter || !domainEqSymmetric) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:domain-axis-stable] consistency violation: domain axis changed across draw-with-null-info");
        }
        if (!rangeEqAfter || !rangeEqSymmetric) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:range-axis-stable] consistency violation: range axis changed across draw-with-null-info");
        }
    }
}

