// relation: dataset_addValue_double_matches_number
// holds because: DefaultCategoryDataset exposes overloads addValue(double, Comparable, Comparable) and addValue(Number, Comparable, Comparable) for the same abstract operation of adding a value to the table; for the same numeric value and keys they must yield the same stored value.
// valid input: Choose any int n and non-empty ASCII row/column keys. Add n via the double overload in one dataset and via the Number overload in another, then read the value back using the key-based accessor.
java.lang.Number v1;
java.lang.Number v2;
try {
    String row = data.consumeAsciiString(8);
    String col = data.consumeAsciiString(8);
    if (row.length() == 0 || col.length() == 0) return;
    int n = data.consumeInt();
    org.jfree.data.category.DefaultCategoryDataset d1 = new org.jfree.data.category.DefaultCategoryDataset();
    org.jfree.data.category.DefaultCategoryDataset d2 = new org.jfree.data.category.DefaultCategoryDataset();
    d1.addValue((double) n, row, col);
    d2.addValue(Integer.valueOf(n), row, col);
    v1 = d1.getValue(row, col);
    v2 = d2.getValue(row, col);
} catch (Exception e) { return; }
boolean eq = (v1 == null ? v2 == null : v1.equals(v2));
if (!eq) {
    throw new RuntimeException("relation dataset_addValue_double_matches_number violated: " + v1 + " vs " + v2);
}

