harness_source:
package org.jfree.chart.plot;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.jfree.chart.axis.CategoryAxis;
import org.jfree.chart.axis.NumberAxis;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        String x1 = data.consumeAsciiString(8);
        String x2 = data.consumeAsciiString(8);
        String y1 = data.consumeAsciiString(8);
        if (x1.length() == 0) {
            x1 = "X1";
        }
        if (x2.length() == 0) {
            x2 = "X2";
        }
        if (y1.length() == 0) {
            y1 = "Y1";
        }

        final CategoryAxis domainAxis1;
        final CategoryAxis domainAxis2;
        final NumberAxis rangeAxis1;
        final CategoryPlot plot;
        try {
            domainAxis1 = new CategoryAxis(x1);
            domainAxis2 = new CategoryAxis(x2);
            rangeAxis1 = new NumberAxis(y1);
            plot = new CategoryPlot(null, domainAxis1, rangeAxis1, null);
        } catch (Throwable t) {
            return;
        }

        final int beforeDomainCount;
        final int beforeRangeCount;
        final CategoryAxis beforeDomain0;
        final NumberAxis beforeRange0;
        try {
            beforeDomainCount = plot.getDomainAxisCount();
            beforeRangeCount = plot.getRangeAxisCount();
            beforeDomain0 = plot.getDomainAxis(0);
            beforeRange0 = (NumberAxis) plot.getRangeAxis(0);
        } catch (Throwable t) {
            return;
        }

        final int actual0;
        try {
            actual0 = plot.getDomainAxisIndex(domainAxis1);
        } catch (Throwable t) {
            return;
        }
        if (actual0 != 0) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-domain-0] semantic mismatch: expected 0 but got " + actual0);
        }

        final int actualMissing;
        try {
            actualMissing = plot.getDomainAxisIndex(domainAxis2);
        } catch (Throwable t) {
            return;
        }
        if (actualMissing != -1) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-domain-missing] semantic mismatch: expected -1 but got " + actualMissing);
        }

        try {
            plot.setDomainAxis(1, domainAxis2);
        } catch (Throwable t) {
            return;
        }

        final int actual1;
        try {
            actual1 = plot.getDomainAxisIndex(domainAxis2);
        } catch (Throwable t) {
            return;
        }
        if (actual1 != 1) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-domain-1] semantic mismatch: expected 1 but got " + actual1);
        }

        final int actualFresh;
        try {
            actualFresh = plot.getDomainAxisIndex(new CategoryAxis(x2));
        } catch (Throwable t) {
            return;
        }
        if (actualFresh != -1) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-domain-fresh] semantic mismatch: expected -1 but got " + actualFresh);
        }

        boolean domainNullViolated = false;
        Throwable domainNullCause = null;
        String domainNullWhat = "completed normally";
        try {
            plot.getDomainAxisIndex(null);
            domainNullViolated = true;
        } catch (IllegalArgumentException expected) {
        } catch (Throwable t) {
            domainNullViolated = true;
            domainNullCause = t;
            domainNullWhat = "wrong exception class " + t.getClass().getName();
        }
        if (domainNullViolated) {
            if (domainNullCause != null) {
                throw new FuzzerSecurityIssueLow("[oracle:domain-null-throws] semantic mismatch: expected IllegalArgumentException but " + domainNullWhat, domainNullCause);
            }
            throw new FuzzerSecurityIssueLow("[oracle:domain-null-throws] semantic mismatch: expected IllegalArgumentException but " + domainNullWhat);
        }

        boolean rangeNullViolated = false;
        Throwable rangeNullCause = null;
        String rangeNullWhat = "completed normally";
        try {
            plot.getRangeAxisIndex(null);
            rangeNullViolated = true;
        } catch (IllegalArgumentException expected) {
        } catch (Throwable t) {
            rangeNullViolated = true;
            rangeNullCause = t;
            rangeNullWhat = "wrong exception class " + t.getClass().getName();
        }
        if (rangeNullViolated) {
            if (rangeNullCause != null) {
                throw new FuzzerSecurityIssueLow("[oracle:range-null-throws] semantic mismatch: expected IllegalArgumentException but " + rangeNullWhat, rangeNullCause);
            }
            throw new FuzzerSecurityIssueLow("[oracle:range-null-throws] semantic mismatch: expected IllegalArgumentException but " + rangeNullWhat);
        }

        final int afterDomainCount;
        final int afterRangeCount;
        final CategoryAxis afterDomain0;
        final CategoryAxis afterDomain1;
        final NumberAxis afterRange0;
        final int[] domainRecovered;
        final int[] rangeRecovered;
        final int firstRepeat;
        final int secondRepeat;

        try {
            afterDomainCount = plot.getDomainAxisCount();
            afterRangeCount = plot.getRangeAxisCount();
            afterDomain0 = plot.getDomainAxis(0);
            afterDomain1 = plot.getDomainAxis(1);
            afterRange0 = (NumberAxis) plot.getRangeAxis(0);

            domainRecovered = new int[afterDomainCount];
            for (int i = 0; i < afterDomainCount; i++) {
                CategoryAxis ax = plot.getDomainAxis(i);
                domainRecovered[i] = (ax == null) ? Integer.MIN_VALUE : plot.getDomainAxisIndex(ax);
            }

            rangeRecovered = new int[afterRangeCount];
            for (int i = 0; i < afterRangeCount; i++) {
                rangeRecovered[i] = (plot.getRangeAxis(i) == null) ? Integer.MIN_VALUE : plot.getRangeAxisIndex(plot.getRangeAxis(i));
            }

            firstRepeat = plot.getDomainAxisIndex(domainAxis1);
            secondRepeat = plot.getDomainAxisIndex(domainAxis1);
        } catch (Throwable t) {
            return;
        }

        /* Contract justification: getDomainAxisIndex()/getRangeAxisIndex() are query methods ("Returns ... index"),
         * so they must not mutate the axes collections. A throw-deleting or bookkeeping bug in the patched code
         * would violate this hidden-state invariant even if one direct return value looked plausible.
         */
        if (beforeDomainCount != afterDomainCount || beforeRangeCount != afterRangeCount
                || beforeDomain0 != afterDomain0 || beforeRange0 != afterRange0 || afterDomain1 != domainAxis2) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:query-no-mutation] consistency violation: domainCount "
                            + beforeDomainCount + "->" + afterDomainCount
                            + ", rangeCount " + beforeRangeCount + "->" + afterRangeCount
                            + ", domain0Same=" + (beforeDomain0 == afterDomain0)
                            + ", range0Same=" + (beforeRange0 == afterRange0)
                            + ", domain1Same=" + (afterDomain1 == domainAxis2));
        }

        /* Contract justification: setDomainAxis(index, axis) writes the same domainAxes state that
         * getDomainAxis(index) and getDomainAxisIndex(axis) read. Therefore for every installed non-null axis,
         * getDomainAxisIndex(getDomainAxis(i)) must recover i.
         */
        for (int i = 0; i < domainRecovered.length; i++) {
            if (domainRecovered[i] != Integer.MIN_VALUE && domainRecovered[i] != i) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:domain-reader-writer-agree] consistency violation: i=" + i + " recovered=" + domainRecovered[i]);
            }
        }

        /* Contract justification: constructor/setRangeAxis populate the same rangeAxes state that
         * getRangeAxis(index) and getRangeAxisIndex(axis) expose, so the reader and reverse-lookup must agree.
         */
        for (int i = 0; i < rangeRecovered.length; i++) {
            if (rangeRecovered[i] != Integer.MIN_VALUE && rangeRecovered[i] != i) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:range-reader-writer-agree] consistency violation: i=" + i + " recovered=" + rangeRecovered[i]);
            }
        }

        /* Equivalent-input metamorphic check: repeated queries on the same axis must be idempotent because
         * index lookup over unchanged object identity cannot change between calls in a correct implementation.
         */
        if (firstRepeat != secondRepeat) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:domain-idempotent] metamorphic violation: repeated getDomainAxisIndex changed from "
                            + firstRepeat + " to " + secondRepeat);
        }
    }
}

