package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.google.javascript.rhino.Node;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String actualSeed;
        try {
            actualSeed = parsePrint("x- -0", false, CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD);
        } catch (Throwable t) {
            return;
        }
        String expectedSeed = "x- -0.0";
        if (!normalizeCode(expectedSeed).equals(normalizeCode(actualSeed))) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-minus-negative-zero] semantic mismatch: input=x- -0 expected=" +
                expectedSeed + " actual=" + actualSeed);
        }

        String id = toIdentifier(data.consumeAsciiString(12));
        String js = id + "- -0";
        String expectedFamily = id + "- -0.0";
        String actualFamily;
        try {
            actualFamily = parsePrint(js, false, CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD);
        } catch (Throwable t) {
            return;
        }
        if (!normalizeCode(expectedFamily).equals(normalizeCode(actualFamily))) {
            throw new RuntimeException(
                "[oracle:identifier-family] metamorphic violation: equivalent seed family for minus-negative-zero input=" +
                js + " expected=" + expectedFamily + " actual=" + actualFamily);
        }

        String lhs;
        String rhs;
        try {
            lhs = parsePrint(js, false, 20);
            rhs = parsePrint(js, false, 80);
        } catch (Throwable t) {
            return;
        }
        if (!normalizeCode(lhs).equals(normalizeCode(rhs))) {
            throw new RuntimeException(
                "[oracle:line-threshold-short-input] metamorphic violation: short output changed across safe thresholds input=" +
                js + " lhs=" + lhs + " rhs=" + rhs);
        }

        try {
            String arbitrary = data.consumeRemainingAsString();
            if (arbitrary.length() > 0) {
                parsePrint(arbitrary, data.consumeBoolean(), 40);
            }
        } catch (Throwable t) {
        }
    }

    private static String parsePrint(String js, boolean prettyPrint, int lineThreshold) {
        Compiler compiler = new Compiler();
        CompilerOptions options = new CompilerOptions();
        compiler.initOptions(options);
        Node root = compiler.parseTestCode(js);
        return new CodePrinter.Builder(root)
            .setPrettyPrint(prettyPrint)
            .setLineLengthThreshold(lineThreshold)
            .build();
    }

    private static String normalizeCode(String s) {
        return s == null ? "null" : s.trim().replaceAll("\\s+", " ");
    }

    private static String toIdentifier(String s) {
        if (s == null || s.length() == 0) {
            return "x";
        }
        StringBuilder out = new StringBuilder();
        char first = s.charAt(0);
        if (Character.isLetter(first) || first == '_' || first == '$') {
            out.append(first);
        } else {
            out.append('x');
        }
        for (int i = 1; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLetterOrDigit(c) || c == '_' || c == '$') {
                out.append(c);
            }
        }
        if (out.length() == 0) {
            return "x";
        }
        return out.toString();
    }
}

