package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import com.google.javascript.rhino.IR;
import com.google.javascript.rhino.Node;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        int threshold = data.consumeInt(20, 200);

        Node liftedRoot =
            IR.script(
                IR.exprResult(
                    IR.sub(IR.name("x"), IR.number(-0.0))));
        String liftedOut =
            new CodePrinter.Builder(liftedRoot)
                .setPrettyPrint(false)
                .setLineLengthThreshold(threshold)
                .build();

        // Lifted oracle from CodePrinterTest.testMinusNegativeZero:
        // assertPrint("x- -0", "x- -0.0");
        // This exact raw string is the trusted ground truth from the failing test.
        if (!"x- -0.0".equals(liftedOut)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:testMinusNegativeZero] semantic mismatch: expected=x- -0.0 actual=" + liftedOut);
        }

        int n = data.consumeInt(1, 1_000_000);
        Node generalRoot =
            IR.script(
                IR.exprResult(
                    IR.sub(IR.name("x"), IR.number(-((double) n)))));
        String generalOut =
            new CodePrinter.Builder(generalRoot)
                .setPrettyPrint(false)
                .setLineLengthThreshold(threshold)
                .build();
        String expectedGeneral = "x- -" + n;

        // Post-condition from CodeConsumer.addNumber's documented contract in the patched method:
        // "This is to prevent misparsing of x- -4 as x--4".
        // For any positive integer n, printing x - (-n) in compact mode must preserve a separator
        // between the two '-' tokens. A patch that merely removes/guards away the separator logic
        // breaks this observable property even if nothing throws.
        if (!expectedGeneral.equals(generalOut)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:minus_negative_int_separator] semantic mismatch: expected="
                    + expectedGeneral + " actual=" + generalOut);
        }
    }
}

