package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static final class WarningSummary {
        final int count;
        final String[] descriptions;

        WarningSummary(int count, String[] descriptions) {
            this.count = count;
            this.descriptions = descriptions;
        }
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        String expectedWarning =
                "assignment\n" +
                "found   : null\n" +
                "required: boolean";

        // Lifted directly from LooseTypeCheckTest.testFunctionArguments13.
        // This program has a JSDoc-declared boolean parameter. The patched code changes
        // declareArguments() so that such parameters are defined as non-inferred. On the buggy
        // build they are incorrectly marked inferred, so assigning null does not produce the
        // expected type warning.
        String seedJs =
                "/** @return {boolean} */ function u() { return true; }" +
                "/** @param {boolean} b\n@return {?boolean} */" +
                "function f(b) { if (u()) { b = null; } return b; }";

        WarningSummary seed = runTypeCheck(seedJs);
        String expectedNorm = normalize(expectedWarning);
        if (!containsNormalized(seed, expectedNorm)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:testFunctionArguments13] semantic mismatch: expected warning="
                            + expectedNorm + " actualCount=" + seed.count
                            + " warnings=" + join(seed.descriptions));
        }

        // Equivalent-input generalization: renaming identifiers preserves the typing semantics.
        // The warning text itself is still fixed because it mentions only the found/required types.
        String uName = sanitizeIdentifier(data.consumeAsciiString(8), "u");
        String fName = sanitizeIdentifier(data.consumeAsciiString(8), "f");
        String pName = sanitizeIdentifier(data.consumeAsciiString(8), "b");
        if (uName.equals(fName)) {
            fName = fName + "x";
        }
        if (pName.equals(uName) || pName.equals(fName)) {
            pName = pName + "y";
        }

        String renamedJs =
                "/** @return {boolean} */ function " + uName + "() { return true; }" +
                "/** @param {boolean} " + pName + "\n@return {?boolean} */" +
                "function " + fName + "(" + pName + ") { if (" + uName + "()) { " + pName +
                " = null; } return " + pName + "; }";

        WarningSummary renamed = runTypeCheck(renamedJs);
        if (!containsNormalized(renamed, expectedNorm)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:renamed-equivalent] semantic mismatch: expected warning="
                            + expectedNorm + " actualCount=" + renamed.count
                            + " warnings=" + join(renamed.descriptions));
        }

        // Consistency cross-check: for a FunctionType built from ordinary required parameters,
        // getParametersNode() exposes the same parameter list summarized by getMinArguments()
        // and getMaxArguments(). A helper returning inconsistent bounds would violate its own API.
        int n = data.consumeInt(1, 3);
        com.google.javascript.rhino.jstype.JSTypeRegistry registry =
                new com.google.javascript.rhino.jstype.JSTypeRegistry(null);
        com.google.javascript.rhino.jstype.FunctionParamBuilder builder =
                new com.google.javascript.rhino.jstype.FunctionParamBuilder(registry);
        for (int i = 0; i < n; i++) {
            builder.addRequiredParams(
                    registry.getNativeType(
                            com.google.javascript.rhino.jstype.JSTypeNative.NUMBER_TYPE));
        }
        com.google.javascript.rhino.Node params = builder.build();
        com.google.javascript.rhino.jstype.FunctionType ft =
                registry.createFunctionType(
                        registry.getNativeType(
                                com.google.javascript.rhino.jstype.JSTypeNative.UNKNOWN_TYPE),
                        params);
        if (ft != null && ft.getParametersNode() != null) {
            int count = 0;
            for (com.google.javascript.rhino.Node p = ft.getParametersNode().getFirstChild();
                 p != null;
                 p = p.getNext()) {
                count++;
            }
            int minArgs = ft.getMinArguments();
            int maxArgs = ft.getMaxArguments();
            if (count != minArgs || count != maxArgs) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:functiontype-parameter-bounds] consistency violation: count="
                                + count + " min=" + minArgs + " max=" + maxArgs);
            }
        }
    }

    private static WarningSummary runTypeCheck(String js) {
        Compiler compiler = new Compiler();
        com.google.javascript.rhino.Node root = compiler.parseTestCode(js);
        new ProcessClosurePrimitives(compiler, CheckLevel.ERROR, true).process(null, root);

        com.google.javascript.rhino.jstype.JSTypeRegistry registry = compiler.getTypeRegistry();
        CodingConvention convention = compiler.getCodingConvention();
        new TypeCheck(
                compiler,
                new ClosureReverseAbstractInterpreter(convention, registry)
                        .append(new SemanticReverseAbstractInterpreter(convention, registry))
                        .getFirst(),
                registry)
                .processForTesting(null, root);

        JSError[] warnings = compiler.getWarnings();
        String[] descriptions = new String[warnings.length];
        for (int i = 0; i < warnings.length; i++) {
            descriptions[i] = warnings[i] == null ? "" : String.valueOf(warnings[i].description);
        }
        return new WarningSummary(compiler.getWarningCount(), descriptions);
    }

    private static boolean containsNormalized(WarningSummary summary, String expectedNorm) {
        for (int i = 0; i < summary.count && i < summary.descriptions.length; i++) {
            if (expectedNorm.equals(normalize(summary.descriptions[i]))) {
                return true;
            }
        }
        return false;
    }

    private static String normalize(String s) {
        return s == null ? "" : s.replaceAll("\\s+", "");
    }

    private static String join(String[] values) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < values.length; i++) {
            if (i != 0) {
                sb.append(" | ");
            }
            sb.append(normalize(values[i]));
        }
        return sb.toString();
    }

    private static String sanitizeIdentifier(String raw, String fallback) {
        if (raw == null || raw.length() == 0) {
            return fallback;
        }
        StringBuilder sb = new StringBuilder();
        char first = raw.charAt(0);
        if (!Character.isLetter(first) && first != '_') {
            sb.append(fallback);
        }
        for (int i = 0; i < raw.length(); i++) {
            char c = raw.charAt(i);
            if (Character.isLetterOrDigit(c) || c == '_') {
                sb.append(c);
            }
        }
        if (sb.length() == 0) {
            return fallback;
        }
        String id = sb.toString();
        if ("for".equals(id) || "if".equals(id) || "while".equals(id) || "do".equals(id)
                || "var".equals(id) || "function".equals(id) || "return".equals(id)
                || "null".equals(id) || "true".equals(id) || "false".equals(id)
                || "new".equals(id) || "this".equals(id)) {
            return fallback + "z";
        }
        return id;
    }
}

package com.google.javascript.jscomp;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        final String expected =
                "inconsistent return type\n" +
                "found   : number\n" +
                "required: string";

        final String seedJs =
                "/** @constructor */ function F() {}" +
                "/** @type {number} */ F.prototype.bar = 3;" +
                "/** @param {!F} f */ function g(f) {" +
                "  /** @return {string} */" +
                "  function h() {" +
                "    return f.bar;" +
                "  }" +
                "}";

        java.util.List<String> seedWarnings = runTypeCheck(seedJs);
        if (seedWarnings == null) {
            return;
        }
        if (!containsNormalized(seedWarnings, expected)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:seed-warning] semantic mismatch: expected warning not found; actualWarnings=" + seedWarnings);
        }

        String ctor = sanitizeIdentifier(data.consumeAsciiString(12), "Ctor");
        String prop = sanitizeIdentifier(data.consumeAsciiString(12), "prop");
        String param = sanitizeIdentifier(data.consumeAsciiString(12), "arg");
        String outer = sanitizeIdentifier(data.consumeAsciiString(12), "outer");
        String inner = sanitizeIdentifier(data.consumeAsciiString(12), "inner");
        String extra = sanitizeIdentifier(data.consumeAsciiString(12), "extra");

        String renamedJs =
                "/** @constructor */ function " + ctor + "() {}" +
                "/** @type {number} */ " + ctor + ".prototype." + prop + " = 3;" +
                "/** @param {!" + ctor + "} " + param + " */ function " + outer + "(" + param + ") {" +
                "  /** @return {string} */" +
                "  function " + inner + "() {" +
                "    return " + param + "." + prop + ";" +
                "  }" +
                "}";

        java.util.List<String> renamedWarnings = runTypeCheck(renamedJs);
        if (renamedWarnings == null) {
            return;
        }
        if (!containsNormalized(renamedWarnings, expected)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:alpha-rename] semantic mismatch: expected warning not found after identifier renaming; actualWarnings=" + renamedWarnings);
        }

        String extraParamJs =
                "/** @constructor */ function " + ctor + "() {}" +
                "/** @type {number} */ " + ctor + ".prototype." + prop + " = 3;" +
                "/** @param {!" + ctor + "} " + param + " */ function " + outer + "(" + param + ", " + extra + ") {" +
                "  /** @return {string} */" +
                "  function " + inner + "() {" +
                "    return " + param + "." + prop + ";" +
                "  }" +
                "}";

        java.util.List<String> extraParamWarnings = runTypeCheck(extraParamJs);
        if (extraParamWarnings == null) {
            return;
        }
        if (!containsNormalized(extraParamWarnings, expected)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:extra-param-boundary] semantic mismatch: expected warning not found with extra trailing parameter; actualWarnings=" + extraParamWarnings);
        }
    }

    private static java.util.List<String> runTypeCheck(String js) {
        try {
            Compiler compiler = new Compiler();
            CompilerOptions options = new CompilerOptions();
            options.setWarningLevel(DiagnosticGroups.CHECK_TYPES, CheckLevel.WARNING);

            java.util.List<JSSourceFile> externs = java.util.Collections.singletonList(
                    JSSourceFile.fromCode("externs.js", ""));
            java.util.List<JSSourceFile> inputs = java.util.Collections.singletonList(
                    JSSourceFile.fromCode("input.js", js));

            Result result = compiler.compile(externs, inputs, options);
            if (result == null) {
                return null;
            }

            java.util.ArrayList<String> out = new java.util.ArrayList<String>();
            if (result.warnings != null) {
                for (JSError warning : result.warnings) {
                    if (warning != null && warning.description != null) {
                        out.add(warning.description);
                    }
                }
            }
            return out;
        } catch (Throwable t) {
            return null;
        }
    }

    private static boolean containsNormalized(java.util.List<String> warnings, String expected) {
        String normalizedExpected = normalize(expected);
        for (String w : warnings) {
            if (normalize(w).equals(normalizedExpected)) {
                return true;
            }
        }
        return false;
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }

    private static String sanitizeIdentifier(String s, String fallback) {
        if (s == null) {
            return fallback;
        }
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            boolean ok = (c >= 'a' && c <= 'z')
                    || (c >= 'A' && c <= 'Z')
                    || (c >= '0' && c <= '9')
                    || c == '_'
                    || c == '$';
            if (!ok) {
                continue;
            }
            if (b.length() == 0 && c >= '0' && c <= '9') {
                b.append('a');
            }
            b.append(c);
        }
        if (b.length() == 0) {
            return fallback;
        }
        return b.toString();
    }
}

// relation: reduced_half_denominator_collapses_to_whole
