package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        MannWhitneyUTest testStatistic = new MannWhitneyUTest();

        try {
            double[] d1 = new double[1500];
            double[] d2 = new double[1500];
            for (int i = 0; i < 1500; i++) {
                d1[i] = 2.0 * i;
                d2[i] = 2.0 * i + 1.0;
            }
            double result = testStatistic.mannWhitneyUTest(d1, d2);
            if (!(result > 0.1)) {
                throw new FuzzerSecurityIssueLow("[oracle:seed-testBigDataSet] semantic mismatch: mannWhitneyUTest(d1,d2)=" + result + " expected > 0.1");
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            return;
        }

        try {
            int shift = data.consumeInt(-100000, 100000);
            double[] d1 = new double[1500];
            double[] d2 = new double[1500];
            for (int i = 0; i < 1500; i++) {
                d1[i] = 2.0 * i + shift;
                d2[i] = 2.0 * i + 1.0 + shift;
            }
            double shifted = testStatistic.mannWhitneyUTest(d1, d2);
            if (!(shifted > 0.1)) {
                throw new FuzzerSecurityIssueLow("[oracle:seed-translation] semantic mismatch: translated seed pattern gave p=" + shifted + " expected > 0.1");
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            return;
        }

        {
            int n1 = data.consumeInt(47000, 50000);
            int n2 = data.consumeInt(47000, 50000);
            double[] x = new double[n1];
            double[] y = new double[n2];
            for (int i = 0; i < n1; i++) {
                x[i] = data.consumeInt(-3, 3);
            }
            for (int j = 0; j < n2; j++) {
                y[j] = data.consumeInt(-3, 3);
            }

            double u;
            double p;
            double expected;
            try {
                u = testStatistic.mannWhitneyU(x, y);
                p = testStatistic.mannWhitneyUTest(x, y);
                double n1n2 = ((double) n1) * ((double) n2);
                double uMin = Math.min(u, n1n2 - u);
                double eu = n1n2 / 2.0;
                double varU = n1n2 * (n1 + n2 + 1.0) / 12.0;
                double z = (uMin - eu) / Math.sqrt(varU);
                org.apache.commons.math3.distribution.NormalDistribution nd =
                        new org.apache.commons.math3.distribution.NormalDistribution(0, 1);
                expected = 2.0 * nd.cumulativeProbability(z);
            } catch (Exception e) {
                return;
            }

            if (!(Math.abs(p - expected) <= 1e-6 * Math.max(1.0, Math.max(Math.abs(p), Math.abs(expected))))) {
                throw new FuzzerSecurityIssueLow("[oracle:asymptotic-from-u] consistency violation: reported p-value disagrees with asymptotic formula derived from public U statistic n1=" + n1 + " n2=" + n2 + " u=" + u + " p=" + p + " expected=" + expected);
            }
        }

        {
            int n1 = data.consumeInt(1, 40);
            int n2 = data.consumeInt(1, 40);
            double[] x = new double[n1];
            double[] y = new double[n2];
            for (int i = 0; i < n1; i++) {
                x[i] = data.consumeInt(-50, 50);
            }
            for (int j = 0; j < n2; j++) {
                y[j] = data.consumeInt(-50, 50);
            }

            double ux;
            double uy;
            try {
                ux = testStatistic.mannWhitneyU(x, y);
                uy = testStatistic.mannWhitneyU(y, x);
            } catch (Exception e) {
                return;
            }

            double expected = ((double) n1) * ((double) n2);
            if (!(Math.abs((ux + uy) - expected) <= 1e-9 * Math.max(1.0, Math.max(Math.abs(ux + uy), Math.abs(expected))))) {
                throw new FuzzerSecurityIssueLow("[oracle:u-complement] metamorphic violation: U(x,y)+U(y,x) must equal n1*n2 lhs=" + (ux + uy) + " rhs=" + expected);
            }
        }

        {
            int n1 = data.consumeInt(1, 80);
            int n2 = data.consumeInt(1, 80);
            double[] x = new double[n1];
            double[] y = new double[n2];
            for (int i = 0; i < n1; i++) {
                x[i] = data.consumeInt(-100, 100);
            }
            for (int j = 0; j < n2; j++) {
                y[j] = data.consumeInt(-100, 100);
            }

            double pxy;
            double pyx;
            try {
                pxy = testStatistic.mannWhitneyUTest(x, y);
                pyx = testStatistic.mannWhitneyUTest(y, x);
            } catch (Exception e) {
                return;
            }

            if (!(Math.abs(pxy - pyx) <= 1e-12 * Math.max(1.0, Math.max(Math.abs(pxy), Math.abs(pyx))))) {
                throw new FuzzerSecurityIssueLow("[oracle:pvalue-swap-symmetry] metamorphic violation: mannWhitneyUTest(x,y) must equal mannWhitneyUTest(y,x) input=(" + n1 + "," + n2 + ") lhs=" + pxy + " rhs=" + pyx);
            }
        }
    }
}

