        double[] smallY = new double[smallN2];
        for (int i = 0; i < smallN1; i++) {
            smallX[i] = data.consumeInt(-50, 50);
        }
        for (int j = 0; j < smallN2; j++) {
            smallY[j] = data.consumeInt(-50, 50);
        }

        double ux;
        double uy;
        try {
            ux = testStatistic.mannWhitneyU(smallX, smallY);
            uy = testStatistic.mannWhitneyU(smallY, smallX);
        } catch (Exception e) {
            return;
        }

