        if (!approximatelyEqual(ux + uy, expectedComplement, 1e-9)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:u-complement] relation u-statistics-complement-under-swap violated: ux+uy="
                    + (ux + uy) + " expected=" + expectedComplement + " ux=" + ux + " uy=" + uy);
        }

