        int largeN2 = data.consumeInt(47000, 50000);
        double[] largeX = new double[largeN1];
        double[] largeY = new double[largeN2];
        for (int i = 0; i < largeN1; i++) {
            largeX[i] = data.consumeInt(-3, 3);
        }
        for (int j = 0; j < largeN2; j++) {
            largeY[j] = data.consumeInt(-3, 3);
        }

        double u;
        double p;
        double expectedP;
        try {
