            expectedP = 2.0 * nd.cumulativeProbability(z);
        } catch (Exception e) {
            return;
        }

        if (!approximatelyEqualRelative(p, expectedP, 1e-6)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:formula-large-product] relation asymptotic-pvalue-matches-u-formula-large-product violated: p="
                    + p + " expected=" + expectedP + " u=" + u + " n1=" + largeN1 + " n2=" + largeN2);
        }

        double pSwapped;
        try {
            pSwapped = testStatistic.mannWhitneyUTest(largeY, largeX);
        } catch (Exception e) {
            return;
        }

        // Two-sided Mann-Whitney testing is order-invariant because swapping samples complements U,
        // and the public method uses Umin; hence both calls must report the same p-value.
        if (!approximatelyEqualRelative(p, pSwapped, 1e-12)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:pvalue-swap-symmetry] consistency violation: p(x,y)=" + p + " p(y,x)=" + pSwapped
                    + " n1=" + largeN1 + " n2=" + largeN2);
        }
    }

    private static boolean approximatelyEqual(double a, double b, double relTol) {
        double scale = Math.max(1.0, Math.max(Math.abs(a), Math.abs(b)));
        return Math.abs(a - b) <= relTol * scale;
    }

    private static boolean approximatelyEqualRelative(double a, double b, double relTol) {
        double scale = Math.max(1.0, Math.max(Math.abs(a), Math.abs(b)));
        return Math.abs(a - b) <= relTol * scale;
    }
}

