import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        reproduceKnownBug();
        exerciseNearbyBoundaries(data);
        checkControlParameterRoundTrips(data);
    }

    private static void reproduceKnownBug() {
        final AdaptiveStepsizeIntegrator integ =
                new DormandPrince853Integrator(0.0, Double.POSITIVE_INFINITY, Double.NaN, Double.NaN);
        final double start = 0.0;
        final double end = 0.001;

        org.apache.commons.math.ode.FirstOrderDifferentialEquations equations =
                new org.apache.commons.math.ode.FirstOrderDifferentialEquations() {
                    public int getDimension() {
                        return 1;
                    }

                    public void computeDerivatives(double t, double[] y, double[] yDot) {
                        if (!(t >= org.apache.commons.math.util.FastMath.nextAfter(start, Double.NEGATIVE_INFINITY))) {
                            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                                    "[oracle:known-test-lower] semantic mismatch: t below allowed lower bound: " + t);
                        }
                        if (!(t <= org.apache.commons.math.util.FastMath.nextAfter(end, Double.POSITIVE_INFINITY))) {
                            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                                    "[oracle:known-test-upper] semantic mismatch: t above allowed upper bound: " + t);
                        }
                        yDot[0] = -100.0 * y[0];
                    }
                };

        integ.setStepSizeControl(0.0, 1.0, 1.0e-6, 1.0e-8);
        integ.integrate(equations, start, new double[] { 1.0 }, end, new double[1]);
    }

    private static void exerciseNearbyBoundaries(FuzzedDataProvider data) {
        final double start = 0.0;
        final double end = data.consumeInt(1, 1000) / 1_000_000.0;
        final double rate = -data.consumeInt(1, 10_000);
        final double y0 = data.consumeInt(1, 1000) / 100.0;

        final DormandPrince853Integrator integ =
                new DormandPrince853Integrator(0.0, Double.POSITIVE_INFINITY, Double.NaN, Double.NaN);
        integ.setStepSizeControl(0.0, 1.0, 1.0e-6, 1.0e-8);

