                new org.apache.commons.math.ode.FirstOrderDifferentialEquations() {
                    public int getDimension() {
                        return 1;
                    }

                    public void computeDerivatives(double t, double[] y, double[] yDot) {
                        if (!(t >= org.apache.commons.math.util.FastMath.nextAfter(start, Double.NEGATIVE_INFINITY))) {
                            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                                    "[oracle:fuzzed-lower] semantic mismatch: t below start neighborhood: t=" + t
                                            + " end=" + end + " rate=" + rate);
                        }
                        if (!(t <= org.apache.commons.math.util.FastMath.nextAfter(end, Double.POSITIVE_INFINITY))) {
                            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                                    "[oracle:fuzzed-upper] semantic mismatch: t above end neighborhood: t=" + t
                                            + " end=" + end + " rate=" + rate);
                        }
                        yDot[0] = rate * y[0];
