package org.apache.commons.math.ode.nonstiff;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.ode.FirstOrderDifferentialEquations;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        reproduceKnownBug();

        double safety = data.consumeInt(1, 1000) / 1000.0;
        DormandPrince853Integrator safetyInteg =
                new DormandPrince853Integrator(1.0e-12, 1.0, 1.0e-8, 1.0e-8);
        double gotSafety;
        try {
            safetyInteg.setSafety(safety);
            gotSafety = safetyInteg.getSafety();
        } catch (Exception e) {
            return;
        }
        if (Double.doubleToLongBits(gotSafety) != Double.doubleToLongBits(safety)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:setSafety_round_trips_through_getSafety] semantic mismatch: set=" +
                    safety + " got=" + gotSafety);
        }

        double minReduction = data.consumeInt(1, 1000) / 1000.0;
        DormandPrince853Integrator reductionInteg =
                new DormandPrince853Integrator(1.0e-12, 1.0, 1.0e-8, 1.0e-8);
        double gotMinReduction;
        try {
            reductionInteg.setMinReduction(minReduction);
            gotMinReduction = reductionInteg.getMinReduction();
        } catch (Exception e) {
            return;
        }
        if (Double.doubleToLongBits(gotMinReduction) != Double.doubleToLongBits(minReduction)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:setMinReduction_round_trips_through_getMinReduction] semantic mismatch: set=" +
                    minReduction + " got=" + gotMinReduction);
        }

        DormandPrince853Integrator orderInteg =
                new DormandPrince853Integrator(1.0e-12, 1.0, 1.0e-8, 1.0e-8);
        if (orderInteg.getOrder() != 8) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:getOrder-dp853] semantic mismatch: expected=8 actual=" + orderInteg.getOrder());
        }

        final double rate = 1.0 + data.consumeInt(0, 500);
        final double end = (1 + data.consumeInt(0, 9999)) / 1000000.0;
        final double splitFraction = data.consumeInt(1, 999) / 1000.0;
        final double mid = end * splitFraction;
        final double initial = (1 + data.consumeInt(0, 999)) / 1000.0;

        final double[] oneShot = new double[1];
        final double[] splitOut = new double[1];
        double oneShotTime;
        double firstLegTime;
        double secondLegTime;
        try {
            DormandPrince853Integrator oneShotInteg =
                    new DormandPrince853Integrator(0, Double.POSITIVE_INFINITY, Double.NaN, Double.NaN);
            oneShotInteg.setStepSizeControl(0, 1.0, 1.0e-6, 1.0e-8);
            oneShotTime = oneShotInteg.integrate(linearEquation(rate), 0.0, new double[] { initial }, end, oneShot);

            DormandPrince853Integrator splitInteg1 =
                    new DormandPrince853Integrator(0, Double.POSITIVE_INFINITY, Double.NaN, Double.NaN);
            splitInteg1.setStepSizeControl(0, 1.0, 1.0e-6, 1.0e-8);
            double[] midState = new double[1];
            firstLegTime = splitInteg1.integrate(linearEquation(rate), 0.0, new double[] { initial }, mid, midState);

            DormandPrince853Integrator splitInteg2 =
                    new DormandPrince853Integrator(0, Double.POSITIVE_INFINITY, Double.NaN, Double.NaN);
            splitInteg2.setStepSizeControl(0, 1.0, 1.0e-6, 1.0e-8);
            secondLegTime = splitInteg2.integrate(linearEquation(rate), mid, midState, end, splitOut);
        } catch (Exception e) {
            return;
        }

        if (Double.doubleToLongBits(oneShotTime) != Double.doubleToLongBits(end)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:integrate-returns-target-time] semantic mismatch: expected=" +
                    end + " actual=" + oneShotTime);
        }
        if (Double.doubleToLongBits(firstLegTime) != Double.doubleToLongBits(mid)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:integrate-returns-mid-time] semantic mismatch: expected=" +
                    mid + " actual=" + firstLegTime);
        }
        if (Double.doubleToLongBits(secondLegTime) != Double.doubleToLongBits(end)) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:integrate-returns-end-time-split] semantic mismatch: expected=" +
                    end + " actual=" + secondLegTime);
        }

        double absDiff = Math.abs(oneShot[0] - splitOut[0]);
        double scale = Math.max(Math.abs(oneShot[0]), Math.abs(splitOut[0]));
        double tol = 1.0e-9 + 1.0e-5 * scale;
        // Correct ODE flow satisfies the semigroup law: integrating 0->end must agree with 0->mid then mid->end.
        // This is an observable post-condition on the patched path: a "fix" that only suppresses out-of-range
        // derivative calls but still computes a wrong step size/state will break one-shot vs split agreement.
        if (absDiff > tol) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:semigroup-linear-ode] metamorphic violation: rate=" + rate +
                    " initial=" + initial +
                    " end=" + end +
                    " mid=" + mid +
                    " oneShot=" + oneShot[0] +
                    " split=" + splitOut[0] +
                    " absDiff=" + absDiff +
                    " tol=" + tol);
        }
    }

    private static void reproduceKnownBug() {
        final double start = 0.0;
        final double end = 0.001;
        DormandPrince853Integrator integ =
                new DormandPrince853Integrator(0, Double.POSITIVE_INFINITY, Double.NaN, Double.NaN);
        integ.setStepSizeControl(0, 1.0, 1.0e-6, 1.0e-8);

        FirstOrderDifferentialEquations equations = new FirstOrderDifferentialEquations() {
            public int getDimension() {
                return 1;
            }

            public void computeDerivatives(double t, double[] y, double[] yDot) {
                double lower = Math.nextAfter(start, Double.NEGATIVE_INFINITY);
                double upper = Math.nextAfter(end, Double.POSITIVE_INFINITY);
                if (!(t >= lower)) {
                    throw new FuzzerSecurityIssueLow(
                            "[oracle:testTooLargeFirstStep-lower-bound] semantic mismatch: t=" + t +
                            " lower=" + lower);
                }
                if (!(t <= upper)) {
                    throw new FuzzerSecurityIssueLow(
                            "[oracle:testTooLargeFirstStep-upper-bound] semantic mismatch: t=" + t +
                            " upper=" + upper);
                }
                yDot[0] = -100.0 * y[0];
            }
        };

        integ.integrate(equations, start, new double[] { 1.0 }, end, new double[1]);
    }

    private static FirstOrderDifferentialEquations linearEquation(final double rate) {
        return new FirstOrderDifferentialEquations() {
            public int getDimension() {
                return 1;
            }

            public void computeDerivatives(double t, double[] y, double[] yDot) {
                yDot[0] = -rate * y[0];
            }
        };
    }
}

