public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        runLiftedCircleFittingOracle();
        runReadOnlyStateChecks();
        runWeightedResidualSumRelation(data);
        runRmsChiSquareRelation(data);
    }

    private static void runLiftedCircleFittingOracle() {
        Circle circle = new Circle();
        circle.addPoint(30.0, 68.0);
        circle.addPoint(50.0, -6.0);
        circle.addPoint(110.0, -20.0);
        circle.addPoint(35.0, 15.0);
        circle.addPoint(45.0, 97.0);
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        VectorialPointValuePair optimum;
        try {
            optimum = optimizer.optimize(
                    circle,
                    new double[] { 0, 0, 0, 0, 0 },
                    new double[] { 1, 1, 1, 1, 1 },
                    new double[] { 98.680, 47.345 });
        } catch (Exception e) {
            return;
        }

        if (!(optimizer.getEvaluations() < 10)) {
            throw new FuzzerSecurityIssueLow("[oracle:testCircleFitting-evaluations] semantic mismatch: expected optimizer.getEvaluations() < 10 but was " + optimizer.getEvaluations());
        }
        if (!(optimizer.getJacobianEvaluations() < 10)) {
            throw new FuzzerSecurityIssueLow("[oracle:testCircleFitting-jacobianEvaluations] semantic mismatch: expected optimizer.getJacobianEvaluations() < 10 but was " + optimizer.getJacobianEvaluations());
        }

        double rms = optimizer.getRMS();
        double scaledRms = Math.sqrt(circle.getN()) * rms;
        if (!approxEquals(scaledRms, 1.768262623567235, 1.0e-10)) {
            throw new FuzzerSecurityIssueLow("[oracle:testCircleFitting-rms] semantic mismatch: expected Math.sqrt(circle.getN()) * rms == 1.768262623567235 +/- 1.0e-10 but was " + scaledRms);
        }

        Point2D.Double center = new Point2D.Double(optimum.getPointRef()[0], optimum.getPointRef()[1]);
        double radius = circle.getRadius(center);
