package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {

    private static final double MACH_EPS = 2.22044604926e-16;

    private static final class FreudensteinRothFunction implements DifferentiableMultivariateVectorialFunction {
        public double[] value(double[] p) throws FunctionEvaluationException {
            if (p == null || p.length != 2) {
                throw new FunctionEvaluationException(p, "dimension mismatch");
            }
            final double x1 = p[0];
            final double x2 = p[1];
            final double f1 = -13.0 + x1 + ((5.0 - x2) * x2 - 2.0) * x2;
            final double f2 = -29.0 + x1 + ((x2 + 1.0) * x2 - 14.0) * x2;
            return new double[] { f1, f2 };
        }

        public MultivariateMatrixFunction jacobian() {
            return new FreudensteinRothJacobian();
        }
    }

    private static final class FreudensteinRothJacobian implements MultivariateMatrixFunction {
        public double[][] value(double[] p) {
            final double x2 = p[1];
            return new double[][] {
                { 1.0, 10.0 * x2 - 3.0 * x2 * x2 - 2.0 },
                { 1.0, 3.0 * x2 * x2 + 2.0 * x2 - 14.0 }
            };
        }
    }

    private static final class Lin2 implements DifferentiableMultivariateVectorialFunction {
        public double[] value(double[] p) throws FunctionEvaluationException {
            if (p == null || p.length != 2) {
                throw new FunctionEvaluationException(p, "dimension mismatch");
            }
            return new double[] { p[0] + 2.0 * p[1], 3.0 * p[0] - p[1] };
        }

        public MultivariateMatrixFunction jacobian() {
            return new Lin2Jacobian();
        }
    }

    private static final class Lin2Jacobian implements MultivariateMatrixFunction {
        public double[][] value(double[] p) {
            return new double[][] { { 1.0, 2.0 }, { 3.0, -1.0 } };
        }
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        checkFreudensteinRothSeed(
                new double[] { 0.5, -2.0 },
                6.99887517584575,
                new double[] { 11.4124844654993, -0.896827913731509 });

        checkFreudensteinRothSeed(
                new double[] { 5.0, -20.0 },
                6.9988751744895,
                new double[] { 11.4121122022341, -0.8968550851268697 });

        checkFreudensteinRothSeed(
                new double[] { 50.0, -200.0 },
                6.99887517242903,
                new double[] { 11.412069435091231, -0.8968582807605691 });

        checkLinearValueMatchesReturnedPoint(data);
        checkLinearExactSolutionFixedPoint(data);
    }

    private static void checkFreudensteinRothSeed(double[] start, double expectedRms, double[] expectedParams) {
        final LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (2 + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(MACH_EPS));
        optimizer.setParRelativeTolerance(Math.sqrt(MACH_EPS));
        optimizer.setOrthoTolerance(MACH_EPS);

        final FreudensteinRothFunction function = new FreudensteinRothFunction();
        final double[] target = new double[] { 0.0, 0.0 };
        final double[] weights = new double[] { 1.0, 1.0 };

        VectorialPointValuePair optimum;
        double actualRms;
        double[] point;
        double[] storedValue;
        double[] recomputedValue;
        double reportedChiSquare;

        try {
            optimum = optimizer.optimize(function, target, weights, start);
            actualRms = optimizer.getRMS();
            point = optimum.getPoint();
            storedValue = optimum.getValue();
            recomputedValue = function.value(point);
            reportedChiSquare = optimizer.getChiSquare();
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        String seedId;
        if (sameStart(start, 0.5, -2.0)) {
            seedId = "fr-seed-1";
        } else if (sameStart(start, 5.0, -20.0)) {
            seedId = "fr-seed-2";
        } else {
            seedId = "fr-seed-3";
        }

        if (!closeEnough(actualRms, expectedRms)) {
            throw new FuzzerSecurityIssueLow("[oracle:" + seedId + "-rms-exact] semantic mismatch: expected RMS="
                    + expectedRms + " but was=" + actualRms);
        }
        if (point.length != expectedParams.length) {
            throw new FuzzerSecurityIssueLow("[oracle:" + seedId + "-point-length] semantic mismatch: expected point length="
                    + expectedParams.length + " but was=" + point.length);
        }
        for (int i = 0; i < expectedParams.length; i++) {
            if (!closeEnough(point[i], expectedParams[i])) {
                throw new FuzzerSecurityIssueLow("[oracle:" + seedId + "-point-" + i + "] semantic mismatch: expected point["
                        + i + "]=" + expectedParams[i] + " but was=" + point[i]);
            }
        }

        /* Contract cross-check:
         * VectorialPointValuePair is documented as storing "a point and the vectorial value
         * of an objective function at this point". So after optimize(...) succeeds, the
         * returned stored value must equal a fresh evaluation of the same real function at
         * the returned point. A patch that only shortcuts/returns early without consistent
         * bookkeeping would break this even if the top-level point looked plausible.
         */
        if (storedValue.length != recomputedValue.length) {
            throw new FuzzerSecurityIssueLow("[oracle:" + seedId + "-value-length] consistency violation: stored length="
                    + storedValue.length + " recomputed length=" + recomputedValue.length);
        }
        for (int i = 0; i < storedValue.length; i++) {
            if (!closeEnough(storedValue[i], recomputedValue[i])) {
                throw new FuzzerSecurityIssueLow("[oracle:" + seedId + "-value-match-" + i + "] consistency violation: storedValue["
                        + i + "]=" + storedValue[i] + " recomputedValue[" + i + "]=" + recomputedValue[i]);
            }
        }

        /* Shared-state consistency check supporting strategy (b):
         * getChiSquare() and getRMS() are summaries of the optimizer's internal residuals,
         * while the returned VectorialPointValuePair exposes the objective value at the final
         * point. For this exact least-squares setup (target = {0,0}, weights = {1,1}),
         * chi-square must equal sum(value[i]^2) and RMS must equal sqrt(chi-square / rows).
         * This independently recomputes the same summaries from exposed output and catches
         * stale/masked internal state even if optimize(...) returns a plausible point.
         */
        double manualChiSquare = 0.0;
        for (int i = 0; i < storedValue.length; i++) {
            manualChiSquare += storedValue[i] * storedValue[i];
        }
        double manualRms = Math.sqrt(manualChiSquare / storedValue.length);

        if (!closeEnough(reportedChiSquare, manualChiSquare)) {
            throw new FuzzerSecurityIssueLow("[oracle:" + seedId + "-chisq-consistency] consistency violation: reported chiSquare="
                    + reportedChiSquare + " manual chiSquare=" + manualChiSquare);
        }
        if (!closeEnough(actualRms, manualRms)) {
            throw new FuzzerSecurityIssueLow("[oracle:" + seedId + "-rms-consistency] consistency violation: reported RMS="
                    + actualRms + " manual RMS=" + manualRms);
        }
    }

    private static void checkLinearValueMatchesReturnedPoint(FuzzedDataProvider data) {
        final LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
        opt.setMaxIterations(100);

        final double s0 = data.consumeInt(-20, 20) / 5.0;
        final double s1 = data.consumeInt(-20, 20) / 5.0;
        final double x0 = data.consumeInt(-20, 20) / 5.0;
        final double x1 = data.consumeInt(-20, 20) / 5.0;
        final double[] start = new double[] { s0, s1 };
        final double[] target = new double[] { x0 + 2.0 * x1, 3.0 * x0 - x1 };
        final double[] weights = new double[] { 1.0, 1.0 };

        VectorialPointValuePair out;
        double[] point;
        double[] storedValue;
        double[] recomputedValue;

        try {
            out = opt.optimize(new Lin2(), target, weights, start);
            point = out.getPoint();
            storedValue = out.getValue();
            recomputedValue = new Lin2().value(point);
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        if (storedValue.length != recomputedValue.length) {
            throw new FuzzerSecurityIssueLow("[oracle:linear-value-length] consistency violation: stored length="
                    + storedValue.length + " recomputed length=" + recomputedValue.length);
        }
        for (int i = 0; i < storedValue.length; i++) {
            if (!closeEnough(storedValue[i], recomputedValue[i])) {
                throw new FuzzerSecurityIssueLow("[oracle:linear-value-match] consistency violation at index " + i
                        + ": stored=" + storedValue[i] + " recomputed=" + recomputedValue[i]
                        + " point0=" + point[0] + " point1=" + point[1]);
            }
        }
    }

    private static void checkLinearExactSolutionFixedPoint(FuzzedDataProvider data) {
        final double x0 = data.consumeInt(-20, 20) / 5.0;
        final double x1 = data.consumeInt(-20, 20) / 5.0;
        final double[] exact = new double[] { x0, x1 };
        final double[] target = new double[] { x0 + 2.0 * x1, 3.0 * x0 - x1 };
        final double[] weights = new double[] { 1.0, 1.0 };

        final LevenbergMarquardtOptimizer opt = new LevenbergMarquardtOptimizer();
        VectorialPointValuePair out;
        double[] point;

        try {
            out = opt.optimize(new Lin2(), target, weights, exact);
            point = out.getPoint();
        } catch (FunctionEvaluationException e) {
            return;
        } catch (OptimizationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        /* Contract:
         * On an invertible linear least-squares problem with an exact zero-residual solution,
         * using that exact solution as the start point already satisfies the optimum. A correct
         * optimizer must therefore return the same parameter vector up to floating-point noise.
         */
        for (int i = 0; i < exact.length; i++) {
            if (!closeEnough(point[i], exact[i])) {
                throw new FuzzerSecurityIssueLow("[oracle:linear-fixed-point] metamorphic violation at index " + i
                        + ": expected=" + exact[i] + " actual=" + point[i]);
            }
        }
    }

    private static boolean sameStart(double[] start, double a, double b) {
        return start != null && start.length == 2 && start[0] == a && start[1] == b;
    }

    private static boolean closeEnough(double actual, double expected) {
        double scale = Math.max(1.0, Math.max(Math.abs(actual), Math.abs(expected)));
        return Math.abs(actual - expected) <= 1.0e-6 * scale;
    }
}

