package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {
    private static final double EXPECTED_RMS = 11.1517793413499;
    private static final double EXPECTED_P0 = 0.2578330049;
    private static final double EXPECTED_P1 = 0.257829976764542;
    private static final double SEED_TOL = 1.0e-6;

    private static final class JennrichSampsonFunction implements DifferentiableMultivariateVectorialFunction {
        private final int m;

        JennrichSampsonFunction(int m) {
            this.m = m;
        }

        public double[] value(double[] point) throws FunctionEvaluationException {
            if (point == null || point.length != 2) {
                throw new FunctionEvaluationException(point, "dimension mismatch");
            }
            double[] values = new double[m];
            final double x1 = point[0];
            final double x2 = point[1];
            for (int i = 0; i < m; i++) {
                final double k = i + 1.0;
                values[i] = Math.exp(k * x1) + Math.exp(k * x2);
            }
            return values;
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] point) throws FunctionEvaluationException {
                    if (point == null || point.length != 2) {
                        throw new FunctionEvaluationException(point, "dimension mismatch");
                    }
                    double[][] j = new double[m][2];
                    final double x1 = point[0];
                    final double x2 = point[1];
                    for (int i = 0; i < m; i++) {
                        final double k = i + 1.0;
                        j[i][0] = k * Math.exp(k * x1);
                        j[i][1] = k * Math.exp(k * x2);
                    }
                    return j;
                }
            };
        }

        double[] getTarget() {
            double[] target = new double[m];
            for (int i = 0; i < m; i++) {
                target[i] = 2.0 + 2.0 * (i + 1.0);
            }
            return target;
        }

        double[] getWeight() {
            double[] weight = new double[m];
            for (int i = 0; i < m; i++) {
                weight[i] = 1.0;
            }
            return weight;
        }

        double[] getStartPoint() {
            return new double[] { 0.3, 0.4 };
        }
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        checkJennrichSampsonSeed();
        exerciseBoundaryVariants(data);
    }

    private static void checkJennrichSampsonSeed() {
        JennrichSampsonFunction function = new JennrichSampsonFunction(10);
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (2 + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setOrthoTolerance(2.22044604926e-16);

        final VectorialPointValuePair optimum;
        try {
            optimum = optimizer.optimize(function, function.getTarget(), function.getWeight(), function.getStartPoint());
        } catch (OptimizationException e) {
            return;
        } catch (FunctionEvaluationException e) {
            return;
        } catch (IllegalArgumentException e) {
            return;
        }

        double[] p = optimum.getPointRef();
        double rms = optimizer.getRMS();

        if (p.length < 2 || Math.abs(p[0] - EXPECTED_P0) > SEED_TOL) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-p0] semantic mismatch: expected p0=" + EXPECTED_P0 + " actual=" + (p.length < 1 ? "missing" : Double.toString(p[0]))
            );
        }
        if (Math.abs(p[1] - EXPECTED_P1) > SEED_TOL) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-p1] semantic mismatch: expected p1=" + EXPECTED_P1 + " actual=" + p[1]
            );
        }
        if (Math.abs(rms - EXPECTED_RMS) > SEED_TOL) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:seed-rms] semantic mismatch: expected rms=" + EXPECTED_RMS + " actual=" + rms
            );
        }

        try {
            double[] recomputed = function.value(p);
            double[] returned = optimum.getValueRef();
            if (recomputed.length != returned.length) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:pair-self-consistency] consistency violation: returned value length=" + returned.length + " recomputed length=" + recomputed.length
                );
            }
            for (int i = 0; i < recomputed.length; i++) {
                if (Math.abs(recomputed[i] - returned[i]) > 1.0e-9) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:pair-self-consistency] consistency violation: VectorialPointValuePair must hold the objective value at its returned point; index=" + i +
                        " point0=" + p[0] + " point1=" + p[1] + " returned=" + returned[i] + " recomputed=" + recomputed[i]
                    );
                }
            }
        } catch (FunctionEvaluationException e) {
            return;
        }

        double chiSquare = optimizer.getChiSquare();
        double expectedRmsFromChi = Math.sqrt(chiSquare / 10.0);
        if (Math.abs(expectedRmsFromChi - rms) > 1.0e-12) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:rms-chi-square] consistency violation: getRMS must equal sqrt(getChiSquare()/rows); rms=" + rms +
                " chiSquare=" + chiSquare + " recomputed=" + expectedRmsFromChi
            );
        }
    }

    private static void exerciseBoundaryVariants(FuzzedDataProvider data) {
        JennrichSampsonFunction function = new JennrichSampsonFunction(10);
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (2 + 1));

        double eps = Math.sqrt(2.22044604926e-16);
        double cScale = 1.0 + (data.consumeInt(-1000, 1000) / 10000.0);
