        optimizer.setParRelativeTolerance(Math.max(1.0e-20, eps * pScale));
        optimizer.setOrthoTolerance(Math.max(1.0e-20, 2.22044604926e-16 * oScale));

        double[] start = function.getStartPoint();
        start[0] += data.consumeInt(-100, 100) / 100000.0;
        start[1] += data.consumeInt(-100, 100) / 100000.0;

        try {
            VectorialPointValuePair optimum = optimizer.optimize(function, function.getTarget(), function.getWeight(), start);
            double[] point = optimum.getPointRef();
            double[] recomputed = function.value(point);
