package org.apache.commons.math.optimization.general;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;

public class FuzzHarness {

    private static final double REL_TOL = 1.0e-6;
    private static final double ABS_TOL = 1.0e-8;

    private static final class FreudensteinRoth implements DifferentiableMultivariateVectorialFunction {
        public double[] value(double[] p) throws FunctionEvaluationException {
            if (p == null || p.length != 2) {
                throw new FunctionEvaluationException(p, "dimension mismatch");
            }
            final double x1 = p[0];
            final double x2 = p[1];
            return new double[] {
                -13.0 + x1 + (((5.0 - x2) * x2) - 2.0) * x2,
                -29.0 + x1 + (((x2 + 1.0) * x2) - 14.0) * x2
            };
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] p) throws FunctionEvaluationException {
                    if (p == null || p.length != 2) {
                        throw new FunctionEvaluationException(p, "dimension mismatch");
                    }
                    final double x2 = p[1];
                    return new double[][] {
                        { 1.0, 10.0 * x2 - 3.0 * x2 * x2 - 2.0 },
                        { 1.0,  3.0 * x2 * x2 + 2.0 * x2 - 14.0 }
                    };
                }
            };
        }
    }

    private static final class Lin2 implements DifferentiableMultivariateVectorialFunction {
        public double[] value(double[] p) throws FunctionEvaluationException {
            if (p == null || p.length != 2) {
                throw new FunctionEvaluationException(p, "dimension mismatch");
            }
            return new double[] { p[0] + 2.0 * p[1], 3.0 * p[0] - p[1] };
        }

        public MultivariateMatrixFunction jacobian() {
            return new MultivariateMatrixFunction() {
                public double[][] value(double[] p) {
                    return new double[][] { { 1.0, 2.0 }, { 3.0, -1.0 } };
                }
            };
        }
    }

    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        checkFreudensteinCase(
            "fr-1",
            new double[] { 0.5, -2.0 },
            6.99887517584575,
            new double[] { 11.4124844654993, -0.896827913731509 }
        );
        checkFreudensteinCase(
            "fr-2",
            new double[] { 5.0, -20.0 },
            6.9988751744895,
            new double[] { 11.4121122022341, -0.8968550851268697 }
        );
        checkFreudensteinCase(
            "fr-3",
            new double[] { 50.0, -200.0 },
            6.99887517242903,
            new double[] { 11.412069435091231, -0.8968582807605691 }
        );

        checkLinearReturnedValueMatchesPoint(data);
        checkLinearExactFixedPointAndCovariance(data);
    }

    private static void checkFreudensteinCase(String id, double[] start, double expectedRms, double[] expectedPoint) {
        final LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100 * (2 + 1));
        optimizer.setCostRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setParRelativeTolerance(Math.sqrt(2.22044604926e-16));
        optimizer.setOrthoTolerance(2.22044604926e-16);

        final FreudensteinRoth function = new FreudensteinRoth();
        final VectorialPointValuePair optimum;
        try {
            optimum = optimizer.optimize(
                function,
                new double[] { 0.0, 0.0 },
                new double[] { 1.0, 1.0 },
                start
            );
        } catch (FunctionEvaluationException e) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-no-exception] unexpected FunctionEvaluationException", e);
        } catch (OptimizationException e) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-no-exception] unexpected OptimizationException", e);
        } catch (IllegalArgumentException e) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-no-exception] unexpected IllegalArgumentException", e);
        }

        final double actualRms = optimizer.getRMS();
        if (!closeEnough(actualRms, expectedRms)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:" + id + "-rms] semantic mismatch: expected RMS=" + expectedRms + " but was=" + actualRms
            );
        }

        final double[] actualPoint = optimum.getPoint();
        if (actualPoint == null || actualPoint.length != expectedPoint.length) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:" + id + "-point-dim] semantic mismatch: expected point length=" +
                expectedPoint.length + " but was=" + (actualPoint == null ? -1 : actualPoint.length)
            );
        }

        for (int i = 0; i < expectedPoint.length; i++) {
            if (!closeEnough(actualPoint[i], expectedPoint[i])) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:" + id + "-param" + i + "] semantic mismatch: expected point[" + i + "]=" +
                    expectedPoint[i] + " but was=" + actualPoint[i]
                );
            }
        }

        try {
            final double[] recomputedValue = function.value(actualPoint);
            final double[] storedValue = optimum.getValue();
            if (storedValue == null || storedValue.length != recomputedValue.length) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:" + id + "-value-dim] semantic mismatch: returned value length=" +
                    (storedValue == null ? -1 : storedValue.length) +
                    " recomputed length=" + recomputedValue.length
                );
            }
            for (int i = 0; i < storedValue.length; i++) {
                if (!closeEnough(storedValue[i], recomputedValue[i])) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:" + id + "-value-at-point] semantic mismatch: returned value[" + i + "]=" +
                        storedValue[i] + " recomputed=" + recomputedValue[i]
                    );
                }
            }
        } catch (FunctionEvaluationException e) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "-value-at-point] unexpected evaluation failure", e);
        }

        final double chiSquare = optimizer.getChiSquare();
        final double rmsFromChiSquare = Math.sqrt(chiSquare / 2.0);
        if (!closeEnough(actualRms, rmsFromChiSquare)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:" + id + "-rms-chi2] consistency violation: getRMS()=" + actualRms +
                " but sqrt(getChiSquare()/rows)=" + rmsFromChiSquare
            );
        }
    }

    private static void checkLinearReturnedValueMatchesPoint(FuzzedDataProvider data) {
        final Lin2 function = new Lin2();
        final LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.setMaxIterations(100);

        final double s0 = data.consumeInt(-20, 20) / 5.0;
        final double s1 = data.consumeInt(-20, 20) / 5.0;
        final double x0 = data.consumeInt(-20, 20) / 5.0;
        final double x1 = data.consumeInt(-20, 20) / 5.0;

        final double[] start = new double[] { s0, s1 };
        final double[] target = new double[] { x0 + 2.0 * x1, 3.0 * x0 - x1 };
        final double[] weights = new double[] { 1.0, 1.0 };

        final VectorialPointValuePair out;
        final double[] point;
        final double[] storedValue;
        final double[] recomputedValue;
        try {
            out = optimizer.optimize(function, target, weights, start);
            point = out.getPoint();
            storedValue = out.getValue();
            recomputedValue = function.value(point);
        } catch (Exception e) {
            return;
        }

        if (storedValue == null || storedValue.length != recomputedValue.length) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:linear-value-dim] consistency violation: stored value length=" +
                (storedValue == null ? -1 : storedValue.length) +
                " recomputed length=" + recomputedValue.length
            );
        }

        for (int i = 0; i < storedValue.length; i++) {
            if (!closeEnough(storedValue[i], recomputedValue[i])) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:linear-value-at-point] consistency violation: stored value[" + i + "]=" +
                    storedValue[i] + " recomputed=" + recomputedValue[i] + " point=(" +
                    point[0] + "," + point[1] + ")"
                );
            }
        }

        final double rms = optimizer.getRMS();
        final double rmsFromChiSquare = Math.sqrt(optimizer.getChiSquare() / 2.0);
        if (!closeEnough(rms, rmsFromChiSquare)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:linear-rms-chi2] consistency violation: getRMS()=" + rms +
                " sqrt(getChiSquare()/2)=" + rmsFromChiSquare
            );
        }
    }

    private static void checkLinearExactFixedPointAndCovariance(FuzzedDataProvider data) {
        final Lin2 function = new Lin2();
        final double x0 = data.consumeInt(-20, 20) / 5.0;
        final double x1 = data.consumeInt(-20, 20) / 5.0;
        final double[] exact = new double[] { x0, x1 };
        final double[] target = new double[] { x0 + 2.0 * x1, 3.0 * x0 - x1 };
        final double[] weights = new double[] { 1.0, 1.0 };

        final LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        final VectorialPointValuePair out;
        final double[][] cov;
        try {
            out = optimizer.optimize(function, target, weights, exact);
            cov = optimizer.getCovariances();
        } catch (Exception e) {
            return;
        }

        final double[] point = out.getPoint();
        for (int i = 0; i < exact.length; i++) {
            if (!closeEnough(point[i], exact[i])) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:linear-fixed-point] semantic mismatch: exact[" + i + "]=" +
                    exact[i] + " but optimized point[" + i + "]=" + point[i]
                );
            }
        }

        if (cov == null || cov.length != 2 || cov[0].length != 2 || cov[1].length != 2) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:linear-cov-dim] consistency violation: unexpected covariance dimensions"
            );
        }

        final double[][] expectedCov = new double[][] {
            { 5.0 / 49.0, 1.0 / 49.0 },
            { 1.0 / 49.0, 10.0 / 49.0 }
        };

        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                if (!closeEnough(cov[i][j], expectedCov[i][j])) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:linear-cov-known] semantic mismatch: cov[" + i + "][" + j + "]=" +
                        cov[i][j] + " expected=" + expectedCov[i][j]
                    );
                }
            }
        }

        if (!closeEnough(cov[0][1], cov[1][0])) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:linear-cov-symmetric] consistency violation: cov[0][1]=" +
                cov[0][1] + " cov[1][0]=" + cov[1][0]
            );
        }
    }

    private static boolean closeEnough(double a, double b) {
        final double diff = Math.abs(a - b);
        final double scale = Math.max(1.0, Math.max(Math.abs(a), Math.abs(b)));
        return diff <= ABS_TOL || diff <= REL_TOL * scale;
    }
}

