package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.analysis.SinFunction;
import org.apache.commons.math.analysis.UnivariateRealFunction;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        UnivariateRealFunction f = new SinFunction();
        BrentSolver solver = new BrentSolver();

        boolean noThrowBadInterval = false;
        Throwable wrongBadInterval = null;
        try {
            solver.solve(f, 1.0, -1.0);
            noThrowBadInterval = true;
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            wrongBadInterval = t;
        }
        if (wrongBadInterval != null) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-bad-interval] semantic mismatch: expected IllegalArgumentException from solver.solve(sin, 1, -1) but got " + wrongBadInterval.getClass().getName(),
                    wrongBadInterval);
        }
        if (noThrowBadInterval) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-bad-interval] semantic mismatch: expected IllegalArgumentException from solver.solve(sin, 1, -1) but call completed normally");
        }

        boolean noThrowNoBracket2 = false;
        Throwable wrongNoBracket2 = null;
        try {
            solver.solve(f, 1.0, 1.5);
            noThrowNoBracket2 = true;
        } catch (IllegalArgumentException expected) {
            // expected
        } catch (Throwable t) {
            wrongNoBracket2 = t;
        }
        if (wrongNoBracket2 != null) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-nonbracketing-2arg] semantic mismatch: expected IllegalArgumentException from solver.solve(sin, 1, 1.5) but got " + wrongNoBracket2.getClass().getName(),
                    wrongNoBracket2);
        }
        if (noThrowNoBracket2) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-nonbracketing-2arg] semantic mismatch: expected IllegalArgumentException from solver.solve(sin, 1, 1.5) but call completed normally");
        }

        boolean noThrowNoBracket3 = false;
        Throwable wrongNoBracket3 = null;
        try {
            solver.solve(f, 1.0, 1.5, 1.2);
            noThrowNoBracket3 = true;
        } catch (IllegalArgumentException expected) {
            // expected; this is the ground-truth failing test input
        } catch (Throwable t) {
            wrongNoBracket3 = t;
        }
        if (wrongNoBracket3 != null) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-nonbracketing-3arg] semantic mismatch: expected IllegalArgumentException from solver.solve(sin, 1, 1.5, 1.2) but got " + wrongNoBracket3.getClass().getName(),
                    wrongNoBracket3);
        }
        if (noThrowNoBracket3) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-nonbracketing-3arg] semantic mismatch: expected IllegalArgumentException from solver.solve(sin, 1, 1.5, 1.2) but call completed normally");
        }

        {
            BrentSolver relationSolver = new BrentSolver();
            UnivariateRealFunction relationF = new SinFunction();
            double min = 1.0 + (data.consumeInt(0, 80) / 100.0);
            double max = min + 0.2;
            double initial = (min + max) / 2.0;

            boolean violated = false;
            Throwable wrong = null;
            try {
                relationSolver.solve(relationF, min, max, initial);
                violated = true;
            } catch (IllegalArgumentException ok) {
                // Contract from solve(f,min,max,initial): IllegalArgumentException when
                // function values at the three points have the same sign. Here 1.0 < min < initial < max < 2.0,
                // all inside (0, pi), so sin(...) is positive at all three points and the call must reject.
                // A throw-deleting patch or a bad special-case around positive initial breaks this observable behaviour.
            } catch (Throwable t) {
                violated = true;
                wrong = t;
            }
            if (wrong != null) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:nonBracketingPositiveInitialMustThrow] consistency violation: expected IllegalArgumentException for positive non-bracketing triple min="
                                + min + " initial=" + initial + " max=" + max + " but got " + wrong.getClass().getName(),
                        wrong);
            }
            if (violated) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:nonBracketingPositiveInitialMustThrow] consistency violation: expected IllegalArgumentException for positive non-bracketing triple min="
                                + min + " initial=" + initial + " max=" + max + " but call completed normally");
            }
        }

        {
            BrentSolver s1 = new BrentSolver();
            BrentSolver s2 = new BrentSolver();
            UnivariateRealFunction relationF = new SinFunction();
            double a = 0.5 + (data.consumeInt(0, 150) / 100.0);
            double b = 0.5 + (data.consumeInt(0, 150) / 100.0);
            double min = -a;
            double max = b;
            double initial = data.consumeBoolean() ? (-a / 2.0) : (b / 2.0);

            double r1;
            double r2;
            try {
                r1 = s1.solve(relationF, min, max);
                r2 = s2.solve(relationF, min, max, initial);
            } catch (Throwable t) {
                return;
            }

            double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(r1), Math.abs(r2)));
            if (Math.abs(r1 - r2) > tol) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:threeArgAndFourArgAgreeOnUniqueRoot] metamorphic violation: solve(f,min,max)="
                                + r1 + " vs solve(f,min,max,initial)=" + r2 + " for min=" + min + " initial=" + initial + " max=" + max);
            }

            // Hidden-state / consistency cross-check: solve(...) writes the solver result via setResult(...)
            // and getResult() reads the same state. For any correct implementation, after a successful solve
            // the returned root and the stored result must agree; a patch that masks a wrong path but leaves
            // solver state inconsistent would violate this even if the top-level return looked plausible.
            double stored1 = s1.getResult();
            double stored2 = s2.getResult();
            if (Math.abs(stored1 - r1) > tol) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:return-vs-stored-result-2arg] consistency violation: returned " + r1 + " but getResult() reported " + stored1);
            }
            if (Math.abs(stored2 - r2) > tol) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:return-vs-stored-result-3arg] consistency violation: returned " + r2 + " but getResult() reported " + stored2);
            }
        }

        {
            BrentSolver stateSolver = new BrentSolver();
            double accuracy = 1.0e-12 + (data.consumeInt(0, 1000) * 1.0e-12);
            stateSolver.setFunctionValueAccuracy(accuracy);
            double reported = stateSolver.getFunctionValueAccuracy();
            if (Double.doubleToLongBits(reported) != Double.doubleToLongBits(accuracy)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:function-value-accuracy-state] consistency violation: setFunctionValueAccuracy(" + accuracy
                                + ") but getFunctionValueAccuracy() returned " + reported);
            }
        }
    }
}

