package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        org.apache.commons.math.analysis.UnivariateRealFunction f =
                new org.apache.commons.math.analysis.SinFunction();

        {
            UnivariateRealSolver solver = new BrentSolver();
            boolean violated = false;
            try {
                solver.solve(f, 1.0, -1.0);
                violated = true;
            } catch (IllegalArgumentException expected) {
            } catch (Throwable t) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:bad-interval] wrong exception type for solver.solve(f, 1, -1): " + t.getClass().getName(),
                        t);
            }
            if (violated) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:bad-interval] semantic mismatch: solver.solve(f, 1, -1) completed normally but test requires IllegalArgumentException");
            }
        }

        {
            UnivariateRealSolver solver = new BrentSolver();
            boolean violated = false;
            try {
                solver.solve(f, 1.0, 1.5);
                violated = true;
            } catch (IllegalArgumentException expected) {
            } catch (Throwable t) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:non-bracket-2arg] wrong exception type for solver.solve(f, 1, 1.5): " + t.getClass().getName(),
                        t);
            }
            if (violated) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:non-bracket-2arg] semantic mismatch: solver.solve(f, 1, 1.5) completed normally but test requires IllegalArgumentException");
            }
        }

        {
            UnivariateRealSolver solver = new BrentSolver();
            boolean violated = false;
            try {
                solver.solve(f, 1.0, 1.5, 1.2);
                violated = true;
            } catch (IllegalArgumentException expected) {
            } catch (Throwable t) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:non-bracket-3arg] wrong exception type for solver.solve(f, 1, 1.5, 1.2): " + t.getClass().getName(),
                        t);
            }
            if (violated) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:non-bracket-3arg] semantic mismatch: solver.solve(f, 1, 1.5, 1.2) completed normally but test requires IllegalArgumentException");
            }
        }

        {
            BrentSolver solver = new BrentSolver();
            double min = 1.0 + (data.consumeInt(0, 80) / 100.0);
            double max = min + 0.2;
            double initial = (min + max) / 2.0;

            boolean violated = false;
            String msg = "completed normally";
            try {
                solver.solve(f, min, max, initial);
                violated = true;
            } catch (IllegalArgumentException ok) {
            } catch (Throwable t) {
                violated = true;
                msg = "wrong exception " + t.getClass().getName();
            }
            if (violated) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:nonBracketingPositiveInitialMustThrow] relation violated: " + msg
                                + " for min=" + min + ", initial=" + initial + ", max=" + max);
            }
        }

        {
            BrentSolver solverThreeArg = new BrentSolver();
            BrentSolver solverFourArg = new BrentSolver();

            double a = 0.5 + (data.consumeInt(0, 150) / 100.0);
            double b = 0.5 + (data.consumeInt(0, 150) / 100.0);
            double min = -a;
            double max = b;
            double initial = data.consumeBoolean() ? (-a / 2.0) : (b / 2.0);

            double r1;
            double r2;
            try {
                r1 = solverThreeArg.solve(f, min, max);
                r2 = solverFourArg.solve(f, min, max, initial);
            } catch (Throwable t) {
                return;
            }

            double reported1;
            double reported2;
            try {
                reported1 = solverThreeArg.getResult();
                reported2 = solverFourArg.getResult();
            } catch (Throwable t) {
                return;
            }

            double tol12 = 1e-9 * Math.max(1.0, Math.max(Math.abs(r1), Math.abs(r2)));
            if (Math.abs(r1 - r2) > tol12) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:threeArgAndFourArgAgreeOnUniqueRoot] metamorphic violation: min=" + min
                                + " max=" + max + " initial=" + initial + " threeArg=" + r1 + " fourArg=" + r2);
            }

            double tol1 = 1e-12 * Math.max(1.0, Math.abs(r1));
            if (Math.abs(r1 - reported1) > tol1) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:getResultMatchesThreeArgSolve] consistency violation: returned=" + r1
                                + " getResult=" + reported1 + " for min=" + min + " max=" + max);
            }

            double tol2 = 1e-12 * Math.max(1.0, Math.abs(r2));
            if (Math.abs(r2 - reported2) > tol2) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:getResultMatchesFourArgSolve] consistency violation: returned=" + r2
                                + " getResult=" + reported2 + " for min=" + min + " max=" + max + " initial=" + initial);
            }
        }

        {
            BrentSolver solver = new BrentSolver();
            double accuracy = Math.pow(10.0, -(1 + data.consumeInt(0, 6)));
            double reported;
            try {
                solver.setFunctionValueAccuracy(accuracy);
                reported = solver.getFunctionValueAccuracy();
            } catch (IllegalArgumentException e) {
                return;
            } catch (Throwable t) {
                return;
            }

            if (Double.doubleToLongBits(accuracy) != Double.doubleToLongBits(reported)) {
                throw new FuzzerSecurityIssueLow(
                        "[oracle:functionValueAccuracyRoundTrip] consistency violation: set="
                                + accuracy + " got=" + reported);
            }
        }
    }
}

