package org.apache.commons.math.ode.nonstiff;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {

    private static double relTol(double a, double b) {
        return 1.0e-8 * Math.max(1.0, Math.max(Math.abs(a), Math.abs(b)));
    }

    private static void checkArrayClose(String oracleId, double[] actual, double[] expected) {
        if (actual == null || expected == null || actual.length != expected.length) {
            throw new FuzzerSecurityIssueLow("[oracle:" + oracleId + "] semantic mismatch: length actual="
                    + (actual == null ? -1 : actual.length) + " expected="
                    + (expected == null ? -1 : expected.length));
        }
        for (int i = 0; i < actual.length; i++) {
