package org.apache.commons.math.optimization.linear;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import org.apache.commons.math.linear.ArrayRealVector;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.optimization.RealPointValuePair;

public class FuzzHarness {
    private static final double TEST_TOL = 0.0000001d;

    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        LinearObjectiveFunction trustedObjective = buildMath288Objective();
        Collection<LinearConstraint> trustedConstraints = buildMath288ConstraintsInOriginalOrder();

        RealPointValuePair trustedSolution;
        try {
            trustedSolution = new SimplexSolver().optimize(
                trustedObjective, trustedConstraints, GoalType.MAXIMIZE, true);
        } catch (Exception e) {
            throw new RuntimeException("[oracle:math288-instance-value] unexpected exception on trusted valid LP", e);
        }

        double trustedValue = trustedSolution.getValue();
        if (Math.abs(trustedValue - 10.0d) > TEST_TOL) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:math288-instance-value] semantic mismatch: expected 10.0 but was " + trustedValue);
        }

        // Contract/post-condition: optimize returns a solution of the supplied objective; the reported value
        // must equal an independent recomputation of that same objective on the returned point.
        // A patch that only changes pivot-row bookkeeping or hides an error could leave a stale/inconsistent
        // RealPointValuePair even if no exception is thrown.
        double independentObjectiveValue = trustedObjective.getValue(trustedSolution.getPoint());
        if (!closeEnough(trustedValue, independentObjectiveValue)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:value-recomputes-from-point] consistency violation: reported=" + trustedValue
                    + " recomputed=" + independentObjectiveValue);
        }

        // Contract/post-condition: a returned optimum for this valid LP must satisfy the provided constraints
        // and the non-negativity restriction passed as 'true' to optimize(..., true).
        // A silent wrong pivot choice can produce a numerically attractive but infeasible point.
        double[] p = trustedSolution.getPoint();
        if (p == null || p.length != 4) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:solution-shape] semantic mismatch: expected 4 decision variables but got "
                    + (p == null ? "null" : p.length));
        }
        for (int i = 0; i < p.length; i++) {
            if (p[i] < -TEST_TOL) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:solution-nonnegative] semantic mismatch: negative variable x" + i + "=" + p[i]);
            }
        }
        checkLeqConstraint("solution-feasibility-c1", p, new double[] { 3, 0, -5, 0 }, 0.0d);
        checkLeqConstraint("solution-feasibility-c2", p, new double[] { 2, 0, 0, -5 }, 0.0d);
        checkLeqConstraint("solution-feasibility-c3", p, new double[] { 0, 3, 0, -5 }, 0.0d);
        checkLeqConstraint("solution-feasibility-c4", p, new double[] { 1, 0, 0, 0 }, 1.0d);
        checkLeqConstraint("solution-feasibility-c5", p, new double[] { 0, 1, 0, 0 }, 1.0d);

        // Strategy (b) consistency cross-check on the masked helper: getPivotRow depends on tableau row order
        // when ratios tie. Constraint order does not change the LP being solved, so any correct implementation
        // must return the same optimum for every permutation of the same constraints.
        Collection<LinearConstraint> permutedConstraints;
        try {
            permutedConstraints = buildPermutedMath288Constraints(data);
        } catch (Exception e) {
            return;
        }

        RealPointValuePair permutedSolution;
        try {
            permutedSolution = new SimplexSolver().optimize(
                buildMath288Objective(), permutedConstraints, GoalType.MAXIMIZE, true);
        } catch (Exception e) {
            return;
        }

        double permutedValue = permutedSolution.getValue();
        if (!closeEnough(trustedValue, permutedValue)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:constraint-permutation-invariance] metamorphic violation: same LP under reordered constraints "
                    + "gave different optimum values original=" + trustedValue + " permuted=" + permutedValue);
        }

        // Lifted/generalized relation candidate: both LinearObjectiveFunction overloads document the same
        // linear formula, so evaluating the same point as double[] and as RealVector must agree.
        double v1;
        double v2;
        try {
            double c1 = (double) data.consumeInt(-20, 20);
            double c2 = (double) data.consumeInt(-20, 20);
            double c3 = (double) data.consumeInt(-20, 20);
            double d = (double) data.consumeInt(-20, 20);
            double x1 = (double) data.consumeInt(-20, 20);
            double x2 = (double) data.consumeInt(-20, 20);
            double x3 = (double) data.consumeInt(-20, 20);
            LinearObjectiveFunction f =
                new LinearObjectiveFunction(new double[] { c1, c2, c3 }, d);
            double[] point = new double[] { x1, x2, x3 };
            v1 = f.getValue(point);
            v2 = f.getValue(new ArrayRealVector(point));
        } catch (Exception e) {
            return;
        }
        if (!closeEnough(v1, v2)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:objective-function-overloads-agree] metamorphic violation: array=" + v1 + " vector=" + v2);
        }
    }

    private static LinearObjectiveFunction buildMath288Objective() {
        return new LinearObjectiveFunction(new double[] { 7, 3, 0, 0 }, 0.0d);
    }

    private static Collection<LinearConstraint> buildMath288ConstraintsInOriginalOrder() {
        ArrayList<LinearConstraint> constraints = new ArrayList<LinearConstraint>();
        constraints.add(new LinearConstraint(new double[] { 3, 0, -5, 0 }, Relationship.LEQ, 0.0d));
        constraints.add(new LinearConstraint(new double[] { 2, 0, 0, -5 }, Relationship.LEQ, 0.0d));
        constraints.add(new LinearConstraint(new double[] { 0, 3, 0, -5 }, Relationship.LEQ, 0.0d));
        constraints.add(new LinearConstraint(new double[] { 1, 0, 0, 0 }, Relationship.LEQ, 1.0d));
        constraints.add(new LinearConstraint(new double[] { 0, 1, 0, 0 }, Relationship.LEQ, 1.0d));
        return constraints;
    }

    private static Collection<LinearConstraint> buildPermutedMath288Constraints(FuzzedDataProvider data) {
        List<LinearConstraint> list = new ArrayList<LinearConstraint>();
        list.add(new LinearConstraint(new double[] { 3, 0, -5, 0 }, Relationship.LEQ, 0.0d));
        list.add(new LinearConstraint(new double[] { 2, 0, 0, -5 }, Relationship.LEQ, 0.0d));
        list.add(new LinearConstraint(new double[] { 0, 3, 0, -5 }, Relationship.LEQ, 0.0d));
        list.add(new LinearConstraint(new double[] { 1, 0, 0, 0 }, Relationship.LEQ, 1.0d));
        list.add(new LinearConstraint(new double[] { 0, 1, 0, 0 }, Relationship.LEQ, 1.0d));

        for (int i = list.size() - 1; i > 0; i--) {
            int j = data.consumeInt(0, i);
            LinearConstraint tmp = list.get(i);
            list.set(i, list.get(j));
            list.set(j, tmp);
        }
        return list;
    }

    private static void checkLeqConstraint(String oracleShortId, double[] point, double[] coeffs, double rhs) {
        double lhs = 0.0d;
        for (int i = 0; i < coeffs.length && i < point.length; i++) {
            lhs += coeffs[i] * point[i];
        }
        if (lhs > rhs + TEST_TOL) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:" + oracleShortId + "] semantic mismatch: violated LEQ constraint lhs=" + lhs + " rhs=" + rhs);
        }
    }

    private static boolean closeEnough(double a, double b) {
        double scale = Math.max(1.0d, Math.max(Math.abs(a), Math.abs(b)));
        return Math.abs(a - b) <= 1.0e-9d * scale;
    }
}

