package org.apache.commons.math.special;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import org.apache.commons.math.MathException;

public class FuzzHarness {
    private static final double LIFTED_EXPECTED = 0.632120558828558;
    private static final double LIFTED_A = 1.0;
    private static final double LIFTED_X = 1.0;
    private static final double LIFTED_TOL = 10e-15;

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        checkLiftedSeedOracle();
        checkLiftedComplementOracle();

        checkZeroBoundaryOracle(data);
        checkPQComplementRelation(data);
        checkProbabilityRangeRelation(data);
        checkAEqualsOneClosedFormConsistency(data);

        exercisePatchedPathWithoutAssertion(data);
    }

    private static void checkLiftedSeedOracle() {
        double actualP;
        try {
            actualP = Gamma.regularizedGammaP(LIFTED_A, LIFTED_X);
        } catch (MathException e) {
            return;
        }
        if (!closeAbs(actualP, LIFTED_EXPECTED, LIFTED_TOL)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:lifted-seed-p] semantic mismatch: Gamma.regularizedGammaP(1.0,1.0) expected="
                    + LIFTED_EXPECTED + " actual=" + actualP);
        }
    }

    private static void checkLiftedComplementOracle() {
        double actualP;
        double actualQ;
        try {
            actualP = Gamma.regularizedGammaP(LIFTED_A, LIFTED_X);
            actualQ = Gamma.regularizedGammaQ(LIFTED_A, LIFTED_X);
        } catch (MathException e) {
            return;
        }
        double expected = 1.0 - actualQ;
        if (!closeAbs(actualP, expected, LIFTED_TOL)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:lifted-seed-complement] semantic mismatch: for Gamma.regularizedGammaP/Q(1.0,1.0), expected P=1-Q="
                    + expected + " actualP=" + actualP + " actualQ=" + actualQ);
        }
    }

    private static void checkZeroBoundaryOracle(FuzzedDataProvider data) {
        double a = data.consumeInt(1, 1000) / 10.0;
        double p;
        double q;
        try {
            /* Contract visible in Gamma.java:
             * - if (x == 0.0) regularizedGammaP returns 0.0
             * - if (x == 0.0) regularizedGammaQ returns 1.0
             * This is a sound post-condition on a valid boundary input, and a patch that merely
             * changes convergence logic or suppresses work must still preserve these exact values.
             */
            p = Gamma.regularizedGammaP(a, 0.0);
            q = Gamma.regularizedGammaQ(a, 0.0);
        } catch (Exception e) {
            return;
        }
        if (Double.doubleToLongBits(p) != Double.doubleToLongBits(0.0)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:x-zero-p] semantic mismatch: Gamma.regularizedGammaP(" + a + ",0.0)=" + p + " expected=0.0");
        }
        if (Double.doubleToLongBits(q) != Double.doubleToLongBits(1.0)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:x-zero-q] semantic mismatch: Gamma.regularizedGammaQ(" + a + ",0.0)=" + q + " expected=1.0");
        }
    }

    private static void checkPQComplementRelation(FuzzedDataProvider data) {
        double a = data.consumeInt(1, 1000) / 10.0;
        double x = data.consumeInt(0, 1000) / 10.0;
        double p;
        double q;
        try {
            /* Documented by the real API path shown above: regularizedGammaQ(a, x) uses
             * 1.0 - regularizedGammaP(a, x) in one branch, and both are the normalized
             * complementary regularized gamma functions. Therefore for every valid input,
             * P(a,x) + Q(a,x) = 1. This is a consistency cross-check: the same quantity is
             * obtained two independent ways, directly as P and indirectly as 1-Q.
             */
            p = Gamma.regularizedGammaP(a, x);
            q = Gamma.regularizedGammaQ(a, x);
        } catch (Exception e) {
            return;
        }
        double expected = 1.0 - q;
        double tol = scaledTol(p, expected, 1e-9);
        if (Math.abs(p - expected) > tol) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:pq-complement] consistency violation: a=" + a + " x=" + x
                    + " p=" + p + " 1-q=" + expected + " q=" + q + " tol=" + tol);
        }
    }

    private static void checkProbabilityRangeRelation(FuzzedDataProvider data) {
        double a = data.consumeInt(1, 1000) / 10.0;
        double x = data.consumeInt(0, 1000) / 10.0;
        double p;
        double q;
        try {
            /* As regularized gamma functions, P and Q are normalized probabilities/complements
             * for valid a > 0 and x >= 0, so each result must lie in [0, 1].
             */
            p = Gamma.regularizedGammaP(a, x);
            q = Gamma.regularizedGammaQ(a, x);
        } catch (Exception e) {
            return;
        }
        if (!(p >= 0.0 && p <= 1.0)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:probability-range-p] relation regularized_gamma_outputs_are_probabilities violated: a="
                    + a + " x=" + x + " p=" + p);
        }
        if (!(q >= 0.0 && q <= 1.0)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:probability-range-q] relation regularized_gamma_outputs_are_probabilities violated: a="
                    + a + " x=" + x + " q=" + q);
        }
    }

    private static void checkAEqualsOneClosedFormConsistency(FuzzedDataProvider data) {
        double x = data.consumeInt(0, 1000) / 10.0;
        double p;
        double q;
        try {
            /* For a = 1, the lower/upper regularized gamma functions reduce to the exponential CDF
             * and survival function: P(1,x)=1-exp(-x), Q(1,x)=exp(-x). This gives a trusted oracle
             * built from a known closed form for the same public API, and it exercises the exact
             * patched series path when x <= a.
             */
            p = Gamma.regularizedGammaP(1.0, x);
            q = Gamma.regularizedGammaQ(1.0, x);
        } catch (Exception e) {
            return;
        }
        double expectedP = 1.0 - Math.exp(-x);
        double expectedQ = Math.exp(-x);
        double tolP = scaledTol(p, expectedP, 1e-12);
        double tolQ = scaledTol(q, expectedQ, 1e-12);
        if (Math.abs(p - expectedP) > tolP) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:a-one-p] semantic mismatch: x=" + x + " p=" + p + " expected=" + expectedP + " tol=" + tolP);
        }
        if (Math.abs(q - expectedQ) > tolQ) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:a-one-q] semantic mismatch: x=" + x + " q=" + q + " expected=" + expectedQ + " tol=" + tolQ);
        }
    }

    private static void exercisePatchedPathWithoutAssertion(FuzzedDataProvider data) {
        double a = (data.consumeInt(1, 2000) / 1000.0);
        double x = (data.consumeInt(0, 2000) / 1000.0);
        if (x > a) {
            x = a;
        }
        double epsilon = Math.pow(10.0, -data.consumeInt(6, 15));
        int maxIterations = data.consumeInt(1, 5000);
        try {
            Gamma.regularizedGammaP(a, x, epsilon, maxIterations);
            Gamma.regularizedGammaQ(a, x, epsilon, maxIterations);
            Gamma.logGamma(a);
        } catch (Exception e) {
            return;
        }
    }

    private static boolean closeAbs(double actual, double expected, double tol) {
        return Math.abs(actual - expected) <= tol;
    }

    private static double scaledTol(double lhs, double rhs, double relTol) {
        return relTol * Math.max(1.0, Math.max(Math.abs(lhs), Math.abs(rhs)));
    }
}

