        checkFuzzedComplementRelation(data);
        checkProbabilityRangeInvariant(data);
        driveRegularizedGammaQContinuedFractionPath(data);
    }

    private static void checkLiftedSeedOracle() {
        try {
            double actualP = Gamma.regularizedGammaP(1.0, 1.0);
            double actualQ = Gamma.regularizedGammaQ(1.0, 1.0);

            if (!withinTolerance(actualP, SEED_EXPECTED_P, TEST_TOL)) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:seed-p] semantic mismatch: Gamma.regularizedGammaP(1.0, 1.0) expected="
                        + SEED_EXPECTED_P + " actual=" + actualP);
            }

            /* Contract lifted verbatim from GammaTest.testRegularizedGamma helper:
             * for the same (a, x), TestUtils.assertEquals(actualP, 1.0 - actualQ, 10e-15).
             * This post-condition catches band-aid fixes that special-case only the known bad P value
             * while leaving the documented complement relation between P and Q wrong.
             */
            double expectedFromQ = 1.0 - actualQ;
            if (!withinTolerance(actualP, expectedFromQ, TEST_TOL)) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:seed-complement] semantic mismatch: P(1.0,1.0)="
                        + actualP + " but 1-Q(1.0,1.0)=" + expectedFromQ + " (Q=" + actualQ + ")");
            }
        } catch (MathException e) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:seed-exception] unexpected exception for Gamma.regularizedGammaP/Q(1.0, 1.0)", e);
        }
    }

    private static void checkFuzzedComplementRelation(FuzzedDataProvider data) {
        /* Documented relation from Gamma.regularizedGammaQ implementation and test helper:
         * Q(a, x) = 1 - P(a, x). For any valid a > 0 and x >= 0, both real API calls must agree.
         * We build valid, moderate inputs by construction and skip any input rejected by exceptions.
         */
        double a = data.consumeInt(1, 1000) / 10.0;
        double x = data.consumeInt(0, 1000) / 10.0;
        double epsilon = Math.pow(10.0, -data.consumeInt(6, 15));
        int maxIterations = data.consumeInt(100, 100000);

        double p;
        double q;
        try {
            p = Gamma.regularizedGammaP(a, x, epsilon, maxIterations);
            q = Gamma.regularizedGammaQ(a, x, epsilon, maxIterations);
        } catch (Exception e) {
            return;
        }

        double expected = 1.0 - q;
        double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(p), Math.abs(expected)));
        if (!(Math.abs(p - expected) <= tol)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:fuzzed-complement] metamorphic violation: P(a,x)=1-Q(a,x) for valid inputs"
                    + " a=" + a + " x=" + x + " epsilon=" + epsilon + " maxIterations=" + maxIterations
                    + " p=" + p + " q=" + q + " expectedFromQ=" + expected + " tol=" + tol);
        }
    }

    private static void checkProbabilityRangeInvariant(FuzzedDataProvider data) {
        /* Contract of regularized gamma functions: as normalized complements, for valid inputs
         * both outputs must be probabilities in [0, 1]. This remains observable even if a patch
         * suppresses exceptions or special-cases only one seed.
         */
        double a = data.consumeInt(1, 1000) / 10.0;
        double x = data.consumeInt(0, 1000) / 10.0;

        double p;
        double q;
        try {
            p = Gamma.regularizedGammaP(a, x);
            q = Gamma.regularizedGammaQ(a, x);
        } catch (Exception e) {
            return;
        }

        if (!(p >= 0.0 && p <= 1.0)) {
