        double x = a + (data.consumeInt(0, 1000) / 10.0);
        double epsilon = Math.pow(10.0, -data.consumeInt(6, 15));
        int maxIterations = data.consumeInt(100, 100000);

        double p;
        double q;
        try {
            p = Gamma.regularizedGammaP(a, x, epsilon, maxIterations);
            q = Gamma.regularizedGammaQ(a, x, epsilon, maxIterations);
        } catch (Exception e) {
            return;
        }

        double sum = p + q;
        double tol = 1e-9 * Math.max(1.0, Math.abs(sum));
        if (!(Math.abs(sum - 1.0) <= tol)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:q-cf-sum] consistency violation: P(a,x)+Q(a,x) must equal 1 on the continued-fraction Q path"
                    + " a=" + a + " x=" + x + " epsilon=" + epsilon + " maxIterations=" + maxIterations
                    + " p=" + p + " q=" + q + " sum=" + sum + " tol=" + tol);
        }
    }

    private static boolean withinTolerance(double actual, double expected, double tol) {
        return Math.abs(actual - expected) <= tol;
    }
}

