import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.lang.reflect.Array;
import java.util.Map;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        assertEqualsOracle("pkg-string-class", "java.lang", ClassUtils.getPackageName(String.class));
        assertEqualsOracle("pkg-map-entry-class", "java.util", ClassUtils.getPackageName(Map.Entry.class));
        assertEqualsOracle("pkg-null-class", "", ClassUtils.getPackageName((Class) null));
        assertEqualsOracle("pkg-string-array-class", "java.lang", ClassUtils.getPackageName(String[].class));
        assertEqualsOracle("pkg-boolean-array-class", "", ClassUtils.getPackageName(boolean[].class));
        assertEqualsOracle("pkg-byte-array-class", "", ClassUtils.getPackageName(byte[].class));
        assertEqualsOracle("pkg-char-array-class", "", ClassUtils.getPackageName(char[].class));
        assertEqualsOracle("pkg-short-array-class", "", ClassUtils.getPackageName(short[].class));
        assertEqualsOracle("pkg-int-array-class", "", ClassUtils.getPackageName(int[].class));
        assertEqualsOracle("pkg-long-array-class", "", ClassUtils.getPackageName(long[].class));
        assertEqualsOracle("pkg-float-array-class", "", ClassUtils.getPackageName(float[].class));
        assertEqualsOracle("pkg-double-array-class", "", ClassUtils.getPackageName(double[].class));
        assertEqualsOracle("pkg-string-2d-array-class", "java.lang", ClassUtils.getPackageName(String[][].class));
        assertEqualsOracle("pkg-string-3d-array-class", "java.lang", ClassUtils.getPackageName(String[][][].class));
        assertEqualsOracle("pkg-string-4d-array-class", "java.lang", ClassUtils.getPackageName(String[][][][].class));

        relationPackageNameClassAgreesWithCanonicalString(data);
        relationShortClassNameArrayAppendsBrackets(data);
        relationPackageNameArrayDimsStableByConstruction(data);
    }

    private static void assertEqualsOracle(String id, String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new FuzzerSecurityIssueLow("[oracle:" + id + "] semantic mismatch: expected=" + expected + " actual=" + actual);
        }
    }

    private static void relationPackageNameClassAgreesWithCanonicalString(FuzzedDataProvider data) {
        Class<?> base;
        int pick = data.consumeInt(0, 3);
        switch (pick) {
            case 0:
                base = String.class;
                break;
            case 1:
                base = Map.Entry.class;
                break;
            case 2:
                base = int.class;
                break;
            default:
                base = boolean.class;
                break;
        }

        int dims = data.consumeInt(0, 3);
        Class<?> cls = base;
        String canonical;
        String lhs;
        String rhs;
        try {
            for (int i = 0; i < dims; i++) {
                cls = Array.newInstance(cls, 0).getClass();
            }
            canonical = cls.getCanonicalName();
            if (canonical == null) {
                return;
            }
            lhs = ClassUtils.getPackageName(cls);
            rhs = ClassUtils.getPackageCanonicalName(canonical);
        } catch (Throwable t) {
            return;
        }

        if (!lhs.equals(rhs)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:packageName-class-vs-canonical] metamorphic violation: getPackageName(Class) must agree with getPackageCanonicalName(String) for the same canonical class name; class="
                    + cls + " canonical=" + canonical + " lhs=" + lhs + " rhs=" + rhs);
        }
    }

    private static void relationShortClassNameArrayAppendsBrackets(FuzzedDataProvider data) {
        Class<?> base;
        int pick = data.consumeInt(0, 3);
        switch (pick) {
            case 0:
                base = String.class;
                break;
            case 1:
                base = Map.Entry.class;
                break;
            case 2:
                base = int.class;
                break;
            default:
                base = boolean.class;
                break;
        }

        int dims = data.consumeInt(1, 4);
        Class<?> arrayCls = base;
        String actual;
        String baseShort;
        try {
            for (int i = 0; i < dims; i++) {
                arrayCls = Array.newInstance(arrayCls, 0).getClass();
            }
            actual = ClassUtils.getShortClassName(arrayCls);
            baseShort = ClassUtils.getShortClassName(base);
        } catch (Throwable t) {
            return;
        }

        String expected = baseShort;
        for (int i = 0; i < dims; i++) {
            expected += "[]";
        }

        if (!actual.equals(expected)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:shortClassName-array-brackets] metamorphic violation: array short name must be component short name plus [] suffixes; class="
                    + arrayCls + " actual=" + actual + " expected=" + expected);
        }
    }

    private static void relationPackageNameArrayDimsStableByConstruction(FuzzedDataProvider data) {
        Class<?> base;
        int pick = data.consumeInt(0, 1);
        switch (pick) {
            case 0:
                base = String.class;
                break;
            default:
                base = int.class;
                break;
        }

        int dims = data.consumeInt(1, 4);
        Class<?> cls = base;
        String actual;
        String expected;
        try {
            for (int i = 0; i < dims; i++) {
                cls = Array.newInstance(cls, 0).getClass();
            }
            actual = ClassUtils.getPackageName(cls);

            // Contract justification: package name depends on the component type's package, not on array dimensionality.
            // For arrays built from a chosen base class with known package answer, every dimension count must preserve that package.
            expected = ClassUtils.getPackageCanonicalName(base.getCanonicalName());
        } catch (Throwable t) {
            return;
        }

        if (!actual.equals(expected)) {
            throw new FuzzerSecurityIssueLow(
                "[oracle:packageName-array-dims-stable] metamorphic violation: array dimensionality must not change package name; base="
                    + base + " dims=" + dims + " actual=" + actual + " expected=" + expected);
        }
    }
}

