            throw new FuzzerSecurityIssueLow("[oracle:pkg-map-entry-class] semantic mismatch: ClassUtils.getPackageName(Map.Entry.class) expected=java.util actual=" + actual1);
        }

        String actual2 = ClassUtils.getPackageName((Class) null);
        if (!"".equals(actual2)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-null-class] semantic mismatch: ClassUtils.getPackageName((Class)null) expected='' actual=" + actual2);
        }

        String actual3 = ClassUtils.getPackageName(String[].class);
        if (!"java.lang".equals(actual3)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-string-array-class] semantic mismatch: ClassUtils.getPackageName(String[].class) expected=java.lang actual=" + actual3);
        }

        String actual4 = ClassUtils.getPackageName(boolean[].class);
        if (!"".equals(actual4)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-boolean-array-class] semantic mismatch: ClassUtils.getPackageName(boolean[].class) expected='' actual=" + actual4);
        }

        String actual5 = ClassUtils.getPackageName(byte[].class);
        if (!"".equals(actual5)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-byte-array-class] semantic mismatch: ClassUtils.getPackageName(byte[].class) expected='' actual=" + actual5);
        }

        String actual6 = ClassUtils.getPackageName(char[].class);
        if (!"".equals(actual6)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-char-array-class] semantic mismatch: ClassUtils.getPackageName(char[].class) expected='' actual=" + actual6);
        }

        String actual7 = ClassUtils.getPackageName(short[].class);
        if (!"".equals(actual7)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-short-array-class] semantic mismatch: ClassUtils.getPackageName(short[].class) expected='' actual=" + actual7);
        }

        String actual8 = ClassUtils.getPackageName(int[].class);
        if (!"".equals(actual8)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-int-array-class] semantic mismatch: ClassUtils.getPackageName(int[].class) expected='' actual=" + actual8);
        }

        String actual9 = ClassUtils.getPackageName(long[].class);
        if (!"".equals(actual9)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-long-array-class] semantic mismatch: ClassUtils.getPackageName(long[].class) expected='' actual=" + actual9);
        }

        String actual10 = ClassUtils.getPackageName(float[].class);
        if (!"".equals(actual10)) {
