             * This is a directly observable post-condition; a patch that merely avoids the buggy path or
             * silently returns a JVM-internal array encoding will violate this agreement.
             */
            lhs = ClassUtils.getPackageName(cls);
            rhs = ClassUtils.getPackageCanonicalName(canonical);
        } catch (Exception e) {
            return;
        }

        if (!safeEquals(lhs, rhs)) {
            throw new FuzzerSecurityIssueLow("[oracle:pkg-class-canonical-agreement] metamorphic violation: ClassUtils.getPackageName(Class) must agree with ClassUtils.getPackageCanonicalName(String) for canonicalName=" + canonical + " lhs=" + lhs + " rhs=" + rhs);
        }
    }

    private static void checkShortClassNameArraySuffixRelation(FuzzedDataProvider data) {
        Class<?> base;
        int pick = data.consumeInt(0, 3);
        switch (pick) {
            case 0:
                base = String.class;
                break;
            case 1:
                base = java.util.Map.Entry.class;
                break;
            case 2:
                base = int.class;
                break;
            default:
                base = boolean.class;
                break;
        }

        int dims = data.consumeInt(1, 4);
        Class<?> arrayCls = base;
        String actual;
        String baseShort;

        try {
            for (int i = 0; i < dims; i++) {
                arrayCls = Array.newInstance(arrayCls, 0).getClass();
            }

            /*
             * Contract justification:
             * getShortClassName(Class) returns the class name without the package. For arrays, the human-readable
             * form is the component short name followed by one [] per dimension, not the JVM internal encoding.
             * Building the array Class from a chosen base and dimension count makes the expected answer trusted:
             * we choose the component type first, then append exactly dims bracket pairs.
             */
