            throw new FuzzerSecurityIssueLow("[oracle:short-array-brackets] metamorphic violation: ClassUtils.getShortClassName(arrayClass) must equal component short name plus [] suffixes dims=" + dims + " base=" + base + " actual=" + actual + " expected=" + expected);
        }
    }

    private static void callPatchedApisOnAdditionalValidInputs(FuzzedDataProvider data) {
        Class<?>[] corpus = new Class<?>[] {
            String.class,
            Map.Entry.class,
            int.class,
            boolean.class
