// relation: packageName_class_overload_agrees_with_canonical_string_over
// holds because: The package-name family distinguishes canonical and non-canonical string forms; for a real Class whose canonical name is available, getPackageName(Class) must agree with getPackageCanonicalName(String) on that canonical name.
// valid input: Choose a valid Class from top-level, inner, primitive, and array cases. Build arrays by repeated Array.newInstance. Use only classes with non-null Class.getCanonicalName().
Class<?> base;
int pick = data.consumeInt(0, 3);
switch (pick) {
  case 0: base = String.class; break;
  case 1: base = java.util.Map.Entry.class; break;
  case 2: base = int.class; break;
  default: base = boolean.class; break;
}
int dims = data.consumeInt(0, 3);
Class<?> cls = base;
String canonical;
String a;
String b;
try {
  for (int i = 0; i < dims; i++) {
    cls = java.lang.reflect.Array.newInstance(cls, 0).getClass();
  }
  canonical = cls.getCanonicalName();
  if (canonical == null) {
    return;
  }
  a = ClassUtils.getPackageName(cls);
  b = ClassUtils.getPackageCanonicalName(canonical);
} catch (Exception e) { return; }
if (!a.equals(b)) {
  throw new RuntimeException("relation packageName_class_overload_agrees_with_canonical_string_overload violated: " + a + " vs " + b);
}

