package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        Locale realDefaultLocale = Locale.getDefault();

        FastDateFormat liftedFormat1;
        FastDateFormat liftedFormat2;
        FastDateFormat liftedFormat3;
        try {
            Locale.setDefault(Locale.US);
            liftedFormat1 = FastDateFormat.getDateTimeInstance(
                    FastDateFormat.FULL, FastDateFormat.FULL, Locale.GERMANY);
            liftedFormat2 = FastDateFormat.getDateTimeInstance(
                    FastDateFormat.FULL, FastDateFormat.FULL);
            Locale.setDefault(Locale.GERMANY);
            liftedFormat3 = FastDateFormat.getDateTimeInstance(
                    FastDateFormat.FULL, FastDateFormat.FULL);
        } catch (Throwable t) {
            Locale.setDefault(realDefaultLocale);
            return;
        }
        Locale.setDefault(realDefaultLocale);

        // Lifted exactly from FastDateFormatTest::test_changeDefault_Locale_DateTimeInstance.
        if (liftedFormat1.getLocale() != Locale.GERMANY) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format1-locale] semantic mismatch: expected same locale de_DE but was "
                            + liftedFormat1.getLocale());
        }
        if (liftedFormat2.getLocale() != Locale.US) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format2-locale] semantic mismatch: expected same locale en_US but was "
                            + liftedFormat2.getLocale());
        }
        if (liftedFormat3.getLocale() != Locale.GERMANY) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format3-locale] semantic mismatch: expected same locale de_DE but was "
                            + liftedFormat3.getLocale());
        }
        if (liftedFormat1 == liftedFormat2) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct formatter instances");
        }
        if (liftedFormat2 == liftedFormat3) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct formatter instances");
        }

        int[] styles = new int[] {
                FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT
        };
        int dateStyle = styles[data.consumeInt(0, 3)];
        int timeStyle = styles[data.consumeInt(0, 3)];
        Locale chosenLocale = data.consumeBoolean() ? Locale.US : Locale.GERMANY;

        FastDateFormat implicitDefaultFmt;
        FastDateFormat explicitLocaleFmt;
        String implicitRendered;
        String explicitRendered;
        try {
            Locale.setDefault(chosenLocale);
            implicitDefaultFmt = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
            explicitLocaleFmt = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, chosenLocale);
            Date sample = new Date(123456789L);
            implicitRendered = implicitDefaultFmt.format(sample);
            explicitRendered = explicitLocaleFmt.format(sample);
        } catch (Throwable t) {
            Locale.setDefault(realDefaultLocale);
            return;
        }
        Locale.setDefault(realDefaultLocale);

        // Contract: getDateTimeInstance(int,int) uses the current default locale.
        // Therefore, with default locale L, it must agree with the explicit-locale overload on locale and rendering.
        if (!chosenLocale.equals(implicitDefaultFmt.getLocale())
                || !chosenLocale.equals(explicitLocaleFmt.getLocale())
                || !normalize(implicitRendered).equals(normalize(explicitRendered))) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:default-vs-explicit-datetime] metamorphic violation: default-locale and explicit-locale dateTime instances disagree"
                            + " dateStyle=" + dateStyle
                            + " timeStyle=" + timeStyle
                            + " chosenLocale=" + chosenLocale
                            + " implicitLocale=" + implicitDefaultFmt.getLocale()
                            + " explicitLocale=" + explicitLocaleFmt.getLocale()
                            + " implicitRendered=" + implicitRendered
                            + " explicitRendered=" + explicitRendered);
        }

        Locale chosenDateLocale = data.consumeBoolean() ? Locale.US : Locale.GERMANY;
        int dateOnlyStyle = styles[data.consumeInt(0, 3)];
        FastDateFormat implicitDateFmt;
        FastDateFormat explicitDateFmt;
        String implicitDateRendered;
        String explicitDateRendered;
        try {
            Locale.setDefault(chosenDateLocale);
            implicitDateFmt = FastDateFormat.getDateInstance(dateOnlyStyle);
            explicitDateFmt = FastDateFormat.getDateInstance(dateOnlyStyle, chosenDateLocale);
            Date sample = new Date(987654321L);
            implicitDateRendered = implicitDateFmt.format(sample);
            explicitDateRendered = explicitDateFmt.format(sample);
        } catch (Throwable t) {
            Locale.setDefault(realDefaultLocale);
            return;
        }
        Locale.setDefault(realDefaultLocale);

        // Same documented guarantee for getDateInstance(int): it uses the current default locale.
        if (!chosenDateLocale.equals(implicitDateFmt.getLocale())
                || !chosenDateLocale.equals(explicitDateFmt.getLocale())
                || !normalize(implicitDateRendered).equals(normalize(explicitDateRendered))) {
            throw new FuzzerSecurityIssueLow(
                    "[oracle:default-vs-explicit-date] metamorphic violation: default-locale and explicit-locale date instances disagree"
                            + " style=" + dateOnlyStyle
                            + " chosenLocale=" + chosenDateLocale
                            + " implicitLocale=" + implicitDateFmt.getLocale()
                            + " explicitLocale=" + explicitDateFmt.getLocale()
                            + " implicitRendered=" + implicitDateRendered
                            + " explicitRendered=" + explicitDateRendered);
        }

        Locale explicitLocale = data.consumeBoolean() ? Locale.US : Locale.GERMANY;
        FastDateFormat directDateTimeFmt;
        FastDateFormat recomputedFromPatternFmt;
        String directOut;
        String recomputedOut;
        String pattern;
        try {
            SimpleDateFormat jdkFmt = (SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle, explicitLocale);
            pattern = jdkFmt.toPattern();
            directDateTimeFmt = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, null, explicitLocale);
            recomputedFromPatternFmt = FastDateFormat.getInstance(pattern, null, explicitLocale);
            Date sample = new Date(Math.abs((long) data.consumeInt()) % 1_000_000L);
            directOut = directDateTimeFmt.format(sample);
            recomputedOut = recomputedFromPatternFmt.format(sample);
        } catch (Throwable t) {
