package org.apache.commons.lang.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import java.util.Date;
import java.util.Locale;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        Locale realDefaultLocale = Locale.getDefault();
        try {
            Locale.setDefault(Locale.US);

            FastDateFormat format1 = FastDateFormat.getDateInstance(FastDateFormat.FULL, Locale.GERMANY);
            FastDateFormat format2 = FastDateFormat.getDateInstance(FastDateFormat.FULL);
            Locale.setDefault(Locale.GERMANY);
            FastDateFormat format3 = FastDateFormat.getDateInstance(FastDateFormat.FULL);

            if (format1.getLocale() != Locale.GERMANY) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-format1-locale] semantic mismatch: expected Locale.GERMANY got " + format1.getLocale());
            }
            if (format2.getLocale() != Locale.US) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-format2-locale] semantic mismatch: expected Locale.US got " + format2.getLocale());
            }
            if (format3.getLocale() != Locale.GERMANY) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-format3-locale] semantic mismatch: expected Locale.GERMANY got " + format3.getLocale());
            }
            if (format1 == format2) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-format1-ne-format2] semantic mismatch: expected distinct formatter instances");
            }
            if (format2 == format3) {
                throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                    "[oracle:lifted-format2-ne-format3] semantic mismatch: expected distinct formatter instances");
            }

            int selector = data.consumeInt(0, 3);
            int style;
            switch (selector) {
                case 0:
                    style = FastDateFormat.FULL;
                    break;
                case 1:
                    style = FastDateFormat.LONG;
                    break;
                case 2:
                    style = FastDateFormat.MEDIUM;
                    break;
                default:
                    style = FastDateFormat.SHORT;
                    break;
            }

            long millis = data.consumeInt(-1000000, 1000000);
            Date probeDate = new Date(millis);

            try {
                Locale.setDefault(Locale.US);
                FastDateFormat implicit = FastDateFormat.getDateInstance(style);
                FastDateFormat explicit = FastDateFormat.getDateInstance(style, Locale.US);

                if (implicit.getLocale() != Locale.US) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:default-vs-explicit-locale] metamorphic violation: omitted locale must use Locale.getDefault(); implicit locale="
                            + implicit.getLocale() + " explicit locale=" + explicit.getLocale() + " style=" + style);
                }

                String implicitPattern = implicit.getPattern();
                String explicitPattern = explicit.getPattern();
                if (!implicitPattern.equals(explicitPattern)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:default-vs-explicit-pattern] metamorphic violation: getDateInstance(style) and getDateInstance(style, Locale.getDefault()) must agree on pattern; style="
                            + style + " implicitPattern=" + implicitPattern + " explicitPattern=" + explicitPattern);
                }

                String implicitText = implicit.format(probeDate).replaceAll("\\s+", "");
                String explicitText = explicit.format(probeDate).replaceAll("\\s+", "");
                if (!implicitText.equals(explicitText)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:default-vs-explicit-format] metamorphic violation: equivalent overloads produced different formatted output; style="
                            + style + " millis=" + millis + " implicit=" + implicitText + " explicit=" + explicitText);
                }
            } catch (RuntimeException e) {
                if (e instanceof com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) {
                    throw e;
                }
            }

            try {
                int dateSelector = data.consumeInt(0, 3);
                int timeSelector = data.consumeInt(0, 3);
                int dateStyle;
                int timeStyle;
                switch (dateSelector) {
                    case 0:
                        dateStyle = FastDateFormat.FULL;
                        break;
                    case 1:
                        dateStyle = FastDateFormat.LONG;
                        break;
                    case 2:
                        dateStyle = FastDateFormat.MEDIUM;
                        break;
                    default:
                        dateStyle = FastDateFormat.SHORT;
                        break;
                }
                switch (timeSelector) {
                    case 0:
                        timeStyle = FastDateFormat.FULL;
                        break;
                    case 1:
                        timeStyle = FastDateFormat.LONG;
                        break;
                    case 2:
                        timeStyle = FastDateFormat.MEDIUM;
                        break;
                    default:
                        timeStyle = FastDateFormat.SHORT;
                        break;
                }

                Locale.setDefault(Locale.GERMANY);
                FastDateFormat dtImplicit = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle);
                FastDateFormat dtExplicit = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.GERMANY);

                String dtImplicitText = dtImplicit.format(probeDate).replaceAll("\\s+", "");
                String dtExplicitText = dtExplicit.format(probeDate).replaceAll("\\s+", "");
                if (!dtImplicitText.equals(dtExplicitText)) {
                    throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                        "[oracle:datetime-default-vs-explicit] metamorphic violation: equivalent getDateTimeInstance overloads disagreed; dateStyle="
                            + dateStyle + " timeStyle=" + timeStyle + " millis=" + millis + " implicit=" + dtImplicitText
                            + " explicit=" + dtExplicitText);
                }
            } catch (RuntimeException e) {
                if (e instanceof com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) {
                    throw e;
                }
            }
        } finally {
            Locale.setDefault(realDefaultLocale);
        }
    }
}

