// relation: dateInstance_defaultLocale_overloadAgreement
// holds because: getDateInstance(int style) is documented as using the default time zone and locale, while getDateInstance(int style, Locale locale) is documented as using the specified locale in the default time zone; therefore with locale == Locale.getDefault() they must produce equivalent formatters.
// valid input: Choose any valid style from {FULL, LONG, MEDIUM, SHORT}. Save the current default locale, set a known default locale (US or GERMANY), call both overloads under that same default, then restore the original default locale.
Locale old = Locale.getDefault();
int[] styles = new int[] { FastDateFormat.FULL, FastDateFormat.LONG, FastDateFormat.MEDIUM, FastDateFormat.SHORT };
int style = styles[data.consumeInt(0, 3)];
Locale chosen = data.consumeBoolean() ? Locale.US : Locale.GERMANY;
FastDateFormat a;
FastDateFormat b;
try {
    Locale.setDefault(chosen);
    a = FastDateFormat.getDateInstance(style);
    b = FastDateFormat.getDateInstance(style, Locale.getDefault());
} catch (Exception e) {
    Locale.setDefault(old);
    return;
}
Locale.setDefault(old);
if (!a.getPattern().equals(b.getPattern()) || !a.getLocale().equals(b.getLocale())) {
    throw new RuntimeException("relation dateInstance_defaultLocale_overloadAgreement violated: pattern/locale differ: " + a.getPattern() + "/" + a.getLocale() + " vs " + b.getPattern() + "/" + b.getLocale());
}

