package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        {
            StrBuilder sb = new StrBuilder("onetwothree");
            sb.deleteFirst("three");

            boolean actualContains = sb.contains('h');
            if (actualContains != false) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lang295-contains] semantic mismatch: expected sb.contains('h')==false after deleting \"three\" from \"onetwothree\", got "
                        + actualContains);
            }

            int actualIndex = sb.indexOf('h');
            if (actualIndex != -1) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:lang295-indexof] semantic mismatch: expected sb.indexOf('h')==-1 after deleting \"three\" from \"onetwothree\", got "
                        + actualIndex);
            }
        }

        {
            String s = data.consumeAsciiString(20);
            if (s.length() > 0) {
                String del = data.consumeAsciiString(8);
                char probe = (char) data.consumeInt(0, 127);

                boolean actualContains;
                int actualIndex;
                try {
                    StrBuilder sb = new StrBuilder(s);
                    sb.deleteFirst(del);
                    actualContains = sb.contains(probe);
                    actualIndex = sb.indexOf(probe);
                } catch (Throwable e) {
                    return;
                }

                boolean expectedContains = actualIndex >= 0;
                if (actualContains != expectedContains) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:contains-indexof-agree] consistency violation: contains(char) disagrees with indexOf(char)>=0"
                            + " input=" + s
                            + " delete=" + del
                            + " probe=" + (int) probe
                            + " contains=" + actualContains
                            + " indexOf=" + actualIndex);
                }
            }
        }

        {
            String s = data.consumeAsciiString(20);
            if (s.length() > 0) {
                int cut = data.consumeInt(1, s.length());
                String suffix = s.substring(s.length() - cut);
                char probe = suffix.charAt(data.consumeInt(0, suffix.length() - 1));

                boolean actual;
                boolean expected;
                try {
                    StrBuilder sb = new StrBuilder(s);
                    sb.deleteFirst(suffix);
                    actual = sb.contains(probe);
                    expected = new String(sb.toCharArray()).indexOf(probe) >= 0;
                } catch (Throwable e) {
                    return;
                }

                if (actual != expected) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:active-length-after-shrink] relation contains_respects_active_length_after_shrink violated: actual="
                            + actual
                            + " expected=" + expected
                            + " original=" + s
                            + " deleted=" + suffix
                            + " probe=" + (int) probe);
                }
            }
        }

        {
            String s = data.consumeAsciiString(20);
            String del = data.consumeAsciiString(8);
            char c = (char) data.consumeInt(0, 127);

            boolean a;
            boolean b;
            try {
                StrBuilder sb = new StrBuilder(s);
                sb.deleteFirst(del);
                a = sb.contains(c);
                b = sb.contains(String.valueOf(c));
            } catch (Throwable e) {
                return;
            }

            if (a != b) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:char-string-overload] relation contains_char_agrees_with_contains_single_char_string violated: charResult="
                        + a
                        + " stringResult=" + b
                        + " input=" + s
                        + " delete=" + del
                        + " char=" + (int) c);
            }
        }

        {
            String s = data.consumeAsciiString(20);
            if (s.length() > 0) {
                int cut = data.consumeInt(1, s.length());
                String suffix = s.substring(s.length() - cut);
                char probe = suffix.charAt(data.consumeInt(0, suffix.length() - 1));

                int lengthBefore;
                int capacityBefore;
                int lengthAfter;
                int capacityAfter;
                try {
                    StrBuilder sb = new StrBuilder(s);
                    sb.deleteFirst(suffix);
                    lengthBefore = sb.length();
                    capacityBefore = sb.capacity();
                    sb.contains(probe);
                    lengthAfter = sb.length();
                    capacityAfter = sb.capacity();
                } catch (Throwable e) {
                    return;
                }

                if (lengthBefore != lengthAfter) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:contains-readonly-length] post-condition violation: contains(char) changed length from "
                            + lengthBefore + " to " + lengthAfter
                            + " original=" + s
                            + " deleted=" + suffix
                            + " probe=" + (int) probe);
                }
                if (capacityBefore != capacityAfter) {
                    throw new FuzzerSecurityIssueLow(
                        "[oracle:contains-readonly-capacity] post-condition violation: contains(char) changed capacity from "
                            + capacityBefore + " to " + capacityAfter
                            + " original=" + s
                            + " deleted=" + suffix
                            + " probe=" + (int) probe);
                }
            }
        }

        {
            String s = data.consumeAsciiString(20);
            String del = data.consumeAsciiString(8);
            char probe = (char) data.consumeInt(0, 127);

            boolean a;
            boolean b;
            try {
                StrBuilder sb1 = new StrBuilder(s);
                sb1.deleteFirst(del);

                StrBuilder sb2 = new StrBuilder(s);
                sb2.deleteFirst(del);

                a = sb1.contains(probe);
                b = sb2.contains(probe);
            } catch (Throwable e) {
                return;
            }

            if (a != b) {
                throw new FuzzerSecurityIssueLow(
                    "[oracle:fresh-object-recompute] consistency violation: identically constructed StrBuilder instances disagree on contains(char)"
                        + " input=" + s
                        + " delete=" + del
                        + " probe=" + (int) probe
                        + " lhs=" + a
                        + " rhs=" + b);
            }
        }
    }
}

