package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        exactLang295Lifted();
        constructedContainsConsistency(data);
        tokenizerSizeVsIterationConsistency(data);
    }

    private static void exactLang295Lifted() {
        StrBuilder sb = new StrBuilder("onetwothree");
        sb.deleteFirst("three");

        boolean actualContains = sb.contains('h');
        if (actualContains != false) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lang295-exact] semantic mismatch: " +
                "The contains(char) method is looking beyond the end of the string " +
                "expected=false actual=" + actualContains);
        }

        int actualIndex = sb.indexOf('h');
        if (actualIndex != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lang295-indexof] semantic mismatch: " +
                "The indexOf(char) method is looking beyond the end of the string " +
                "expected=-1 actual=" + actualIndex);
        }
    }

    private static void constructedContainsConsistency(FuzzedDataProvider data) {
        try {
            char needle = visibleChar(data.consumeByte());

            String keptRaw = data.consumeAsciiString(24);
            String kept = stripChar(keptRaw, needle);
            if (kept.length() == 0) {
                kept = "SAFE";
            }

            String removableMiddle = stripChar(data.consumeAsciiString(8), '\0');
            String removable = "X" + needle + removableMiddle + "Y";

            StrBuilder sb = new StrBuilder(kept + removable);
            sb.deleteFirst(removable);

            boolean actualContainsChar = sb.contains(needle);
            int actualIndexOfChar = sb.indexOf(needle);
            boolean actualContainsString = sb.contains(String.valueOf(needle));
            boolean actualContainsMatcher = sb.contains(StrMatcher.charMatcher(needle));

            if (actualContainsChar) {
                throw new RuntimeException(
                    "[oracle:constructed-absence] metamorphic violation: " +
                    "constructed suffix was deleted, so the chosen character must be absent " +
                    "inputKept=" + kept + " removable=" + removable + " needle=" + (int) needle +
                    " contains(char)=" + actualContainsChar);
            }

            if (actualIndexOfChar != -1) {
                throw new RuntimeException(
                    "[oracle:indexof-agrees] metamorphic violation: " +
                    "for a correct implementation, contains(char)==false implies indexOf(char)==-1 " +
                    "inputKept=" + kept + " removable=" + removable + " needle=" + (int) needle +
                    " contains(char)=" + actualContainsChar + " indexOf(char)=" + actualIndexOfChar);
            }

            if (actualContainsString != actualContainsChar) {
                throw new RuntimeException(
                    "[oracle:char-vs-string] metamorphic violation: " +
                    "contains(char) and contains(String.valueOf(char)) are sibling contains overloads " +
                    "for the same one-character query and must agree " +
                    "inputKept=" + kept + " removable=" + removable + " needle=" + (int) needle +
                    " lhs=" + actualContainsChar + " rhs=" + actualContainsString);
            }

            if (actualContainsMatcher != actualContainsChar) {
                throw new RuntimeException(
                    "[oracle:char-vs-matcher] metamorphic violation: " +
                    "contains(char) and contains(StrMatcher.charMatcher(char)) search for the same character and must agree " +
                    "inputKept=" + kept + " removable=" + removable + " needle=" + (int) needle +
                    " lhs=" + actualContainsChar + " rhs=" + actualContainsMatcher);
            }
        } catch (Throwable ignored) {
            if (ignored instanceof com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) {
                throw (com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) ignored;
            }
            if (ignored instanceof RuntimeException && hasOraclePrefix(ignored.getMessage())) {
                throw (RuntimeException) ignored;
            }
        }
    }

    private static void tokenizerSizeVsIterationConsistency(FuzzedDataProvider data) {
        try {
            String middle = data.consumeAsciiString(20);
            if (middle.length() == 0) {
                middle = "mid";
            }

            String removable = " tail";
            StrBuilder sb = new StrBuilder("head " + middle + removable);
            sb.deleteFirst(removable);

