            // A fresh tokenizer over the same builder must therefore report the same count that
            // another fresh tokenizer yields by manual hasNext()/next() iteration.
            StrTokenizer reportedTokenizer = sb.asTokenizer();
            int reportedSize = reportedTokenizer.size();

            StrTokenizer iterTokenizer = sb.asTokenizer();
            int counted = 0;
            while (iterTokenizer.hasNext()) {
                Object token = iterTokenizer.next();
                if (token != null) {
                    token.toString();
                }
                counted++;
            }

