                throw new RuntimeException(
                    "[oracle:tokenizer-size-count] consistency violation: " +
                    "reportedSize=" + reportedSize + " counted=" + counted +
                    " builder=" + normalize(sb.toString()));
            }
        } catch (Throwable ignored) {
            if (ignored instanceof com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) {
                throw (com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow) ignored;
            }
            if (ignored instanceof RuntimeException && hasOraclePrefix(ignored.getMessage())) {
                throw (RuntimeException) ignored;
            }
        }
    }

    private static boolean hasOraclePrefix(String message) {
        return message != null && message.startsWith("[oracle:");
    }

    private static char visibleChar(byte b) {
        return (char) ('!' + (b & 63));
    }

    private static String stripChar(String s, char ch) {
        if (s == null || s.length() == 0) {
            return "";
        }
        StringBuffer out = new StringBuffer(s.length());
        for (int i = 0; i < s.length(); i++) {
            char cur = s.charAt(i);
            if (cur != ch) {
                out.append(cur);
            }
        }
        return out.toString();
    }

    private static String normalize(String s) {
        return s == null ? "null" : s.replaceAll("\\s+", "");
    }
}

