package org.jfree.data.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        TimePeriodValues s = new TimePeriodValues("Test");

        int actual0 = s.getMaxMiddleIndex();
        if (actual0 != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-empty] semantic mismatch: getMaxMiddleIndex() on new TimePeriodValues(\"Test\") expected=-1 actual=" + actual0);
        }

        s.add(new SimpleTimePeriod(100L, 200L), 1.0);
        int actual1 = s.getMaxMiddleIndex();
        if (actual1 != 0) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-after-1] semantic mismatch: after add(new SimpleTimePeriod(100L, 200L), 1.0) expected=0 actual=" + actual1);
        }

        s.add(new SimpleTimePeriod(300L, 400L), 2.0);
        int actual2 = s.getMaxMiddleIndex();
        if (actual2 != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-after-2] semantic mismatch: after add(new SimpleTimePeriod(300L, 400L), 2.0) expected=1 actual=" + actual2);
        }

        s.add(new SimpleTimePeriod(0L, 50L), 3.0);
        int actual3 = s.getMaxMiddleIndex();
        if (actual3 != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-after-3] semantic mismatch: after add(new SimpleTimePeriod(0L, 50L), 3.0) expected=1 actual=" + actual3);
        }

        s.add(new SimpleTimePeriod(150L, 200L), 4.0);
        int actual4 = s.getMaxMiddleIndex();
        if (actual4 != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-after-4] semantic mismatch: after add(new SimpleTimePeriod(150L, 200L), 4.0) expected=1 actual=" + actual4);
        }

        /*
         * Contract justification:
         * - getMaxMiddleIndex() "Returns the index of the time period with the maximum middle milliseconds."
         * - add(...) is the real public writer that establishes the stored periods and internally updates bounds.
         * Therefore, after construction through add(...), the index reported by getMaxMiddleIndex() must identify
         * an existing element whose middle instant is maximal among the series' current periods.
         * A patch that silently returns the wrong field (for example maxEndIndex) violates this observable post-condition
         * even though no exception is thrown.
         */
        int itemCount = s.getItemCount();
        int reported = s.getMaxMiddleIndex();
        if (reported < 0 || reported >= itemCount) {
            throw new RuntimeException(
                "[oracle:constructed-max-middle-seed] metamorphic violation: reported index out of bounds itemCount="
                    + itemCount + " reported=" + reported);
        }
        int expectedFromPeriods = computeExpectedMaxMiddleIndex(s);
        if (reported != expectedFromPeriods) {
            throw new RuntimeException(
                "[oracle:constructed-max-middle-seed] metamorphic violation: getMaxMiddleIndex must point to period with maximum middle milliseconds"
                    + " reported=" + reported + " expected=" + expectedFromPeriods);
        }

        try {
            int n = data.consumeInt(1, 6);
            TimePeriodValues fuzzSeries = new TimePeriodValues("Fuzz-" + data.consumeAsciiString(8));
            for (int i = 0; i < n; i++) {
                int start = data.consumeInt(-1_000_000, 1_000_000);
                int width = data.consumeInt(0, 10_000);
                int end = start + width;
                if (data.consumeBoolean()) {
                    fuzzSeries.add(new SimpleTimePeriod((long) start, (long) end), Double.valueOf(i));
                } else {
                    fuzzSeries.add(new TimePeriodValue(new SimpleTimePeriod((long) start, (long) end), Double.valueOf(i)));
                }
            }

            /*
             * Contract justification:
             * - The three add overloads all add the same logical datum to the series.
             * - getMaxMiddleIndex() is a read-only getter over the resulting collection state.
             * - For any correct implementation, if we construct the periods ourselves, we know which inserted index
             *   has the maximum middle milliseconds, so the getter must return that index.
             * This is an oracle-from-the-input-itself: we choose the periods first, then check the API recovers
             * the known answer established by those real add(...) calls.
             */
            int fuzzExpected = computeExpectedMaxMiddleIndex(fuzzSeries);
            int fuzzActual = fuzzSeries.getMaxMiddleIndex();
            if (fuzzActual != fuzzExpected) {
                throw new RuntimeException(
                    "[oracle:constructed-max-middle-fuzz] metamorphic violation: getMaxMiddleIndex must equal the inserted period index with maximum middle milliseconds"
                        + " expected=" + fuzzExpected + " actual=" + fuzzActual + " itemCount=" + fuzzSeries.getItemCount());
            }

            /*
             * Contract justification:
             * - clone() returns "A clone of the time series."
             * - get* readers and hashCode() are documented read-only observers of that state.
             * Therefore a correct clone must preserve the observable bounds readers for the same contents.
             */
            TimePeriodValues clone = (TimePeriodValues) fuzzSeries.clone();
            if (clone.getItemCount() != fuzzSeries.getItemCount()
                || clone.getMinStartIndex() != fuzzSeries.getMinStartIndex()
                || clone.getMaxStartIndex() != fuzzSeries.getMaxStartIndex()
                || clone.getMinMiddleIndex() != fuzzSeries.getMinMiddleIndex()
                || clone.getMaxMiddleIndex() != fuzzSeries.getMaxMiddleIndex()
                || clone.getMinEndIndex() != fuzzSeries.getMinEndIndex()
                || clone.getMaxEndIndex() != fuzzSeries.getMaxEndIndex()) {
                throw new RuntimeException(
                    "[oracle:clone-readers] metamorphic violation: clone must preserve observable bound index readers"
                        + " origMaxMiddle=" + fuzzSeries.getMaxMiddleIndex()
                        + " cloneMaxMiddle=" + clone.getMaxMiddleIndex());
            }
        } catch (com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow e) {
            throw e;
        } catch (RuntimeException e) {
            throw e;
        } catch (Throwable t) {
            return;
        }
    }

    private static int computeExpectedMaxMiddleIndex(TimePeriodValues series) {
        int count = series.getItemCount();
        if (count == 0) {
            return -1;
        }
        int bestIndex = -1;
        long bestMiddle = Long.MIN_VALUE;
        for (int i = 0; i < count; i++) {
            TimePeriod p = series.getTimePeriod(i);
            long middle = middleMillis(p);
            if (bestIndex < 0 || middle > bestMiddle) {
                bestIndex = i;
                bestMiddle = middle;
            }
        }
        return bestIndex;
    }

    private static long middleMillis(TimePeriod p) {
        long start = p.getStart().getTime();
        long end = p.getEnd().getTime();
        return start + ((end - start) / 2L);
    }
}

