package org.jfree.data.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        TimePeriodValues lifted = new TimePeriodValues("Test");
        if (lifted.getMaxMiddleIndex() != -1) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-empty] semantic mismatch: expected -1 but was "
                    + lifted.getMaxMiddleIndex());
        }
        lifted.add(new SimpleTimePeriod(100L, 200L), 1.0);
        if (lifted.getMaxMiddleIndex() != 0) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-after-1] semantic mismatch: expected 0 but was "
                    + lifted.getMaxMiddleIndex());
        }
        lifted.add(new SimpleTimePeriod(300L, 400L), 2.0);
        if (lifted.getMaxMiddleIndex() != 1) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-after-2] semantic mismatch: expected 1 but was "
                    + lifted.getMaxMiddleIndex());
        }
        lifted.add(new SimpleTimePeriod(0L, 50L), 3.0);
        if (lifted.getMaxMiddleIndex() != 1) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-after-3] semantic mismatch: expected 1 but was "
                    + lifted.getMaxMiddleIndex());
        }
        lifted.add(new SimpleTimePeriod(150L, 200L), 4.0);
        if (lifted.getMaxMiddleIndex() != 1) {
            throw new FuzzerSecurityIssueLow("[oracle:lifted-after-4] semantic mismatch: expected 1 but was "
                    + lifted.getMaxMiddleIndex());
        }

        try {
            int count = data.consumeInt(1, 5);
            SimpleTimePeriod[] periods = new SimpleTimePeriod[count];
            Number[] values = new Number[count];

            for (int i = 0; i < count; i++) {
                long start = data.consumeInt(-1_000_000, 1_000_000);
                long width = data.consumeInt(0, 10_000);
                long end = start + width;
                periods[i] = new SimpleTimePeriod(start, end);
                values[i] = new Integer(data.consumeInt(-1_000_000, 1_000_000));
            }

            TimePeriodValues viaDouble = new TimePeriodValues("A");
            TimePeriodValues viaNumber = new TimePeriodValues("A");
            TimePeriodValues viaItem = new TimePeriodValues("A");

            for (int i = 0; i < count; i++) {
                viaDouble.add(periods[i], values[i].doubleValue());
                viaNumber.add(periods[i], values[i]);
                viaItem.add(new TimePeriodValue(periods[i], values[i]));
            }

            // The three add overloads are documented as adding the same data item to the series,
            // so equivalent inputs must produce equal series and equal observable readers.
            if (!viaDouble.equals(viaNumber) || !viaNumber.equals(viaItem)) {
                throw new RuntimeException("[oracle:overload-eq] metamorphic violation: equivalent add overloads produced unequal series");
            }
            if (viaDouble.hashCode() != viaNumber.hashCode() || viaNumber.hashCode() != viaItem.hashCode()) {
                throw new RuntimeException("[oracle:overload-hash] metamorphic violation: equal series had different hash codes"
                        + " hd=" + viaDouble.hashCode()
                        + " hn=" + viaNumber.hashCode()
                        + " hi=" + viaItem.hashCode());
            }

            // Contract cited by the API: getMaxMiddleIndex() returns "the index of the time period
            // with the maximum middle milliseconds". After add()/delete(), a correct implementation
            // must report an index whose period really has the maximal middle among all stored items.
            // A patch that only changes reachability/throws or leaves stale bookkeeping breaks this.
            checkMaxMiddleContract(viaDouble, "max-middle-contract-double-empty", "max-middle-contract-double-mismatch");
            checkMaxMiddleContract(viaNumber, "max-middle-contract-number-empty", "max-middle-contract-number-mismatch");
            checkMaxMiddleContract(viaItem, "max-middle-contract-item-empty", "max-middle-contract-item-mismatch");

            if (count >= 2) {
                int delStart = data.consumeInt(0, count - 1);
                int delEnd = data.consumeInt(delStart, count - 1);

                TimePeriodValues deleted = (TimePeriodValues) viaItem.clone();
                deleted.delete(delStart, delEnd);

                TimePeriodValues expectedRemaining = new TimePeriodValues("A");
                for (int i = 0; i < count; i++) {
                    if (i < delStart || i > delEnd) {
                        expectedRemaining.add(new TimePeriodValue(periods[i], values[i]));
                    }
                }

                // delete(start,end) is documented to delete an inclusive range; a correct
                // implementation must leave the same remaining series as rebuilding from the
                // non-deleted items, and the bound readers must agree with that rebuilt state.
                if (!deleted.equals(expectedRemaining)) {
                    throw new RuntimeException("[oracle:delete-eq] metamorphic violation: delete result differed from rebuilt remaining series");
                }
                if (deleted.getMaxMiddleIndex() != expectedRemaining.getMaxMiddleIndex()) {
                    throw new RuntimeException("[oracle:delete-max-middle] metamorphic violation: delete/rebuild disagreement"
                            + " deleted=" + deleted.getMaxMiddleIndex()
                            + " rebuilt=" + expectedRemaining.getMaxMiddleIndex());
                }
                checkMaxMiddleContract(deleted, "delete-contract-empty", "delete-contract-mismatch");
            }

            TimePeriodValues copied = viaNumber.createCopy(0, viaNumber.getItemCount() - 1);
            // createCopy(start,end) copies a subset of items; copying the full range must preserve
            // the observable series state, including the reported max-middle index.
            if (!copied.equals(viaNumber)) {
                throw new RuntimeException("[oracle:copy-eq] metamorphic violation: full-range copy was not equal to original");
            }
            if (copied.getMaxMiddleIndex() != viaNumber.getMaxMiddleIndex()) {
                throw new RuntimeException("[oracle:copy-max-middle] metamorphic violation: full-range copy changed max middle index"
                        + " original=" + viaNumber.getMaxMiddleIndex()
                        + " copy=" + copied.getMaxMiddleIndex());
            }
            checkMaxMiddleContract(copied, "copy-contract-empty", "copy-contract-mismatch");
        } catch (Throwable t) {
            if (t instanceof FuzzerSecurityIssueLow) {
                throw (FuzzerSecurityIssueLow) t;
            }
            if (t instanceof RuntimeException) {
                String msg = t.getMessage();
                if (msg != null && msg.startsWith("[oracle:")) {
                    throw (RuntimeException) t;
                }
            }
            return;
        }
    }

    private static void checkMaxMiddleContract(TimePeriodValues series, String emptyOracleId, String mismatchOracleId) {
        int count = series.getItemCount();
        int actual = series.getMaxMiddleIndex();
        if (count == 0) {
            if (actual != -1) {
                throw new RuntimeException("[oracle:" + emptyOracleId + "] metamorphic violation: empty series must report -1 but was " + actual);
            }
            return;
        }

        int expectedIndex = 0;
        long expectedMiddle = middleOf(series.getTimePeriod(0));
        for (int i = 1; i < count; i++) {
            long candidateMiddle = middleOf(series.getTimePeriod(i));
            if (candidateMiddle > expectedMiddle) {
                expectedMiddle = candidateMiddle;
                expectedIndex = i;
            }
        }

        if (actual != expectedIndex) {
            throw new RuntimeException("[oracle:" + mismatchOracleId + "] metamorphic violation: getMaxMiddleIndex disagreed with stored periods"
                    + " expected=" + expectedIndex
                    + " actual=" + actual
                    + " expectedMiddle=" + expectedMiddle);
        }
    }

    private static long middleOf(TimePeriod period) {
        long start = period.getStart().getTime();
        long end = period.getEnd().getTime();
        return start / 2L + end / 2L + ((start & 1L) + (end & 1L)) / 2L;
    }
}

